{"schema":1,"platform":"sgsol-pc","repository":"13835629670/sgsol-pc-updates","minLoader":1,"sequence":8,"version":"1.0.7","files":{"sgsol-mail-assistant.user.js":{"code":"// ==UserScript==
// @name         SGSOL 邮件助手（独立版）
// @namespace    local.sanguosha.mail-assistant
// @version      1.1.0
// @author       local
// @description  独立的 SGSOL 邮件归档、自动循环、日常奖励、官阶与用户资料工具；不依赖手气卡或小抄主干。
// @match        https://www.sanguosha.com/*
// @match        https://web.sanguosha.com/*
// @match        https://*.sanguosha.com/*
// @grant        GM_getValue
// @grant        GM_setValue
// @grant        GM_deleteValue
// @grant        GM_registerMenuCommand
// @grant        unsafeWindow
// @run-at       document-start
// ==/UserScript==

window.__H5_COMBINED_BOOT_STATE__ = window.__H5_COMBINED_BOOT_STATE__ || { version: '1.0.2-mail-standalone', archiveLoaded: false, errors: [] };
window.__H5_MAIL_ARCHIVE_COMBINED_MODE__ = true;
window.__H5_MAIL_ARCHIVE_TEST_OPTIONS__ = Object.assign({}, window.__H5_MAIL_ARCHIVE_TEST_OPTIONS__ || {}, { disableUi: true });

(function installAccountIdResolver() {
	'use strict';
	const API_KEY = '__SGSOL_ACCOUNT_ID_RESOLVER__';
	if (window[API_KEY]) return;
	const CLIENT_FIELDS = Object.freeze([
		'clientId', 'ClientId', 'clientID', 'ClientID',
		'accountId', 'AccountId', 'accountID', 'AccountID'
	]);
	const USER_FIELDS = Object.freeze([
		'userId', 'UserId', 'userID', 'UserID', 'uid', 'UID', 'uuid', 'Uuid', 'account'
	]);
	const NESTED_FIELDS = Object.freeze(['Self', 'self', 'userInfo', 'UserInfo', 'baseInfo', 'Info', 'data']);
	let lastSnapshot = { accountId: '', source: '', unityStorageCandidates: [] };

	function normalize(value) {
		if (typeof value !== 'string' && typeof value !== 'number') return '';
		const normalized = String(value).trim();
		return /^\d{1,32}$/.test(normalized) && normalized !== '0' ? normalized : '';
	}

	function readObject(source, fields, depth = 0, seen = new Set()) {
		if (!source || (typeof source !== 'object' && typeof source !== 'function') || seen.has(source) || depth > 2) return '';
		seen.add(source);
		for (const field of fields) {
			try {
				const accountId = normalize(source[field]);
				if (accountId) return accountId;
			} catch (_) {}
		}
		for (const field of NESTED_FIELDS) {
			try {
				const accountId = readObject(source[field], fields, depth + 1, seen);
				if (accountId) return accountId;
			} catch (_) {}
		}
		return '';
	}

	function unityStorageCandidates() {
		const ids = new Set();
		try {
			for (let index = 0; index < window.localStorage.length; index += 1) {
				const key = String(window.localStorage.key(index) || '');
				const match = /^(\d{6,32})::/.exec(key);
				if (match) ids.add(match[1]);
			}
		} catch (_) {}
		return Array.from(ids).sort();
	}

	function resolve(sources) {
		const sourceList = Array.isArray(sources) ? sources : [sources];
		for (const source of sourceList) {
			const accountId = readObject(source, CLIENT_FIELDS);
			if (accountId) {
				lastSnapshot = { accountId, source: 'game-client-object', unityStorageCandidates: [] };
				return accountId;
			}
		}
		const candidates = unityStorageCandidates();
		if (candidates.length === 1) {
			const accountId = candidates[0];
			lastSnapshot = { accountId, source: 'unity-local-storage-prefix', unityStorageCandidates: candidates };
			return accountId;
		}
		if (candidates.length > 1) {
			lastSnapshot = { accountId: '', source: '', unityStorageCandidates: candidates };
			return '';
		}
		for (const source of sourceList) {
			const accountId = readObject(source, USER_FIELDS);
			if (accountId) {
				lastSnapshot = { accountId, source: 'game-user-object-fallback', unityStorageCandidates: candidates };
				return accountId;
			}
		}
		lastSnapshot = { accountId: '', source: '', unityStorageCandidates: candidates };
		return '';
	}

	window[API_KEY] = Object.freeze({
		resolve,
		snapshot: () => ({ ...lastSnapshot, unityStorageCandidates: lastSnapshot.unityStorageCandidates.slice() })
	});
})();

(function installSgsolMailRuntimeResolver() {
    'use strict';

    const API_KEY = '__SGSOL_MAIL_RUNTIME_RESOLVER__';
    const RUNTIME_KEY = '__SGSOL_MAIL_GAME_RUNTIME__';
    const pageWindow = typeof unsafeWindow !== 'undefined' ? unsafeWindow : window;
    const isRuntime = (value) => Boolean(value && typeof value.class === 'function');

    /*
     * 邮件助手自己的最小 H5 runtime adapter。
     *
     * 这层只负责把官方页面现有的 Laya / 游戏管理器暴露成邮件模块已经使用的
     * class()/win()/get()/del()/goods()/stage 接口，不依赖手气卡助手或旧主干。
     *
     * 管理器定位方式沿用现有客户端运行时结构：
     * - GameEventDispatcher 可从已存在的舞台对象或 PopUpWindow.ged 取得；
     * - WindowManager 监听 GameEventDispatcher 的 HIDE_WINDOW；
     * - ServerProxy 来自 WindowManager.proxy；
     * - 其他管理器通过 ServerProxy.constructor._events 中对应官方回包处理器的 caller 取得。
     */
    const MANAGER_EVENT_HINTS = Object.freeze({
        AchievementManager: ['ClientDbsGetuserachinfoRep'],
        ActivityManager: ['ClientJDInfoNtf'],
        BlessManager: ['ClientQifuRankRep'],
        BlessNewManager: ['decodeClientQiFuNewData'],
        GameGeneralManager: ['ClientGeneralFromRep'],
        GameGoodsManager: ['DbsCcMovegoodsRep'],
        GiftManager: ['ClientPickupgiftbagRep'],
        MailManager: ['decodeClientGetMailNtf'],
        NewFuLiManager: ['decodeSetOutGiftInfoResp'],
        NewSecKillManager: ['decodeClientNewSeckillInfoRep'],
        OfficerManager: ['ClientOfficerInfoRep'],
        TaskManager: ['SmsgTaskFailed'],
        TimerManager: ['ClientPingMsg'],
        TreasureManger: ['ClientDuobaoInfoRep'],
        WelfareManger: ['ClientLotteryRep']
    });

    const MANAGER_PROPERTY_HINTS = Object.freeze({
        FriendManager: 'blackFriendsDic'
    });

    const METHOD_ALIAS_HINTS = Object.freeze({
        ActivityManager: Object.freeze([
            ['SendGetWyqjTiyanCardReq', 'CLIENT_NEWBIE_WANT_STRONG_GENERAL_EXPERIENCE_CARD_REQ']
        ]),
        TaskManager: Object.freeze([
            ['RequestTaskAward', 'TaskRewardSelectWindow'],
            ['GetAllTaskDataByTaskID', 'GetNoGetTaskDataByTaskID']
        ]),
        NewSecKillManager: Object.freeze([
            ['ReqBuySeckillGoods', 'newSecKill_baseID']
        ])
    });

    let current = null;
    let runtimeSource = '';
    let timerId = 0;
    let adapterCreated = false;
    let buildAttempts = 0;
    let lastBuildError = '';

    function currentLaya() {
        try { return pageWindow.Laya || window.Laya || null; } catch (_) { return null; }
    }

    function ownValue(object, key) {
        if (!object) return undefined;
        try {
            const descriptor = Object.getOwnPropertyDescriptor(object, key);
            if (descriptor && Object.prototype.hasOwnProperty.call(descriptor, 'value')) return descriptor.value;
            return object[key];
        } catch (_) {
            return undefined;
        }
    }

    function objectChildren(node) {
        if (!node) return [];
        for (const key of ['_children', '_childs', 'children']) {
            const value = ownValue(node, key);
            if (Array.isArray(value) && value.length) return value;
        }
        return [];
    }

    function walkStage(predicate, maxNodes = 3000) {
        const Laya = currentLaya();
        const root = Laya && Laya.stage;
        if (!root) return null;
        const pending = [root];
        const seen = new Set();
        let visited = 0;
        while (pending.length && visited < maxNodes) {
            const node = pending.shift();
            if (!node || seen.has(node)) continue;
            seen.add(node);
            visited += 1;
            try {
                if (predicate(node)) return node;
            } catch (_) {}
            const children = objectChildren(node);
            if (children.length) pending.push(...children);
        }
        return null;
    }

    function normalizeEventEntries(value) {
        if (!value) return [];
        return Array.isArray(value) ? value : [value];
    }

    function eventTable(value) {
        if (!value) return null;
        try {
            const ctor = value.constructor;
            if (ctor && ctor._events) return ctor._events;
        } catch (_) {}
        try {
            if (value._events) return value._events;
        } catch (_) {}
        return null;
    }

    function callerFromEvent(host, eventName, requiredOwnKey = '') {
        const events = eventTable(host);
        if (!events || !eventName) return null;
        let entries = null;
        try { entries = events[eventName]; } catch (_) { return null; }
        for (const entry of normalizeEventEntries(entries)) {
            let caller = null;
            try { caller = entry && entry.caller; } catch (_) {}
            if (!caller) continue;
            if (!requiredOwnKey) return caller;
            try {
                if (Object.keys(caller).includes(requiredOwnKey)) return caller;
            } catch (_) {}
        }
        return null;
    }

    function patchMethodAliases(manager, managerName) {
        if (!manager) return manager;
        const hints = METHOD_ALIAS_HINTS[managerName];
        if (!hints || !hints.length) return manager;

        const container = manager.__proto__ || (manager.constructor && manager.constructor.prototype) || manager;
        if (!container) return manager;

        for (const [alias, sourceNeedle] of hints) {
            try {
                if (typeof manager[alias] === 'function') continue;
            } catch (_) {}

            let foundName = '';
            let node = container;
            let depth = 0;
            while (node && node !== Object.prototype && depth < 6 && !foundName) {
                for (const name of Object.getOwnPropertyNames(node)) {
                    if (name === 'constructor') continue;
                    let descriptor = null;
                    try { descriptor = Object.getOwnPropertyDescriptor(node, name); } catch (_) {}
                    const fn = descriptor && descriptor.value;
                    if (typeof fn !== 'function') continue;
                    let source = '';
                    try { source = Function.prototype.toString.call(fn); } catch (_) {}
                    if (source.includes(sourceNeedle)) {
                        foundName = name;
                        break;
                    }
                }
                node = Object.getPrototypeOf(node);
                depth += 1;
            }

            if (!foundName || foundName === alias) continue;
            try {
                manager[alias] = function mailRuntimeAliasedMethod() {
                    return manager[foundName].apply(this, arguments);
                };
            } catch (_) {}
        }
        return manager;
    }

    function buildMailRuntime() {
        buildAttempts += 1;
        const Laya = currentLaya();
        if (!Laya || !Laya.stage) {
            lastBuildError = !Laya ? 'official-laya-missing' : 'laya-stage-missing';
            return null;
        }

        const cache = Object.create(null);
        const instances = Object.create(null);

        function getClassUtils() {
            try { return Laya.ClassUtils || null; } catch (_) { return null; }
        }

        function getInstance(className, data, destroyMode = false, callback) {
            if (!className) return null;

            if (cache[className] && typeof cache[className] === 'function') {
                try {
                    const created = new cache[className](data);
                    if (typeof callback === 'function') callback(created);
                    return created;
                } catch (_) {}
            }

            if (!instances[className]) {
                const classUtils = getClassUtils();
                if (!classUtils || typeof classUtils.getInstance !== 'function') return null;
                let instance = null;
                try { instance = classUtils.getInstance(className, data); } catch (_) { return null; }
                if (!instance) return null;

                try {
                    if (instance.protoName === 'Protocol') return instance;
                } catch (_) {}

                if (data !== null && data !== undefined) {
                    try {
                        if (typeof instance.Init === 'function') instance.Init();
                    } catch (_) {}
                }
                instances[className] = instance;
            }

            const instance = instances[className];
            if (instance && instance.timeoutId) {
                try { clearTimeout(instance.timeoutId); } catch (_) {}
                try { delete instance.timeoutId; } catch (_) {}
            }
            if (typeof callback === 'function') {
                try { callback(instance); } catch (_) {}
            }
            if (destroyMode !== false && destroyMode !== null) {
                delInstance(className, destroyMode);
            }
            return instance;
        }

        function destroyInstanceNow(className) {
            const instance = instances[className];
            if (!instance) return;
            try {
                if (!instance.parent) {
                    if (typeof instance.Close === 'function') instance.Close();
                    else if (typeof instance.destroy === 'function') instance.destroy();
                }
            } catch (_) {}
            try { delete instance.timeoutId; } catch (_) {}
            delete instances[className];
        }

        function delInstance(className, mode = true) {
            const instance = instances[className];
            if (!instance || mode === false || mode === null) return;
            if (instance.timeoutId) {
                try { clearTimeout(instance.timeoutId); } catch (_) {}
                try { delete instance.timeoutId; } catch (_) {}
            }
            if (mode === true) {
                destroyInstanceNow(className);
                return;
            }
            const delay = Number(mode);
            if (!Number.isFinite(delay) || delay < 0) return;
            instance.timeoutId = setTimeout(() => destroyInstanceNow(className), delay);
        }

        function existingGameEventDispatcher() {
            if (cache.GameEventDispatcher) return cache.GameEventDispatcher;

            const fromStage = walkStage((node) => Boolean(ownValue(node, 'ged')));
            if (fromStage) {
                const ged = ownValue(fromStage, 'ged');
                if (ged) return ged;
            }

            const popup = getInstance('PopUpWindow', null, false);
            const ged = ownValue(popup, 'ged');
            return ged || null;
        }

        function windowManagerFromExistingDispatcher() {
            const dispatcher = cache.GameEventDispatcher || existingGameEventDispatcher();
            if (!dispatcher) return null;
            return callerFromEvent(dispatcher, 'HIDE_WINDOW') || null;
        }

        function managerFromManagerList(propertyName) {
            const windowManager = classOf('WindowManager');
            if (!windowManager || !propertyName) return null;
            let list = null;
            try { list = windowManager.constructor && windowManager.constructor.managerList; } catch (_) {}
            if (!Array.isArray(list)) return null;
            for (const manager of list) {
                if (!manager) continue;
                try {
                    if (Object.keys(manager).includes(propertyName)) return manager;
                } catch (_) {}
            }
            return null;
        }

        function managerFromServerProxy(eventNames) {
            const proxy = classOf('ServerProxy');
            if (!proxy) return null;
            for (const eventName of eventNames || []) {
                const manager = callerFromEvent(proxy, eventName);
                if (manager) return manager;
            }
            return null;
        }

        function globalClassCandidate(name) {
            for (const target of [pageWindow, window]) {
                try {
                    const value = target && target[name];
                    if (value) return value;
                } catch (_) {}
            }
            const classUtils = getClassUtils();
            if (classUtils) {
                for (const methodName of ['getClass', 'getRegClass', 'getClassByName']) {
                    try {
                        if (typeof classUtils[methodName] !== 'function') continue;
                        const value = classUtils[methodName](name);
                        if (value) return value;
                    } catch (_) {}
                }
            }
            return null;
        }

        function resolveUserData() {
            const direct = globalClassCandidate('UserData');
            if (direct && (direct.Self || direct.self || typeof direct === 'function')) return direct;

            const existing = walkStage((node) => {
                const value = ownValue(node, 'userData');
                return Boolean(value);
            }, 1800);
            if (existing) {
                const value = ownValue(existing, 'userData');
                if (value) {
                    try {
                        const ctor = Object.getPrototypeOf(value) && Object.getPrototypeOf(value).constructor;
                        if (ctor && ctor !== Object) return ctor;
                    } catch (_) {}
                    return value;
                }
            }

            const birthday = getInstance('BirthdayWishWin', null, false);
            if (!birthday) return null;
            let userData = ownValue(birthday, 'userData');
            if (!userData) {
                try {
                    if (typeof birthday.refreshIcon === 'function') birthday.refreshIcon();
                } catch (_) {}
                userData = ownValue(birthday, 'userData');
            }
            if (!userData) return null;
            try {
                const ctor = Object.getPrototypeOf(userData) && Object.getPrototypeOf(userData).constructor;
                return ctor && ctor !== Object ? ctor : userData;
            } catch (_) {
                return userData;
            }
        }

        function resolveGoodsGetter() {
            const preview = getInstance('SgxFPreviewWindow', null, false);
            const getter = ownValue(preview, 'getGoodConfig');
            return typeof getter === 'function' ? getter : null;
        }

        function classOf(name, force = false, supplied) {
            if (!name) return null;
            if (!force && cache[name]) return cache[name];

            let value = null;
            try {
                if (typeof supplied === 'function') value = supplied();
                else if (supplied) value = supplied;
            } catch (_) {}

            if (!value) {
                if (name === 'GameEventDispatcher') value = existingGameEventDispatcher();
                else if (name === 'WindowManager') value = windowManagerFromExistingDispatcher();
                else if (name === 'ServerProxy') {
                    const wm = classOf('WindowManager');
                    value = wm && ownValue(wm, 'proxy');
                } else if (name === 'UserData') value = resolveUserData();
                else if (name === 'GetGoodsByID') value = resolveGoodsGetter();
                else if (MANAGER_PROPERTY_HINTS[name]) value = managerFromManagerList(MANAGER_PROPERTY_HINTS[name]);
                else if (MANAGER_EVENT_HINTS[name]) value = managerFromServerProxy(MANAGER_EVENT_HINTS[name]);
                else value = globalClassCandidate(name);
            }

            if (value) {
                value = patchMethodAliases(value, name);
                cache[name] = value;
            }
            return value || null;
        }

        function readWindowInstanceFromDictionary(dictionary, windowName) {
            if (!dictionary) return null;
            try {
                if (typeof dictionary.get === 'function') {
                    const value = dictionary.get(windowName);
                    if (value) return value;
                }
            } catch (_) {}
            try {
                if (dictionary._maps && dictionary._maps[windowName]) return dictionary._maps[windowName];
            } catch (_) {}
            try {
                if (dictionary[windowName]) return dictionary[windowName];
            } catch (_) {}
            return null;
        }

        function activeWindow(windowName) {
            const wm = classOf('WindowManager');
            let dictionary = null;
            try { dictionary = wm && wm.WindowInstanceDict; } catch (_) {}
            const fromDictionary = readWindowInstanceFromDictionary(dictionary, windowName);
            if (fromDictionary) return fromDictionary;

            return walkStage((node) => {
                const names = [];
                try { names.push(node.name, node.sceneName, node.id); } catch (_) {}
                try { names.push(node.constructor && node.constructor.name); } catch (_) {}
                return names.some((value) => value === windowName);
            }, 3500);
        }

        function goods(baseId) {
            const id = Number(baseId);
            const getter = classOf('GetGoodsByID');
            if (typeof getter === 'function') {
                try {
                    const value = getter(id);
                    if (value) return value;
                } catch (_) {}
            }
            const manager = classOf('GameGoodsManager');
            if (manager) {
                for (const methodName of ['GetGoodsByID', 'getGoodsByID', 'GetGoodsById', 'getGoodsById']) {
                    try {
                        if (typeof manager[methodName] !== 'function') continue;
                        const value = manager[methodName](id);
                        if (value) return value;
                    } catch (_) {}
                }
            }
            return null;
        }

        const runtime = {
            version: '1.0.2-mail-runtime',
            instance: instances,
            classes: cache,
            class: classOf,
            get: getInstance,
            del: delInstance,
            win: activeWindow,
            goods,
            get stage() {
                const current = currentLaya();
                return current && current.stage || null;
            },
            get scene() {
                const manager = classOf('SceneManager');
                try {
                    if (manager && manager.CurrentScene) return manager.CurrentScene;
                } catch (_) {}
                return walkStage((node) => node && node.sceneName === 'SceneLayer') || null;
            },
            get gamescene() {
                const manager = classOf('SceneManager');
                try {
                    return manager && manager.IsGameScene ? runtime.scene : null;
                } catch (_) {
                    return null;
                }
            },
            _peekClass(name) {
                return cache[name] || null;
            }
        };

        /*
         * SceneManager 在旧 runtime 中也是通过游戏事件定位的；邮件助手当前并不依赖它，
         * 因此仅在能从现有对象直接得到时缓存，不主动创建额外 UI。
         */
        try {
            const directSceneManager = globalClassCandidate('SceneManager');
            if (directSceneManager) cache.SceneManager = directSceneManager;
        } catch (_) {}

        lastBuildError = '';
        adapterCreated = true;
        return runtime;
    }

    function publish(runtime, source = 'external') {
        if (!isRuntime(runtime)) return null;
        current = runtime;
        runtimeSource = source;
        for (const target of [pageWindow, window]) {
            try { target[RUNTIME_KEY] = runtime; } catch (_) {}
        }
        if (timerId) {
            window.clearInterval(timerId);
            timerId = 0;
        }
        return runtime;
    }

    function resolve() {
        if (isRuntime(current)) return current;

        const candidates = [];
        try { candidates.push(['mail-runtime', pageWindow[RUNTIME_KEY]]); } catch (_) {}
        try { candidates.push(['mail-runtime', window[RUNTIME_KEY]]); } catch (_) {}
        try { candidates.push(['compat-h5-runtime', pageWindow.__H5_SKIN_RUNTIME__]); } catch (_) {}
        try { candidates.push(['compat-page-laya', pageWindow.laya]); } catch (_) {}
        try { candidates.push(['compat-h5-runtime', window.__H5_SKIN_RUNTIME__]); } catch (_) {}
        try { candidates.push(['compat-page-laya', window.laya]); } catch (_) {}

        for (const [source, candidate] of candidates) {
            const runtime = publish(candidate, source);
            if (runtime) return runtime;
        }

        let built = null;
        try { built = buildMailRuntime(); }
        catch (error) {
            lastBuildError = error && error.message ? error.message : String(error);
        }
        return built ? publish(built, 'mail-adapter') : null;
    }

    function diagnostics() {
        const Laya = currentLaya();
        const runtime = isRuntime(current) ? current : null;
        const missingCapabilities = [];
        if (!Laya) missingCapabilities.push('window.Laya');
        if (!(Laya && Laya.stage)) missingCapabilities.push('Laya.stage');
        if (!runtime) missingCapabilities.push('runtime');
        if (runtime) {
            for (const name of ['class', 'win', 'get', 'del', 'goods']) {
                if (typeof runtime[name] !== 'function') missingCapabilities.push(name);
            }
        }

        let userDataReady = false;
        let mailManagerReady = false;
        if (runtime && typeof runtime._peekClass === 'function') {
            try { userDataReady = Boolean(runtime._peekClass('UserData')); } catch (_) {}
            try { mailManagerReady = Boolean(runtime._peekClass('MailManager')); } catch (_) {}
        }

        return Object.freeze({
            officialLayaPresent: Boolean(Laya),
            stagePresent: Boolean(Laya && Laya.stage),
            adapterCreated,
            runtimeResolved: Boolean(runtime),
            runtimeSource,
            classResolverReady: Boolean(runtime && typeof runtime.class === 'function'),
            userDataReady,
            mailManagerReady,
            buildAttempts,
            lastBuildError,
            missingCapabilities
        });
    }

    const api = Object.freeze({
        resolve,
        get: resolve,
        isReady: () => Boolean(resolve()),
        diagnostics
    });

    for (const target of [pageWindow, window]) {
        try { target[API_KEY] = api; } catch (_) {}
    }

    if (!resolve()) timerId = window.setInterval(resolve, 500);
})();

(function installSgsolMailRuntimeServices() {
    'use strict';
    const API_KEY = '__SGSOL_MAIL_RUNTIME_SERVICES__';
    const pageWindow = typeof unsafeWindow !== 'undefined' ? unsafeWindow : window;
    let laya = null;
    let Laya = null;

    function currentRuntime() {
        const resolver = pageWindow.__SGSOL_MAIL_RUNTIME_RESOLVER__ || window.__SGSOL_MAIL_RUNTIME_RESOLVER__;
        const runtime = resolver && typeof resolver.resolve === 'function' ? resolver.resolve() : null;
        if (runtime && typeof runtime.class === 'function') {
            laya = runtime;
            try { Laya = pageWindow.Laya || window.Laya || Laya; } catch (_) {}
        }
        return laya;
    }

    function sleep(n, t) {
    		return new Promise(((i, e) => {
    			setTimeout((() => i(t)), n);
    		}))
    	}

    function collectGiftExchangeMessages() {
