    const generalUpgradeKnownStates = new Map();

    let generalUpgradeKnownAccountId = "";

    function normalizeGeneralUpgradeCounts(value) {
    		const source = value && "object" == typeof value ? value : {};
    		const values = GENERAL_UPGRADE_STAGES.map((stage, index) => {
    			const raw = source[stage.key] ?? source[index] ?? 0;
    			const parsed = Math.floor(Number(raw));
    			return Math.max(0, Math.min(GENERAL_UPGRADE_MAX_COUNT, Number.isFinite(parsed) ? parsed : 0));
    		});
    		// 后一层必须是前一层的子集；若用户直接调高后层，就自动补足前置层人数。
    		for (let index = values.length - 2; index >= 0; index -= 1) values[index] = Math.max(values[index], values[index + 1]);
    		return Object.fromEntries(GENERAL_UPGRADE_STAGES.map((stage, index) => [stage.key, values[index]]));
    	}

    function normalizeGeneralUpgradeRosterIds(value) {
    		return Array.from(new Set((Array.isArray(value) ? value : [])
    			.map((id) => Math.floor(Number(id) || 0))
    			.filter((id) => Number.isInteger(id) && id > 0)))
