	const SCAN_INTERVAL_MS = 16;
	const BLOCKER_KEY = "__H5_OFFICER_PROMOTION_ANIMATION_BLOCKER__";

	if (window[BLOCKER_KEY]) return;

	let blockedCount = 0;
	const blockedNodes = new WeakSet();

	function resourcePath(node) {
		return String(
			node.url ||
			node.skin ||
			node._skin ||
			(node.texture && node.texture.url) ||
			(node._texture && node._texture.url) ||
			""
		);
	}

	function hideNode(node) {
		if (!node || node.destroyed) return;
		if (!blockedNodes.has(node)) {
			blockedNodes.add(node);
			blockedCount += 1;
		}
		node.visible = false;
		node.mouseEnabled = false;
		node.mouseThrough = true;
	}

	function hidePromotionBackgrounds(promotionWindow) {
		const parent = promotionWindow.parent;
		const count = Number(parent && parent.numChildren) || 0;
		for (let index = 0; index < count; index += 1) {
			const sibling = parent.getChildAt(index);
			if (
				sibling.name === PROMOTION_MODAL_BACKGROUND_NAME ||
				resourcePath(sibling).includes(BIG_PROMOTION_BACKGROUND_PATH)
			) {
				hideNode(sibling);
			}
		}
	}

	function visit(node) {
		if (!node || node.destroyed) return;
		if (TARGET_WINDOW_NAMES.has(node.name)) {
			hideNode(node);
			hidePromotionBackgrounds(node);
			return;
		}
