			Number(a.requestedAt || a.respondedAt || 0) - Number(b.requestedAt || b.respondedAt || 0)
		);
		return cloneJson(candidates[candidates.length - 1], null);
	}

	function compactRecordForDurableStore(record) {
		const compact = cloneJson(record, null);
		if (!compact) return null;
		const latestSuccess = latestExplicitSuccessAttempt(record);
		compact.claimAttempts = latestSuccess ? [latestSuccess] : [];
		compact.lastConfirmedSuccessAttempt = latestSuccess;
		return compact;
	}

	function durableWhitelistRecords() {
		return records
			.filter(record =>
				record &&
				record.accountId === accountId &&
				record.jsonAutoClaim === true &&
				["single-gift", "dbs-item"].includes(record.claimRoute)
			)
			.map(compactRecordForDurableStore)
			.filter(Boolean);
	}

	function rebuildRecordIndex() {
		recordsByMid = new Map();
		for (const record of records) {
			if (record && record.mid != null) recordsByMid.set(String(record.mid), record);
		}
	}

	function rebuildCrossRecordIndex() {
		crossRecordsByKey = new Map();
		for (const record of crossRecords) {
			if (!record || record.mid == null || !record.originAccountId) continue;
			crossRecordsByKey.set(crossRecordKey(record.originAccountId, record.mid), record);
		}
	}

	function getDurableStoreBridge() {
		const bridge = window.__SGSOL_BRIDGE__;
		const available = Boolean(
			bridge &&
			typeof bridge.readMailArchiveStore === "function" &&
			typeof bridge.writeMailArchiveStore === "function"
		);
		durableStoreAvailable = available;
		return available ? bridge : null;
	}

	function readDurableAccount(targetAccountId) {
		const bridge = getDurableStoreBridge();
		if (!bridge) return null;
		try {
			const response = bridge.readMailArchiveStore(targetAccountId);
			if (!response || response.ok !== true) {
				lastError = "durable-archive-load:" + String(response && response.error || "bridge-read-failed");
				return null;
			}
			if (!response.found || !response.data) return null;
			const data = response.data;
			if (String(data.accountId || "") !== String(targetAccountId)) {
				lastError = "durable-archive-load:account-mismatch";
				return null;
			}
			durableStoreLoaded = true;
			return data;
		} catch (error) {
			lastError = "durable-archive-load:" + String(error && error.message || error);
			return null;
		}
	}

	function persistLocalRecords() {
		if (!accountId) return false;
		try {
			window.localStorage.setItem(storageKey(accountId), JSON.stringify(records));
			window.localStorage.setItem(userExcludedMidsStorageKey(accountId), JSON.stringify(Array.from(userExcludedMids)));
			return true;
		} catch (error) {
			lastError = "archive-save:" + String(error && error.message || error);
			return false;
		}
	}

	function persistLocalCross() {
		if (!accountId) return false;
		try {
			for (const record of crossRecords) {
				if (!record.claimAttempts || !record.claimAttempts.length) continue;
				const key = crossRecordKey(record.originAccountId, record.mid);
				crossAttemptLedger[key] = cloneJson(record.claimAttempts[record.claimAttempts.length - 1], record.claimAttempts[record.claimAttempts.length - 1]);
			}
			if (crossRecords.length) window.localStorage.setItem(crossStorageKey(accountId), JSON.stringify(crossRecords));
			else window.localStorage.removeItem(crossStorageKey(accountId));
			if (Object.keys(crossAttemptLedger).length) window.localStorage.setItem(crossLedgerStorageKey(accountId), JSON.stringify(crossAttemptLedger));
			else window.localStorage.removeItem(crossLedgerStorageKey(accountId));
			return true;
		} catch (error) {
			lastError = "cross-archive-save:" + String(error && error.message || error);
			return false;
		}
	}

	function persistDurableStore() {
		if (!accountId) return false;
		const bridge = getDurableStoreBridge();
		if (!bridge) return true;
		try {
			// Keep the bounded MID probe ledger in the same durable JSON without
			// mixing probe candidates into the normal auto-claim whitelist.
			const preserved = {};
			try {
				const current = bridge.readMailArchiveStore(accountId);
				const currentData = current && current.ok === true && current.found ? current.data : null;
				if (currentData && Array.isArray(currentData.probeCandidates)) preserved.probeCandidates = cloneJson(currentData.probeCandidates, []);
				if (currentData && currentData.probeState && typeof currentData.probeState === "object") preserved.probeState = cloneJson(currentData.probeState, {});
			} catch (error) {}
			const response = bridge.writeMailArchiveStore(accountId, {
				accountId: accountId,
				records: durableWhitelistRecords(),
				userExcludedMids: Array.from(userExcludedMids),
				crossRecords: [],
				crossAttemptLedger: {},
				...preserved
			});
			if (!response || response.ok !== true) {
				lastError = "durable-archive-save:" + String(response && response.error || "bridge-write-failed");
				return false;
			}
			lastDurableSaveAt = Number(response.savedAt) || Date.now();
			durableStoreLoaded = true;
			return true;
		} catch (error) {
			lastError = "durable-archive-save:" + String(error && error.message || error);
			return false;
		}
	}

	function loadAccount(nextAccountId) {
		if (accountId && accountId !== nextAccountId) {
			for (const record of records.concat(crossRecords)) {
				for (const attempt of record.claimAttempts || []) {
					if (attempt.state !== "waiting-response") continue;
					attempt.state = "stopped:account-changed";
					record.lastClaimResult = attempt.state;
					const timeoutId = pendingTimeouts.get(attempt.id);
					if (timeoutId) window.clearTimeout(timeoutId);
					pendingTimeouts.delete(attempt.id);
				}
			}
			removeAllClaimProtocolListeners("account-changed");
			persistAll();
		}
		accountId = nextAccountId;
		autoGiftSessionAccountId = nextAccountId;
		autoGiftProcessedMids = new Set();
		autoGiftRunResults = [];
		autoGiftPendingEntries = [];
		autoGiftProcessedThisRun = 0;
		autoGiftFinalizedResult = null;
		autoGiftDeferFinalWait = false;
		autoGiftFinalWaitTimedOut = false;
		autoGiftCurrentMid = "";
		autoGiftCompletedCount = 0;
		autoGiftFailedCount = 0;
		autoGiftEnabled = false;
		try { window.localStorage.setItem(autoGiftEnabledStorageKey(accountId), "false"); } catch (error) {}
		lastAutoGiftResult = "waiting:after-live-mail";
		records = [];
		userExcludedMids = new Set();
		crossRecords = [];
		crossAttemptLedger = {};
		durableStoreLoaded = false;
		try {
			const parsed = JSON.parse(window.localStorage.getItem(storageKey(accountId)) || "[]");
			if (Array.isArray(parsed)) records = parsed.filter(record => record && String(record.accountId) === accountId);
		} catch (error) {
			lastError = "archive-load:" + String(error && error.message || error);
		}
		try {
			const parsed = JSON.parse(window.localStorage.getItem(userExcludedMidsStorageKey(accountId)) || "[]");
			if (Array.isArray(parsed)) userExcludedMids = new Set(parsed.map(normalizeArchiveMid).filter(Boolean).slice(0, 500));
		} catch (error) {
			lastError = "excluded-mids-load:" + String(error && error.message || error);
		}
		try {
			const parsed = JSON.parse(window.localStorage.getItem(crossStorageKey(accountId)) || "[]");
			if (Array.isArray(parsed)) {
				crossRecords = parsed.filter(record => record && String(record.importedIntoAccountId) === accountId && String(record.originAccountId) !== accountId);
			}
		} catch (error) {
			lastError = "cross-archive-load:" + String(error && error.message || error);
		}
		try {
			const parsed = JSON.parse(window.localStorage.getItem(crossLedgerStorageKey(accountId)) || "{}");
			if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) crossAttemptLedger = parsed;
		} catch (error) {
			lastError = "cross-ledger-load:" + String(error && error.message || error);
		}
		const durableAccount = readDurableAccount(accountId);
		if (durableAccount) {
			records = Array.isArray(durableAccount.records)
				? durableAccount.records.filter(record => record && String(record.accountId) === accountId)
				: [];
			crossRecords = Array.isArray(durableAccount.crossRecords)
				? durableAccount.crossRecords.filter(record => record && String(record.importedIntoAccountId) === accountId && String(record.originAccountId) !== accountId)
				: [];
			crossAttemptLedger = durableAccount.crossAttemptLedger &&
				typeof durableAccount.crossAttemptLedger === "object" &&
				!Array.isArray(durableAccount.crossAttemptLedger)
				? durableAccount.crossAttemptLedger
				: {};
			if (Array.isArray(durableAccount.userExcludedMids)) {
				userExcludedMids = new Set(durableAccount.userExcludedMids.map(normalizeArchiveMid).filter(Boolean).slice(0, 500));
			}
			lastDurableSaveAt = Number(durableAccount.savedAt) || 0;
		}
		records = records.filter(record => record && !isArchiveMidSuppressed(accountId, record.mid));
		applyOneTimeDurableCompactMigration(accountId);
		for (const record of records) {
			if (!Array.isArray(record.claimAttempts)) record.claimAttempts = [];
			record.lastConfirmedSuccessAttempt = latestExplicitSuccessAttempt(record);
			record.presentInLiveList = false;
		}
		for (const record of crossRecords) {
			if (!Array.isArray(record.claimAttempts)) record.claimAttempts = [];
			const ledgerAttempt = crossAttemptLedger[crossRecordKey(record.originAccountId, record.mid)];
			if (!record.claimAttempts.length && ledgerAttempt) {
				record.claimAttempts = [cloneJson(ledgerAttempt, ledgerAttempt)];
				record.lastClaimResult = record.claimAttempts[0].state || "attempt-recorded";
			}
		}
		rebuildRecordIndex();
		rebuildCrossRecordIndex();
		archiveCount = records.length;
		// 首次升级时把已有 localStorage 归档迁移进微端专用文件；以后则以专用文件为准并同步页面缓存。
		persistAll();
	}

	function persist() {
		const localSaved = persistLocalRecords();
		const durableSaved = persistDurableStore();
		return localSaved && durableSaved;
	}

	function persistCross() {
		const localSaved = persistLocalCross();
		const durableSaved = persistDurableStore();
		return localSaved && durableSaved;
	}

	function persistAll() {
		const recordsSaved = persistLocalRecords();
		const crossSaved = persistLocalCross();
		const durableSaved = persistDurableStore();
		return recordsSaved && crossSaved && durableSaved;
	}

	function asArray(value) {
		if (Array.isArray(value)) return value.slice();
		if (value == null) return [];
		return [value];
	}

	function readAttachmentField(attachment, key) {
		if (!attachment) return [];
		try {
			if (typeof attachment.getStringKey === "function") return asArray(attachment.getStringKey(key));
			if (typeof attachment.get === "function") return asArray(attachment.get(key));
			return asArray(attachment[key]);
		} catch (error) {
			return [];
		}
	}

	function getAttachmentType(mail) {
		const direct = Number(mail && mail.AttachmentType);
		if (Number.isFinite(direct) && direct > 0) return direct;
		const values = readAttachmentField(mail && mail.attachment, "type");
		return Number(values[0]) || 0;
	}

	function mailHasAttachment(mail) {
		if (!mail) return false;
		if (mail.hasAttachMent || mail.hasAttachment || mail.HasAttachment) return true;
		if (getAttachmentType(mail) > 0) return true;
		return ["id", "key"].some(field => readAttachmentField(mail.attachment, field).some(value => value != null && String(value) !== ""));
	}

	function getClaimRoute(attachmentType) {
		if (attachmentType === GIFT_ATTACHMENT) return "single-gift";
		if (attachmentType === ITEM_ATTACHMENT) return "dbs-item";
		return "unsupported";
	}

	function autoWhitelistLiveRecord(record, mail, now) {
		if (!record || !mail || record.presentInLiveList !== true) return false;
		if (!mailHasAttachment(mail)) return false;
		if (!["single-gift", "dbs-item"].includes(record.claimRoute)) return false;
		if (record.jsonAutoClaim === true) return false;
		record.jsonAutoClaim = true;
		record.hasAttachment = true;
		record.autoWhitelistSource = "live-scan";
		record.autoWhitelistedAt = Number(record.autoWhitelistedAt) || Number(now) || Date.now();
		return true;
	}

	function sanitizeImportedArray(value) {
		return asArray(value).slice(0, 100).map(item => {
			if (item == null || ["string", "number", "boolean"].includes(typeof item)) return item;
			return String(item);
		});
	}

	function sanitizeClaimAttempts(value, limit) {
		if (!Array.isArray(value)) return [];
		return value.slice(-Math.max(1, limit || MAX_ATTEMPTS_PER_MAIL)).map(attempt => cloneJson(attempt, null)).filter(Boolean);
	}

	function sanitizeLocalArchiveRecord(source, targetAccountId) {
		if (!source || source.mid == null || String(source.accountId || "") !== targetAccountId) return null;
		const attachment = source.attachment || {};
		const attachmentType = Number(source.attachmentType || sanitizeImportedArray(attachment.type)[0]) || 0;
		const attempts = sanitizeClaimAttempts(source.claimAttempts, MAX_ATTEMPTS_PER_MAIL);
		return {
			version: 1,
			accountId: targetAccountId,
			mid: String(source.mid),
			category: source.category === "friend" ? "friend" : "system",
			title: String(source.title || "未命名邮件"),
			content: String(source.content || ""),
			type: Number(source.type) || 0,
			fromUserName: String(source.fromUserName || ""),
			sendtime: Number(source.sendtime) || 0,
			originalEndtime: Number(source.originalEndtime) || 0,
			capturedAt: Number(source.capturedAt) || Date.now(),
			lastSeenAt: Number(source.lastSeenAt) || 0,
			presentInLiveList: false,
			jsonAutoClaim: true,
			autoWhitelistSource: String(source.autoWhitelistSource || "").slice(0, 64),
			autoWhitelistedAt: Number(source.autoWhitelistedAt) || 0,
			hasAttachment: Boolean(source.hasAttachment || source.attachment),
			getedAtCapture: Boolean(source.getedAtCapture),
			lastKnownGeted: Boolean(source.lastKnownGeted),
			lastConfirmedSuccessAttempt: latestExplicitSuccessAttempt(source),
			attachmentType: attachmentType,
			attachment: {
				id: sanitizeImportedArray(attachment.id),
				ctn: sanitizeImportedArray(attachment.ctn),
				key: sanitizeImportedArray(attachment.key),
				type: sanitizeImportedArray(attachment.type),
				opt: sanitizeImportedArray(attachment.opt)
			},
			claimRoute: getClaimRoute(attachmentType),
			claimAttempts: attempts,
			lastClaimResult: String(source.lastClaimResult || (attempts.length ? attempts[attempts.length - 1].state : "never-requested"))
		};
	}

	function sanitizeCrossRecord(source, originAccountId, importedIntoAccountId, importedAt, sourceExportedAt) {
		if (!source || source.mid == null || String(source.accountId || "") !== originAccountId) return null;
		const attachment = source.attachment || {};
		const attachmentType = Number(source.attachmentType || sanitizeImportedArray(attachment.type)[0]) || 0;
		return {
			version: 1,
			crossAccountTest: true,
			originAccountId: originAccountId,
			importedIntoAccountId: importedIntoAccountId,
			importedAt: importedAt,
			sourceExportedAt: Number(sourceExportedAt) || 0,
			accountId: originAccountId,
			mid: String(source.mid),
			category: source.category === "friend" ? "friend" : "system",
			title: String(source.title || "未命名邮件"),
			content: String(source.content || ""),
			type: Number(source.type) || 0,
			fromUserName: String(source.fromUserName || ""),
			sendtime: Number(source.sendtime) || 0,
			originalEndtime: Number(source.originalEndtime) || 0,
			capturedAt: Number(source.capturedAt) || 0,
			hasAttachment: Boolean(source.hasAttachment || source.attachment),
			getedAtCapture: Boolean(source.getedAtCapture),
			lastKnownGeted: Boolean(source.lastKnownGeted),
			attachmentType: attachmentType,
			attachment: {
				id: sanitizeImportedArray(attachment.id),
				ctn: sanitizeImportedArray(attachment.ctn),
				key: sanitizeImportedArray(attachment.key),
				type: sanitizeImportedArray(attachment.type),
				opt: sanitizeImportedArray(attachment.opt)
			},
			claimRoute: getClaimRoute(attachmentType),
			sourceClaimAttemptCount: Array.isArray(source.claimAttempts) ? source.claimAttempts.length : 0,
			claimAttempts: [],
			lastClaimResult: "never-requested"
		};
	}

	function mergeAttemptLists(current, incoming, limit) {
		const byId = new Map();
		for (const attempt of (current || []).concat(incoming || [])) {
			if (!attempt) continue;
			const key = String(attempt.id || [attempt.route, attempt.requestedAt, attempt.state].join(":"));
			byId.set(key, attempt);
		}
		return Array.from(byId.values())
			.sort((a, b) => Number(a.requestedAt || 0) - Number(b.requestedAt || 0))
			.slice(-Math.max(1, limit || MAX_ATTEMPTS_PER_MAIL));
	}

	function importSameAccountBackup(input) {
		if (!resolveRuntimeObjects()) throw new Error(lastResult);
		const detected = detectAccountId();
		if (!detected) throw new Error("current-account-unavailable");
		if (detected !== accountId) loadAccount(detected);
		let payload = input;
		if (typeof payload === "string") {
			try { payload = JSON.parse(payload); } catch (error) { throw new Error("invalid-json"); }
		}
		if (!payload || typeof payload !== "object" || !Array.isArray(payload.records)) throw new Error("invalid-archive-format");
		const backupAccountId = String(payload.accountId || "").trim();
		if (!backupAccountId) throw new Error("missing-backup-account-id");
		if (backupAccountId !== accountId) throw new Error("backup-account-mismatch:" + backupAccountId + "->" + accountId);
		if (payload.records.length > MAX_CROSS_IMPORT_RECORDS) throw new Error("too-many-records:" + payload.records.length);

		let previousWhitelistDisabledCount = 0;
		for (const record of records) {
			if (!record || record.jsonAutoClaim !== true) continue;
			record.jsonAutoClaim = false;
			previousWhitelistDisabledCount += 1;
		}
		let localImportedCount = 0;
		let localMergedCount = 0;
		let restoredTombstoneCount = 0;
		let skippedCount = 0;
		for (const source of payload.records) {
			const incoming = sanitizeLocalArchiveRecord(source, accountId);
			if (!incoming || !incoming.hasAttachment) {
				skippedCount += 1;
				continue;
			}
			// “导入本账号 JSON”是用户主动恢复操作：允许恢复用户自己删除过的 MID；
			// 内置固定排除项仍继续生效，自动扫描也仍受墓碑保护。
			if (userExcludedMids.delete(incoming.mid)) restoredTombstoneCount += 1;
			if (isArchiveMidSuppressed(accountId, incoming.mid)) {
				skippedCount += 1;
				continue;
			}
			const existing = recordsByMid.get(incoming.mid);
			if (!existing) {
				records.push(incoming);
				recordsByMid.set(incoming.mid, incoming);
				localImportedCount += 1;
				continue;
			}
			existing.claimAttempts = mergeAttemptLists(existing.claimAttempts, incoming.claimAttempts, MAX_ATTEMPTS_PER_MAIL);
			if ((!existing.attachment || !existing.attachment.key || !existing.attachment.key.length) && incoming.attachment.key.length) {
				existing.attachment = incoming.attachment;
				existing.attachmentType = incoming.attachmentType;
				existing.claimRoute = incoming.claimRoute;
			}
			if (!existing.originalEndtime) existing.originalEndtime = incoming.originalEndtime;
			if (!existing.capturedAt || incoming.capturedAt < existing.capturedAt) existing.capturedAt = incoming.capturedAt;
			if (!existing.presentInLiveList) existing.lastKnownGeted = incoming.lastKnownGeted;
			existing.jsonAutoClaim = true;
			if (existing.claimAttempts.length) existing.lastClaimResult = existing.claimAttempts[existing.claimAttempts.length - 1].state || incoming.lastClaimResult;
			localMergedCount += 1;
		}

		let crossImportedCount = 0;
		for (const source of Array.isArray(payload.crossAccountTests) ? payload.crossAccountTests.slice(0, MAX_CROSS_IMPORT_RECORDS) : []) {
			const originAccountId = String(source && source.originAccountId || "").trim();
			if (!originAccountId || originAccountId === accountId || String(source.importedIntoAccountId || "") !== accountId) {
				skippedCount += 1;
				continue;
			}
			const key = crossRecordKey(originAccountId, source.mid);
			const incoming = sanitizeCrossRecord(source, originAccountId, accountId, Number(source.importedAt) || Date.now(), source.sourceExportedAt);
			if (!incoming) {
				skippedCount += 1;
				continue;
			}
			incoming.claimAttempts = sanitizeClaimAttempts(source.claimAttempts, 1);
			incoming.lastClaimResult = String(source.lastClaimResult || (incoming.claimAttempts.length ? incoming.claimAttempts[0].state : "never-requested"));
			const existing = crossRecordsByKey.get(key);
			if (!existing) {
				crossRecords.push(incoming);
				crossRecordsByKey.set(key, incoming);
				crossImportedCount += 1;
			} else if (!existing.claimAttempts.length && incoming.claimAttempts.length) {
				existing.claimAttempts = incoming.claimAttempts;
				existing.lastClaimResult = incoming.lastClaimResult;
			}
		}

		const importedLedger = payload.crossAccountAttemptLedger;
		if (importedLedger && typeof importedLedger === "object" && !Array.isArray(importedLedger)) {
			for (const [key, attempt] of Object.entries(importedLedger)) {
				if (!attempt || String(attempt.currentAccountId || "") !== accountId || String(attempt.originAccountId || "") === accountId) continue;
				if (!crossAttemptLedger[key]) crossAttemptLedger[key] = cloneJson(attempt, attempt);
			}
		}
		for (const record of crossRecords) {
			const ledgerAttempt = crossAttemptLedger[crossRecordKey(record.originAccountId, record.mid)];
			if (!record.claimAttempts.length && ledgerAttempt) {
				record.claimAttempts = [cloneJson(ledgerAttempt, ledgerAttempt)];
				record.lastClaimResult = record.claimAttempts[0].state || "attempt-recorded";
			}
		}

		archiveCount = records.length;
		persistAll();
		const jsonWhitelistCount = records.filter(record => record && record.jsonAutoClaim === true).length;
		lastResult = "json-whitelist-replaced:" + jsonWhitelistCount + ",imported:" + localImportedCount + ",merged:" + localMergedCount + ",restored-tombstones:" + restoredTombstoneCount + ",skipped:" + skippedCount;
		renderPanel();
		return { accountId, localImportedCount, localMergedCount, crossImportedCount, skippedCount, jsonWhitelistCount, previousWhitelistDisabledCount, restoredTombstoneCount };
	}

	function importCrossAccountArchive(input) {
		if (!resolveRuntimeObjects()) throw new Error(lastResult);
		const detected = detectAccountId();
		if (!detected) throw new Error("current-account-unavailable");
		if (detected !== accountId) loadAccount(detected);
		let payload = input;
		if (typeof payload === "string") {
			try { payload = JSON.parse(payload); } catch (error) { throw new Error("invalid-json"); }
		}
		if (!payload || typeof payload !== "object" || !Array.isArray(payload.records)) throw new Error("invalid-archive-format");
		const originAccountId = String(payload.accountId || "").trim();
		if (!originAccountId) throw new Error("missing-origin-account-id");
		if (originAccountId === accountId) throw new Error("origin-and-current-account-must-differ");
		if (payload.records.length > MAX_CROSS_IMPORT_RECORDS) throw new Error("too-many-records:" + payload.records.length);

		const importedAt = Date.now();
		let importedCount = 0;
		let duplicateCount = 0;
		let skippedCount = 0;
		for (const source of payload.records) {
			const record = sanitizeCrossRecord(source, originAccountId, accountId, importedAt, payload.exportedAt);
			if (!record || !record.hasAttachment) {
				skippedCount += 1;
				continue;
			}
			const key = crossRecordKey(originAccountId, record.mid);
			if (crossRecordsByKey.has(key)) {
				duplicateCount += 1;
				continue;
			}
			if (crossAttemptLedger[key]) {
				record.claimAttempts = [cloneJson(crossAttemptLedger[key], crossAttemptLedger[key])];
				record.lastClaimResult = record.claimAttempts[0].state || "attempt-recorded";
			}
			crossRecords.push(record);
			crossRecordsByKey.set(key, record);
			importedCount += 1;
		}
		persistCross();
		lastResult = "cross-imported:" + importedCount;
		renderPanel();
		return { originAccountId, currentAccountId: accountId, importedCount, duplicateCount, skippedCount };
	}

	function getMailLists() {
		if (!mailManager) return { system: [], friend: [] };
		let system = [];
		let friend = [];
		try {
			system = typeof mailManager.GetSystemMailList === "function" ? mailManager.GetSystemMailList() : mailManager.systemMailList;
			friend = typeof mailManager.GetFriendMailList === "function" ? mailManager.GetFriendMailList() : mailManager.friendMailList;
		} catch (error) {
			lastError = "mail-list:" + String(error && error.message || error);
		}
		return {
			system: Array.isArray(system) ? system : [],
			friend: Array.isArray(friend) ? friend : []
		};
	}

	function getServerNow() {
		for (const field of ["LocalServerTime", "ServerTime"]) {
			try {
				const value = Number(timerManager && timerManager[field]);
				if (Number.isFinite(value) && value > 0) return Math.floor(value);
			} catch (error) {}
		}
		return Math.floor(Date.now() / 1000);
	}

	function createArchiveRecord(mail, category, now) {
		const attachmentType = getAttachmentType(mail);
		return {
			version: 1,
			accountId: accountId,
			mid: String(mail.mid),
			category: category,
			title: String(mail.title || "未命名邮件"),
			content: String(mail.content || ""),
			type: Number(mail.type) || 0,
			fromUserName: String(mail.fromUserName || ""),
			sendtime: Number(mail.sendtime) || 0,
			originalEndtime: Number(mail.endtime) || 0,
			capturedAt: now,
			lastSeenAt: now,
			presentInLiveList: true,
			jsonAutoClaim: false,
			autoWhitelistSource: "",
			autoWhitelistedAt: 0,
			hasAttachment: mailHasAttachment(mail),
			getedAtCapture: Boolean(mail.Geted),
			lastKnownGeted: Boolean(mail.Geted),
			lastConfirmedSuccessAttempt: null,
			attachmentType: attachmentType,
			attachment: {
				id: readAttachmentField(mail.attachment, "id"),
				ctn: readAttachmentField(mail.attachment, "ctn"),
				key: readAttachmentField(mail.attachment, "key"),
				type: readAttachmentField(mail.attachment, "type"),
				opt: readAttachmentField(mail.attachment, "opt")
			},
			claimRoute: getClaimRoute(attachmentType),
			claimAttempts: [],
			lastClaimResult: "never-requested"
		};
	}

	function updateArchiveRecord(record, mail, category, now) {
		let changed = false;
		if (now - Number(record.lastSeenAt || 0) >= LAST_SEEN_PERSIST_INTERVAL_MS) {
			record.lastSeenAt = now;
			changed = true;
		}
		if (!record.presentInLiveList) {
			record.presentInLiveList = true;
			changed = true;
		}
		if (record.category !== category) {
			record.category = category;
			changed = true;
		}
		if (record.lastKnownGeted !== Boolean(mail.Geted)) {
			record.lastKnownGeted = Boolean(mail.Geted);
			changed = true;
		}
		if (!record.title && mail.title) { record.title = String(mail.title); changed = true; }
		if (!record.content && mail.content) { record.content = String(mail.content); changed = true; }
		if (!record.originalEndtime) { record.originalEndtime = Number(mail.endtime) || 0; changed = true; }
		if (!record.sendtime) { record.sendtime = Number(mail.sendtime) || 0; changed = true; }
		if (!record.fromUserName && mail.fromUserName) { record.fromUserName = String(mail.fromUserName); changed = true; }
		if (!record.attachment || !record.attachment.key || !record.attachment.key.length) {
			const fresh = createArchiveRecord(mail, category, now);
			record.attachment = fresh.attachment;
			record.attachmentType = fresh.attachmentType;
			record.claimRoute = fresh.claimRoute;
			changed = true;
		}
		return changed;
	}

	function archiveLoadedMails() {
		if (!accountId || !mailManager) return 0;
		const lists = getMailLists();
		const now = Date.now();
		let added = 0;
		let changed = false;
		liveMailsByMid = new Map();
		const seenAttachmentMids = new Set();

		for (const entry of [
			{ category: "system", mails: lists.system },
			{ category: "friend", mails: lists.friend }
		]) {
			for (const mail of entry.mails) {
				if (!mail || mail.mid == null) continue;
				const mid = String(mail.mid);
				liveMailsByMid.set(mid, mail);
				if (isArchiveMidSuppressed(accountId, mid)) continue;
				if (!mailHasAttachment(mail)) continue;
				seenAttachmentMids.add(mid);
				let record = recordsByMid.get(mid);
				if (!record) {
					record = createArchiveRecord(mail, entry.category, now);
					records.push(record);
					recordsByMid.set(mid, record);
					added += 1;
					changed = true;
				} else {
					changed = updateArchiveRecord(record, mail, entry.category, now) || changed;
				}
				changed = autoWhitelistLiveRecord(record, mail, now) || changed;
			}
		}
		for (const record of records) {
			if (!seenAttachmentMids.has(record.mid) && record.presentInLiveList) {
				record.presentInLiveList = false;
				changed = true;
			}
		}

		archiveCount = records.length;
		if (changed) persist();
		lastResult = added ? "archived:" + added : "ready:no-new-attachment-mail";
		return added;
	}

	function ensureArchiveAccountReady() {
		if (!resolveRuntimeObjects()) throw new Error(lastResult || "runtime-not-ready");
		const detected = detectAccountId();
		if (!detected) throw new Error("current-account-unavailable");
		if (detected !== accountId) loadAccount(detected);
		return detected;
	}

	function normalizeManualAttachmentId(value) {
		const text = String(value == null ? "" : value).trim();
		if (!/^\d{1,16}$/.test(text) || Number(text) <= 0 || !Number.isSafeInteger(Number(text))) return 0;
		return Number(text);
	}

	function upsertManualArchiveRecord(input) {
		ensureArchiveAccountReady();
		const source = input && typeof input === "object" ? input : {};
		const mid = normalizeArchiveMid(source.mid);
		if (!mid) throw new Error("MID 必须是 1～32 位数字");
		const title = String(source.title || source.name || "").trim().slice(0, 100);
		if (!title) throw new Error("请填写邮件名称");
		const attachmentType = Number(source.attachmentType) === ITEM_ATTACHMENT ? ITEM_ATTACHMENT : GIFT_ATTACHMENT;
		const attachmentId = normalizeManualAttachmentId(source.giftId != null ? source.giftId : source.attachmentId);
		if (!attachmentId) throw new Error(attachmentType === GIFT_ATTACHMENT ? "请填写有效 GiftID" : "请填写有效道具 ID");
		const count = Math.max(1, Math.min(999999, Math.floor(Number(source.count) || 1)));
		const verificationKey = String(source.key || "").trim().slice(0, 256);
		if (attachmentType === ITEM_ATTACHMENT && !verificationKey) throw new Error("道具附件必须填写验证码 Key");
		const now = Date.now();
		let record = recordsByMid.get(mid);
		const created = !record;
		if (!record) {
			record = {
				version: 1,
				accountId: accountId,
				mid: mid,
				category: "system",
				content: "",
				type: 3,
				fromUserName: "",
				sendtime: Math.floor(now / 1000),
				originalEndtime: 0,
				capturedAt: now,
				lastSeenAt: 0,
				presentInLiveList: false,
				getedAtCapture: false,
				lastKnownGeted: false,
				lastConfirmedSuccessAttempt: null,
				claimAttempts: [],
				lastClaimResult: "never-requested"
			};
			records.push(record);
			recordsByMid.set(mid, record);
		}
		record.title = title;
		record.content = String(source.content || record.content || "").slice(0, 2000);
		record.attachmentType = attachmentType;
		record.attachment = {
			id: [attachmentId],
			ctn: [count],
			key: verificationKey ? [verificationKey] : [],
			type: [attachmentType],
			opt: []
		};
		record.claimRoute = getClaimRoute(attachmentType);
		record.hasAttachment = true;
		record.jsonAutoClaim = true;
		record.autoWhitelistSource = "manual-ui";
		record.autoWhitelistedAt = Number(record.autoWhitelistedAt) || now;
		record.manualUpdatedAt = now;
		userExcludedMids.delete(mid);
		archiveCount = records.length;
		persistAll();
		lastResult = (created ? "manual-added:" : "manual-updated:") + mid;
		renderPanel();
		return { created: created, accountId: accountId, record: cloneJson(record, {}) };
	}

	function removeArchiveRecord(mid, options) {
		options = options || {};
		ensureArchiveAccountReady();
		const normalized = normalizeArchiveMid(mid);
		if (!normalized) throw new Error("invalid-mid");
		const record = recordsByMid.get(normalized);
		if (!record) return { removed: false, mid: normalized, reason: "not-found" };
		if ((record.claimAttempts || []).some(attempt => attempt && attempt.state === "waiting-response")) {
			throw new Error("该邮件仍在等待服务器回包，暂不能删除");
		}
		// 微端会拦截原生 window.confirm 并把提示堆成页面横幅。交互确认由邮件库卡片完成；
		// 其他调用者必须显式传入 skipConfirmation，避免任何隐式删除。
		if (!options.skipConfirmation) return { removed: false, mid: normalized, reason: "confirmation-required" };
		records = records.filter(item => item && String(item.mid) !== normalized);
		if (options.suppressFromScan === false) userExcludedMids.delete(normalized);
		else userExcludedMids.add(normalized);
		rebuildRecordIndex();
		archiveCount = records.length;
		persistAll();
		lastResult = "manual-removed:" + normalized;
		renderPanel();
		return { removed: true, mid: normalized, suppressedFromScan: options.suppressFromScan !== false };
	}

	function scanCurrentAttachmentMails() {
		ensureArchiveAccountReady();
		const beforeMids = new Set(records.map(record => String(record && record.mid || "")));
		const lists = getMailLists();
		const visibleAttachmentMails = lists.system.concat(lists.friend).filter(mail => mail && mail.mid != null && mailHasAttachment(mail));
		archiveLoadedMails();
		const addedMids = records.map(record => String(record && record.mid || "")).filter(mid => mid && !beforeMids.has(mid));
		lastResult = "manual-scan:visible-" + visibleAttachmentMails.length + ",added-" + addedMids.length;
		renderPanel();
		return {
			accountId: accountId,
			visibleMailCount: lists.system.length + lists.friend.length,
			visibleAttachmentCount: visibleAttachmentMails.length,
			addedCount: addedMids.length,
			addedMids: addedMids,
			recordCount: records.length,
			excludedMids: Array.from(userExcludedMids)
		};
	}

	function requestMailRefreshAndArchive() {
		if (manualRefreshPending) return manualRefreshPromise;
		if (stopped) return Promise.reject(new Error("script-stopped"));
		scan(false);
		if (!mailManager || typeof mailManager.GetMessages !== "function") {
			lastResult = "error:mail-refresh-unavailable";
			renderPanel();
			return Promise.resolve({ requested: false, added: 0, reason: "GetMessages-unavailable" });
		}

		const refreshAccountId = accountId;
		const beforeCount = records.length;
		manualRefreshPending = true;
		manualRefreshCount += 1;
		lastManualRefreshAt = Date.now();
		lastResult = "refreshing:mail-list";
		renderPanel();
		try {
			mailManager.GetMessages();
		} catch (error) {
			manualRefreshPending = false;
			lastError = String(error && error.message || error);
			lastResult = "error:mail-refresh:" + lastError;
			renderPanel();
			return Promise.reject(error);
		}

		const delays = Array.from(new Set(MANUAL_REFRESH_DELAYS_MS
			.map(value => Math.max(0, Number(value) || 0))))
			.sort((a, b) => a - b);
		if (!delays.length) delays.push(0);
		manualRefreshPromise = new Promise(resolve => {
			for (const delay of delays) {
				const timerId = window.setTimeout(function rescanAfterMailRefresh() {
					manualRefreshTimers.delete(timerId);
					if (!stopped && accountId === refreshAccountId) archiveLoadedMails();
					if (delay !== delays[delays.length - 1]) {
						lastResult = "refreshing:mail-list";
						renderPanel();
						return;
					}
					manualRefreshPending = false;
					lastManualRefreshAdded = accountId === refreshAccountId ? Math.max(0, records.length - beforeCount) : 0;
					lastResult = accountId === refreshAccountId
						? "manual-refresh-complete:added-" + lastManualRefreshAdded
						: "manual-refresh-stopped:account-changed";
					manualRefreshPromise = null;
					renderPanel();
					resolve({ requested: true, added: lastManualRefreshAdded, accountId: refreshAccountId });
				}, delay);
				manualRefreshTimers.add(timerId);
			}
		});
		return manualRefreshPromise;
	}

	function pauseConflictingFeatures() {
		const autoApi = window.__H5_AUTO_CDK_REDEEMER__;
		if (window.__H5_MAIL_ARCHIVE_COMBINED_MODE__) {
			autoMailPaused = true;
			autoCdkPaused = false;
		}
		if (!autoMailPaused && autoApi && typeof autoApi.stop === "function") {
			try {
				autoApi.stop();
				autoMailPaused = true;
				autoCdkPaused = true;
			} catch (error) {
				lastError = "pause-auto-mail:" + String(error && error.message || error);
			}
		}

		const displayApi = window.__H5_MAIL_99_DAY_DISPLAY__;
		if (!display99Paused && displayApi) {
			try {
				if (typeof displayApi.restoreOriginal === "function") {
					displayApi.restoreOriginal();
					display99Restored = true;
				}
				if (typeof displayApi.stop === "function") {
					displayApi.stop();
					display99Paused = true;
				}
			} catch (error) {
				lastError = "pause-99-day-display:" + String(error && error.message || error);
			}
		}
		conflictPauseAttempted = true;
	}

	function resolveRuntimeObjects() {
		runtime = getRuntime();
		if (!runtime || typeof runtime.class !== "function") {
			lastResult = "waiting:runtime";
			return false;
		}
		mailManager = resolveSingleton(getClass("MailManager")) || mailManager;
		giftManager = resolveSingleton(getClass("GiftManager")) || giftManager;
		goodsManager = resolveSingleton(getClass("GameGoodsManager")) || goodsManager;
		timerManager = resolveSingleton(getClass("TimerManager")) || timerManager;
		if (!mailManager) {
			lastResult = "waiting:mail-manager";
			return false;
		}
		installResponseHooks();
		return true;
	}

	function protocolSnapshot(protocol) {
		if (!protocol || typeof protocol !== "object") return null;
		const result = {};
		for (const key of Object.keys(protocol)) {
			const value = protocol[key];
			if (value == null || ["string", "number", "boolean"].includes(typeof value)) result[key] = value;
			else if (Array.isArray(value)) result[key] = cloneJson(value, String(value));
		}
		return result;
	}

	function protocolIdentity(protocol) {
		const midValue = protocol && (protocol.mid != null
			? protocol.mid
			: (protocol.messid != null ? protocol.messid : (protocol.MID != null ? protocol.MID : protocol.Mid)));
		const giftIdValue = protocol && (protocol.GiftID != null ? protocol.GiftID : protocol.giftId);
		const giftId = Number(giftIdValue);
		return {
			mid: midValue == null ? "" : String(midValue),
			giftId: giftIdValue != null && Number.isFinite(giftId) ? giftId : null,
			cdKey: String(protocol && protocol.CDKey != null ? protocol.CDKey : "").trim()
		};
	}

	function countPendingSingleGiftAttempts(giftId) {
		let count = 0;
		for (const record of records.concat(crossRecords)) {
			for (const attempt of record.claimAttempts || []) {
				if (attempt.route !== "single-gift" || attempt.state !== "waiting-response") continue;
				if (Number(attempt.request && attempt.request.giftId) === Number(giftId)) count += 1;
			}
		}
		return count;
	}

	function matchSingleGiftProtocolResponse(record, attempt, protocol) {
		const actual = protocolIdentity(protocol);
		const expectedMid = String(record && record.mid || "");
		const expectedGiftId = Number(attempt && attempt.request && attempt.request.giftId);
		if (actual.mid) {
			if (actual.mid !== expectedMid) return { matched: false, reason: "mid-mismatch:" + actual.mid, ...actual };
			if (Number.isFinite(expectedGiftId) && actual.giftId != null && actual.giftId !== expectedGiftId) {
				return { matched: false, reason: "gift-id-mismatch:" + actual.giftId, ...actual };
			}
			return { matched: true, reason: "mid-match", ...actual };
		}
		if (actual.cdKey) return { matched: false, reason: "cdkey-response-without-mid", ...actual };
		if (Number.isFinite(expectedGiftId) && actual.giftId === expectedGiftId) {
			const sameGiftPending = countPendingSingleGiftAttempts(expectedGiftId);
			if (sameGiftPending === 1) return { matched: true, reason: "gift-id-fallback", ...actual };
			return { matched: false, reason: "missing-mid-ambiguous:" + sameGiftPending, ...actual };
		}
		return { matched: false, reason: actual.giftId == null ? "missing-mid-and-gift-id" : "gift-id-mismatch:" + actual.giftId, ...actual };
	}

	function removeClaimProtocolListener(attemptId, reason) {
		const entry = pendingProtocolListeners.get(String(attemptId || ""));
		if (!entry) return false;
		pendingProtocolListeners.delete(String(attemptId));
		try {
			entry.proxy.RemoveEventListener(entry.protocolId, entry.owner, entry.handler);
		} catch (error) {
			entry.diagnostic.removeError = String(error && error.message || error);
		}
		entry.diagnostic.active = false;
		entry.diagnostic.removedAt = Date.now();
		entry.diagnostic.removeReason = String(reason || "removed");
		return true;
	}

	function removeAllClaimProtocolListeners(reason) {
		for (const attemptId of Array.from(pendingProtocolListeners.keys())) {
			removeClaimProtocolListener(attemptId, reason);
		}
	}

	function installClaimProtocolListener(record, attempt) {
		const protocolId = attempt && attempt.route === "single-gift" ? SINGLE_GIFT_RESPONSE_PROTOCOL_ID : null;
		const diagnostic = {
			mode: protocolId ? "protocol-direct" : "legacy-fallback",
			protocolId: protocolId,
			supported: false,
			registered: false,
			active: false,
			registeredAt: 0,
			receivedCount: 0,
			unmatchedCount: 0,
			matchedAt: 0,
			matchReason: "",
			lastUnmatchedReason: "",
			lastReceivedMid: "",
			lastReceivedGiftId: null,
			lastReceivedResult: null,
			error: ""
		};
		attempt.responseListener = diagnostic;
		if (!protocolId) {
			diagnostic.error = "protocol-id-unresolved";
			return false;
		}
		let proxy = giftManager && giftManager.proxy;
		if (!proxy || typeof proxy.AddEventListener !== "function" || typeof proxy.RemoveEventListener !== "function") {
			proxy = getClass("ServerProxy");
		}
		if (!proxy || typeof proxy.AddEventListener !== "function" || typeof proxy.RemoveEventListener !== "function") {
			diagnostic.error = "server-proxy-listener-unavailable";
			return false;
		}
		diagnostic.supported = true;
		const owner = { __sgsolMailClaimAttemptId: attempt.id };
		const handler = function directClaimProtocolHandler(packet) {
			if (attempt.state !== "waiting-response") {
				removeClaimProtocolListener(attempt.id, "attempt-no-longer-pending");
				return;
			}
			const protocol = packet && packet.Protocol || packet || null;
			if (!protocol || typeof protocol !== "object") return;
			diagnostic.receivedCount += 1;
			diagnostic.lastReceivedAt = Date.now();
			const match = matchSingleGiftProtocolResponse(record, attempt, protocol);
			diagnostic.lastReceivedMid = match.mid;
			diagnostic.lastReceivedGiftId = match.giftId;
			const receivedResult = Number(protocol.Result);
			diagnostic.lastReceivedResult = Number.isFinite(receivedResult) ? receivedResult : null;
			if (!match.matched) {
				diagnostic.unmatchedCount += 1;
				diagnostic.lastUnmatchedReason = match.reason;
				return;
			}
			diagnostic.matchedAt = Date.now();
			diagnostic.matchReason = match.reason;
			recordNativeResponse("single-gift", packet, {
				source: "protocol-direct",
				protocolId: protocolId,
				record: record,
				attempt: attempt
			});
		};
		try {
			proxy.AddEventListener(protocolId, owner, handler);
			diagnostic.registered = true;
			diagnostic.active = true;
			diagnostic.registeredAt = Date.now();
			pendingProtocolListeners.set(attempt.id, { proxy, protocolId, owner, handler, diagnostic });
			return true;
		} catch (error) {
			diagnostic.error = String(error && error.message || error);
			return false;
		}
	}

	function responseVerdict(route, resultCode) {
		if (route === "dbs-item") {
			if (resultCode === 0) return "server-accepted";
			if (resultCode === 2) return "server-reported-already-handled";
			return "server-rejected:" + resultCode;
		}
		if (route === "single-gift") {
			if (resultCode === 1 || resultCode === 2) return "server-accepted";
			if (resultCode === 15) return "server-reported-already-claimed";
			return "server-rejected:" + resultCode;
		}
		return "server-response:" + resultCode;
	}

	function findPendingAttempt(route, mid) {
		const normalizedMid = mid == null ? "" : String(mid);
		const candidates = [];
		for (const record of records.concat(crossRecords)) {
			if (normalizedMid && record.mid !== normalizedMid) continue;
			for (let index = record.claimAttempts.length - 1; index >= 0; index -= 1) {
				const attempt = record.claimAttempts[index];
				if (attempt.route === route && attempt.state === "waiting-response") {
					candidates.push({ record: record, attempt: attempt });
					break;
				}
			}
		}
		candidates.sort((a, b) => Number(b.attempt.requestedAt) - Number(a.attempt.requestedAt));
		if (normalizedMid) return candidates[0] || null;
		return candidates.length === 1 ? candidates[0] : null;
	}

	function recordNativeResponse(route, packet, capture) {
		const protocol = packet && packet.Protocol || packet || null;
		const mid = protocol && (protocol.mid != null ? protocol.mid : protocol.messid);
		const directRecord = capture && capture.record;
		const directAttempt = capture && capture.attempt;
		const pending = directRecord && directAttempt && directAttempt.route === route && directAttempt.state === "waiting-response"
			? { record: directRecord, attempt: directAttempt }
			: findPendingAttempt(route, mid);
		if (!pending) return false;
		const resultCode = Number(route === "single-gift" ? protocol && protocol.Result : protocol && protocol.result);
		const { record, attempt } = pending;
		attempt.respondedAt = Date.now();
		attempt.responseMs = attempt.respondedAt - Number(attempt.sentAt || attempt.requestedAt);
		attempt.resultCode = Number.isFinite(resultCode) ? resultCode : null;
		attempt.response = protocolSnapshot(protocol);
		attempt.responseCaptureSource = String(capture && capture.source || "legacy-manager-hook");
		attempt.responseProtocolId = capture && capture.protocolId != null && Number.isFinite(Number(capture.protocolId)) ? Number(capture.protocolId) : null;
		const identity = protocolIdentity(protocol);
		attempt.responseMid = identity.mid;
		attempt.responseGiftId = identity.giftId;
		attempt.state = responseVerdict(route, attempt.resultCode);
		record.lastClaimResult = attempt.state;
		const timeoutId = pendingTimeouts.get(attempt.id);
		if (timeoutId) window.clearTimeout(timeoutId);
		pendingTimeouts.delete(attempt.id);
		removeClaimProtocolListener(attempt.id, "matched-response");
		if (attempt.state === "server-accepted") {
			record.lastConfirmedSuccessAttempt = cloneJson(attempt, null);
		}
