			autoGiftRunResults = [];
			autoGiftPendingEntries = [];
			autoGiftProcessedThisRun = 0;
			autoGiftCompletedCount = 0;
			autoGiftFailedCount = 0;
			autoGiftFinalWaitTimedOut = false;
			autoGiftFinalizedResult = null;
		}
		autoGiftDeferFinalWait = deferFinalWait;
		autoGiftEnabled = true;
		lastAutoGiftResult = "starting:after-live-mail";
		try {
			await startAutoGiftQueue({ deferFinalWait: deferFinalWait });
			if (deferFinalWait) return makeAutoGiftQueueResult({ deferred: true });
			return await finalizeAutoGiftQueue();
		} catch (error) {
			autoGiftEnabled = false;
			autoGiftDeferFinalWait = false;
			throw error;
		} finally {
			if (!deferFinalWait) {
				autoGiftEnabled = false;
				autoGiftDeferFinalWait = false;
				try { window.localStorage.setItem(autoGiftEnabledStorageKey(accountId), "false"); } catch (error) {}
			}
		}
	}

	function formatBeijing(timestamp, seconds) {
		const milliseconds = seconds ? Number(timestamp) * 1000 : Number(timestamp);
		if (!Number.isFinite(milliseconds) || milliseconds <= 0) return "未知";
		try {
			return new Intl.DateTimeFormat("zh-CN", {
				timeZone: "Asia/Shanghai",
				year: "numeric", month: "2-digit", day: "2-digit",
				hour: "2-digit", minute: "2-digit", second: "2-digit",
				hour12: false
			}).format(new Date(milliseconds));
		} catch (error) {
			return new Date(milliseconds).toLocaleString();
		}
	}

	function translateResult(result) {
		if (!result || result === "never-requested") return "尚未尝试";
		if (result === "waiting-response") return "等待服务器回包";
		if (result === "server-accepted") return "服务器接受请求";
		if (result === "server-reported-already-handled") return "服务器表示已处理";
		if (result === "server-reported-already-claimed") return "服务器表示已经领取";
		if (result === "no-response-timeout") return "12 秒内未捕获回包";
		if (result.startsWith("server-rejected:")) return "服务器拒绝，结果码 " + result.split(":")[1];
		if (result.startsWith("request-error")) return "请求异常";
		return result;
	}

	function attachmentSummary(record) {
		const ids = record.attachment && record.attachment.id || [];
		const counts = record.attachment && record.attachment.ctn || [];
		if (record.claimRoute === "single-gift") return "礼包 ID " + (ids[0] == null ? "未知" : ids[0]);
		if (record.claimRoute === "dbs-item") {
			return ids.map((id, index) => String(id) + " x" + (counts[index] == null ? "?" : counts[index])).join("，") || "道具信息缺失";
		}
		return "未知附件类型 " + record.attachmentType;
	}

	function addText(parent, className, text) {
		const node = document.createElement("div");
		node.className = className;
		node.textContent = text;
		parent.appendChild(node);
		return node;
	}

	function renderRecords() {
		if (!listNode) return;
		listNode.textContent = "";
		const sorted = records.slice().sort((a, b) => (Number(b.originalEndtime) || 0) - (Number(a.originalEndtime) || 0));
		if (!sorted.length) {
			addText(listNode, "h5mca-empty", "尚未发现带附件邮件。请保持游戏在线并等待邮件列表加载。");
			return;
		}
		const serverNow = getServerNow();
		for (const record of sorted) {
			const card = document.createElement("div");
			card.className = "h5mca-card";
			const head = document.createElement("div");
			head.className = "h5mca-card-head";
			const title = document.createElement("strong");
			title.textContent = record.title;
			head.appendChild(title);
			const live = document.createElement("span");
			live.className = "h5mca-badge " + (record.presentInLiveList ? "is-live" : "is-archived");
			live.textContent = record.presentInLiveList ? "正式列表中" : "仅归档保留";
			head.appendChild(live);
			card.appendChild(head);

			const expired = record.originalEndtime > 0 && serverNow >= record.originalEndtime;
			addText(card, "h5mca-meta", "MID " + record.mid + " · " + (record.category === "friend" ? "好友邮件" : "系统邮件"));
			addText(card, "h5mca-meta", "原过期时间：" + formatBeijing(record.originalEndtime, true) + "（" + (expired ? "已到期" : "尚未到期") + "）");
			addText(card, "h5mca-meta", "领取标记：" + (record.lastKnownGeted ? "游戏显示已领取，可测试重复请求" : "游戏显示未领取"));
			addText(card, "h5mca-meta", "附件：" + attachmentSummary(record));
			addText(card, "h5mca-result", "最近结果：" + translateResult(record.lastClaimResult));

			const actions = document.createElement("div");
			actions.className = "h5mca-actions";
			const button = document.createElement("button");
			button.type = "button";
			button.textContent = "尝试领取";
			const validationError = validateClaim(record);
			button.disabled = Boolean(validationError) || record.claimAttempts.some(attempt => attempt.state === "waiting-response");
			button.title = validationError || "发送一次真实原生领取请求";
			button.addEventListener("click", function() {
				claimArchivedMail(record.mid).catch(error => {
					lastError = String(error && error.message || error);
					renderPanel();
				});
			});
			actions.appendChild(button);
			const attempts = document.createElement("span");
			attempts.textContent = "已尝试 " + record.claimAttempts.length + " 次";
			actions.appendChild(attempts);
			card.appendChild(actions);
			listNode.appendChild(card);
		}
	}

	function renderCrossRecords() {
		if (!crossListNode) return;
		crossListNode.textContent = "";
		if (!crossRecords.length) {
			addText(crossListNode, "h5mca-empty", "尚未导入其他测试账号的归档 JSON。");
			return;
		}
		const sorted = crossRecords.slice().sort((a, b) => Number(b.importedAt) - Number(a.importedAt));
		for (const record of sorted) {
			const card = document.createElement("div");
			card.className = "h5mca-card h5mca-cross-card";
			const head = document.createElement("div");
			head.className = "h5mca-card-head";
			const title = document.createElement("strong");
			title.textContent = record.title;
			head.appendChild(title);
			const badge = document.createElement("span");
			badge.className = "h5mca-badge is-cross";
			badge.textContent = "归属校验";
			head.appendChild(badge);
			card.appendChild(head);
			addText(card, "h5mca-meta", "来源 A " + record.originAccountId + " → 当前 B " + accountId);
			addText(card, "h5mca-meta", "MID " + record.mid + " · 原过期时间 " + formatBeijing(record.originalEndtime, true));
			addText(card, "h5mca-meta", "A 侧领取标记：" + (record.lastKnownGeted ? "已领取，可测试重复请求" : "未领取"));
			addText(card, "h5mca-meta", "附件：" + attachmentSummary(record));
			addText(card, "h5mca-result", "测试结果：" + translateResult(record.lastClaimResult));
			const actions = document.createElement("div");
			actions.className = "h5mca-actions";
			const button = document.createElement("button");
			button.type = "button";
			const waitingResponse = record.claimAttempts.some(attempt => attempt.state === "waiting-response");
			button.textContent = waitingResponse ? "等待服务器响应" : record.claimAttempts.length ? "再次发送归属校验" : "发送归属校验";
			const validationError = validateCrossAccountClaim(record);
			button.disabled = Boolean(validationError);
			button.title = validationError || "使用当前账号会话再次发送来源账号的邮件领取请求";
			button.addEventListener("click", function() {
				claimCrossAccountRecord(record.originAccountId, record.mid).catch(error => {
					lastError = String(error && error.message || error);
					renderPanel();
				});
			});
			actions.appendChild(button);
			const state = document.createElement("span");
			state.textContent = waitingResponse ? "请求进行中" : "已尝试 " + record.claimAttempts.length + " 次";
			actions.appendChild(state);
			card.appendChild(actions);
			crossListNode.appendChild(card);
		}
	}

	function updatePanelState() {
		if (!statusNode || !conflictNode) return;
		statusNode.textContent = "账号 " + (accountId || "等待登录") + " · 本账号归档 " + archiveCount + " 封 · 跨账号测试 " + crossRecords.length + " 封 · " + lastResult;
		const notes = [];
		if (autoMailPaused) notes.push("已暂停换肤版自动邮件领取");
		if (autoCdkPaused) notes.push("已同时暂停自动 CDK");
		if (display99Restored) notes.push("已恢复邮件原始过期时间");
		if (display99Paused) notes.push("已暂停 99 天显示脚本");
		if (!notes.length && conflictPauseAttempted) notes.push("未发现冲突的自动领取/99天显示功能");
		conflictNode.textContent = notes.join("；") + (notes.length ? "。刷新页面后相关功能会恢复。" : "");
		if (scanButton) {
			scanButton.disabled = manualRefreshPending;
			scanButton.textContent = manualRefreshPending ? "正在刷新…" : "刷新并归档";
		}
		if (autoGiftToggle) autoGiftToggle.checked = autoGiftEnabled;
		if (autoGiftStatusNode) {
			autoGiftStatusNode.textContent = "自动礼包：" + (autoGiftEnabled ? "已启用" : "已关闭") +
				" · 本次登录已处理 " + autoGiftCompletedCount + " 封" +
				(autoGiftCurrentMid ? " · 当前 MID " + autoGiftCurrentMid : "") +
				" · " + lastAutoGiftResult;
		}
	}

	function renderPanel() {
		if (!panel) return;
		updatePanelState();
		renderRecords();
		renderCrossRecords();
	}

	function savePanelState(state) {
		try { window.localStorage.setItem(PANEL_STATE_KEY, JSON.stringify(state)); } catch (error) {}
	}

	function readPanelState() {
		try { return JSON.parse(window.localStorage.getItem(PANEL_STATE_KEY) || "{}"); } catch (error) { return {}; }
	}

