	function installDrag(header) {
		let drag = null;
		header.addEventListener("pointerdown", function(event) {
			if (event.target && event.target.closest && event.target.closest("button")) return;
			const rect = panel.getBoundingClientRect();
			drag = { dx: event.clientX - rect.left, dy: event.clientY - rect.top };
			header.setPointerCapture && header.setPointerCapture(event.pointerId);
		});
		header.addEventListener("pointermove", function(event) {
			if (!drag) return;
			const left = Math.max(0, Math.min(window.innerWidth - panel.offsetWidth, event.clientX - drag.dx));
			const top = Math.max(0, Math.min(window.innerHeight - 42, event.clientY - drag.dy));
			panel.style.left = left + "px";
			panel.style.top = top + "px";
			panel.style.right = "auto";
		});
		header.addEventListener("pointerup", function() {
			if (!drag) return;
			drag = null;
			savePanelState({ left: panel.style.left, top: panel.style.top, collapsed: panel.classList.contains("is-collapsed") });
		});
	}

