		if (state.left) { panel.style.left = state.left; panel.style.right = "auto"; }
		if (state.top) panel.style.top = state.top;
		window.requestAnimationFrame(function keepMailPanelVisible() {
			const rect = panel.getBoundingClientRect();
			panel.style.left = Math.max(0, Math.min(window.innerWidth - panel.offsetWidth, rect.left)) + "px";
			panel.style.top = Math.max(0, Math.min(window.innerHeight - 42, rect.top)) + "px";
			panel.style.right = "auto";
		});
		if (state.collapsed) panel.classList.add("is-collapsed");
		const fold = panel.querySelector(".h5mca-fold");
		fold.textContent = panel.classList.contains("is-collapsed") ? "+" : "−";
		fold.addEventListener("click", function() {
			panel.classList.toggle("is-collapsed");
			fold.textContent = panel.classList.contains("is-collapsed") ? "+" : "−";
			savePanelState({ left: panel.style.left, top: panel.style.top, collapsed: panel.classList.contains("is-collapsed") });
