		});
		panel.querySelector(".h5mca-export").addEventListener("click", exportCurrentAccount);
		const restoreInput = panel.querySelector(".h5mca-restore-file");
		panel.querySelector(".h5mca-restore").addEventListener("click", function() { restoreInput.click(); });
		restoreInput.addEventListener("change", async function() {
			const file = restoreInput.files && restoreInput.files[0];
			if (!file) return;
			try {
				const text = typeof file.text === "function" ? await file.text() : await readBrowserFile(file);
				const summary = importSameAccountBackup(text);
				lastResult = "same-account-restored:" + summary.localImportedCount + ",merged:" + summary.localMergedCount;
			} catch (error) {
				lastError = String(error && error.message || error);
				lastResult = "error:same-account-restore:" + lastError;
			} finally {
				restoreInput.value = "";
				renderPanel();
