		panel.querySelector(".h5mca-import").addEventListener("click", function() { fileInput.click(); });
		fileInput.addEventListener("change", async function() {
			const file = fileInput.files && fileInput.files[0];
			if (!file) return;
			try {
				const text = typeof file.text === "function" ? await file.text() : await readBrowserFile(file);
				const summary = importCrossAccountArchive(text);
				lastResult = "cross-imported:" + summary.importedCount + ",duplicates:" + summary.duplicateCount;
			} catch (error) {
				lastError = String(error && error.message || error);
				lastResult = "error:cross-import:" + lastError;
			} finally {
				fileInput.value = "";
				renderPanel();
			}
		});
		panel.querySelector(".h5mca-clear-cross").addEventListener("click", clearCrossAccountTests);
		installDrag(panel.querySelector(".h5mca-header"));
