	function readBrowserFile(file) {
		return new Promise((resolve, reject) => {
			const reader = new FileReader();
			reader.onload = () => resolve(String(reader.result || ""));
			reader.onerror = () => reject(reader.error || new Error("file-read-failed"));
			reader.readAsText(file, "utf-8");
		});
	}

	function exportCurrentAccount() {
		const payload = {
			formatVersion: 2,
			exportedAt: Date.now(),
			exportedAtBeijing: formatBeijing(Date.now(), false),
			accountId: accountId,
			records: cloneJson(records, []),
			crossAccountTests: cloneJson(crossRecords, []),
			crossAccountAttemptLedger: cloneJson(crossAttemptLedger, {})
		};
		const json = JSON.stringify(payload, null, 2);
		if (testOptions.disableUi || typeof Blob === "undefined" || !document.createElement) return json;
		const blob = new Blob([json], { type: "application/json;charset=utf-8" });
		const url = URL.createObjectURL(blob);
		const anchor = document.createElement("a");
		anchor.href = url;
		anchor.download = "mail-claim-archive-" + (accountId || "unknown") + "-" + Date.now() + ".json";
		anchor.style.display = "none";
		document.body.appendChild(anchor);
		anchor.click();
		anchor.remove();
		window.setTimeout(() => URL.revokeObjectURL(url), 1000);
		return json;
	}

	function scan(forceRender) {
		if (stopped) return false;
		try {
