            const value = await response.json().catch(() => ({}));
            if (!response.ok) throw new Error(value.error || ('本地桥返回 HTTP ' + response.status));
            return value;
        } catch (error) {
            if (error && error.name === 'AbortError') throw new Error('本地桥响应超时');
            throw error;
        } finally {
            if (timer) window.clearTimeout(timer);
        }
    }



