    function syncMinuteSecondInputs(minuteInput, secondInput, currentMs) {
        const parts = splitDurationMinutesSeconds(currentMs);
        if (minuteInput) minuteInput.value = String(parts.minutes);
        if (secondInput) secondInput.value = String(parts.seconds);
    }

    function commitMinuteSecondInputs(minuteInput, secondInput, currentMs, setter, label) {
        const minuteRaw = String(minuteInput?.value || '').trim();
        const secondRaw = String(secondInput?.value || '').trim();
        const minutes = Number(minuteRaw);
        const seconds = Number(secondRaw);
        const valid = minuteRaw && secondRaw && Number.isInteger(minutes) && Number.isInteger(seconds) &&
            minutes >= 0 && seconds >= 0 && seconds <= 59;
        if (!valid) {
            syncMinuteSecondInputs(minuteInput, secondInput, currentMs);
            setMessage(`${label}请输入有效的整数分钟和 0～59 秒`);
            return false;
        }
        setter((minutes * 60 + seconds) * 1000);
        return true;
    }

    function bindMinuteSecondInputs(minuteInput, secondInput, readCurrentMs, setter, label) {
        const commit = () => commitMinuteSecondInputs(minuteInput, secondInput, readCurrentMs(), setter, label);
        for (const input of [minuteInput, secondInput]) {
            input.addEventListener('change', commit);
            input.addEventListener('keydown', (event) => {
                if (event.key === 'Enter') {
                    event.preventDefault();
                    input.blur();
                } else if (event.key === 'Escape') {
                    event.preventDefault();
                    syncMinuteSecondInputs(minuteInput, secondInput, readCurrentMs());
                    input.blur();
                }
            });
        }
    }





