        for (let index = values.length - 2; index >= 0; index -= 1) values[index] = Math.max(values[index], values[index + 1]);
        return Object.fromEntries(GENERAL_UPGRADE_STAGE_DEFS.map((stage, index) => [stage.key, values[index]]));
    }

