	function normalizeGeneralUpgradeRosterEntry(value) {
		if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
		const scanMode = String(value.scanMode || '');
		if (scanMode !== 'getOwnGeneral-v1' && scanMode !== 'getOwnGeneral-v2') return null;
		const ids = normalizeGeneralUpgradeRosterIdsConfig(value.ids);
		if (!ids.length) return null;
		const sourceCounts = Array.isArray(value.sourceCounts)
			? value.sourceCounts.map((item) => ({
				name: String(item?.name || '').slice(0, 80),
				count: Math.max(0, Math.floor(Number(item?.count) || 0)),
				rawCount: Math.max(0, Math.floor(Number(item?.rawCount) || Number(item?.count) || 0)),
				rejectedCount: Math.max(0, Math.floor(Number(item?.rejectedCount) || 0))
			})).filter((item) => item.name && item.rawCount > 0).slice(0, 20)
			: [];
		return {
			ids,
			count: ids.length,
			firstId: ids[0],
			lastId: ids[ids.length - 1],
			scanMode,
			accountId: String(value.accountId || '').trim().slice(0, 64),
			rawCount: Math.max(ids.length, Math.floor(Number(value.rawCount) || 0)),
			acceptedCount: Math.max(ids.length, Math.floor(Number(value.acceptedCount) || ids.length)),
			rejectedCount: Math.max(0, Math.floor(Number(value.rejectedCount) || 0)),
			updatedAt: String(value.updatedAt || '').slice(0, 40),
            scanWaitedMs: Math.max(0, Math.floor(Number(value.scanWaitedMs) || 0)),
            sourceCounts
        };
    }

