    function saveGeneralUpgradeRoster(accountId, scanResult) {
        const normalizedAccountId = String(accountId || '').trim().slice(0, 64);
        const ids = normalizeGeneralUpgradeRosterIdsConfig(scanResult?.ids);
        if (!normalizedAccountId || !ids.length) return null;
        const ledger = readGeneralUpgradeRosterLedger();
        const entry = normalizeGeneralUpgradeRosterEntry({
            ids,
            scanMode: scanResult?.scanMode,
			updatedAt: new Date().toISOString(),
			scanWaitedMs: scanResult?.waitedMs,
			accountId: scanResult?.accountId || normalizedAccountId,
			rawCount: scanResult?.rawCount,
			acceptedCount: scanResult?.acceptedCount,
			rejectedCount: scanResult?.rejectedCount,
			sourceCounts: scanResult?.sourceCounts
        });
        ledger[normalizedAccountId] = entry;
        const trimmed = Object.fromEntries(Object.entries(ledger)
            .sort((left, right) => String(right[1]?.updatedAt || '').localeCompare(String(left[1]?.updatedAt || '')))
            .slice(0, 32));
        storageSet(GENERAL_UPGRADE_ROSTER_KEY, trimmed);
        storageSet(DAILY_LAST_KEY, '');
        return entry;
