        if (!accountId) {
            setMessage('武将名单扫描失败：当前账号尚未识别');
            renderGeneralUpgradePage();
            return;
        }
        const bridge = mailRuntimeServices();
        if (!bridge || typeof bridge.scanOwnedGenerals !== 'function') {
            setMessage('武将名单扫描接口尚未加载，请重启微端后重试');
            renderGeneralUpgradePage();
            return;
        }
        if (generalUpgradeRosterScanButton) generalUpgradeRosterScanButton.disabled = true;
        if (generalUpgradeRosterStatus) generalUpgradeRosterStatus.textContent = '正在稳定扫描当前本地拥有武将…';
        try {
			const result = await withTimeout(Promise.resolve(bridge.scanOwnedGenerals()), 8000, '本地拥有武将扫描超过8秒');
			if (!result?.ready) throw new Error(describeGeneralUpgradeRosterScanFailure(result));
			const scannedAccountId = String(result.accountId || '').trim();
			if (scannedAccountId && scannedAccountId !== accountId) throw new Error(describeGeneralUpgradeRosterScanFailure({ status: 'account-mismatch' }));
            const entry = saveGeneralUpgradeRoster(accountId, result);
            if (!entry) throw new Error('扫描结果没有有效武将 ID，旧名单已保留');
			setMessage(`武将快照已更新：当前账号记录 ${entry.count} 名，升阶每轮实时重读；首 ID=${entry.firstId}`);
        } catch (error) {
            setMessage(`武将名单扫描失败：${error instanceof Error ? error.message : String(error)}；原名单未改动`);
