		if (generalUpgradeRunBusy) return;
		if (typeof workerBusy !== "undefined" && workerBusy) {
			setMessage("当前自动日常流程正在执行，请等待本轮结束");
			return;
		}
		const bridge = mailRuntimeServices();
		if (!bridge || typeof bridge.claimDailyRewards !== "function") {
			setMessage("独立执行接口尚未加载，请重启微端后重试");
			return;
		}
		const selection = standaloneRewardSelection(kind);
		if (kind === "generalUpgrade" && !Object.values(selection.generalUpgradeCounts).some((value) => value > 0)) {
			setMessage("武将升阶：请先设置至少一个目标人数");
			return;
		}
		generalUpgradeRunBusy = !0;
		if (generalUpgradeRunButton) generalUpgradeRunButton.disabled = !0;
		if (generalUpgradeTaskButton) generalUpgradeTaskButton.disabled = !0;
		if (generalUpgradeRunStatus) generalUpgradeRunStatus.textContent = kind === "generalUpgrade" ? "正在独立执行武将升阶…" : "正在独立执行官阶任务…";
		try {
			const result = await Promise.resolve(bridge.claimDailyRewards(selection));
			appendDailyRewardTrace(selection, result, null, null, "day");
			const text = kind === "generalUpgrade"
				? describeGeneralUpgradeReport(result && result.generalUpgrade)
				: describeStandaloneOfficerTasks(result && result.officerTasks);
			if (generalUpgradeRunStatus) generalUpgradeRunStatus.textContent = text;
			setMessage(text);
		} catch (error) {
			const text = `独立执行失败：${error instanceof Error ? error.message : String(error)}`;
			if (generalUpgradeRunStatus) generalUpgradeRunStatus.textContent = text;
			setMessage(text);
		} finally {
			generalUpgradeRunBusy = !1;
			if (generalUpgradeRunButton) generalUpgradeRunButton.disabled = !1;
			if (generalUpgradeTaskButton) generalUpgradeTaskButton.disabled = !1;
		}
	}

	function calculateGeneralUpgradePlan(rawCounts = readGeneralUpgradeCounts(), rawResources = readGeneralUpgradeResources()) {
        const counts = normalizeGeneralUpgradeCountsConfig(rawCounts);
        const resources = normalizeGeneralUpgradeResources(rawResources);
        const totalResourceCount = GENERAL_UPGRADE_RESOURCE_DEFS.reduce((sum, resource) => sum + resources[resource.key], 0);
        const totalExp = GENERAL_UPGRADE_RESOURCE_DEFS.reduce((sum, resource) => sum + resources[resource.key] * resource.exp, 0);
        const requiredExp = GENERAL_UPGRADE_STAGE_DEFS.reduce((sum, stage) => sum + counts[stage.key] * stage.exp, 0);
        const targetPoints = GENERAL_UPGRADE_STAGE_DEFS.reduce((sum, stage) => sum + counts[stage.key] * stage.points, 0);
        const totalUpgradeActions = GENERAL_UPGRADE_STAGE_DEFS.reduce((sum, stage) => sum + counts[stage.key], 0);
        let expRemaining = totalExp;
        let previousPoolCompleted = Number.POSITIVE_INFINITY;
        let previousFixedCompleted = Number.POSITIVE_INFINITY;
        let feasiblePoints = 0;
        const stages = GENERAL_UPGRADE_STAGE_DEFS.map((stage) => {
            const target = counts[stage.key];
            const dependencyLimit = Math.min(target, previousPoolCompleted);
            const poolCompleted = Math.min(dependencyLimit, Math.floor(expRemaining / stage.exp));
            expRemaining -= poolCompleted * stage.exp;
            previousPoolCompleted = poolCompleted;
            feasiblePoints += poolCompleted * stage.points;
            const fixedCompleted = Math.min(target, previousFixedCompleted, resources[stage.key]);
            previousFixedCompleted = fixedCompleted;
            return {
                ...stage,
                target,
                poolCompleted,
                fixedCompleted,
                standaloneMax: Math.floor(totalExp / stage.exp)
            };
        });
        const targetEnough = stages.every((stage) => stage.poolCompleted >= stage.target);
        const fixedSealsEnough = stages.every((stage) => stage.fixedCompleted >= stage.target);
        return {
            counts,
            resources,
            totalResourceCount,
            totalExp,
            requiredExp,
            targetPoints,
            uniqueGeneralCount: counts.stage1,
            totalUpgradeActions,
            feasiblePoints,
            expRemaining: Math.max(0, expRemaining),
            expShortage: Math.max(0, requiredExp - totalExp),
            targetEnough,
            fixedSealsEnough,
            stages
        };
    }

    function legacyDailyRewardItems() {
        const mode = storageGet(DAILY_MODE_KEY, 'off');
        const safeEnabled = mode === 'safe' || mode === 'all';
        return {
			mailClaim: true,
			freeBless: safeEnabled,
			activityAll: safeEnabled,
			newJd: false,
			officerPromote: true,
            officerTasks: true,
            generalUpgrade: false,
            officerSprint: true,
            officerDailyWeekly: true,
            giftCodes: true,
            blackMagicOrb: true
        };
    }

    function normalizeDailyRewardItems(value, fallback) {
        const source = value && typeof value === 'object' && !Array.isArray(value) ? value : {};
        const base = fallback && typeof fallback === 'object' ? fallback : legacyDailyRewardItems();
        const normalized = {};
        for (const item of DAILY_REWARD_ITEM_DEFS) {
            if (Object.prototype.hasOwnProperty.call(source, item.key)) {
                normalized[item.key] = source[item.key] === true;
                continue;
            }
            if (item.key === 'officerPromote') {
                const hasOldPromotionControl = Object.prototype.hasOwnProperty.call(source, 'officerSprint')
                    || Object.prototype.hasOwnProperty.call(source, 'officerTasks');
                normalized[item.key] = hasOldPromotionControl
                    ? source.officerSprint === true || source.officerTasks === true
                    : base.officerPromote === true;
                continue;
            }
            if (item.key === 'generalUpgrade') {
                // 新增的消耗型功能必须默认关闭，不能从任何旧官阶开关继承点亮状态。
                normalized[item.key] = false;
                continue;
            }
            if (item.key === 'officerSprint') {
                normalized[item.key] = Object.prototype.hasOwnProperty.call(source, 'officerRewards')
                    ? source.officerRewards === true
                    : (Object.prototype.hasOwnProperty.call(source, 'officerSprint') ? source.officerSprint === true : base.officerSprint === true);
                continue;
            }
            if (item.key === 'officerDailyWeekly') {
                if (Object.prototype.hasOwnProperty.call(source, 'officerRewards')) normalized[item.key] = source.officerRewards === true;
                else {
                    const oldRewardKeys = ['officerDay', 'officerWeek'];
                    const hasOldRewardControl = oldRewardKeys.some((key) => Object.prototype.hasOwnProperty.call(source, key));
                    normalized[item.key] = hasOldRewardControl
                        ? oldRewardKeys.some((key) => source[key] === true)
                        : base.officerDailyWeekly === true;
                }
                continue;
            }
            normalized[item.key] = DAILY_REWARD_SUPPORTED_ITEM_KEYS.has(item.key) && base[item.key] === true;
        }
        return normalized;
    }

    function readDailyRewardItems() {
        const stored = storageGet(DAILY_ITEMS_KEY, null);
        if (stored && typeof stored === 'object' && !Array.isArray(stored)) {
            const normalized = normalizeDailyRewardItems(stored);
            const changed = DAILY_REWARD_ITEM_DEFS.some((item) => (stored[item.key] === true) !== (normalized[item.key] === true))
                || Object.keys(stored).some((key) => !DAILY_REWARD_SUPPORTED_ITEM_KEYS.has(key));
            if (changed) storageSet(DAILY_ITEMS_KEY, normalized);
            return normalized;
        }
        const migrated = legacyDailyRewardItems();
        storageSet(DAILY_ITEMS_KEY, migrated);
        return migrated;
    }

    function isCurrentMailClaimEnabled() {
        // 默认保持开启，兼容加入面板前的原有每轮行为；该开关只控制发包，
        // 不影响邮件列表刷新、扫描或归档。
        return readDailyRewardItems().mailClaim === true;
