    function enabledDailyRewardItems(items) {
        return DAILY_REWARD_ITEM_DEFS.filter((item) => items && items[item.key] === true);
    }

    function toggleDailyRewardItem(key) {
        const definition = DAILY_REWARD_ITEM_DEFS.find((item) => item.key === key);
        if (!definition) return;
        if (!DAILY_REWARD_SUPPORTED_ITEM_KEYS.has(key)) {
            setMessage(`${definition.label}：当前不可使用`);
            renderPanel();
            return;
        }
        const items = readDailyRewardItems();
        items[key] = items[key] !== true;
        storageSet(DAILY_ITEMS_KEY, items);
        // 修改任一开关后允许新设置立即执行，不必等到次日。
        storageSet(DAILY_LAST_KEY, '');
        const action = ['officerPromote', 'generalUpgrade'].includes(key) ? '晋升' : '领取';
        setMessage(`${definition.label}：${items[key] ? `已点亮，每轮将尝试${action}` : `已熄灭，每轮跳过${action}`}`);
