    function describeGeneralUpgradeReport(value) {
        const report = compactGeneralUpgradeReport(value);
        if (!report) return '失败：本轮无返回结果';
        const statusText = report.status === 'success' ? '成功'
            : report.status === 'partial' ? '部分成功'
                : report.status === 'no-target' ? '跳过'
                    : '失败';
        const reasonText = ({
            'target-empty': '目标人数均为0',
            'manager-unavailable': '管理器未就绪',
            'interface-unavailable': '接口未就绪',
            'no-one-star-general': '没有可选的一阶武将',
            'runtime-error': '执行异常',
			'account-not-ready': '当前账号未识别，已阻止发包',
			'account-mismatch': '实时快照账号与当前账号不一致，已阻止发包',
            'local-general-state-unstable': '本地武将列表未稳定，已阻止发包',
            'local-upgrade-state-not-reset': '本地已有高于一阶武将，已阻止本轮全部升阶',
			'roster-not-scanned': '实时拥有武将快照未就绪，已阻止发包',
			'roster-sentinel-unavailable': '实时快照目标前缀状态无法稳定读取，已阻止发包'
        })[report.reason] || '';
        const stages = report.stages.map((stage) => {
            const details = [];
            if (stage.alreadySatisfiedCount > 0) details.push(`当前已达标${stage.alreadySatisfiedCount}`);
            if (stage.transitionConfirmedCount > 0) {
                const ids = stage.confirmedIds.slice(0, 12);
                details.push(`实时捕获${stage.transitionConfirmedCount}${ids.length ? `（ID:${ids.join(',')}）` : ''}`);
            }
            if (stage.unconfirmedCount > 0) details.push(`单次窗口未捕获${stage.unconfirmedCount}`);
            if (stage.blockedCount > 0) details.push(`前层未达标${stage.blockedCount}`);
			if (stage.missingCount > 0) details.push(`实时快照不足${stage.missingCount}`);
            if (stage.unsentCount > 0) details.push(`总确认预算到期未发${stage.unsentCount}`);
			if (stage.materialFallbackCount > 0) {
				const fallbackTotals = new Map();
				for (const item of stage.materialPlans.filter((entry) => entry.fallback && entry.name)) {
					fallbackTotals.set(item.name, (fallbackTotals.get(item.name) || 0) + Math.max(0, Number(item.count) || 0));
				}
				const fallbackText = Array.from(fallbackTotals.entries()).map(([name, count]) => `${name}×${count}`).join('/');
				details.push(`材料回退${stage.materialFallbackCount}${fallbackText ? `（${fallbackText}）` : ''}`);
			}
			if (stage.materialUnavailableCount > 0) details.push(`已知材料不足${stage.materialUnavailableCount}`);
            if (stage.blockedReason === 'previous-stage-state-not-refreshed') details.push('前层未确认，已阻止继续升阶');
            return `${stage.from}→${stage.to} 本轮满足${stage.confirmedCount}/${stage.targetCount}${details.length ? `（${details.join('、')}）` : ''}`;
        });
		const preflightText = report.preflight
			? report.preflight.sentinelId
				? `；预检：实时快照${report.preflight.snapshot ? `${report.preflight.snapshot.acceptedCount}/${report.preflight.snapshot.rawCount}名、拒绝${report.preflight.snapshot.rejectedCount}名` : `${report.preflight.rosterCount}名`}、核对前缀${report.preflight.checkedCount || 1}名、首ID=${report.preflight.sentinelId}为${report.preflight.sentinelStar || '?'}阶、${report.preflight.stable ? '前缀稳定' : '前缀未稳定'}、${report.preflight.waitedMs}ms`
				: `；预检：${report.preflight.stable ? '列表稳定' : '列表未稳定'}、${report.preflight.waitedMs}ms`
            : '';
        const executionText = report.execution
			? `；调度：并发${report.execution.workerCount}、峰值在途${report.execution.maxActiveConfirmations}、新武将间隔${report.execution.sendIntervalMs}ms、事件监听${report.execution.eventMonitorInstalled ? '已装' : '未装'}、事件确认${report.execution.eventObservedSuccessCount}次、迟到回收${report.execution.lateConfirmedCount}次、整体最小间隔${report.execution.minimumObservedSendGapMs}ms、耗时${report.execution.elapsedMs}ms`
            : '';
        return `${statusText}${stages.length ? `：${stages.join('；')}` : reasonText ? `：${reasonText}` : ''}${reasonText && stages.length ? `；${reasonText}` : ''}${preflightText}${executionText}`;
    }

    function classifyDailyRewardTraceItems(selection, result) {
        const source = result && typeof result === 'object' ? result : {};
        const groups = {
            done: Array.isArray(source.done) ? source.done.map(String) : [],
            requested: Array.isArray(source.requested) ? source.requested.map(String) : [],
            skipped: Array.isArray(source.skipped) ? source.skipped.map(String) : [],
            errors: Array.isArray(source.errors) ? source.errors.map(String) : []
        };
        const matchesLabels = (text, labels) => labels.some((label) => String(text).includes(label));
        const output = {};
        for (const definition of DAILY_REWARD_ITEM_DEFS) {
            const key = definition.key;
            if (['mailClaim', 'giftCodes', 'blackMagicOrb'].includes(key)) continue;
            const labels = DAILY_REWARD_TRACE_LABELS[key] || [definition.label];
            if (key === 'generalUpgrade' && selection && selection[key] === true && source.generalUpgrade) {
                const report = compactGeneralUpgradeReport(source.generalUpgrade);
                output[key] = {
                    label: definition.label,
                    enabled: true,
                    status: report?.success === true ? 'server-confirmed'
                        : report?.status === 'partial' ? 'partial-confirmed'
                            : report?.status === 'unconfirmed' ? 'timeout-or-unconfirmed'
                                : report?.status === 'no-target' ? 'not-claimable' : 'failed',
                    evidence: [{ group: 'result', text: describeGeneralUpgradeReport(report) }]
                };
                continue;
            }
            const evidence = [];
            for (const [group, values] of Object.entries(groups)) {
                for (const text of values) {
                    if (matchesLabels(text, labels)) evidence.push({ group, text });
                }
            }
            let status = selection && selection[key] === true ? 'no-result' : 'disabled';
            if (evidence.some((item) => item.group === 'done')) status = 'server-confirmed';
            else if (evidence.some((item) => item.group === 'skipped' && /服务器拒绝|Result\s*(?:=|:)?\s*\d+/i.test(item.text))) status = 'server-rejected';
            else if (evidence.some((item) => /官方活动数据未加载/.test(item.text))) status = 'official-data-unavailable';
            else if (evidence.some((item) => /数据.*(?:未就绪|未初始化)|任务字典.*未加载/.test(item.text))) status = 'data-not-ready';
            else if (evidence.some((item) => item.group === 'requested' || /未确认|未收到.*回包|请求已发送.*未收到/.test(item.text))) status = 'timeout-or-unconfirmed';
            else if (evidence.some((item) => item.group === 'errors')) status = 'local-or-request-error';
            else if (evidence.some((item) => /管理器无|接口无|接口不完整|监听接口无|状态接口无/.test(item.text))) status = 'interface-unavailable';
            else if (evidence.length) status = 'not-claimable';
            output[key] = {
                label: definition.label,
                enabled: selection && selection[key] === true,
                status,
                evidence
            };
        }
        return output;
    }

    function readDailyRewardTrace() {
        const stored = storageGet(DAILY_REWARD_TRACE_KEY, []);
        return Array.isArray(stored) ? stored.slice(-DAILY_REWARD_TRACE_LIMIT) : [];
    }

    function readDailyRewardTraceSummary() {
        const stored = storageGet(DAILY_REWARD_TRACE_SUMMARY_KEY, null);
        return stored && typeof stored === 'object' && !Array.isArray(stored)
            ? stored
            : { schema: 'sgsol-daily-reward-trace-summary/v1', totalCycles: 0, updatedAt: '', items: {} };
    }

    function updateDailyRewardTraceSummary(entry) {
        const summary = readDailyRewardTraceSummary();
        summary.schema = 'sgsol-daily-reward-trace-summary/v1';
        summary.totalCycles = Math.max(0, Number(summary.totalCycles) || 0) + 1;
        summary.updatedAt = entry.at;
        if (!summary.items || typeof summary.items !== 'object' || Array.isArray(summary.items)) summary.items = {};
        for (const [key, item] of Object.entries(entry.items || {})) {
            const previous = summary.items[key] && typeof summary.items[key] === 'object'
                ? summary.items[key]
                : { label: item.label, enabledCycles: 0, statuses: {} };
            previous.label = item.label;
            if (item.enabled) previous.enabledCycles = Math.max(0, Number(previous.enabledCycles) || 0) + 1;
            if (!previous.statuses || typeof previous.statuses !== 'object' || Array.isArray(previous.statuses)) previous.statuses = {};
            previous.statuses[item.status] = Math.max(0, Number(previous.statuses[item.status]) || 0) + 1;
            previous.lastStatus = item.status;
            previous.lastAt = entry.at;
            previous.lastCycleId = entry.cycleId;
            previous.lastEvidence = Array.isArray(item.evidence) ? item.evidence.slice(-4) : [];
            summary.items[key] = previous;
        }
        storageSet(DAILY_REWARD_TRACE_SUMMARY_KEY, summary);
    }

    function appendDailyRewardTrace(selection, result, before, after, frequency) {
        if (!TOP_WINDOW) return null;
        try {
            const state = readState();
            const entry = {
                schema: 'sgsol-daily-reward-trace/v1',
                at: new Date().toISOString(),
                scriptVersion: VERSION,
                cycleId: String(state.cycleId || ''),
                phase: String(state.phase || ''),
                frequency: frequency === 'cycle' ? 'cycle' : 'day',
                ready: result && result.ready === true,
                error: result && result.ready === false ? String(result.error || 'not-ready') : '',
                items: classifyDailyRewardTraceItems(selection, result),
                raw: {
                    done: Array.isArray(result?.done) ? result.done.map(String) : [],
                    requested: Array.isArray(result?.requested) ? result.requested.map(String) : [],
                    skipped: Array.isArray(result?.skipped) ? result.skipped.map(String) : [],
                    errors: Array.isArray(result?.errors) ? result.errors.map(String) : []
                },
                officerTasks: compactOfficerTaskReport(result?.officerTasks),
                generalUpgrade: compactGeneralUpgradeReport(result?.generalUpgrade),
                settleWaitMs: Math.max(0, Number(result?.settleWaitMs) || 0),
                before: compactDailyRewardStateSnapshot(before),
                after: compactDailyRewardStateSnapshot(after)
            };
            const recent = readDailyRewardTrace();
            recent.push(entry);
            storageSet(DAILY_REWARD_TRACE_KEY, recent.slice(-DAILY_REWARD_TRACE_LIMIT));
            updateDailyRewardTraceSummary(entry);
            lastDailyRewardTraceEntry = entry;
            return entry;
        } catch (_) {
            // 追踪日志是旁路诊断；任何文件异常都不能改变领取或退出流程。
            return null;
        }
    }

    function todayStamp() {
        const d = new Date();
        return `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`;
    }

    async function runDailyRewardsOncePerDay(bridge) {
        // 每项独立开关；全灭时完全不调用日常奖励桥。
        try {
            const { selection, frequency: freq, dailyFrequencyDue } = dailyRewardBridgeSelection();
            // 开黑魔珠属于同一组 UI 开关，但必须在每个账号登录后重新查官方进度，
            // 不受“每天一次”日戳限制；它在本函数之后由独立兑换步骤执行。
            // 官阶链和武将升阶固定每轮执行；全局“每天/每轮”只控制其他普通日常项目。
            const enabledItems = enabledDailyRewardItems(selection).filter((item) => !['mailClaim', 'giftCodes', 'blackMagicOrb'].includes(item.key));
            if (!enabledItems.length) return '';
            if (!bridge || typeof bridge.claimDailyRewards !== 'function') return '；[日常奖励] 桥未提供接口（需重启微端注入新版）';
            const res = await Promise.resolve(bridge.claimDailyRewards(selection));
            appendDailyRewardTrace(
                selection,
                res,
                res && res.officerBefore ? res.officerBefore : null,
                res && res.officerAfter ? res.officerAfter : null,
                freq
            );
            if (!res || res.ready === false) return `；[日常奖励] 未执行（${res?.error || '游戏未就绪'}），下轮再试`;
            // 各项目独立执行：某一项接口尚未注册时，只让该项下轮重试，不能抹掉其他项目本轮的真实结果。
            const notReadyItems = (res.skipped || []).filter((x) => /管理器无|接口无|接口不完整/.test(x));
            const notReady = notReadyItems.length;
            // “每天一次”只有在全部已点亮项目均完成接口检查后才落日戳，避免未就绪项目漏领一整天。
            const ranDailyFrequencyItem = dailyFrequencyDue && enabledItems.some((item) => !DAILY_REWARD_FIXED_EACH_CYCLE_KEYS.has(item.key));
            if (freq === 'day' && ranDailyFrequencyItem && notReady === 0 && !(res.errors || []).length && !(res.requested || []).length && !(res.skipped || []).some(text => /拒绝|未确认|未返回|未收到|失败/.test(text))) storageSet(DAILY_LAST_KEY, todayStamp());
			// 军典档位、节钺令与武将升阶会在“本轮功能结果”中各显示一次，这里不再重复铺开。
            const withoutSummarizedFeatures = (values) => (Array.isArray(values) ? values : [])
                .map(String)
				.filter((text) => !text.includes('武将升阶') && !text.includes('军典档位一键') && !text.includes('节钺令'));
            const doneText = withoutSummarizedFeatures(res.done).join('、') || '无';
            const requestedText = withoutSummarizedFeatures(res.requested).join('、') || '无';
            const skipText = withoutSummarizedFeatures(res.skipped).join('、') || '无';
            const otherErrors = withoutSummarizedFeatures(res.errors);
            const errText = otherErrors.length ? `；异常：${otherErrors.join('、')}` : '';
            const retryText = notReady
                ? `；接口待就绪：${notReadyItems.join('、')}（仅这些项目下轮重试）`
                : '';
            return `；[日常奖励·独立${enabledItems.length}项·${freq === 'cycle' ? '全部每轮' : '官阶/升阶每轮，普通每天'}] 确认成功：${doneText}；待确认：${requestedText}；跳过：${skipText}${retryText}${errText}`;
        } catch (error) {
            return `；[日常奖励] 异常：${error instanceof Error ? error.message : String(error)}`;
        }
    }

    async function exchangeBlackMagicOrbsEachCycleResult(bridge) {
        try {
            if (readDailyRewardItems().blackMagicOrb !== true) return { text: '', status: 'disabled', success: true, enabled: false };
            if (!bridge || typeof bridge.exchangeBlackMagicOrbs !== 'function') {
                return { text: '；[竞猜币兑换] 桥未提供接口（需重启微端注入新版）', status: 'bridge-unavailable', success: false, enabled: true };
            }
            const result = await withTimeout(
                Promise.resolve(bridge.exchangeBlackMagicOrbs()),
                8000,
                '竞猜币兑换执行超过 8 秒'
            );
            try { pushRawLog('black-magic-orb-exchange', JSON.stringify(result || {})); } catch (_) {}
            if (!result || result.ready === false) {
                return { text: `；[竞猜币兑换] 未执行（${result?.status || result?.error || '游戏未就绪'}），下轮再试`, status: String(result?.status || result?.error || 'not-ready'), success: false, enabled: true };
            }
            const before = Math.max(0, Number(result.beforeTimes || 0));
            const after = Math.max(0, Number(result.afterTimes || 0));
            const sent = Math.max(0, Number(result.sentExchanges || 0));
            if (result.status === 'weekly-limit-reached') {
                return { text: `；[竞猜币兑换] 开黑魔珠本周已兑换 ${after}/2，跳过发包`, status: result.status, success: true, enabled: true, before, after, sent };
            }
            if (result.status === 'activity-outside-time') {
                return { text: '；[竞猜币兑换] 开黑魔珠活动不在开放时间，跳过发包', status: result.status, success: false, enabled: true, before, after, sent };
            }
            if (result.confirmed) {
                return { text: `；[竞猜币兑换] 开黑魔珠服务器确认完成 ${Math.max(0, after - before) || sent} 次（周进度 ${after}/2）`, status: 'server-confirmed', success: true, enabled: true, before, after, sent };
            }
            if (sent > 0) {
                return { text: `；[竞猜币兑换] 已请求开黑魔珠 ${sent} 次，4 秒内未确认（周进度 ${before}→${after}）`, status: 'sent-unconfirmed', success: false, enabled: true, before, after, sent };
            }
            return { text: `；[竞猜币兑换] 未发包（${result.status || result.error || '未知状态'}）`, status: String(result.status || result.error || 'not-sent'), success: false, enabled: true, before, after, sent };
        } catch (error) {
            return { text: `；[竞猜币兑换] 异常：${error instanceof Error ? error.message : String(error)}`, status: 'error', success: false, enabled: true };
        }
    }

    async function exchangeBlackMagicOrbsEachCycle(bridge) {
        const result = await exchangeBlackMagicOrbsEachCycleResult(bridge);
        return result.text || '';
    }

    function giftCodeUtf8Length(value) {
        const text = String(value || '');
        if (typeof TextEncoder === 'function') return new TextEncoder().encode(text).length;
        return unescape(encodeURIComponent(text)).length;
    }

    function normalizeGiftCodes(value) {
        const rawCodes = Array.isArray(value)
            ? value
            : String(value || '').split(/[\r\n,，;；]+/);
        const seen = new Set();
        return rawCodes.map((code) => String(code || '').trim()).filter((code) => {
            if (!code || /\s/.test(code) || giftCodeUtf8Length(code) > 64 || seen.has(code)) return false;
            seen.add(code);
            return true;
        }).slice(0, 50);
    }

    function normalizeGiftCodeEntry(value, index = 0, strict = false) {
        try {
            const source = typeof value === 'string' ? { code: value } : value;
            if (!source || typeof source !== 'object' || Array.isArray(source)) throw new Error(`第 ${index + 1} 项不是对象或字符串`);
            const code = String(source.code ?? source.CDKey ?? '').trim();
            if (!code) throw new Error(`第 ${index + 1} 项缺少 code`);
            if (/\s/.test(code)) throw new Error(`兑换码“${code}”包含空白字符`);
            if (giftCodeUtf8Length(code) > 64) throw new Error(`兑换码“${code}”超过协议 64 字节上限`);

            const rawGiftId = Number(source.giftId ?? source.GiftID ?? 0);
            if (!Number.isInteger(rawGiftId) || rawGiftId < 0 || rawGiftId > 65535) {
                throw new Error(`兑换码“${code}”的 giftId 超出 0~65535`);
            }
            const rawType = Number(source.type ?? source.Type ?? 0);
            if (!Number.isInteger(rawType) || rawType < 0 || rawType > 255) {
                throw new Error(`兑换码“${code}”的 type 超出 0~255`);
            }
            const route = String(source.route || 'auto');
            if (!['auto', 'direct', 'window'].includes(route)) {
                throw new Error(`兑换码“${code}”的 route 只能是 auto/direct/window`);
            }
            const rawStatus = String(source.status || 'pending');
            const rawLastResult = String(source.lastResult || '');
            const legacyServerFeedback = /^(?:server-|submitted-unconfirmed)/.test(rawStatus) ||
                /服务器(?:确认成功|明确失败|提示已领取|回包超时)|Result=\d+/.test(rawLastResult);

            return {
                id: String(source.id || `cdk-${index + 1}`),
                code,
                giftId: rawGiftId,
                type: rawType,
                route,
                enabled: source.enabled !== false,
                source: String(source.source || (typeof value === 'string' ? 'legacy' : 'saved')),
                note: String(source.note || ''),
                attempts: Math.max(0, Math.min(MAX_GIFT_CODE_ATTEMPTS, Number(source.attempts || 0))),
                status: legacyServerFeedback ? 'ready' : rawStatus,
                lastResult: legacyServerFeedback ? '' : rawLastResult,
                lastResultCode: !legacyServerFeedback && source.lastResultCode != null && Number.isFinite(Number(source.lastResultCode))
                    ? Number(source.lastResultCode)
                    : null,
                updatedAt: Number(source.updatedAt || 0)
            };
        } catch (error) {
            if (strict) throw error;
            return null;
        }
    }

    function readGiftCodeQueue() {
        const saved = storageGet(GIFT_CODE_QUEUE_KEY, null);
        const source = Array.isArray(saved) ? saved : DEFAULT_GIFT_CODES.map((code) => ({ code, source: 'default' }));
        const seen = new Set();
        return source.map((entry, index) => normalizeGiftCodeEntry(entry, index, false)).filter((entry) => {
            if (!entry || seen.has(entry.code)) return false;
            seen.add(entry.code);
            return true;
        }).slice(0, 50);
    }

    function writeGiftCodeQueue(queue) {
        const normalized = (Array.isArray(queue) ? queue : [])
            .map((entry, index) => normalizeGiftCodeEntry(entry, index, false))
            .filter(Boolean)
            .slice(0, 50);
        storageSet(GIFT_CODE_QUEUE_KEY, normalized);
        if (giftCodeStatus) giftCodeStatus.textContent = formatGiftCodeQueueStatus();
    }

    function parseGiftCodeJsonPayload(input) {
        let payload = input;
        if (typeof payload === 'string') {
            try {
                payload = JSON.parse(payload);
            } catch (error) {
                throw new Error(`JSON 解析失败：${error instanceof Error ? error.message : String(error)}`);
            }
        }
        if (Array.isArray(payload)) payload = { schema: GIFT_CODE_JSON_SCHEMA, codes: payload };
        if (!payload || typeof payload !== 'object') throw new Error('CDK JSON 顶层必须是对象或数组');
        if (payload.schema && payload.schema !== GIFT_CODE_JSON_SCHEMA) {
            throw new Error(`不支持的 CDK JSON schema：${String(payload.schema)}`);
        }
        const sourceCodes = Array.isArray(payload.codes) ? payload.codes : (Array.isArray(payload.cdks) ? payload.cdks : null);
        if (!sourceCodes) throw new Error('CDK JSON 缺少 codes 数组');
        if (sourceCodes.length > 50) throw new Error('CDK JSON 最多导入 50 个兑换码');

        const seen = new Set();
        const codes = sourceCodes.map((entry, index) => normalizeGiftCodeEntry(entry, index, true)).filter((entry) => {
            if (seen.has(entry.code)) return false;
            seen.add(entry.code);
            return true;
        }).map((entry) => ({
            ...entry,
            source: 'json',
            attempts: 0,
            status: 'imported',
            lastResult: '',
            updatedAt: Date.now()
        }));
        return {
            schema: GIFT_CODE_JSON_SCHEMA,
            accountId: String(payload.accountId || ''),
            codes
        };
    }

    function importGiftCodeJsonText(text, fileName = '') {
        const payload = parseGiftCodeJsonPayload(text);
        writeGiftCodeQueue(payload.codes);
        syncGiftCodeInput();
        const accountTip = payload.accountId ? `；文件账号标记 ${payload.accountId}（实际兑换仍以当前登录账号为准）` : '';
        setMessage(`已从${fileName ? `“${fileName}”` : ' JSON'}导入 ${payload.codes.length} 个兑换码并永久保存${accountTip}；将在下一轮依次兑换，可点“立即执行”测试`);
        return payload;
    }

    function readGiftCodeFileText(file) {
        if (!file) return Promise.reject(new Error('未选择 JSON 文件'));
        if (typeof file.text === 'function') return file.text();
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(String(reader.result || ''));
            reader.onerror = () => reject(reader.error || new Error('读取 JSON 文件失败'));
            reader.readAsText(file, 'utf-8');
        });
    }

    async function importGiftCodeJsonFile(file) {
        try {
            const text = await readGiftCodeFileText(file);
            return importGiftCodeJsonText(text, String(file?.name || ''));
        } catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            setMessage(`CDK JSON 导入失败：${message}`);
            throw error;
        } finally {
            if (giftCodeFileInput) giftCodeFileInput.value = '';
        }
    }

    function triggerGiftCodeJsonImport() {
        if (!giftCodeFileInput) {
            setMessage('CDK JSON 文件选择器未就绪');
            return;
        }
        giftCodeFileInput.value = '';
        giftCodeFileInput.click();
    }

    function exportGiftCodeJson() {
        const queue = readGiftCodeQueue();
        const payload = {
            schema: GIFT_CODE_JSON_SCHEMA,
            exportedAt: new Date().toISOString(),
            accountId: '',
            codes: queue.map((entry) => ({
                id: entry.id,
                code: entry.code,
                giftId: entry.giftId,
                type: entry.type,
                route: entry.route,
                enabled: entry.enabled,
                note: entry.note,
                status: entry.status,
                lastResult: entry.lastResult,
                lastResultCode: entry.lastResultCode,
                updatedAt: entry.updatedAt
            }))
        };
        const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = url;
        link.download = `SGSOL-CDK-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
        link.style.display = 'none';
        (document.body || document.documentElement).appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
        setMessage(`已导出 ${queue.length} 个兑换码 JSON`);
    }

    function formatGiftCodeQueueStatus() {
        const queue = readGiftCodeQueue();
        if (!queue.length) return '未设置兑换码';
        const enabledCount = queue.filter((entry) => entry.enabled).length;
        const jsonCount = queue.filter((entry) => entry.source === 'json').length;
        const latest = queue.slice().sort((left, right) => Number(right.updatedAt || 0) - Number(left.updatedAt || 0))[0];
        const latestResult = String(latest?.lastResult || '').trim();
        const compactResult = latestResult.length > 56 ? `${latestResult.slice(0, 56)}…` : latestResult;
        return `共 ${queue.length} 个（启用 ${enabledCount}，JSON ${jsonCount}）；每码每轮 ${MAX_GIFT_CODE_ATTEMPTS} 次${compactResult ? `；最近：${compactResult}` : ''}`;
    }

    function syncGiftCodeInput() {
        if (giftCodeInput) giftCodeInput.value = readGiftCodeQueue().filter((entry) => entry.enabled).map((entry) => entry.code).join('\n');
        if (giftCodeStatus) giftCodeStatus.textContent = formatGiftCodeQueueStatus();
    }

    function saveGiftCodeInput() {
        const requestedCodes = normalizeGiftCodes(giftCodeInput?.value || '');
        const previousByCode = new Map(readGiftCodeQueue().map((entry) => [entry.code, entry]));
        const nextQueue = requestedCodes.map((code, index) => previousByCode.get(code) || ({
            id: `text-${index + 1}`,
            code,
            giftId: 0,
            type: 0,
            route: 'auto',
            enabled: true,
            source: 'text',
            note: '',
            attempts: 0,
            status: 'pending',
            lastResult: '',
            updatedAt: Date.now()
        })).map((entry) => ({ ...entry, enabled: true }));
        writeGiftCodeQueue(nextQueue);
        syncGiftCodeInput();
        setMessage(nextQueue.length
            ? `已保存 ${nextQueue.length} 个兑换码；JSON/面板只提供配置，短码走游戏内部直调，长码无 GiftID 时走官方窗口；每轮在邮件后发起，刷新窗口以邮件反馈为准`
            : '兑换码队列已清空；后续轮次不会提交兑换请求');
    }

    function clearGiftCodeResults() {
        const queue = readGiftCodeQueue().map((entry) => ({
            ...entry,
            attempts: 0,
            status: 'ready',
            lastResult: '',
            updatedAt: Date.now()
        }));
        writeGiftCodeQueue(queue);
        syncGiftCodeInput();
        setMessage(queue.length
            ? `已清除 ${queue.length} 个兑换码的最近提示`
            : '没有可清除提示的兑换码');
    }

    function describeGiftCodeMailWindow(mailFeedback) {
        if (mailFeedback?.deferred === true) return '邮件请求已全部发送，回包正在后台收集';
        const accepted = Math.max(0, Number(mailFeedback?.accepted || 0));
        const already = Math.max(0, Number(mailFeedback?.already || 0));
        const rejected = Math.max(0, Number(mailFeedback?.rejected || mailFeedback?.failed || 0));
        const unconfirmed = Math.max(0, Number(mailFeedback?.timedOut || 0)) +
            Math.max(0, Number(mailFeedback?.unconfirmed || 0));
        if (accepted > 0) return `邮件确认本轮刷新成功（${accepted} 封）`;
        if (already > 0) return `邮件提示本轮尚未刷新（已领取 ${already} 封）`;
        if (rejected > 0) return `邮件本轮请求失败（${rejected} 封）`;
        if (unconfirmed > 0) return `邮件本轮反馈未确认（${unconfirmed} 封）`;
        return '邮件本轮没有可判断的服务器反馈';
    }

    async function redeemGiftCodesEachCycle(bridge) {
        const queue = readGiftCodeQueue();
        const entries = queue.filter(entry => entry.enabled);
        if (!entries.length) return '';
        if (!bridge || typeof bridge.redeemGiftCode !== 'function') return '；兑换码：接口未就绪';
        const cycleId = readState().cycleId;
        const accountId = currentGeneralUpgradeAccountId();
        const pending = [];
        for (const entry of entries) {
            if (!readState().enabled || readState().cycleId !== cycleId) break;
            const direct = entry.route === 'direct' || entry.giftId > 0 || entry.route !== 'window' && entry.code.length < 16;
            const task = Promise.resolve().then(() => bridge.redeemGiftCode(entry)).then(
                result => ({ entry, result }), error => ({ entry, result: { submitted: false, error: String(error.message || error) } }));
            pending.push(task);
            // Official window requests share a single UI; finish one before opening the next.
            if (!direct) await task;
            if (!direct && entry !== entries[entries.length - 1]) {
                await new Promise(resolve => setTimeout(resolve, GIFT_CODE_BETWEEN_MS));
            }
        }
        const results = await Promise.all(pending);
        if (readState().cycleId !== cycleId || currentGeneralUpgradeAccountId() !== accountId) return '；兑换码：旧轮结果未写入当前账号';
        const latest = readGiftCodeQueue();
        const summaries = [];
        for (const { entry, result } of results) {
            const index = latest.findIndex(item => item.code === entry.code && item.giftId === entry.giftId && item.type === entry.type && item.route === entry.route);
            if (index < 0) continue;
            const label = !result.submitted ? '请求失败' : result.accepted ? '确认成功' : result.alreadyClaimed ? '已领取' : result.confirmed ? '服务器拒绝' : '已发送未确认';
            latest[index] = { ...latest[index], attempts: result.submitted ? 1 : 0,
                status: result.serverState || (result.submitted ? 'submitted-unconfirmed' : 'request-error'),
                lastResult: label, lastResultCode: result.resultCode == null ? null : result.resultCode,
                lastRoute: result.route || entry.route, updatedAt: Date.now() };
            summaries.push(`“${entry.code}”：${label}`);
        }
        writeGiftCodeQueue(latest);
        return '；兑换码：' + summaries.join('、');
    }

    function clampPanelPosition(left, top) {
        const margin = 8;
        const visibleHeaderHeight = 48;
        return {
            left: Math.min(Math.max(margin, left), Math.max(margin, window.innerWidth - panel.offsetWidth - margin)),
            // 记录展开后面板可能接近视口高度；只要求标题栏留在屏幕内，不能把拖拽位置锁死在顶部。
            top: Math.min(Math.max(margin, top), Math.max(margin, window.innerHeight - visibleHeaderHeight - margin))
        };
    }

    function applyPanelPosition(left, top, persist = false) {
        if (!panel) return;
        const position = clampPanelPosition(left, top);
        panel.style.right = 'auto';
        panel.style.bottom = 'auto';
        panel.style.left = `${position.left}px`;
        panel.style.top = `${position.top}px`;
        if (persist) savePanelUi(position);
    }

    function setPanelCollapsed(collapsed, persist = false) {
        if (!panel || !panelPages || !panelCollapseButton) return;
        panelPages.hidden = collapsed;
        panel.style.width = collapsed ? '188px' : '348px';
        panelCollapseButton.textContent = collapsed ? '+' : '−';
        panelCollapseButton.title = collapsed ? '展开助手' : '折叠助手';
        panelCollapseButton.setAttribute('aria-label', panelCollapseButton.title);
        panelCollapseButton.setAttribute('aria-expanded', collapsed ? 'false' : 'true');
        if (persist) savePanelUi({ collapsed });
        window.requestAnimationFrame(() => {
            const rect = panel.getBoundingClientRect();
            if (panel.style.left) applyPanelPosition(rect.left, rect.top, persist);
        });
    }

    function installPanelDragHandle(handle) {
        if (!panel || !handle || handle.dataset.sgsDragHandle === '1') return;
        handle.dataset.sgsDragHandle = '1';
        let dragState = null;
        handle.addEventListener('pointerdown', (event) => {
            const interactiveTarget = event.target instanceof Element
                ? event.target.closest('button,input,select,textarea,a,summary,[role="button"],[role="tab"]')
                : null;
            if (interactiveTarget || event.isPrimary === false || (event.pointerType === 'mouse' && event.button !== 0)) return;
            const rect = panel.getBoundingClientRect();
            dragState = { pointerId: event.pointerId, offsetX: event.clientX - rect.left, offsetY: event.clientY - rect.top };
            panel.style.right = 'auto';
            panel.style.bottom = 'auto';
            panel.classList.add('local-sgs-panel-dragging');
            if (typeof handle.setPointerCapture === 'function') handle.setPointerCapture(event.pointerId);
            event.preventDefault();
        });
        handle.addEventListener('pointermove', (event) => {
            if (!dragState || event.pointerId !== dragState.pointerId) return;
            applyPanelPosition(event.clientX - dragState.offsetX, event.clientY - dragState.offsetY);
            event.preventDefault();
        });
        const finishDrag = (event) => {
            if (!dragState || event.pointerId !== dragState.pointerId) return;
            const rect = panel.getBoundingClientRect();
            dragState = null;
            panel.classList.remove('local-sgs-panel-dragging');
            if (typeof handle.releasePointerCapture === 'function') handle.releasePointerCapture(event.pointerId);
            applyPanelPosition(rect.left, rect.top, true);
        };
        handle.addEventListener('pointerup', finishDrag);
        handle.addEventListener('pointercancel', finishDrag);
    }

    function enablePanelDrag(handle, savedUi) {
        if (!panel || !handle) return;
        const savedLeft = Number(savedUi?.left);
        const savedTop = Number(savedUi?.top);
        if (Number.isFinite(savedLeft) && Number.isFinite(savedTop)) applyPanelPosition(savedLeft, savedTop);
        installPanelDragHandle(handle);
        if (panel.dataset.sgsResizeClamp !== '1') {
            panel.dataset.sgsResizeClamp = '1';
            window.addEventListener('resize', () => {
            const rect = panel.getBoundingClientRect();
            applyPanelPosition(rect.left, rect.top, true);
            });
        }
    }

    function readState() {
        const saved = storageGet(STATE_KEY, null);
        const state = saved && typeof saved === 'object'
            ? { ...defaultState, ...saved }
            : { ...defaultState };
        // 2.8.x 不再支持调相、登录提前和失败加时；始终清理旧轮次字段，避免旧状态被误读。
        state.lastWaitExtraMs = 0;
        state.lastWaitExtraKind = '';
        for (const key of Object.keys(state)) if (key.indexOf('phaseTune') === 0) delete state[key];
        if (Number(state.scheduleVersion) !== 2) {
            if (state.enabled && ['idle', 'login', 'login_submitted'].includes(state.phase) && state.offlineScheduleAnchorAt) {
                const target = Number(state.offlineScheduleAnchorAt) + readCycleMs();
                state.targetLoginAt = target;
                state.scheduledEntryAt = target;
                if (state.phase === 'idle') state.nextRunAt = Date.now();
            }
            state.scheduleVersion = 2;
        }
        return { ...state, claimMode: 'all' };
    }

    function writeState(patch, options = {}) {
        const current = readState();
        if (current.phase === 'recovery_wait' && !options.allowRecoveryTransition) {
            return current;
        }
        const next = { ...current, ...patch };
        const bridge = mailAssistantSharedBridge();
        if (bridge && Number(bridge.version) >= 7) {
            storageSet(STATE_KEY, { ...patch, scheduleVersion: 2 }, { patch: true,
                expectedCycleId: current.cycleId || '',
                requireEnabled: current.enabled === true && patch.enabled !== false });
        } else storageSet(STATE_KEY, next);
        const saved = readState();
        renderPanel(saved);
        return saved;
    }

    function readLogs() {
        const logs = storageGet(LOG_KEY, []);
        return Array.isArray(logs) ? logs : [];
    }

    function readTotalLogs() {
        const logs = storageGet(TOTAL_LOG_KEY, null);
        // 首次升级时用原来的可见记录作为总记录初始值，避免丢掉已有记录。
        return Array.isArray(logs) ? logs : readLogs();
    }

    function reportMailAssistantWatchdog(state = readState(), entries = readTotalLogs()) {
        try {
            const bridge = pageWindow && pageWindow.__SGSOL_BRIDGE__;
            if (!bridge || typeof bridge.reportMailAssistantProgress !== 'function') return;
            const officerTab = readOfficerLinkTab();
            const listenerOnly = officerTab.mode === 'listener';
            const logs = Array.isArray(entries) ? entries : [];
            const latest = logs.length ? logs[logs.length - 1] : null;
            const fingerprint = latest
                ? [
                    logs.length,
                    Number(latest.at || 0),
                    String(latest.cycleId || ''),
                    String(latest.phase || ''),
                    String(latest.message || '').slice(0, 320)
                ].join('|')
                : 'empty-log';
            bridge.reportMailAssistantProgress({
                // 监听端与接收端可同时启动两个微端进程，但二者会看到同一份共享状态。
                // 监听端只负责好友官阶观察，绝不能把接收端的运行轮次上报给自己的主进程守护。
                enabled: listenerOnly ? false : state && state.enabled === true,
                phase: listenerOnly ? 'officer_listener' : String(state && state.phase || ''),
                cycleId: listenerOnly ? '' : String(state && state.cycleId || ''),
                nextRunAt: listenerOnly ? 0 : Math.max(0, Number(state && state.nextRunAt) || 0),
                fingerprint,
                recordCount: logs.length,
                latestRecordAt: latest ? Math.max(0, Number(latest.at) || 0) : 0
            });
        } catch (_) {
            // 守护上报只能辅助恢复，任何异常都不能打断正常领取。
        }
    }

    function isRoutineLoginLogoutMessage(message) {
        return /^(?:已拦截重复的程序化登录提交|本轮登录请求已经发送，等待结果|登录请求已发送，本轮不会再次提交|已选择(?:经典版|重制版)，等待游戏加载|已选择(?:经典版|重制版)，正在点击进入（第 \d+\/\d+ 次；仍停留此页会自动重试）|已识别(?:经典版|重制版)游戏页面，继续一键领取|检测到(?:经典版|重制版)入口仍停留在登录页，已恢复自动点击重试|检测到官网账号仍处于登录状态，继续确认退出|正在退出官方账号|已确认官方账号退出(?:；周期从退出请求发送时刻开始计算)?|未找到官方退出按钮，正在刷新登录页|刷新登录页后仍未找到官方退出按钮)$/.test(String(message || '').trim());
    }

    function persistLogEntry(entry) {
        if (!entry || isRoutineLoginLogoutMessage(entry.message)) {
            return { visible: readLogs(), total: readTotalLogs() };
        }
        const visible = readLogs()
            .filter((item) => !isRoutineLoginLogoutMessage(item?.message))
            .map(normalizeLogEntry)
            .filter(isPanelLog);
        const total = readTotalLogs().filter((item) => !isRoutineLoginLogoutMessage(item?.message));
        const normalizedEntry = normalizeLogEntry(entry);
        if (isPanelLog(normalizedEntry)) visible.push(normalizedEntry);
        const previous = total[total.length - 1];
        if (previous && previous.cycleId === entry.cycleId && previous.phase === entry.phase && previous.message === entry.message) {
            return { visible, total };
        }
        total.push(entry);
        const nextVisible = visible.slice(-VISIBLE_LOG_LIMIT);
        const nextTotal = total.slice(-TOTAL_LOG_LIMIT);
        storageSet(LOG_KEY, nextVisible);
        storageSet(TOTAL_LOG_KEY, nextTotal);
        return { visible: nextVisible, total: nextTotal };
    }

    function isTransientGiftCodeProgressMessage(message) {
        return /^正在领取兑换码“[^”]+”[\s\S]*等待服务器回包/.test(String(message || '').trim());
    }

    function isTransientJsonArchiveReadinessMessage(message) {
        return /^JSON 白名单准备中：[\s\S]*保持在游戏页等待/.test(String(message || '').trim());
    }

    function freeBlessReference(message) {
        const text = String(message || '');
        const match = text.match(/免费祈福(?:(?:\([^；、]*\))|(?::[^；、]*))/);
        if (!match) return null;
        const detail = match[0].trim();
        const isDailyRewardException = /异常：[^；]*免费祈福:/.test(text);
        if (isDailyRewardException || /服务器拒绝|发包或监听失败|配置请求失败|活动入口配置\d+(?:\.\d+)?秒内未返回|活动入口无|活动入口未找到|免费状态已变化|请求异常|请求错误|接口不完整|接口无|管理器无|监听接口无|状态接口无/.test(detail)) {
            return { level: 'error', status: 'error', summary: '祈福异常', detail };
        }
        if (/服务器确认成功|状态确认已领取/.test(detail)) {
            return { level: 'success', status: 'confirmed', summary: '祈福成功', detail };
        }
        if (/未收到奖励回包|结果未确认|未捕获回包|请求已发送/.test(detail)) {
            return { level: 'success', status: 'unconfirmed', summary: '祈福未确认', detail };
        }
        return { level: 'info', status: 'not-claimable', summary: '祈福未满足条件', detail };
    }

    function shouldPersistLog(state) {
        const message = String(state?.message || '');
        if (isRoutineLoginLogoutMessage(message) || isTransientGiftCodeProgressMessage(message)) return false;
        if (isTransientJsonArchiveReadinessMessage(message)) return false;
        const isRuntimeRecovery = /(?:经典版|重制版|所选版本)加载期间已退回登录表单|(?:经典版|重制版|所选版本)加载超过 (?:30|60) 秒无结果：Electron 已刷新|检测到(?:经典版|重制版|所选版本) runtime 连续|(?:经典版|重制版|所选版本) runtime 刷新后仍未就绪/.test(message);
        const isFailureOrRetry = /失败|错误|未就绪|重试|超时|弹窗|未找到|请求出错|领取流程异常|异常\s*[1-9]\d*\s*次|微端重启|黑屏恢复/.test(message);
        /* 邮件附件记录是当前唯一的龙珠统计来源，始终保留这类轮次摘要。 */
        const isTrackedClaimSummary = /邮件附件记录/.test(message);
        const isGiftCodeActivity = /兑换码(?:[“”]|本轮|：)|正在(?:兑换|领取)兑换码/.test(message);
        const isFreeBlessOutcome = ['success', 'error'].includes(freeBlessReference(message)?.level);
        const isStrictFeatureOutcome = /\[本轮功能结果\]|\[本轮总判定\]/.test(message);
        // 修复：把“未领到 / 无可领邮件（未刷新）”这类判因信息也保留，便于回看每轮为什么没领到。
        const isClaimOutcome = /领到|到账|无可领邮件|未刷新|未确认|未增加|龙珠/.test(message);
        return isRuntimeRecovery || isFailureOrRetry || isTrackedClaimSummary || isGiftCodeActivity || isFreeBlessOutcome || isStrictFeatureOutcome || isClaimOutcome;
    }

    function appendLog(state) {
        if (!shouldPersistLog(state)) return;
        const level = classifyLogMessage(state.message, state.phase);
        const stored = persistLogEntry({
            at: state.messageAt,
            cycleId: state.cycleId,
            phase: state.phase,
            message: state.message,
            level,
            summary: compactLogSummary(state.message, level)
        });
        lastLogRenderSignature = '';
        refreshLogButtonLabel(stored.total);
    }

    const LOG_LEVEL_META = Object.freeze({
        error: { label: '错误', color: '#ff9a8e', border: '#8e4942', background: 'rgba(112,45,39,.28)' },
        warning: { label: '正常', color: '#94d39a', border: '#456f49', background: 'rgba(45,91,52,.24)' },
        recovered: { label: '已恢复', color: '#8fc8d8', border: '#466d78', background: 'rgba(45,82,91,.24)' },
        success: { label: '正常', color: '#94d39a', border: '#456f49', background: 'rgba(45,91,52,.24)' },
        info: { label: '过程', color: '#b9ad94', border: '#5f5545', background: 'rgba(70,62,50,.22)' }
    });

    function isExplicitServerFailureMessage(message) {
        const text = String(message || '');
        const jsonMailFeedback = text.match(/JSON 专用自动化完成：[\s\S]*?服务器确认成功\s*(\d+)、已领取\s*(\d+)、失败\s*(\d+)、超时\/未确认\s*(\d+)/);
        if (jsonMailFeedback) {
            const already = Number(jsonMailFeedback[2]) || 0;
            const rejected = Number(jsonMailFeedback[3]) || 0;
            if (already > 0 || rejected > 0) return true;
        }
        const countNeutralText = text
            .replace(/已领取\s*0(?:\s*封)?/g, '')
            .replace(/失败\s*0(?:\s*封)?/g, '');
        return /server-reported-already-(?:claimed|handled)|server-rejected|Result\s*(?:=|:)?\s*15\b|服务器(?:明确失败|明确返回失败|明确判定失败|提示已领取|返回已领取|表示已经领取|拒绝(?:领取)?)/i.test(countNeutralText);
    }

    function classifyLogMessage(message, phase = '') {
        const text = String(message || '');
		if (String(phase || '') === 'black-magic-orb-exchange') return 'info';
        if (/(?:经典版|重制版|所选版本)加载期间已退回登录表单|(?:经典版|重制版|所选版本)加载超过 (?:30|60) 秒无结果：Electron 已刷新|检测到(?:经典版|重制版|所选版本) runtime 连续|(?:经典版|重制版|所选版本) runtime 刷新后仍未就绪/.test(text)) return 'recovered';
        const freeBless = freeBlessReference(text);
        const strictFeatureResult = text.match(/\[本轮总判定\]\s*(成功|异常)/);
        if (strictFeatureResult) return strictFeatureResult[1] === '成功' ? 'success' : 'error';
        const jsonMailFeedback = text.match(/JSON 专用自动化完成：[\s\S]*?服务器确认成功\s*(\d+)、已领取\s*(\d+)、失败\s*(\d+)、超时\/未确认\s*(\d+)/);
        if (jsonMailFeedback) {
            const accepted = Number(jsonMailFeedback[1]) || 0;
            const already = Number(jsonMailFeedback[2]) || 0;
            const rejected = Number(jsonMailFeedback[3]) || 0;
            const unconfirmed = Number(jsonMailFeedback[4]) || 0;
            if (already > 0 || rejected > 0 || freeBless?.level === 'error') return 'error';
            if (accepted > 0 || unconfirmed > 0 || freeBless?.level === 'success') return 'success';
            return 'error';
        }
        if (freeBless?.level === 'error') return 'error';
        if (freeBless?.level === 'success') return 'success';
        const countNeutralText = text
            .replace(/已领取\s*0(?:\s*封)?/g, '')
            .replace(/失败\s*0(?:\s*封)?/g, '')
            .replace(/超时\/未确认\s*0(?:\s*封)?/g, '')
            .replace(/超时\s*0(?:\s*封)?/g, '')
            .replace(/(?:其他)?未确认\s*0(?:\s*封)?/g, '')
            .replace(/异常\s*0\s*次/g, '');
        if (isExplicitServerFailureMessage(text)) return 'error';
        if (/失败|错误|异常|未领取|未领到|未收到服务器龙珠奖励记录|无可领邮件|未刷新|请求异常|请求错误|请求出错/.test(countNeutralText)) return 'error';
        if (/server-accepted|服务器确认成功|no-response-timeout|超时|未确认|未捕获回包/.test(countNeutralText)) return 'success';
        return 'error';
    }

    function compactLogSummary(message, level = 'info') {
        const text = String(message || '').trim().replace(/\s+/g, ' ');
        const freeBless = freeBlessReference(text);
        const strictFeature = text.match(/\[本轮功能结果\][\s\S]*?\[本轮总判定\]\s*(成功|异常)（(\d+)\/(\d+) 项成功）/);
        if (strictFeature) return `功能 ${strictFeature[1]}｜${strictFeature[2]}/${strictFeature[3]} 项成功`;
        const jsonClaim = text.match(/JSON 专用自动化完成：已发送\s*(\d+)\/(\d+)\s*封；服务器确认成功\s*(\d+)、已领取\s*(\d+)、失败\s*(\d+)、超时\/未确认\s*(\d+)/);
        if (jsonClaim) {
            return `发送 ${jsonClaim[1]}/${jsonClaim[2]}｜成功 ${jsonClaim[3]}｜已领取 ${jsonClaim[4]}｜失败 ${jsonClaim[5]}｜超时未确认 ${jsonClaim[6]}${freeBless && freeBless.level !== 'info' ? `｜${freeBless.summary}` : ''}`;
        }
        if (freeBless && freeBless.level !== 'info') return freeBless.summary;
        const success = text.match(/本轮已点击\s*(\d+)\s*封领取；收到服务器奖励记录共\s*(\d+)\s*个龙珠/);
        if (success) {
            const reward = text.match(/服务器奖励记录（[^）]*）：([^；]+)/);
            return `龙珠 +${success[2]}｜邮件 ${success[1]} 封${reward ? `｜${reward[1]}` : ''}`;
        }
        const unconfirmed = text.match(/本轮发现\s*(\d+)\s*封；.*?未收到服务器龙珠奖励记录/);
        if (unconfirmed) {
            const clicked = text.match(/已点击\s*(\d+)\s*封/);
            return `未确认到账｜发现 ${unconfirmed[1]} 封${clicked ? `，点击 ${clicked[1]} 封` : ''}`;
        }
        const gift = text.match(/正在(?:兑换|领取)兑换码“([^”]+)”（本轮第\s*([^；）]+)/);
        if (gift) return `兑换码｜${gift[1]}｜${gift[2]}`;
        if (/检测到官网账号仍处于登录状态/.test(text)) return '退出账号｜官网仍登录，继续确认';

        let compact = text
            .replace(/；\[mail-reward-probe\][\s\S]*?(?=；\[mail-probe\]|；\[日常奖励|；准备退出|$)/g, '')
            .replace(/；\[mail-probe\][\s\S]*?(?=；\[日常奖励|；准备退出|$)/g, '')
            .replace(/；\[日常奖励[^\]]*\][\s\S]*?(?=；准备退出|$)/g, '')
            .replace(/（(?:mail|game|PopUpWindow)[^）]+）/gi, '')
            .replace(/；准备退出$/, '');
        if (level === 'error') compact = compact.replace(/^本轮暂未领到：/, '');
        return compact.length > 116 ? `${compact.slice(0, 113)}…` : compact;
    }

    function normalizeLogEntry(entry) {
        const message = String(entry?.message || '');
        // 始终用当前规则重分并重写历史摘要，避免旧等级或“已恢复”残留影响展示。
        const level = classifyLogMessage(message, entry?.phase);
        return {
            at: Number(entry?.at || 0),
            cycleId: String(entry?.cycleId || ''),
            phase: String(entry?.phase || ''),
            message,
            level,
            summary: compactLogSummary(message, level)
        };
    }

    function isProblemLog(entry) {
        return entry.level === 'error';
    }

    function isNormalLog(entry) {
        return entry.level === 'success';
    }

    function claimStatusMessage(message) {
        const text = String(message || '').trim();
        const freeBless = freeBlessReference(text);
        const freeBlessText = freeBless && freeBless.level !== 'info' ? `免费祈福参考：${freeBless.detail}` : '';
        const strictFeature = text.match(/\[本轮功能结果\][\s\S]*?\[本轮总判定\]\s*(成功|异常)（\d+\/\d+ 项成功）/);
        if (strictFeature) return strictFeature[0];
        const headline = text.match(/JSON 专用自动化完成：[\s\S]*?服务器确认成功\s*\d+、已领取\s*\d+、失败\s*\d+、超时\/未确认\s*\d+/);
        if (!headline) return freeBlessText;
        let result = headline[0].trim();
        const detailStart = text.indexOf('；JSON 逐封结果：', headline.index + headline[0].length);
        if (detailStart < 0) return [result, freeBlessText].filter(Boolean).join('\n');
        const stopMarkers = ['；兑换码', '；刷新状态', '；[日常奖励', '；到账', '；钱包/数值变化', '；官阶', '；未调用现场邮箱', '；准备退出'];
        let detailEnd = text.length;
        for (const marker of stopMarkers) {
            const markerIndex = text.indexOf(marker, detailStart + 1);
            if (markerIndex >= 0 && markerIndex < detailEnd) detailEnd = markerIndex;
        }
        result += text.slice(detailStart, detailEnd);
        return [result.trim(), freeBlessText].filter(Boolean).join('\n');
    }

    function isClaimStatusLog(entry) {
        return Boolean(claimStatusMessage(entry?.message));
    }

    function isPanelLog(entry) {
        return isClaimStatusLog(entry) && (isProblemLog(entry) || isNormalLog(entry));
    }

    function isRecoverableClaimProblem(entry) {
        return isProblemLog(entry) && /本轮暂未领到|未收到服务器龙珠奖励记录|mail-window-not-ready|mail-content-not-ready|game-ui-not-ready|mail-content-window-lost|领取控件|20\s*秒后重试|微端重启中断|领取阶段超过\s*180\s*秒/.test(entry.message);
    }

    function resolveRecoveredLogEntries(entries) {
        return entries;
    }

    const prepareLogEntriesCache = new WeakMap();
    function prepareLogEntries(logs) {
        if (!Array.isArray(logs)) return prepareLogEntriesUncached(logs);
        if (!prepareLogEntriesCache.has(logs)) prepareLogEntriesCache.set(logs, prepareLogEntriesUncached(logs));
        return prepareLogEntriesCache.get(logs);
    }
    function prepareLogEntriesUncached(logs) {
        return resolveRecoveredLogEntries(logs
            .map(normalizeLogEntry)
            .filter((entry) => !isRoutineLoginLogoutMessage(entry.message)));
    }

    const prepareVisibleLogEntriesCache = new WeakMap();
    function prepareVisibleLogEntries(logs) {
        if (!Array.isArray(logs)) return prepareVisibleLogEntriesUncached(logs);
        if (!prepareVisibleLogEntriesCache.has(logs)) prepareVisibleLogEntriesCache.set(logs, prepareVisibleLogEntriesUncached(logs));
        return prepareVisibleLogEntriesCache.get(logs);
    }
    function prepareVisibleLogEntriesUncached(logs) {
        return prepareLogEntries(logs).filter(isPanelLog);
    }

    function refreshLogButtonLabel(logs = readTotalLogs()) {
        if (!logButton) return;
        const entries = prepareVisibleLogEntries(logs);
        const problemCount = entries.filter(isProblemLog).length;
        logButton.textContent = problemCount ? `记录 · 异常 ${problemCount}` : '记录 · 正常';
        logButton.style.borderColor = problemCount ? '#9a6541' : '#52734f';
    }

    let logDisplayLimit = 100;
    function renderLogs(force = false) {
        if (!logBox) return;
        const totalEntries = prepareVisibleLogEntries(readTotalLogs());
        const entries = totalEntries.slice().reverse();
        const newest = entries[0];
        const totalProblemCount = totalEntries.filter(isProblemLog).length;
        const signature = `${logView}|${entries.length}|${totalEntries.length}|${totalProblemCount}|${newest?.at || 0}|${newest?.message || ''}`;
        if (!force && signature === lastLogRenderSignature) return;
        lastLogRenderSignature = signature;
        const previousScroll = logBox.scrollTop;
        const expanded = new Set(Array.from(logBox.querySelectorAll('details[open]')).map(node => node.dataset.logKey));
        while (logBox.firstChild) logBox.removeChild(logBox.firstChild);

        const problemCount = totalProblemCount;
        const normalCount = totalEntries.filter(isNormalLog).length;
        const toolbar = document.createElement('div');
        toolbar.className = 'local-sgs-log-drag-handle';
        toolbar.style.cssText = 'position:sticky;top:0;z-index:1;display:flex;align-items:center;gap:5px;padding:6px;border-bottom:1px solid #5f513c;background:#1c1711';
        const countLabel = document.createElement('span');
        countLabel.textContent = `面板 ${totalEntries.length}｜异常 ${problemCount}｜正常 ${normalCount}`;
        countLabel.title = '这里只显示最终邮件领取状态；调试和过程记录仅保留在导出日志中';
        countLabel.style.cssText = 'margin-right:auto;color:#d8c9aa;font:11px/1.2 system-ui,sans-serif';
        toolbar.appendChild(countLabel);

        for (const [view, label] of [['problem', '异常'], ['normal', '正常'], ['all', '全部']]) {
            const button = document.createElement('button');
            button.type = 'button';
            button.textContent = label;
            const active = logView === view;
            button.style.cssText = `border:1px solid ${active ? '#b38b4d' : '#665234'};border-radius:4px;padding:2px 7px;background:${active ? '#5a4224' : '#2b241a'};color:${active ? '#fff0c4' : '#b9ad94'};cursor:pointer;font-size:11px`;
            button.addEventListener('click', () => {
                logView = view;
                lastLogRenderSignature = '';
                renderLogs(true);
            });
            toolbar.appendChild(button);
        }
        const exportLogButton = document.createElement('button');
        exportLogButton.type = 'button';
        exportLogButton.textContent = '导出';
        exportLogButton.title = `导出最多 ${TOTAL_LOG_LIMIT} 条总运行记录及异常/正常统计`;
        exportLogButton.style.cssText = 'border:1px solid #55728b;border-radius:4px;padding:2px 7px;background:#243340;color:#b9d5e7;cursor:pointer;font-size:11px';
        exportLogButton.addEventListener('click', exportTotalLogs);
        toolbar.appendChild(exportLogButton);
        if (entries.length > logDisplayLimit) {
            const more = document.createElement('button');
            more.textContent = '再显示100条';
            more.addEventListener('click', () => { logDisplayLimit += 100; renderLogs(true); });
            toolbar.appendChild(more);
        }
        const clearLogButton = document.createElement('button');
        clearLogButton.type = 'button';
        clearLogButton.textContent = '清除';
        clearLogButton.title = '一键清除全部运行记录';
        clearLogButton.style.cssText = 'border:1px solid #80514a;border-radius:4px;padding:2px 7px;background:#3a2420;color:#e7b2aa;cursor:pointer;font-size:11px';
        clearLogButton.addEventListener('click', clearLogs);
        toolbar.appendChild(clearLogButton);
        logBox.appendChild(toolbar);
        installPanelDragHandle(toolbar);

        const visibleEntries = entries.filter((entry) => {
            if (logView === 'problem') return isProblemLog(entry);
            if (logView === 'normal') return isNormalLog(entry);
            return true;
        });
        if (!visibleEntries.length) {
            const empty = document.createElement('div');
            empty.textContent = logView === 'problem' ? '暂无异常记录' : '暂无对应记录';
            empty.style.cssText = 'padding:14px 8px;text-align:center;color:#8f826b;font:12px/1.4 system-ui,sans-serif';
            logBox.appendChild(empty);
            return;
        }

        for (const entry of visibleEntries.slice(0, logDisplayLimit)) {
            const meta = LOG_LEVEL_META[entry.level] || LOG_LEVEL_META.info;
            const details = document.createElement('details');
            details.dataset.logKey = String(entry.at) + ':' + String(entry.cycleId || '');
            details.open = expanded.has(details.dataset.logKey);
            details.style.cssText = `margin:6px;border:1px solid ${meta.border};border-radius:5px;background:${meta.background};overflow:hidden`;
            const summary = document.createElement('summary');
            summary.style.cssText = 'padding:6px 7px;cursor:pointer;list-style-position:inside;color:#e6dcc8;font:11px/1.35 system-ui,sans-serif';
            const badge = document.createElement('span');
            badge.textContent = meta.label;
            badge.style.cssText = `display:inline-block;min-width:38px;margin-right:6px;color:${meta.color};font-weight:700`;
            const time = document.createElement('span');
            time.textContent = new Date(entry.at).toLocaleString('zh-CN', { hour12: false });
            time.style.cssText = 'margin-right:7px;color:#94866d;font-variant-numeric:tabular-nums';
            const brief = document.createElement('span');
            brief.textContent = entry.summary;
            summary.append(badge, time, brief);

            const raw = document.createElement('pre');
            raw.textContent = claimStatusMessage(entry.message);
            raw.style.cssText = 'margin:0;padding:7px 9px;border-top:1px dashed #5b4d39;white-space:pre-wrap;word-break:break-word;background:rgba(12,10,8,.36);color:#cfc2a5;font:11px/1.45 Consolas,monospace';
            details.append(summary, raw);
            logBox.appendChild(details);
        }
        logBox.scrollTop = previousScroll;
    }

    function toggleLogs() {
        if (!logBox) return;
        logBox.hidden = !logBox.hidden;
        if (!logBox.hidden) renderLogs(true);
    }

    function exportTotalLogs() {
        const entries = prepareLogEntries(readTotalLogs()).slice(-TOTAL_LOG_LIMIT);
        const claimEntries = entries.filter(isPanelLog);
        const abnormal = claimEntries.filter(isProblemLog).length;
        const normal = claimEntries.filter(isNormalLog).length;
        const process = entries.length - claimEntries.length;
        const payload = {
            schema: 'sgsol-runtime-log/v1',
            exportedAt: new Date().toISOString(),
            scriptVersion: VERSION,
            totalLimit: TOTAL_LOG_LIMIT,
            visibleLimit: VISIBLE_LOG_LIMIT,
            count: entries.length,
            statistics: { abnormal, normal, process },
            dailyRewardTraceSummary: readDailyRewardTraceSummary(),
            dailyRewardTrace: readDailyRewardTrace(),
            entries
        };
        const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json;charset=utf-8' });
        const objectUrl = URL.createObjectURL(blob);
        const link = document.createElement('a');
        link.href = objectUrl;
        link.download = `SGSOL-总运行记录-${new Date().toISOString().replace(/[:.]/g, '-')}.json`;
        link.style.display = 'none';
        (document.body || document.documentElement).appendChild(link);
        link.click();
        link.remove();
        setTimeout(() => URL.revokeObjectURL(objectUrl), 1000);
        if (panelMessage) panelMessage.textContent = `已导出总运行记录 ${entries.length} 条（异常 ${abnormal}｜正常 ${normal}｜过程 ${process}）`;
    }

    function clearLogs() {
        storageSet(LOG_KEY, []);
        storageSet(TOTAL_LOG_KEY, []);
        lastLogRenderSignature = '';
        refreshLogButtonLabel([]);
        if (logBox) renderLogs(true);
        if (panelMessage) panelMessage.textContent = '可见记录和总运行记录均已清除';
    }

    function setMessage(message, patch = {}, options = {}) {
        const next = writeState({
            ...patch,
            message,
            messageAt: Date.now()
        }, options);
        appendLog(next);
        reportMailAssistantWatchdog(next);
        return next;
    }

    function makeCycleId() {
        return `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
    }

    function isOfficialHost(hostname = location.hostname) {
        return hostname === 'sanguosha.com' || hostname.endsWith('.sanguosha.com');
    }

    function isLoginUrl() {
        return location.hostname === 'web.sanguosha.com' && location.pathname.startsWith('/login/');
    }

    function hasLoginUi() {
        return Boolean(document.querySelector('#SGS_login-form, #selectGame'));
    }

    function findVisibleLogoutButton() {
        const candidates = [
            ...document.querySelectorAll('#logoutBtn, [data-action="logout"], button, a')
        ];
        return candidates.find((element) => {
            if (!isVisible(element)) return false;
            const text = String(element.textContent || element.value || '').trim();
            return element.id === 'logoutBtn' || /^(?:退出登录|退出账号|登出)$/.test(text);
        }) || null;
    }

    function hasLoggedOutLoginUi() {
        const form = document.querySelector('#SGS_login-form');
        const account = document.querySelector('#SGS_login-account');
        const password = document.querySelector('#SGS_login-password');
        return isLoginUrl() && !findVisibleLogoutButton() && isVisible(form) && isVisible(account) && isVisible(password);
    }

    function isVisible(element) {
        if (!element) return false;
        const style = getComputedStyle(element);
        const rect = element.getBoundingClientRect();
        return style.display !== 'none' && style.visibility !== 'hidden' && rect.width > 0 && rect.height > 0;
    }

    function formatDuration(ms) {
        const totalSeconds = Math.max(0, Math.ceil(ms / 1000));
        const minutes = Math.floor(totalSeconds / 60);
        const seconds = String(totalSeconds % 60).padStart(2, '0');
        return `${minutes}:${seconds}`;
    }

    function phaseLabel(phase) {
        return ({
            idle: '等待下轮',
            login: '准备登录',
            login_submitted: '等待登录结果',
            game_loading: '等待所选版本加载',
            claiming: '正在一键领取',
            logout_pending: '准备退出登录',
            recovery_wait: '微端恢复等待',
            stopped: '已暂停'
        })[phase] || phase;
    }

    function requestTopNavigation(url) {
        if (TOP_WINDOW) {
            location.assign(url);
            return;
        }
        window.top.postMessage({ type: MESSAGE_TYPE, action: 'navigate', url }, '*');
    }

    function nextAdaptiveBackoffMs(previousMs, baseMs) {
        // 沿阶梯抬到“比当前和基础间隔都更大”的下一档；阶梯只含实测稳定值(60/180)，避开不稳的 40s。
        for (const step of ADAPTIVE_INTERVAL_LADDER_MS) {
            if (step > previousMs && step > baseMs) return Math.min(step, ADAPTIVE_INTERVAL_MAX_MS);
        }
        return Math.min(ADAPTIVE_INTERVAL_MAX_MS, Math.max(baseMs, previousMs));
    }

    function resolveNextIntervalMs(current, options) {
        const baseMs = readCycleMs();
        if (!ADAPTIVE_INTERVAL_ENABLED) return baseMs;
        const cycleId = current.cycleId;
        const keepCurrent = () => Math.min(ADAPTIVE_INTERVAL_MAX_MS, Math.max(baseMs, Number(current.adaptiveIntervalMs) || baseMs));
        const backoff = () => nextAdaptiveBackoffMs(Math.max(baseMs, Number(current.adaptiveIntervalMs) || baseMs), baseMs);
        // 优先用本轮领取的“确定性结论”(lastClaimOutcome)决定下一轮间隔：
        //   claimed=确认到账→回基础快间隔；no-mail/no-grant=确认没领到→退避等刷新；unconfirmed=未开核对无法确认→保持当前档(不退避不加速)。
        const outcome = current.lastClaimOutcomeCycle === cycleId ? String(current.lastClaimOutcome || '') : '';
        if (outcome === 'claimed' || options.completed) return baseMs;
        if (outcome === 'no-mail' || outcome === 'no-grant' || options.backoff) return backoff();
        if (outcome === 'unconfirmed') return keepCurrent();
        // 兼容无 outcome 的旧路径（如“近期已登录、本轮跳过”等中性结束）。
        const actuallyClaimed = Boolean(cycleId) && current.mailClaimedForCycle === cycleId;
        if (actuallyClaimed) return baseMs;
        const claimStepDoneButNoMail = Boolean(cycleId) && current.claimSucceededFor === cycleId && current.mailClaimedForCycle !== cycleId;
        if (claimStepDoneButNoMail) return backoff();
        return keepCurrent();
    }


    function claimCompletionSchedulePatch(completedAt, forcedFailure = false) {
        return { cycleHadClaimFailure: Boolean(readState().cycleHadClaimFailure) || forcedFailure,
            lastWaitExtraMs: 0, lastWaitExtraKind: '', scheduledEntryAt: 0, nextRunAt: 0,
            targetLoginAt: 0, plannedLoginDispatchAt: 0, offlineScheduleAnchorAt: 0 };
    }

    function finishCycle(message, options = {}) {
        const now = Date.now();
        const current = readState();
        if (readOfficerLinkTab().mode !== 'timer') {
            return finishOfficerModeCycle(message, options);
        }
        if (current.cycleId && current.scheduleFinalizedForCycle === current.cycleId) {
            if (current.phase === 'idle' && Number(current.nextRunAt || 0) > 0) return current;
            const retainedIntervalMs = Math.max(CYCLE_MIN_MS, Number(current.adaptiveIntervalMs) || readCycleMs());
            const retainedExtraMs = 0;
            const retainedAnchorAt = Number(current.offlineScheduleAnchorAt)
                || Number(current.lastLogoutStartedAt)
                || now;
            const retainedSchedule = buildOfflineLoginSchedule(retainedAnchorAt, retainedIntervalMs, retainedExtraMs);
            clearScheduledLoginTimer();
            return setMessage('检测到同一轮重复退出确认：已恢复首次生成的登录计划，不重新计算周期', {
                ...retainedSchedule,
                phase: 'idle',
                forceLogin: false,
                retryAt: 0,
                retryAction: '',
                logoutAttemptAt: 0,
                logoutUiStableSince: 0,
                logoutPageRefreshAt: 0
            });
        }
        const claimedThisCycle = Boolean(current.cycleId) && current.claimSucceededFor === current.cycleId;
        const intervalMs = resolveNextIntervalMs(current, options);
        const extraWaitMs = 0;
        const extraWaitKind = "";
        const requestedAnchorAt = Number(options.scheduleAnchorAt);
        const scheduleAnchorAt = Number.isFinite(requestedAnchorAt) && requestedAnchorAt > 0
            ? Math.min(now, requestedAnchorAt)
            : now;
        const schedule = buildOfflineLoginSchedule(scheduleAnchorAt, intervalMs, extraWaitMs);
        const finalMessage = message;
        clearScheduledLoginTimer();
        return setMessage(finalMessage, {
            ...schedule,
            phase: 'idle',
            forceLogin: false,
            claimMode: 'all',
            retryAt: 0,
            retryAction: '',
            logoutAttemptAt: 0,
            logoutUiStableSince: 0,
            logoutPageRefreshAt: 0,
            adaptiveIntervalMs: intervalMs,
            lastWaitExtraMs: extraWaitMs,
            lastWaitExtraKind: extraWaitKind,
            scheduleFinalizedForCycle: current.cycleId,
            ...(options.logoutConfirmed === true ? { lastLogoutStartedAt: scheduleAnchorAt } : {}),
            ...(options.logoutConfirmed === true ? { lastLogoutConfirmedAt: now } : {}),
            ...((options.completed || claimedThisCycle) ? { lastCompleteAt: now } : {})
        });
    }



    function readWatchdogRecoverySignal() {
        if (!TOP_WINDOW) return null;
        try {
            const bridge = pageWindow && pageWindow.__SGSOL_BRIDGE__;
            if (!bridge || typeof bridge.readRecoverySignal !== 'function') return null;
            const signal = bridge.readRecoverySignal();
            const id = String((signal && signal.id) || '');
            const resumeNotBefore = Date.parse(String((signal && signal.resumeNotBefore) || ''));
            if (!signal || Number(signal.schemaVersion) !== 1 || signal.type !== WATCHDOG_RECOVERY_SIGNAL_TYPE || !id || !Number.isFinite(resumeNotBefore)) return null;
            return { id, resumeNotBefore };
        } catch (_) {
            return null;
        }
    }

    function clearLoginLock() {
        try {
            localStorage.removeItem(LOGIN_LOCK_KEY);
        } catch (_) {
            // 锁清理失败时仍会创建新轮，登录页会用新的轮次编号重新判定。
        }
    }

    function stopCurrentCycleForWatchdogRecovery(state, signal) {
        const now = Date.now();
        const recoveryPatch = {
            recoveryHoldId: signal.id,
            recoveryHoldUntil: now,
            recoveryResetForId: signal.id,
            recoveryTriggeredAt: now
        };

        if (!state.enabled) {
            return writeState(recoveryPatch, { allowRecoveryTransition: true });
        }

        clearLoginLock();
        return setMessage(
            '检测到微端重启：已终止旧轮并清除旧重试；立即开启全新一轮',
            {
                ...recoveryPatch,
                enabled: true,
                forceLogin: false,
                claimMode: 'all',
                phase: 'recovery_wait',
                cycleId: '',
                nextRunAt: now,
                targetLoginAt: now,
                plannedLoginDispatchAt: now,
                offlineScheduleAnchorAt: now,
                loginSubmittedAt: 0,
                gameLaunchAt: 0,
                classicEntryAttemptCount: 0,
                classicEntryLastAttemptAt: 0,
                classicEntryStartedAt: 0,
                claimStartedFor: '',
                claimSucceededFor: '',
                logoutClickedFor: '',
                logoutAttemptAt: 0,
                logoutUiStableSince: 0,
                logoutPageRefreshAt: 0,
                retryAt: 0,
                retryAction: '',
                retryCount: 0,
                lastCompleteAt: 0
            },
            { allowRecoveryTransition: true }
        );
    }

    function applyWatchdogRecovery(state) {
        const signal = readWatchdogRecoverySignal();
        if (!signal || state.recoveryResetForId === signal.id) return state;
        return stopCurrentCycleForWatchdogRecovery(state, signal);
    }

    function startFreshCycleAfterWatchdogRecovery(state) {
        if (!state.enabled || state.phase !== 'recovery_wait') return state;
        const now = Date.now();
        clearLoginLock();
        return startCycle({
            fromWatchdogRecovery: true,
            scheduledDispatchAt: now,
            targetLoginAt: now
        });
    }

    function recoverInterruptedClaimingState(state) {
        if (!TOP_WINDOW || workerBusy || !state.enabled || state.phase !== 'claiming') return state;
        const claimingMarkedAt = Math.max(
            Number(state.messageAt || 0),
            Number(state.gameLaunchAt || 0)
        );
        const inheritedFromPreviousProcess = claimingMarkedAt <= 0 ||
            claimingMarkedAt < RUNTIME_INSTANCE_STARTED_AT;
        const exceededHardLimit = claimingMarkedAt > 0 &&
            Date.now() - claimingMarkedAt >= CLAIM_CALL_TIMEOUT_MS + 60 * 1000;
        if (!inheritedFromPreviousProcess && !exceededHardLimit) return state;

        const now = Date.now();
        const resumeOnLoadedGamePage = !isLoginUrl() && !hasLoginUi();
        return setMessage(
            inheritedFromPreviousProcess
                ? '检测到微端重启中断上一轮领取：已自动恢复并重新执行本轮'
                : '检测到领取阶段超过 180 秒未结束：已自动恢复并重新执行本轮',
            {
                phase: resumeOnLoadedGamePage ? 'game_loading' : 'login',
                loginSubmittedAt: resumeOnLoadedGamePage ? state.loginSubmittedAt : 0,
                gameLaunchAt: resumeOnLoadedGamePage ? now - GAME_LOAD_WAIT_MS : 0,
                claimStartedFor: '',
                claimSucceededFor: '',
                retryAt: 0,
                retryAction: ''
            },
            { allowRecoveryTransition: true }
        );
    }

    function withTimeout(promise, timeoutMs, message) {
        return Promise.race([
            Promise.resolve(promise),
            new Promise((_, reject) => {
                setTimeout(() => reject(new Error(message)), timeoutMs);
            })
        ]);
    }

    function clearScheduledLoginTimer() {
        if (scheduledLoginTimerId) window.clearTimeout(scheduledLoginTimerId);
        scheduledLoginTimerId = 0;
        scheduledLoginTimerAt = 0;
    }

    async function prepareScheduledLoginPage(state) {
        if (!TOP_WINDOW || !state?.enabled || state.phase !== 'idle' || !isLoginUrl() || !hasLoggedOutLoginUi()) return false;
        const account = document.querySelector('#SGS_login-account');
        const password = document.querySelector('#SGS_login-password');
        if (!account || !password) return false;
        restoreSessionCredentials(account, password);
        if (account.value && password.value) cacheSessionCredentials(account, password);
        const protocolReady = await ensureProtocolAccepted();
        return Boolean(account.value && password.value && protocolReady);
    }

    async function dispatchScheduledLoginEarly(state = readState()) {
        if (!TOP_WINDOW || scheduledLoginDispatchBusy) return false;
        if (readOfficerLinkTab().mode !== 'timer') return false;
        const current = readState();
        const entryAt = Number(current.scheduledEntryAt || current.targetLoginAt || 0);
        if (!current.enabled || current.phase !== 'idle' || !isLoginUrl() || !hasLoggedOutLoginUi() || entryAt <= Date.now()) return false;
        scheduledLoginDispatchBusy = true;
        try {
            const loginReady = await prepareScheduledLoginPage(current);
            if (!loginReady) return false;
            const latest = readState();
            const latestEntryAt = Number(latest.scheduledEntryAt || latest.targetLoginAt || 0);
            if (!latest.enabled || latest.phase !== 'idle' || latest.cycleId !== current.cycleId || latestEntryAt <= Date.now()) return false;
            clearScheduledLoginTimer();
            startCycle({
                prepareVersionPage: true,
                scheduledDispatchAt: Date.now(),
                targetLoginAt: latestEntryAt,
                gameEntryTarget: latest.gameEntryTarget
            });
            await handleLoginPage();
            return true;
        } finally {
            scheduledLoginDispatchBusy = false;
        }
    }

    async function dispatchScheduledLogin(expectedDispatchAt = 0) {
        if (!TOP_WINDOW || scheduledLoginDispatchBusy) return false;
        if (readOfficerLinkTab().mode !== 'timer') return false;
        const state = readState();
        const dispatchAt = Number(state.nextRunAt) || 0;
        if (!state.enabled || state.phase !== 'idle' || dispatchAt <= 0) return false;
        if (expectedDispatchAt > 0 && Math.abs(dispatchAt - expectedDispatchAt) > 5) return false;
        if (Date.now() + 5 < dispatchAt) {
            armScheduledLogin(state);
            return false;
        }

        scheduledLoginDispatchBusy = true;
        clearScheduledLoginTimer();
        try {
            if (!isLoginUrl()) {
                requestTopNavigation(LOGIN_URL);
                return false;
            }
            const loginReady = await prepareScheduledLoginPage(state);
            if (!loginReady) {
                const staleLogout = findVisibleLogoutButton();
                if (staleLogout && isVisible(staleLogout)) {
                    const now = Date.now();
                    const latestBeforeLogout = readState();
                    setMessage('定时登录到点但账号仍在版本选择页：禁止启动新轮，继续执行真正退出；首次进入计划保持不变', {
                        phase: 'logout_pending',
                        nextRunAt: 0,
                        logoutClickedFor: latestBeforeLogout.cycleId,
                        logoutAttemptAt: now,
                        logoutUiStableSince: 0,
                        logoutPageRefreshAt: 0,
                        retryAt: 0,
                        retryAction: ''
                    });
                    pushRawLog('logout-timing', `定时登录拦截：账密表单未出现且退出按钮仍可见 @ ${new Date(now).toISOString()}`);
                    staleLogout.click();
                } else {
                    requestTopNavigation(LOGIN_URL);
                }
                return false;
            }
            const latest = readState();
            if (!latest.enabled || latest.phase !== 'idle' || Number(latest.nextRunAt) !== dispatchAt) return false;
            const scheduledEntryAt = Number(latest.scheduledEntryAt || latest.targetLoginAt || 0);
            if (scheduledEntryAt > Date.now()) {
                clearScheduledLoginTimer();
                startCycle({
                    prepareVersionPage: true,
                    scheduledDispatchAt: Date.now(),
                    targetLoginAt: scheduledEntryAt,
                    gameEntryTarget: latest.gameEntryTarget
                });
                await handleLoginPage();
                return true;
            }
            startCycle({
                scheduledDispatchAt: dispatchAt,
                targetLoginAt: Number(latest.targetLoginAt) || dispatchAt
            });
            await handleLoginPage();
            return true;
        } finally {
            scheduledLoginDispatchBusy = false;
        }
    }

    function armScheduledLogin(state = readState()) {
        if (!TOP_WINDOW || readOfficerLinkTab().mode !== 'timer' || !state.enabled || state.phase !== 'idle') {
            clearScheduledLoginTimer();
            return;
        }
        const dispatchAt = Number(state.nextRunAt) || 0;
        if (dispatchAt <= 0) return;
        if (scheduledLoginTimerId && Math.abs(scheduledLoginTimerAt - dispatchAt) <= 5) return;
        clearScheduledLoginTimer();
        scheduledLoginTimerAt = dispatchAt;
        const delayMs = Math.max(0, dispatchAt - Date.now());
        scheduledLoginTimerId = window.setTimeout(() => {
            scheduledLoginTimerId = 0;
            scheduledLoginTimerAt = 0;
            void dispatchScheduledLogin(dispatchAt);
        }, delayMs);
    }

    function startCycle(options = {}) {
        const state = readState();
        if (!state.enabled) return;
        const gameEntryTarget = normalizeGameEntryTarget(options.gameEntryTarget || readGameEntryTarget());
        const fromWatchdogRecovery = Boolean(options.fromWatchdogRecovery);
        const prepareVersionPage = Boolean(options.prepareVersionPage);
        const cycleId = makeCycleId();
        const forceLogin = Boolean(options.forceLogin);
        const scheduledDispatchAt = forceLogin || prepareVersionPage
            ? Date.now()
            : (Number(options.scheduledDispatchAt) || Number(state.nextRunAt) || Date.now());
        const targetLoginAt = forceLogin
            ? scheduledDispatchAt
            : (Number(options.targetLoginAt) || Number(state.targetLoginAt) || scheduledDispatchAt);
        if (state.phase === 'recovery_wait' && !fromWatchdogRecovery && !forceLogin) return state;
        const claimMode = options.claimMode === 'first' ? 'first' : 'all';
        const startMessage = fromWatchdogRecovery
            ? '微端恢复完成：已创建全新一轮，前往官方登录页'
            : (claimMode === 'all'
            ? (forceLogin ? '强制立即执行：准备领取全部邮件' : (prepareVersionPage
                ? '已完成退出：登录后停留在版本选择页，倒计时结束进入游戏'
                : '开始本轮：前往官方登录页并领取全部邮件'))
            : (forceLogin ? '强制立即执行：忽略近期登录请求' : '开始本轮：前往官方登录页'));
        const next = setMessage(startMessage, {
            phase: 'login',
            forceLogin,
            claimMode,
            cycleId,
            loginSubmittedAt: 0,
            loginContainerRecoveryCycleId: '',
            loginContainerRecoveryLastAt: 0,
            loginContainerRecoveryCount: 0,
            gameLaunchAt: 0,
            gameRuntimeWaitStartedAt: 0,
            gameRuntimeRecoveryCount: 0,
            gameRuntimeRecoveryLastAt: 0,
            gameRuntimeRecoveryKind: '',
            gameRuntimeRecoveryLoggedAt: 0,
            gameEntryTarget,
            classicEntryAttemptCount: 0,
            classicEntryLastAttemptAt: 0,
            classicEntryStartedAt: 0,
            claimStartedFor: '',
            claimSucceededFor: '',
            logoutClickedFor: '',
            logoutAttemptAt: 0,
            logoutUiStableSince: 0,
            logoutPageRefreshAt: 0,
            retryAt: 0,
            retryAction: '',
            retryCount: 0,
            cycleHadClaimFailure: false,
            lastWaitExtraMs: 0,
            lastWaitExtraKind: '',
            scheduleFinalizedForCycle: '',
            targetLoginAt,
            scheduledEntryAt: prepareVersionPage && targetLoginAt > Date.now() ? targetLoginAt : 0,
            plannedLoginDispatchAt: scheduledDispatchAt,
            nextRunAt: scheduledDispatchAt
        }, { allowRecoveryTransition: fromWatchdogRecovery || forceLogin });
        if (!isLoginUrl()) requestTopNavigation(LOGIN_URL);
        return next;
    }

    function setInputValue(input, value) {
        const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set;
        if (setter) setter.call(input, value);
        else input.value = value;
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
    }

    function restoreSessionCredentials(account, password) {
        const persisted = storageGet(CREDENTIALS_KEY, null);
        const persistedAccount = persisted && typeof persisted === 'object' ? String(persisted.account || '') : '';
        const persistedPassword = persisted && typeof persisted === 'object' ? String(persisted.password || '') : '';
        const cachedAccount = sessionStorage.getItem(SESSION_ACCOUNT_KEY) || persistedAccount;
        const cachedPassword = sessionStorage.getItem(SESSION_PASSWORD_KEY) || persistedPassword;
        if (!account.value && cachedAccount) setInputValue(account, cachedAccount);
        if (!password.value && cachedPassword) setInputValue(password, cachedPassword);
        cacheSessionCredentials(account, password);
    }

    function cacheSessionCredentials(account, password) {
        if (!account.value || !password.value) return;
        sessionStorage.setItem(SESSION_ACCOUNT_KEY, account.value);
        sessionStorage.setItem(SESSION_PASSWORD_KEY, password.value);
        storageSet(CREDENTIALS_KEY, { account: account.value, password: password.value });
    }

    function cacheCredentialsFromLoginPage() {
        const account = document.querySelector('#SGS_login-account');
        const password = document.querySelector('#SGS_login-password');
        if (account && password) cacheSessionCredentials(account, password);
    }

    function installCredentialSessionCache() {
        const cacheWhenCredentialsChange = (event) => {
            const target = event.target;
            if (target?.matches?.('#SGS_login-account, #SGS_login-password')) cacheCredentialsFromLoginPage();
        };
        document.addEventListener('input', cacheWhenCredentialsChange, true);
        document.addEventListener('change', cacheWhenCredentialsChange, true);
        document.addEventListener('submit', (event) => {
            if (event.target?.matches?.('#SGS_login-form')) cacheCredentialsFromLoginPage();
        }, true);
        document.addEventListener('keydown', (event) => {
            if (event.key === 'Enter' && event.target?.matches?.('#SGS_login-account, #SGS_login-password')) {
                cacheCredentialsFromLoginPage();
            }
        }, true);
    }

    function clearSessionCredentials() {
        sessionStorage.removeItem(SESSION_ACCOUNT_KEY);
        sessionStorage.removeItem(SESSION_PASSWORD_KEY);
        storageRemove(CREDENTIALS_KEY);
        setMessage('已清除本机保存的账号密码');
    }

    async function ensureProtocolAccepted() {
        const checkbox = document.querySelector('#SGS_userProto');
        if (!checkbox) return false;
        if (!checkbox.checked) {
            checkbox.click();
            await new Promise((resolve) => setTimeout(resolve, 120));
        }
        if (!checkbox.checked) {
            const setter = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'checked')?.set;
            if (setter) setter.call(checkbox, true);
            else checkbox.checked = true;
            checkbox.dispatchEvent(new Event('input', { bubbles: true }));
            checkbox.dispatchEvent(new Event('change', { bubbles: true }));
        }
        if (checkbox.checked) checkbox.parentElement?.classList.add('on');
        return checkbox.checked;
    }

    function readLoginLock() {
        try {
            const lock = JSON.parse(localStorage.getItem(LOGIN_LOCK_KEY) || 'null');
            return lock && typeof lock === 'object' ? lock : null;
        } catch (_) {
            return null;
        }
    }

    function writeLoginLock(cycleId) {
        localStorage.setItem(LOGIN_LOCK_KEY, JSON.stringify({ cycleId, at: Date.now() }));
    }

    function activeLoginLock() {
        const lock = readLoginLock();
        return lock && Date.now() - Number(lock.at || 0) < readCycleMs() ? lock : null;
    }

    function installLoginClickGuard() {
        document.addEventListener('click', (event) => {
            const button = event.target?.closest?.('#SGS_login-btn');
            if (!button) return;
            cacheCredentialsFromLoginPage();

            const authorizedCycle = button.dataset.localSgsAuthorizedCycle || '';
            if (authorizedCycle) {
                delete button.dataset.localSgsAuthorizedCycle;
                writeLoginLock(authorizedCycle);
                return;
            }

            if (event.isTrusted) {
                writeLoginLock('manual');
                return;
            }

            if (activeLoginLock()) {
                event.preventDefault();
                event.stopImmediatePropagation();
                setMessage('已拦截重复的程序化登录提交');
                return;
            }

            writeLoginLock('external-script');
        }, true);
    }

    function popupRetryAction(state) {
        if (['login', 'login_submitted'].includes(state.phase)) return 'login';
        if (state.phase === 'game_loading') return 'enter_game';
        if (state.phase === 'claiming') return 'claim';
        if (state.phase === 'logout_pending') return 'logout';
        return '';
    }

    function schedulePopupRetry(message) {
        const state = readState();
        const action = popupRetryAction(state);
        if (!state.enabled || !action) return false;

        const retryAt = Date.now() + RETRY_WAIT_MS;
        const patch = {
            retryAt,
            retryAction: action,
            retryCount: Number(state.retryCount || 0) + 1
        };

        if (action === 'login') {
            patch.phase = 'login';
            patch.loginSubmittedAt = 0;
        } else if (action === 'enter_game') {
            patch.phase = 'login_submitted';
            patch.gameLaunchAt = 0;
        } else if (action === 'claim') {
            patch.phase = 'game_loading';
            patch.gameLaunchAt = Date.now() - GAME_LOAD_WAIT_MS;
            patch.claimStartedFor = '';
        } else if (action === 'logout') {
            patch.phase = 'logout_pending';
            patch.logoutClickedFor = '';
            patch.logoutAttemptAt = 0;
            patch.logoutPageRefreshAt = 0;
        }

        const summary = String(message ?? '').trim().replace(/\s+/g, ' ').slice(0, 120) || '未知提示';
        setMessage(`官网弹窗：${summary}；20 秒后重试`, patch);
        return true;
    }

    function rebuildLoginContainerAfterTimeout(message) {
        const summary = String(message ?? '').trim().replace(/\s+/g, ' ').slice(0, 120);
        if (!/请求超时[，,：:\s]*请稍后再试|登录(?:请求)?超时/i.test(summary)) return false;

        const state = readState();
        if (!state.enabled || !['login', 'login_submitted'].includes(state.phase) || !state.cycleId) return false;
        if (state.loginContainerRecoveryCycleId === state.cycleId) return false;

        let bridge = null;
        try { bridge = pageWindow.__SGSOL_BRIDGE__; } catch (_) {}
        if (!bridge || typeof bridge.requestWebviewRecovery !== 'function') return false;

        cacheCredentialsFromLoginPage();
        clearLoginLock();
        const now = Date.now();
        setMessage(`官网弹窗：${summary || '登录请求超时'}；正在通过微端原生 OL 入口刷新页面，3 秒后重新登录`, {
            phase: 'login',
            loginSubmittedAt: 0,
            loginContainerRecoveryCycleId: state.cycleId,
            loginContainerRecoveryLastAt: now,
            loginContainerRecoveryCount: Number(state.loginContainerRecoveryCount || 0) + 1,
            classicEntryAttemptCount: 0,
            classicEntryLastAttemptAt: 0,
            classicEntryStartedAt: 0,
            gameLaunchAt: 0,
            retryAt: now + LOGIN_CONTAINER_RETRY_AFTER_REBUILD_MS,
            retryAction: 'login',
            retryCount: Number(state.retryCount || 0) + 1
        });
        pushRawLog('login-container-recovery', `官网登录请求超时：已请求微端原生 OL 刷新；cycle=${state.cycleId}`);

        const response = bridge.requestWebviewRecovery({
            kind: 'app-ol-refresh',
            cycleId: state.cycleId
        });
        if (response && response.ok === true) return true;

        writeState({
            loginContainerRecoveryCycleId: '',
            loginContainerRecoveryLastAt: 0
        });
        return false;
    }

    function describeClaimCause(error) {
        // 把 claim 返回的英文错误码翻成“到底为什么没领到”，便于在运行记录里区分“无可领/未刷新”与“界面没跟上”。
        const raw = String(error || '');
        if (/initial-open-control-not-found/i.test(raw)) return '邮箱已打开但领取控件未出现（多为无可领/未刷新，偶尔是界面未稳）';
        if (/mail-content-window-lost/i.test(raw)) return '邮箱内容窗口丢失（界面抖动）';
        if (/mail-content-not-ready/i.test(raw)) return '邮箱内容未就绪（界面未加载稳）';
        if (/PopUpWindow.*(?:null|undefined)/i.test(raw)) return '邮箱弹窗未就绪（可能无可领，或界面未稳）';
        if (/^game-ui-not-ready/i.test(raw)) return '游戏界面还没加载好';
        if (/^mail-window-not-ready/i.test(raw)) return '邮箱窗口未就绪';
        return raw || '未知原因';
    }

    function scheduleMailboxRetry(state, error) {
        const nextRetryCount = Number(state.retryCount || 0) + 1;
        // 修复：重试次数封顶。原逻辑每 20 秒无限重试，页面改版/接口长期不就绪时会一直空转刷屏；
        // 超过上限就结束本轮、按正常周期等待下一轮，避免卡死在 game_loading。
        if (nextRetryCount > MAX_MAILBOX_RETRIES) {
            finishCycle(`本轮未领到：${describeClaimCause(error)}（${error}）；已达到 ${MAX_MAILBOX_RETRIES} 次重试上限，本轮结束并按设定周期等待下一轮`, { claimFailure: true });
            return;
        }
        const retryAt = Date.now() + RETRY_WAIT_MS;
        setMessage(`本轮暂未领到：${describeClaimCause(error)}（${error}）；20 秒后重试一次（第 ${nextRetryCount}/${MAX_MAILBOX_RETRIES} 次）`, {
            phase: 'game_loading',
            gameLaunchAt: Date.now() - GAME_LOAD_WAIT_MS,
            claimStartedFor: '',
            retryAt,
            retryAction: 'claim',
            retryCount: nextRetryCount
        });
    }

    function handleNativeDialog(message) {
        const text = String(message ?? '');
        if (rebuildLoginContainerAfterTimeout(text)) return true;
        if (!schedulePopupRetry(text)) return false;
        const retryState = readState();
        if (retryState.retryAction === 'logout' && isLoginUrl()) requestTopNavigation(LOGIN_URL);
        return true;
    }

    function installTimeoutAlertGuard() {
        try {
            const receiveEarlyDialog = (event) => {
                const detail = event?.detail;
                handleNativeDialog(detail && typeof detail === 'object' ? detail.message : detail);
            };
            pageWindow.addEventListener(EARLY_DIALOG_EVENT, receiveEarlyDialog);
            const queuedDialogs = Array.isArray(pageWindow[EARLY_DIALOG_QUEUE_KEY]) ? pageWindow[EARLY_DIALOG_QUEUE_KEY].splice(0) : [];
            for (const dialog of queuedDialogs) handleNativeDialog(dialog?.message);

            const nativeAlert = pageWindow.alert.bind(pageWindow);
            pageWindow.alert = function (message) {
                if (handleNativeDialog(message)) return;
                // 修复：微端 preload 会把原生 alert 换成静默桩，导致“未被识别的官网弹窗”（含风险提示）
                // 既不弹出也无痕迹。放行给（可能已是桩的）nativeAlert 前，先打一条可见日志，
                // 让被吞掉的提示至少能在控制台看到；根因修复见随附的可选 electron_renderer.js。
                try { console.warn('[邮件助手] 官网弹窗（未拦截，可能被微端静默）:', String(message ?? '')); } catch (_) {}
                nativeAlert(message);
            };
        } catch (_) {
            // 替换失败时保留官网原始提示。
        }
    }

    async function submitLoginOnce(state) {
        const account = document.querySelector('#SGS_login-account');
        const password = document.querySelector('#SGS_login-password');
        const submit = document.querySelector('#SGS_login-btn');
        if (!account || !password || !submit || !isVisible(submit)) return;

        restoreSessionCredentials(account, password);
        if (!account.value || !password.value) {
            setMessage('等待密码管理器填充，或请在本标签页手动输入一次');
            return;
        }

        cacheSessionCredentials(account, password);
        setInputValue(account, account.value);
        setInputValue(password, password.value);

        if (!await ensureProtocolAccepted()) {
            finishCycle('协议未能自动勾选；本轮已停止');
            return;
        }

        const lock = activeLoginLock();
        const isScheduledRetry = state.retryAction === 'login' && Number(state.retryAt || 0) <= Date.now();
        if (lock && !state.forceLogin && !isScheduledRetry) {
            if (lock.cycleId === state.cycleId) {
                setMessage('本轮登录请求已经发送，等待结果', {
                    phase: 'login_submitted',
                    loginSubmittedAt: Number(lock.at || Date.now())
                });
            } else {
                finishCycle('检测到近期已有登录请求；本轮不重复发送');
            }
            return;
        }

        writeLoginLock(state.cycleId);
        submit.dataset.localSgsAuthorizedCycle = state.cycleId;
        const actualDispatchAt = Date.now();
        const plannedDispatchAt = Number(state.plannedLoginDispatchAt) || actualDispatchAt;
        const targetLoginAt = Number(state.targetLoginAt) || plannedDispatchAt;
        const localDispatchErrorMs = actualDispatchAt - plannedDispatchAt;
        const targetOffsetMs = actualDispatchAt - targetLoginAt;
        setMessage(Number(state.scheduledEntryAt || 0) > actualDispatchAt
            ? `登录请求已发送；将在${gameEntryLabel(state.gameEntryTarget || readGameEntryTarget())}版本页等待倒计时结束`
            : '登录请求已发送，本轮不会再次提交', {
            phase: 'login_submitted',
            loginSubmittedAt: actualDispatchAt,
            lastLoginDispatchAt: actualDispatchAt,
            lastLoginDispatchErrorMs: localDispatchErrorMs,
            classicEntryAttemptCount: 0,
            classicEntryLastAttemptAt: 0,
            classicEntryStartedAt: 0,
            retryAt: 0,
            retryAction: ''
        });
        submit.click();
    }

    async function enterSelectedGameOnce(state) {
        const target = normalizeGameEntryTarget(state.gameEntryTarget || readGameEntryTarget());
        const entryLabel = gameEntryLabel(target);
        const gameCard = findGameEntryCard(target);
        const enter = document.querySelector('#goInGameBtn');
        if (!gameCard || !enter || !isVisible(gameCard) || !isVisible(enter)) return false;

        const now = Date.now();
        const scheduledEntryAt = Number(state.scheduledEntryAt || 0);
        if (state.scheduledEntryAt && scheduledEntryAt > now) {
            // 已提前登录并抵达版本选择页：只停留等待，不提前点击“进入游戏”。
            // 倒计时仍由 scheduledEntryAt 驱动，避免把登录结果等待误判成 30 秒超时。
            return true;
        }
        const lastAttemptAt = Number(state.classicEntryLastAttemptAt || 0);
        if (lastAttemptAt && now - lastAttemptAt < CLASSIC_ENTRY_RETRY_MS) return true;

        const previousAttempts = Math.max(0, Number(state.classicEntryAttemptCount || 0));
        if (previousAttempts >= CLASSIC_ENTRY_MAX_ATTEMPTS) {
            finishCycle(`${entryLabel}进入按钮连续点击 ${previousAttempts} 次仍未离开登录页；本轮停止，下一轮再试`, { backoff: true });
            return true;
        }

        gameCard.click();
        await new Promise((resolve) => setTimeout(resolve, CLASSIC_SELECT_SETTLE_MS));

        // 选择版本后官网会重绘入口区域，旧的 #goInGameBtn 节点可能已经脱离
        // document。必须重新查询并验证新按钮，否则一次无效点击会永久卡住。
        const latestState = readState();
        if (!latestState.enabled
            || latestState.cycleId !== state.cycleId
            || !['login', 'login_submitted'].includes(latestState.phase)) {
            return true;
        }
        const freshEnter = document.querySelector('#goInGameBtn');
        const disabled = !freshEnter
            || !isVisible(freshEnter)
            || freshEnter.disabled === true
            || freshEnter.hasAttribute('disabled')
            || freshEnter.getAttribute('aria-disabled') === 'true'
            || freshEnter.classList.contains('disabled')
            || getComputedStyle(freshEnter).pointerEvents === 'none';
        if (disabled) {
            setMessage(`已识别${entryLabel}，但进入按钮尚未就绪；稍后自动重试`, {
                phase: 'login_submitted',
                loginSubmittedAt: Number(latestState.loginSubmittedAt || Date.now()),
                classicEntryLastAttemptAt: Date.now(),
                classicEntryStartedAt: Number(latestState.classicEntryStartedAt || Date.now()),
                gameLaunchAt: 0,
                retryAt: 0,
                retryAction: ''
            });
            return true;
        }

        const attempt = Math.max(0, Number(latestState.classicEntryAttemptCount || 0)) + 1;
        setMessage(`已选择${entryLabel}，正在点击进入（第 ${attempt}/${CLASSIC_ENTRY_MAX_ATTEMPTS} 次；仍停留此页会自动重试）`, {
            // 点击后仍保留 login_submitted。只有页面真正跳转且游戏 runtime
            // 可用时，adoptAlreadyLoadedGamePage 才会切到 game_loading。
            phase: 'login_submitted',
            loginSubmittedAt: Number(latestState.loginSubmittedAt || Date.now()),
            classicEntryAttemptCount: attempt,
            classicEntryLastAttemptAt: Date.now(),
            classicEntryStartedAt: Number(latestState.classicEntryStartedAt || Date.now()),
            scheduledEntryAt: 0,
            gameLaunchAt: 0,
            retryAt: 0,
            retryAction: ''
        });
        freshEnter.click();
        return true;
    }

    async function handleLogout(state) {
        if (state.claimSucceededFor !== state.cycleId) {
            finishCycle('没有一键领取成功记录，已取消退出');
            return;
        }
        if (Number(state.retryAt || 0) > Date.now()) return;
        const logout = findVisibleLogoutButton();
        const now = Date.now();
        // 版本选择页底层可能仍保留登录表单节点，但只要“退出登录”按钮可见，
        // 账号就尚未真正退出，不能提前完成本轮排程。
        if (hasLoggedOutLoginUi() && (!logout || !isVisible(logout))) {
            const stableSince = Math.max(0, Number(state.logoutUiStableSince) || 0);
            if (!stableSince) {
                setMessage('已看到账号密码登录表单，等待短暂稳定后再确认退出', {
                    logoutUiStableSince: now
                });
                return;
            }
            if (now - stableSince < LOGOUT_UI_STABLE_CONFIRM_MS) return;
            const logoutStartedAt = Number(state.logoutAttemptAt) > 0 ? Number(state.logoutAttemptAt) : now;
            const confirmationMs = Math.max(0, now - logoutStartedAt);
            pushRawLog('logout-timing', `官方登录页确认退出 @ ${new Date(now).toISOString()}；退出确认耗时 ${(confirmationMs / 1000).toFixed(3)} 秒`);
            finishCycle('已确认官方账号退出；周期从退出请求发送时刻开始计算', {
                logoutConfirmed: true,
                scheduleAnchorAt: logoutStartedAt
            });
            return;
        }
        if (Number(state.logoutUiStableSince || 0) > 0) {
            state = writeState({ logoutUiStableSince: 0 });
        }
        if (!logout || !isVisible(logout)) {
            if (state.logoutAttemptAt && now - Number(state.logoutAttemptAt) >= LOGOUT_CONFIRM_WAIT_MS) {
                schedulePopupRetry('退出后未回到账号密码登录页');
            } else if (!state.logoutAttemptAt) {
                const logoutPageRefreshAt = Number(state.logoutPageRefreshAt || 0);
                if (!logoutPageRefreshAt) {
                    setMessage('未找到官方退出按钮，正在刷新登录页', {
                        phase: 'logout_pending',
                        logoutPageRefreshAt: now,
                        retryAt: 0,
                        retryAction: ''
                    });
                    requestTopNavigation(LOGIN_URL);
                } else if (now - logoutPageRefreshAt >= LOGOUT_PAGE_REFRESH_GRACE_MS) {
                    schedulePopupRetry('刷新登录页后仍未找到官方退出按钮');
                }
            }
            return;
        }

        if (state.logoutAttemptAt) {
            if (now - Number(state.logoutAttemptAt) < LOGOUT_CONFIRM_WAIT_MS) return;
            schedulePopupRetry('退出状态未在 5 秒内确认');
            return;
        }

        const logoutMessage = state.message.includes('五次流程结束')
            ? `${state.message}；正在退出官方账号`
            : '正在退出官方账号';
        setMessage(logoutMessage, {
            logoutClickedFor: state.cycleId,
            logoutAttemptAt: now,
            logoutUiStableSince: 0,
            phase: 'logout_pending',
            forceLogin: false,
            claimMode: 'all',
            retryAt: 0,
            retryAction: '',
            logoutPageRefreshAt: 0
        });
        pushRawLog('logout-timing', `退出请求发送 @ ${new Date(now).toISOString()}；本轮周期从此刻开始`);
        logout.click();
    }

    async function handleLoginPage() {
        if (!TOP_WINDOW || workerBusy) return;
        let state = readState();
        if (!state.enabled) return;

        if (Number(state.retryAt || 0) > Date.now()) return;

		// 经典版加载失败时，官网有时直接退回账号/密码表单。此时 runtime 已不存在，
		// 不能继续等游戏页恢复；启用状态下立即新开一轮，暂停状态由上面的 enabled 护栏拦截。
		if (state.phase === 'game_loading' && hasLoggedOutLoginUi()) {
			restartCycleFromUnexpectedLoggedOutPage(state);
			state = readState();
		}

        // 兼容 2.5.26 已保存的卡死状态：旧版在真正离开登录页前就写入
        // game_loading，之后不会再点击入口。只要入口仍清晰可见，就退回
        // login_submitted 并交给新的可重试流程。
        if (state.phase === 'game_loading') {
            const gameCard = findGameEntryCard(state.gameEntryTarget || readGameEntryTarget());
            const enter = document.querySelector('#goInGameBtn');
            if (gameCard && enter && isVisible(gameCard) && isVisible(enter)) {
                state = setMessage(`检测到${gameEntryLabel(state.gameEntryTarget || readGameEntryTarget())}入口仍停留在登录页，已恢复自动点击重试`, {
                    phase: 'login_submitted',
                    loginSubmittedAt: Date.now(),
                    gameLaunchAt: 0,
                    classicEntryAttemptCount: 0,
                    classicEntryLastAttemptAt: 0,
                    classicEntryStartedAt: 0
                });
            }
        }

        if (state.phase === 'idle'
            && state.claimSucceededFor === state.cycleId
            && state.lastCompleteAt
            && Date.now() - Number(state.lastCompleteAt) < 2 * 60 * 1000
            && findVisibleLogoutButton()) {
            setMessage(state.scheduleFinalizedForCycle === state.cycleId
                ? '检测到版本选择页仍有退出按钮：此前退出确认无效，继续执行真正退出；首次进入计划保持不变'
                : '检测到官网账号仍处于登录状态，继续确认退出', {
                phase: 'logout_pending',
                nextRunAt: 0,
                logoutClickedFor: '',
                logoutAttemptAt: 0,
                logoutUiStableSince: 0,
                logoutPageRefreshAt: 0
            });
            return;
        }

        workerBusy = true;
        try {
            if (state.phase === 'logout_pending') {
                await handleLogout(state);
                return;
            }

            if (!['login', 'login_submitted'].includes(state.phase)) return;
            if (await enterSelectedGameOnce(state)) return;

            if (state.phase === 'login') {
                await submitLoginOnce(state);
                return;
            }

            const waitingOnScheduledEntryPage = Boolean(state.scheduledEntryAt)
                && Number(state.scheduledEntryAt) > 0
                && (findGameEntryCard(state.gameEntryTarget || readGameEntryTarget())
                    || isVisible(document.querySelector('#selectGame'))
                    || Boolean(findVisibleLogoutButton()));
            if (!waitingOnScheduledEntryPage && Date.now() - state.loginSubmittedAt >= LOGIN_TIMEOUT_MS) {
                if (rebuildLoginContainerAfterTimeout('登录请求超时')) return;
                finishCycle('30 秒内未得到登录结果；微端 OL 刷新仍未恢复登录', {
                    backoff: true,
                    loginFailure: true
                });
            }
        } finally {
            workerBusy = false;
        }
    }

    // ── #2 邮件到达监听（纯监听、不发包，风险最低）─────────────────────────────
    // 挂到游戏 ServerProxy 的 "decodeClientGetMailNtf" 事件：每当服务器推送邮件通知，
    // 就把精确时刻(含毫秒)+当前可领封数+首封服务器时间写进运行记录，用于把“刷新时刻”钉死。
    // 每次回到游戏页(重登后 laya/ServerProxy 重建)幂等重装；任何异常静默降级，绝不影响领取。
    let mailNtfHookedProxy = null;
    let lastMailNtfLoggedAt = 0;
    const mailNtfHookCaller = { __localSgsMailNtfHook: true };

    function pushRawLog(phase, message) {
        try {
            let cycleId = '';
            try { cycleId = String(readState()?.cycleId || ''); } catch (_) {}
            const level = classifyLogMessage(message, phase);
            const stored = persistLogEntry({
                at: Date.now(),
                cycleId,
                phase,
                message,
                level,
                summary: compactLogSummary(message, level)
            });
            lastLogRenderSignature = '';
            refreshLogButtonLabel(stored.total);
            reportMailAssistantWatchdog(readState(), stored.total);
        } catch (_) {}
    }

    function onMailNtfEvent() {
        try {
            const now = Date.now();
            if (now - lastMailNtfLoggedAt < 1500) return; // 轻 throttle，防同一推送重复记
            lastMailNtfLoggedAt = now;
            let detail = '';
            try {
                const runtime = resolveMailRuntime();
                const mm = runtime && typeof runtime.class === 'function' ? runtime.class('MailManager') : null;
                const list = mm && Array.isArray(mm.systemMailList) ? mm.systemMailList : null;
                if (list) {
                    const claimable = list.filter((m) => m && m.mid && Number(m.AttachmentType) === 1);
                    const first = claimable[0];
                    const st = first && (first.time || first.createTime || first.sendTime || first.mailTime);
                    detail = `当前可领 ${claimable.length} 封` + (first ? `（首封 mid=${first.mid}${st ? ('、服务器时间=' + st) : ''}）` : '');
                }
            } catch (_) {}
            const t = new Date(now);
            const ms = String(t.getMilliseconds()).padStart(3, '0');
            pushRawLog('mail-ntf', `服务器推送邮件通知(decodeClientGetMailNtf) @ ${t.toLocaleTimeString()}.${ms}${detail ? '；' + detail : ''}`);
        } catch (_) {}
    }

    function ensureMailArrivalHook() {
        try {
            const runtime = resolveMailRuntime();
            if (!runtime || typeof runtime.class !== 'function') return false;
            const proxy = runtime.class('ServerProxy');
            if (!proxy) return false;
            if (mailNtfHookedProxy === proxy && proxy.__localMailNtfHooked) return true;
            // 优先：用 Laya EventDispatcher 的 on() 追加自己的监听，不动游戏原有处理器。
            if (typeof proxy.on === 'function') {
                proxy.on('decodeClientGetMailNtf', mailNtfHookCaller, onMailNtfEvent);
                proxy.__localMailNtfHooked = true;
                mailNtfHookedProxy = proxy;
                return true;
            }
            // 兜底：包裹 _events 里已注册处理器的 run()。
            const ev = proxy._events && proxy._events['decodeClientGetMailNtf'];
            if (ev) {
                const wrapOne = (h) => {
                    if (!h || typeof h.run !== 'function' || h.__localMailNtfWrapped) return;
                    const originalRun = h.run;
                    h.run = function () { try { onMailNtfEvent(); } catch (_) {} return originalRun.apply(this, arguments); };
                    h.__localMailNtfWrapped = true;
                };
                (Array.isArray(ev) ? ev : [ev]).forEach(wrapOne);
                proxy.__localMailNtfHooked = true;
                mailNtfHookedProxy = proxy;
                return true;
            }
            return false;
        } catch (_) { return false; }
    }

    // ── #1 日常奖励 · 第一步「只读探测」───────────────────────────────────────
    // 离线看不到真机的窗口/方法名，盲写领取多半打空或误触。先只读枚举各奖励管理器的真实方法名，
    // 写进运行记录；你把 daily-probe 各行发我，再据此写“真正会用”的领取。零风险、不发包、不点按钮。
    let dailyProbeDone = false;
    const DAILY_PROBE_KEY = 'localSgsMailCycle.v2.dailyProbe.v2';

    function probeDailyRewards() {
        let resolved = 0;
        try {
            const runtime = resolveMailRuntime();
            if (!runtime || typeof runtime.class !== 'function') { pushRawLog('daily-probe', 'laya 未就绪'); return 0; }
            const MANAGERS = ['OfficerManager', 'TaskManager', 'WelfareManger', 'NewFuLiManager', 'BlessManager', 'BlessNewManager', 'ActivityManager', 'AchievementManager', 'NewSecKillManager', 'TreasureManger', 'GameGoodsManager'];
            const HOT = /award|reward|claim|receive|lottery|welfare|sign|task|gift|fuli|lingqu|out|draw|qifu|bless|jd|get/i;
            pushRawLog('daily-probe', '=== 日常奖励接口探测(只读) ===');
            for (const name of MANAGERS) {
                let mgr = null;
                try { mgr = runtime.class(name); } catch (_) {}
                if (!mgr) { pushRawLog('daily-probe', name + ': <取不到>'); continue; }
                resolved += 1;
                const all = new Set();
                try {
                    for (const k of Object.keys(mgr)) { try { if (typeof mgr[k] === 'function') all.add(k); } catch (_) {} }
                    let proto = Object.getPrototypeOf(mgr), depth = 0;
                    while (proto && proto !== Object.prototype && depth < 4) {
                        for (const k of Object.getOwnPropertyNames(proto)) { if (k !== 'constructor') { try { if (typeof mgr[k] === 'function') all.add(k); } catch (_) {} } }
                        proto = Object.getPrototypeOf(proto); depth += 1;
                    }
                } catch (_) {}
                const arr = Array.from(all);
                const hot = arr.filter((k) => HOT.test(k));
                const show = (hot.length ? hot : arr).slice(0, 24);
                pushRawLog('daily-probe', name + '[' + arr.length + ']: ' + show.join(','));
            }
            pushRawLog('daily-probe', '=== 探测完毕，请把以上 daily-probe 各行发我 ===');
        } catch (e) { pushRawLog('daily-probe', '探测异常: ' + (e && e.message ? e.message : String(e))); }
        return resolved;
    }

    function maybeRunDailyProbeOnce() {
        try {
            if (dailyProbeDone) return;
            if (storageGet(DAILY_PROBE_KEY, false)) { dailyProbeDone = true; return; }
            const runtime = resolveMailRuntime();
            if (!runtime || typeof runtime.class !== 'function') return;
            const resolved = probeDailyRewards();   // 在“刚领完邮件”后调用，游戏与管理器已确保就绪
            if (resolved >= 1) { dailyProbeDone = true; storageSet(DAILY_PROBE_KEY, true); }
        } catch (_) {}
    }

    // #1 探测(内联版)：把 daily-probe 拼进领取汇总行（走已验证会显示的 setMessage 路径），每轮最新一行可见，
    // 避免一次性 pushRawLog 输出被 120 条日志上限刷掉。拿到真名后即移除。
    function dailyProbeCompact() {
        // 诊断版：报告本注入环境里怎样才能拿到 laya / 管理器，绝不静默返回空。拿到结论后改回真正的探测。
        try {
            const tof = (v) => { try { return typeof v; } catch (_) { return 'err'; } };
            const p = [];
            let bareLaya; try { bareLaya = resolveMailRuntime() || undefined; } catch (_) { bareLaya = undefined; }
            p.push('laya=' + tof(bareLaya) + (bareLaya ? '(cls:' + tof(bareLaya.class) + ',win:' + tof(bareLaya.win) + ')' : ''));
            let pw = null; try { pw = (typeof pageWindow !== 'undefined') ? pageWindow : null; } catch (_) {}
            let pwLaya = null; try { pwLaya = pw ? pw.laya : null; } catch (_) {}
            p.push('pw=' + tof(pw) + ',pw.laya=' + tof(pwLaya) + (pwLaya ? '(cls:' + tof(pwLaya.class) + ')' : ''));
            const L = (bareLaya && typeof bareLaya.class === 'function') ? bareLaya : ((pwLaya && typeof pwLaya.class === 'function') ? pwLaya : null);
            if (L) {
                let tm; try { tm = L.class('TaskManager'); } catch (_) { tm = 'throw'; }
                let om; try { om = L.class('OfficerManager'); } catch (_) { om = 'throw'; }
                p.push('via=' + (L === bareLaya ? 'laya' : 'pw.laya') + ',Task=' + tof(tm) + ',Officer=' + tof(om));
            } else {
                p.push('via=NONE(两种 laya 都没有可用的 class 方法)');
            }
            p.push('Laya=' + tof((typeof Laya !== 'undefined') ? Laya : undefined));
            return '；[daily-probe] ' + p.join(' ');
        } catch (e) { return '；[daily-probe] ERR:' + (e && e.message ? e.message : String(e)); }
    }









    function describeClickedMailDragonRewards(result) {
        const clickedCount = Math.max(0, Number(result?.processed || 0));
        const recordMailCount = Math.max(0, Number(result?.mailClickedAttachmentRecordMails || 0));
        const rewardMailCount = Math.max(0, Number(result?.mailClickedDragonRewardMailCount || 0));
        const configuredRewards = (Array.isArray(result?.mailClickedDragonRewards) ? result.mailClickedDragonRewards : [])
            .map((item) => ({
                name: String(item?.name || '').trim(),
                count: Number(item?.count || 0)
            }))
            .filter((item) => item.name && Number.isFinite(item.count) && item.count > 0);
        const serverRewards = (Array.isArray(result?.mailServerDragonRewards) ? result.mailServerDragonRewards : [])
            .map((item) => ({
                name: String(item?.name || '').trim(),
                count: Number(item?.count || 0)
            }))
            .filter((item) => item.name && Number.isFinite(item.count) && item.count > 0);
        const eventCount = Math.max(0, Number(result?.mailServerDragonRewardEventCount || 0));
        if (serverRewards.length) {
            const types = (Array.isArray(result?.mailServerDragonRewardTypes) ? result.mailServerDragonRewardTypes : []).filter(Boolean).join('、');
            return `；服务器奖励记录（本轮点击期间 ${eventCount} 条${types ? `；${types}` : ''}）：${serverRewards.slice(0, 8).map((item) => `${item.name} +${item.count}`).join('、')}；不读取背包、不删除邮件`;
        }
        if (configuredRewards.length) {
            return `；邮件附件配置（已点击 ${recordMailCount || rewardMailCount}/${clickedCount} 封；尚未收到服务器龙珠奖励记录）：${configuredRewards.slice(0, 8).map((item) => `${item.name} ×${item.count}`).join('、')}；不读取背包、不删除邮件`;
        }
        if (clickedCount > 0) {
            const probe = String(result?.mailRewardProbe || '').trim();
            return `；邮件附件记录：已点击 ${clickedCount} 封，但未取得可识别清单，也未收到服务器龙珠奖励记录（不读取背包）${probe ? `；[mail-reward-probe] ${probe}` : ''}`;
        }
        return '；邮件附件记录：本轮没有点击可领取邮件';
    }

    function serverMailDragonRewardTotal(result) {
        const total = Number(result?.mailServerDragonRewardTotal || 0);
        return Number.isFinite(total) && total > 0 ? total : 0;
    }

    function adoptAlreadyLoadedGamePage() {
        if (isLoginUrl() || hasLoginUi()) return false;
        const state = readState();
        if (!state.enabled || !['login', 'login_submitted'].includes(state.phase)) return false;
        if (Number(state.retryAt || 0) > Date.now()) return false;

        const bridge = mailRuntimeServices();
        if (!bridge) return false;
        if (typeof bridge.isGameReady === 'function' && !bridge.isGameReady()) return false;

        setMessage(`已识别${gameEntryLabel(state.gameEntryTarget || readGameEntryTarget())}游戏页面，继续一键领取`, {
            phase: 'game_loading',
            gameLaunchAt: Date.now() - GAME_LOAD_WAIT_MS,
            classicEntryAttemptCount: 0,
            classicEntryLastAttemptAt: 0,
            classicEntryStartedAt: 0
        });
        return true;
    }

    function isActiveClaimCycle(expectedState) {
        const current = readState();
        return current.cycleId === expectedState.cycleId
            && current.phase === 'claiming'
            && Number(current.retryAt || 0) <= Date.now();
    }

    function describeJsonArchiveReadiness(reason) {
        return ({
            'archive-api-not-ready': '归档模块尚未完成初始化',
            'runtime-not-ready': '游戏 runtime 尚未完成初始化',
            'mail-manager-not-ready': '邮件管理器尚未注册',
            'account-not-ready': '当前游戏账号尚未识别',
            'gift-manager-not-ready': '礼包领取管理器尚未注册',
            'persisted-list-not-ready': '本机持久化清单尚未读取完成',
            'durable-bridge-unavailable': '本机持久化桥接尚未连接',
            'daily-reward-not-ready': '日常奖励管理器尚未注册',
            'laya-not-ready': '游戏 runtime 尚未完成初始化',
            'daily-reward-readiness-error': '日常奖励状态读取异常'
        })[String(reason || '')] || '账号、邮件模块或本机持久化清单尚未全部就绪';
    }

    function keepGamePageWaitingForJsonArchive(readiness = {}) {
        const missing = Array.isArray(readiness.missing) && readiness.missing.length ? `（${readiness.missing.join('、')}）` : '';
        const message = `自动任务准备中：${describeJsonArchiveReadiness(readiness.reason || readiness.readinessReason)}${missing}；保持在游戏页等待，不发送邮件/CDK请求、不退出账号`;
        const current = readState();
        if (current.phase === 'game_loading' && current.message === message) return current;
        return setMessage(message, {
            phase: 'game_loading',
            gameLaunchAt: Date.now() - GAME_LOAD_WAIT_MS,
            claimStartedFor: '',
            retryAt: 0,
            retryAction: ''
        });
    }

    function inspectDailyRewardReadiness(bridge) {
        const { selection } = dailyRewardBridgeSelection();
        const active = enabledDailyRewardItems(selection).some((item) => !['mailClaim', 'giftCodes', 'blackMagicOrb'].includes(item.key));
        if (!active) {
            return { ready: true, reason: 'daily-reward-not-needed', missing: [] };
        }
        if (!bridge || typeof bridge.isDailyRewardReady !== 'function') {
            return { ready: false, reason: 'daily-reward-not-ready', missing: ['daily-bridge'] };
        }
        try {
            const result = bridge.isDailyRewardReady(selection);
            return result && result.ready === true
                ? { ready: true, reason: 'ready', missing: [] }
                : {
                    ready: false,
                    reason: result?.reason || 'daily-reward-not-ready',
                    missing: Array.isArray(result?.missing) ? result.missing : []
                };
        } catch (error) {
            return { ready: false, reason: 'daily-reward-readiness-error', missing: [String(error && error.message || error)] };
        }
    }

    function recordPendingElectronGamePageRecovery(state) {
        const recoveryKind = String(state?.gameRuntimeRecoveryKind || '');
        if (!TOP_WINDOW || !state || state.enabled !== true ||
            !['electron-page-refresh', 'electron-webview-rebuild', 'electron-app-restart'].includes(recoveryKind)) return state;
        const recoveredAt = Math.max(0, Number(state.gameRuntimeRecoveryLastAt) || 0);
        const loggedAt = Math.max(0, Number(state.gameRuntimeRecoveryLoggedAt) || 0);
        if (!recoveredAt || recoveredAt <= loggedAt) return state;
        const count = Math.max(1, Number(state.gameRuntimeRecoveryCount) || 1);
        const entryLabel = gameEntryLabel(state.gameEntryTarget || readGameEntryTarget());
        const message = recoveryKind === 'electron-webview-rebuild'
            ? `${entryLabel}加载超过 30 秒无结果：Electron 已重建游戏容器（第 ${count}/2 级恢复）`
            : (recoveryKind === 'electron-app-restart'
                ? `重建游戏容器后仍未恢复：Electron 正在安全重启微端（第 ${count}/2 级恢复）`
                : `${entryLabel}加载超过 30 秒无结果：Electron 已刷新当前游戏网页（兼容旧恢复记录，第 ${count}/2 次）`);
        pushRawLog('game-runtime-recovery', message);
        return writeState({
            gameRuntimeRecoveryLoggedAt: recoveredAt,
            message,
            messageAt: recoveredAt
        });
    }

    function restartCycleFromUnexpectedLoggedOutPage(state) {
        if (!TOP_WINDOW || !state.enabled || state.phase !== 'game_loading' || !hasLoggedOutLoginUi()) return false;
        const now = Date.now();
        clearLoginLock();
        const nextCycleId = makeCycleId();
        setMessage(`${gameEntryLabel(state.gameEntryTarget || readGameEntryTarget())}加载期间已退回登录表单：不再等待 runtime，立即开启新一轮`, {
            enabled: true,
            forceLogin: false,
            claimMode: 'all',
            phase: 'login',
            cycleId: nextCycleId,
            nextRunAt: now,
            targetLoginAt: now,
            scheduledEntryAt: 0,
            plannedLoginDispatchAt: now,
            offlineScheduleAnchorAt: now,
            loginSubmittedAt: 0,
            gameLaunchAt: 0,
            gameRuntimeWaitStartedAt: 0,
            gameRuntimeRecoveryCount: 0,
            gameRuntimeRecoveryLastAt: now,
            gameRuntimeRecoveryKind: 'unexpected-logged-out',
            gameRuntimeRecoveryLoggedAt: now,
            classicEntryAttemptCount: 0,
            classicEntryLastAttemptAt: 0,
            classicEntryStartedAt: 0,
            claimStartedFor: '',
            claimSucceededFor: '',
            mailClaimedForCycle: '',
            logoutClickedFor: '',
            logoutAttemptAt: 0,
            logoutUiStableSince: 0,
            logoutPageRefreshAt: 0,
            retryAt: 0,
            retryAction: '',
            retryCount: 0,
            cycleHadClaimFailure: false,
            lastWaitExtraMs: 0,
            lastWaitExtraKind: '',
            scheduleFinalizedForCycle: '',
        }, { allowRecoveryTransition: true });
        return true;
    }

    function disabledCurrentMailResult() {
        return {
            text: '；当前邮件领取已关闭，本轮未发送邮件请求',
            currentMailClaimDisabled: true,
            eligibleCount: 0,
            processed: 0,
            failed: 0,
            accepted: 0,
            already: 0,
            rejected: 0,
            timedOut: 0,
            unconfirmed: 0,
            processedMids: [],
            claimResults: []
        };
    }

    function buildStrictDailyFeatureSummary({ mailClaimEnabled, jsonResult, traceEntry, blackMagicResult } = {}) {
        const items = readDailyRewardItems();
        const rows = [];
        const addRow = (key, label, enabled, success, detail, reference = false, outcome = '') => {
            if (!enabled) return;
            rows.push({ key, label, success: success === true, detail: String(detail || ''), reference: reference === true, outcome: String(outcome || '') });
        };
        if (mailClaimEnabled) {
            const eligible = Math.max(0, Number(jsonResult?.eligibleCount || 0));
            const accepted = Math.max(0, Number(jsonResult?.accepted || 0));
            const already = Math.max(0, Number(jsonResult?.already || 0));
            const rejected = Math.max(0, Number(jsonResult?.rejected || jsonResult?.failed || 0));
            const timedOut = Math.max(0, Number(jsonResult?.timedOut || 0));
            const unconfirmed = Math.max(0, Number(jsonResult?.unconfirmed || 0));
            const success = eligible > 0 && accepted === eligible && already === 0 && rejected === 0 && timedOut === 0 && unconfirmed === 0;
            const detail = success
                ? `服务器确认 ${accepted}/${eligible}`
                : `成功 ${accepted}/${eligible}、已领取 ${already}、拒绝 ${rejected}、超时/未确认 ${timedOut + unconfirmed}`;
            addRow('mailClaim', '当前邮件', true, success, detail, true);
        }
        const traceItems = traceEntry && traceEntry.items && typeof traceEntry.items === 'object' ? traceEntry.items : {};
        if (items.freeBless === true) {
            const item = traceItems.freeBless;
            const evidence = Array.isArray(item?.evidence) ? item.evidence.map((entry) => String(entry?.text || '')).join('；') : '';
            addRow('freeBless', '免费祈福', true, item?.status === 'server-confirmed', item ? `${item.status}${evidence ? `：${evidence}` : ''}` : '本轮无结果', true);
        }
		if (items.activityAll === true) {
            const item = traceItems.activityAll;
            const detail = item?.status === 'server-confirmed' ? '服务器确认' : String(item?.status || '本轮无结果');
			addRow('activityAll', '军典档位', true, item?.status === 'server-confirmed', detail);
		}
		if (items.newJd === true) {
			const item = traceItems.newJd;
			const detail = item?.status === 'server-confirmed' ? '服务器确认' : String(item?.status || '本轮无结果');
			addRow('newJd', '节钺令', true, item?.status === 'server-confirmed', detail);
		}
		const addOfficerTraceRow = (key, label) => {
			if (items[key] !== true) return;
			const item = traceItems[key];
			const status = String(item?.status || 'no-result');
			const evidence = Array.isArray(item?.evidence)
				? item.evidence.map((entry) => String(entry?.text || '')).filter(Boolean).join('；')
				: '';
			addRow(key, label, true, ['server-confirmed', 'not-claimable'].includes(status),
				evidence ? `${status}：${evidence}` : status, false,
				status === 'official-data-unavailable' ? '跳过' : '');
		};
		addOfficerTraceRow('officerPromote', '官阶晋升');
		if (items.officerTasks === true) {
			const report = traceEntry?.officerTasks || null;
			const confirmedPoint = Math.max(0, Number(report?.confirmedPoint) || 0);
			const detail = report
				? report.success === true
					? String(report.status || '')
					: `${String(report.status || 'failed')}${Number(report.readinessWaitedMs) > 0 ? `，就绪等待${Number(report.readinessWaitedMs)}ms` : ''}`
				: 'no-result';
			addRow('officerTasks', `官阶任务-帅点数${confirmedPoint}`, true, report?.success === true, detail);
		}
		addOfficerTraceRow('officerSprint', '官阶冲刺');
        if (items.generalUpgrade === true) {
            const report = traceEntry?.generalUpgrade;
            addRow('generalUpgrade', '武将升阶', true, report?.success === true, describeGeneralUpgradeReport(report));
        }
        if (items.blackMagicOrb === true) {
            const result = blackMagicResult && typeof blackMagicResult === 'object' ? blackMagicResult : null;
            addRow('blackMagicOrb', '开黑魔珠', true, result?.success === true, result ? String(result.status || 'unknown') : '本轮无结果');
        }
        // 正常/异常仍只由邮件与免费祈福参考；其他日常仅展示结果，不改变调相或失败加时。
        const referenceRows = rows.filter((row) => row.reference);
        const successCount = referenceRows.filter((row) => row.success).length;
        const allSuccess = referenceRows.length === 0 || successCount === referenceRows.length;
        const text = `；[本轮功能结果] ${rows.length
            ? rows.map((row) => `${row.label}=${row.outcome || (row.success ? '成功' : '异常')}${row.detail ? `（${row.detail}）` : ''}`).join('；')
            : '无已开启功能'}；[本轮总判定] ${allSuccess ? '成功' : '异常'}（${successCount}/${referenceRows.length} 项成功）`;
        return { text, success: allSuccess, rows, enabledCount: rows.length, successCount, referenceCount: referenceRows.length };
    }

    async function runDailyRewardBundle(bridge) {
        // “当前邮件”是日常奖励中的一个并行分支；邮件扫描/归档仍由原归档模块自行运行。
        lastDailyRewardTraceEntry = null;
        const dailyReadiness = inspectDailyRewardReadiness(bridge);
        if (!dailyReadiness.ready) {
            return {
                mailClaimEnabled: isCurrentMailClaimEnabled(),
                jsonResult: disabledCurrentMailResult(),
                dailyText: '',
                giftCodeText: '',
                readinessFailed: true,
                dailyReadiness
            };
        }
        const mailClaimEnabled = isCurrentMailClaimEnabled();
        const mailPromise = mailClaimEnabled
            ? claimJsonWhitelistedArchive({ deferFinalWait: true })
            : Promise.resolve(disabledCurrentMailResult());
        const dailyPromise = (async () => {
            let text = '';
            try { text = await runDailyRewardsOncePerDay(bridge); } catch (_) {}
            return text;
        })();
        let jsonResult = await mailPromise;
        if (jsonResult?.readinessFailed) {
            await dailyPromise;
            return { mailClaimEnabled, jsonResult, dailyText: '', giftCodeText: '', readinessFailed: true };
        }
        const giftCodePromise = readDailyRewardItems().giftCodes === true
            ? redeemGiftCodesEachCycle(bridge, jsonResult)
            : Promise.resolve('；[日常奖励·兑换码] 已熄灭，本轮未提交（队列保留）');
        const [dailyText, giftCodeText] = await Promise.all([dailyPromise, giftCodePromise]);
        jsonResult = await finalizeJsonWhitelistedArchive(jsonResult);
        const mailDailyText = mailClaimEnabled
            ? (Number(jsonResult?.eligibleCount || 0) > 0
                ? (Number(jsonResult?.accepted || 0) > 0
                    ? `；[日常奖励·当前邮件并行] 服务器确认成功 ${Number(jsonResult.accepted)}/${Number(jsonResult.eligibleCount)}`
                    : (Number(jsonResult?.already || 0) > 0
                        ? `；[日常奖励·当前邮件并行] 服务器提示已领取 ${Number(jsonResult.already)}/${Number(jsonResult.eligibleCount)}`
                        : (Number(jsonResult?.rejected || jsonResult?.failed || 0) > 0
                            ? `；[日常奖励·当前邮件并行] 服务器拒绝 ${Number(jsonResult.rejected || jsonResult.failed)}/${Number(jsonResult.eligibleCount)}`
                            : `；[日常奖励·当前邮件并行] 结果未确认 ${Number(jsonResult?.timedOut || 0) + Number(jsonResult?.unconfirmed || 0)}/${Number(jsonResult.eligibleCount)}`)))
                : '；[日常奖励·当前邮件并行] 无可处理附件')
            : '；[日常奖励·当前邮件并行] 已关闭';
        return { mailClaimEnabled, jsonResult, dailyText: mailDailyText + dailyText, giftCodeText, readinessFailed: false };
    }

    async function handleJsonOnlyMailCycle(state, bridge) {
        if (!isActiveClaimCycle(state)) return;
        const bundle = await runDailyRewardBundle(bridge);
        if (bundle.readinessFailed) {
            keepGamePageWaitingForJsonArchive(bundle.dailyReadiness || bundle.jsonResult);
            return;
        }
        if (!isActiveClaimCycle(state)) return;
        const mailClaimEnabled = bundle.mailClaimEnabled;
        const jsonResult = bundle.jsonResult;
        const giftCodeText = bundle.giftCodeText || '';
        const dailyProbeText = bundle.dailyText || '';
        const blackMagicResult = await exchangeBlackMagicOrbsEachCycleResult(bridge);
        const exchangeText = blackMagicResult.text || '';
        if (!isActiveClaimCycle(state)) return;

        const eligibleCount = Math.max(0, Number(jsonResult?.eligibleCount || 0));
        const processed = Math.max(0, Number(jsonResult?.processed || 0));
        const accepted = Math.max(0, Number(jsonResult?.accepted || 0));
        const already = Math.max(0, Number(jsonResult?.already || 0));
        const rejected = Math.max(0, Number(jsonResult?.rejected || jsonResult?.failed || 0));
        const timedOut = Math.max(0, Number(jsonResult?.timedOut || 0));
        const unconfirmed = Math.max(0, Number(jsonResult?.unconfirmed || 0));
        const qifuEnabled = readDailyRewardItems().freeBless === true;
        const qifuItem = lastDailyRewardTraceEntry
            && String(lastDailyRewardTraceEntry.cycleId || '') === String(state.cycleId || '')
            ? lastDailyRewardTraceEntry.items?.freeBless
            : null;
        const featureSummary = buildStrictDailyFeatureSummary({
            mailClaimEnabled,
            jsonResult,
            traceEntry: lastDailyRewardTraceEntry,
            blackMagicResult
        });
        const outcome = !mailClaimEnabled
            ? 'disabled'
            : (accepted > 0
                ? 'claimed'
                : (already > 0
                    ? 'already-claimed'
                    : (rejected > 0 ? 'failed' : (eligibleCount > 0 ? 'unconfirmed' : 'no-json'))));
        const claimFailed = !featureSummary.success;
        const headline = !mailClaimEnabled
            ? '当前邮件领取已关闭：本轮未发送邮件请求'
            : (eligibleCount > 0
                ? `JSON 专用自动化完成：已发送 ${processed}/${eligibleCount} 封；服务器确认成功 ${accepted}、已领取 ${already}、失败 ${rejected}、超时/未确认 ${timedOut + unconfirmed}`
                : 'JSON 专用自动化未发送请求：本账号尚无可处理的 JSON 白名单邮件');
        setMessage(`${headline}${jsonResult?.text || ''}${giftCodeText}${dailyProbeText}${exchangeText}${featureSummary.text}；准备退出`, {
            cycleHadClaimFailure: claimFailed
        });
        maybeRunDailyProbeOnce();
        await new Promise((resolve) => setTimeout(resolve, CLAIM_SAVE_WAIT_MS));

        const completedAt = Date.now();
        const latest = readState();
        if (latest.cycleId !== state.cycleId) return;
        writeState({
            ...claimCompletionSchedulePatch(completedAt, claimFailed),
            claimSucceededFor: state.cycleId,
            mailClaimedForCycle: accepted > 0 ? state.cycleId : '',
            lastClaimOutcome: featureSummary.success ? outcome : 'failed',
            lastClaimOutcomeCycle: state.cycleId,
            lastCompleteAt: completedAt,
            phase: 'logout_pending',
            message: !mailClaimEnabled
                ? '当前邮件领取已关闭，本轮跳过邮件，返回登录页退出账号'
                : (accepted > 0
                    ? `JSON 白名单服务器确认成功 ${accepted}/${eligibleCount} 封，返回登录页退出账号`
                    : (eligibleCount > 0
                        ? `JSON 白名单本轮无新增成功（已领取 ${already}、失败 ${rejected}、超时/未确认 ${timedOut + unconfirmed}），返回登录页退出账号`
                        : 'JSON 白名单为空，未调用现场邮箱，返回登录页退出账号')),
            messageAt: completedAt
        });
        requestTopNavigation(LOGIN_URL);
    }

	async function handleGamePage() {
		if (workerBusy || generalUpgradeRunBusy || isLoginUrl() || hasLoginUi()) return;
        const bridge = mailRuntimeServices();
        const state = readState();
        if (!state.enabled || state.phase !== 'game_loading') return;
        if (Number(state.retryAt || 0) > Date.now()) return;
        if (!state.gameLaunchAt || Date.now() - state.gameLaunchAt < GAME_LOAD_WAIT_MS) return;
        if (state.claimStartedFor === state.cycleId) return;

        const claimAllMode = state.claimMode === 'all';
        const currentMailClaimEnabled = isCurrentMailClaimEnabled();
        const clickMailButton = claimAllMode ? bridge?.claimAllMailIndividually : bridge?.clickFirstMailButton;
        if (!JSON_ONLY_MAIL_AUTOMATION && currentMailClaimEnabled && typeof clickMailButton !== 'function') return;
        if (bridge && typeof bridge.isGameReady === 'function' && !bridge.isGameReady()) {
            keepGamePageWaitingForJsonArchive({ reason: 'runtime-not-ready' });
            return;
        }
        if (JSON_ONLY_MAIL_AUTOMATION && currentMailClaimEnabled) {
            const archiveReadiness = inspectPersistedJsonArchiveReadiness();
            if (!archiveReadiness.ready) {
                keepGamePageWaitingForJsonArchive(archiveReadiness);
                return;
            }
        }
        const dailyReadiness = inspectDailyRewardReadiness(bridge);
        if (!dailyReadiness.ready) {
            keepGamePageWaitingForJsonArchive(dailyReadiness);
            return;
        }
        workerBusy = true;
        writeState({
            phase: 'claiming',
            claimStartedFor: state.cycleId,
            gameRuntimeWaitStartedAt: 0,
            gameRuntimeRecoveryCount: 0,
            gameRuntimeRecoveryLastAt: 0,
            gameRuntimeRecoveryKind: '',
            gameRuntimeRecoveryLoggedAt: 0
        });
        // 当前邮件与日常奖励在同一轮并行启动；邮件附件统计仍只来自邮件自带清单，不读取背包。
        let dailyProbeText = '';
        setMessage(JSON_ONLY_MAIL_AUTOMATION
            ? '准备执行 JSON 专用自动化（不打开现场邮箱、不删除邮件）'
            : (claimAllMode
                ? '正在读取邮件附件记录并逐封点击领取（不读取背包、不删除邮件）'
                : '准备依次执行：打开首封详情 → 点击“领取首封”'));

        try {
            if (JSON_ONLY_MAIL_AUTOMATION) {
                await handleJsonOnlyMailCycle(state, bridge);
                return;
            }
            if (claimAllMode) {
                const stateBeforeClaim = readState();
                if (stateBeforeClaim.cycleId !== state.cycleId || stateBeforeClaim.phase !== 'claiming' || Number(stateBeforeClaim.retryAt || 0) > Date.now()) return;
                setMessage('正在调用 H5 外部接口 claimAllMailIndividually，逐封打开并尝试领取');
                const result = await withTimeout(
                    clickMailButton.call(bridge),
                    CLAIM_CALL_TIMEOUT_MS,
                    '逐封处理系统信件超过 120 秒'
                );
                const stateAfterClaim = readState();
                if (stateAfterClaim.cycleId !== state.cycleId || stateAfterClaim.phase !== 'claiming' || Number(stateAfterClaim.retryAt || 0) > Date.now()) return;
                const itemErrors = Array.isArray(result?.errors) ? result.errors : [];
                const topError = result?.error ? String(result.error) : '';
                const allClaimErrors = [...itemErrors, ...(topError ? [topError] : [])];
                const retryableClaimError = allClaimErrors.find((error) => /^(?:game-ui-not-ready|mail-window-not-ready|mail-content-not-ready)/.test(error) || /(?:PopUpWindow.*(?:null|undefined)|mail-content-window-lost)/i.test(error));
                if (retryableClaimError) {
                    scheduleMailboxRetry(state, retryableClaimError);
                    return;
                }
                const errorCount = itemErrors.length + (topError ? 1 : 0);
                const errorText = allClaimErrors.join('；');
                const emptyListText = result?.mailListEmptyAfterWait ? `；邮件列表在等待 ${Math.round(Number(result?.mailContentWaitedMs || 0) / 1000)} 秒后仍为空` : '';
                const archiveGiftResult = await claimJsonWhitelistedArchive();
                const archiveGiftText = archiveGiftResult.text;
                const stateAfterArchiveGift = readState();
                if (stateAfterArchiveGift.cycleId !== state.cycleId || stateAfterArchiveGift.phase !== 'claiming' || Number(stateAfterArchiveGift.retryAt || 0) > Date.now()) return;
				const giftCodeText = archiveGiftText + (readDailyRewardItems().giftCodes === true
					? await redeemGiftCodesEachCycle(bridge, archiveGiftResult)
					: '；[日常奖励·兑换码] 已熄灭，本轮未提交（队列保留）');
                const stateAfterGiftCode = readState();
                if (stateAfterGiftCode.cycleId !== state.cycleId || stateAfterGiftCode.phase !== 'claiming' || Number(stateAfterGiftCode.retryAt || 0) > Date.now()) return;
                try { dailyProbeText = await runDailyRewardsOncePerDay(bridge); } catch (_) { dailyProbeText = ''; }
                const exchangeText = await exchangeBlackMagicOrbsEachCycle(bridge);
                const stateAfterExchange = readState();
                if (stateAfterExchange.cycleId !== state.cycleId || stateAfterExchange.phase !== 'claiming' || Number(stateAfterExchange.retryAt || 0) > Date.now()) return;
                const mailProbeText = result?.mailProbe ? `；[mail-probe] ${result.mailProbe}` : '';
                const dragonText = describeClickedMailDragonRewards(result) + mailProbeText + dailyProbeText + exchangeText;
                const totalFound = Number(result?.total || 0);
                const clickedCount = Number(result?.processed || 0);
                const serverDragonTotal = serverMailDragonRewardTotal(result);
                // 附件清单只说明本封邮件配置；只有点击期间收到游戏 GoodsList 奖励通知才记为本轮到账。
                // 全程不读背包，也不把邮件/附件状态变化当成计数依据。
                const outcome = totalFound <= 0 ? 'no-mail' : (serverDragonTotal > 0 ? 'claimed' : 'unconfirmed');
                const claimedOk = outcome === 'claimed';
                const claimFailed = errorCount > 0 || (totalFound > 0 && !claimedOk);
                if (outcome === 'claimed') {
                    const headline = `本轮已点击 ${clickedCount} 封领取；收到服务器奖励记录共 ${serverDragonTotal} 个龙珠`;
                    setMessage(`${headline}（发现 ${totalFound} 封，异常 ${errorCount} 次）${errorText ? `；${errorText}` : ''}${emptyListText}${giftCodeText}${dragonText}；准备退出`, { cycleHadClaimFailure: claimFailed });
                } else if (outcome === 'unconfirmed') {
                    const reason = clickedCount > 0
                        ? '已点击邮件领取，但本轮未收到服务器龙珠奖励记录（常见于刷新间隔未到）'
                        : '未成功点击邮件领取';
                    setMessage(`本轮发现 ${totalFound} 封；${reason} → 保持当前间隔${errorText ? `；${errorText}` : ''}${emptyListText}${giftCodeText}${dragonText}；准备退出`, { cycleHadClaimFailure: claimFailed });
                } else {
                    setMessage(`本轮无可领邮件（邮箱已打开、发现 0 封可领；多为刷新窗口未到，或已领完）→ 下轮按设定间隔再试${errorText ? `；${errorText}` : ''}${emptyListText}${giftCodeText}${dragonText}；准备退出`, { cycleHadClaimFailure: claimFailed });
                }
                maybeRunDailyProbeOnce();
                await new Promise((resolve) => setTimeout(resolve, CLAIM_SAVE_WAIT_MS));

                const completedAt = Date.now();
                const latest = readState();
                if (latest.cycleId !== state.cycleId) return;
                writeState({
                    ...claimCompletionSchedulePatch(completedAt, claimFailed),
                    claimSucceededFor: state.cycleId,
                    mailClaimedForCycle: claimedOk ? state.cycleId : '',
                    lastClaimOutcome: outcome,
                    lastClaimOutcomeCycle: state.cycleId,
                    lastCompleteAt: completedAt,
                    phase: 'logout_pending',
                    message: claimedOk
                        ? `已收到服务器奖励记录 ${serverDragonTotal} 个龙珠，返回登录页退出账号`
                        : (outcome === 'unconfirmed'
                            ? '本轮未收到服务器龙珠奖励记录，返回登录页退出、保持当前间隔'
                            : '本轮无可领邮件，返回登录页退出、下轮按设定间隔再试'),
                    messageAt: completedAt
                });
                requestTopNavigation(LOGIN_URL);
                return;
            }

            let attemptedCount = 0;
            let errorCount = 0;
            let lastError = '';
            let stoppedAfterUiRefresh = false;
            for (let index = 1; index <= 5; index += 1) {
                setMessage(`第 ${index}/5 次：正在打开首封详情并点击领取`);
                try {
                    const result = await withTimeout(
                        clickMailButton.call(bridge),
                        CLAIM_CALL_TIMEOUT_MS,
                        `第 ${index} 次按钮处理超过 20 秒`
                    );
                    if (result?.uiClicked) attemptedCount += 1;
                    if (!result?.ready || result?.error) {
                        const resultError = String(result?.error || '按钮未返回就绪状态');
                        const uiGoneAfterTrigger = attemptedCount > 0 && [
                            'first-mail-button-not-ready',
                            'mail-window-not-ready',
                            'first-mail-claim-button-not-ready'
                        ].includes(resultError);
                        if (uiGoneAfterTrigger) {
                            stoppedAfterUiRefresh = true;
                            setMessage(`已触发 ${attemptedCount} 次；领取后邮件界面已刷新，正常结束`);
                            break;
                        }
                        errorCount += 1;
                        lastError = resultError;
                    }
                } catch (error) {
                    errorCount += 1;
                    lastError = error instanceof Error ? error.message : String(error);
                }
                if (index < 5) await new Promise((resolve) => setTimeout(resolve, 1200));
            }

            const finishLabel = stoppedAfterUiRefresh ? '领取后界面已刷新' : '五次流程结束';
            const exchangeText = await exchangeBlackMagicOrbsEachCycle(bridge);
            setMessage(`${finishLabel}：实际触发 ${attemptedCount} 次，异常 ${errorCount} 次${lastError ? `；最后错误：${lastError}` : ''}${exchangeText}；准备退出`, {
                cycleHadClaimFailure: errorCount > 0 || attemptedCount <= 0
            });
            await new Promise((resolve) => setTimeout(resolve, CLAIM_SAVE_WAIT_MS));

            const completedAt = Date.now();
            const latest = readState();
            if (latest.cycleId !== state.cycleId) return;
            const claimFailed = errorCount > 0 || attemptedCount <= 0;
            writeState({
                ...claimCompletionSchedulePatch(completedAt, claimFailed),
                claimSucceededFor: state.cycleId,
                lastCompleteAt: completedAt,
                phase: 'logout_pending',
                message: '首封领取尝试已完成，返回登录页退出账号',
                messageAt: completedAt
            });
            requestTopNavigation(LOGIN_URL);
        } catch (error) {
            const completedAt = Date.now();
            setMessage(`领取流程异常但按设置继续退出：${error instanceof Error ? error.message : String(error)}`, {
                ...claimCompletionSchedulePatch(completedAt, true),
                claimSucceededFor: state.cycleId,
                cycleHadClaimFailure: true,
                lastCompleteAt: completedAt,
                phase: 'logout_pending'
            });
            requestTopNavigation(LOGIN_URL);
        } finally {
            workerBusy = false;
        }
    }

    function toggleEnabled() {
        if (readOfficerLinkTab().mode !== 'timer') {
            toggleOfficerLinkActive();
            return;
        }
        const state = readState();
        if (state.enabled) {
            clearScheduledLoginTimer();
            setMessage('自动循环已暂停', { enabled: false, phase: 'stopped' }, { allowRecoveryTransition: true });
            return;
        }
        const now = Date.now();
        writeState({ enabled: true, phase: 'idle', targetLoginAt: now, scheduledEntryAt: 0, plannedLoginDispatchAt: now, nextRunAt: now }, { allowRecoveryTransition: true });
        startCycle();
    }

    function runNow() {
        clearScheduledLoginTimer();
        const now = Date.now();
        writeState({ enabled: true, phase: 'idle', targetLoginAt: now, scheduledEntryAt: 0, plannedLoginDispatchAt: now, nextRunAt: now }, { allowRecoveryTransition: true });
        startCycle({ forceLogin: true, claimMode: 'all' });
    }

    function findArchiveApi() {
        const queue = [pageWindow];
        const visited = new Set();
        let best = null;
        let bestScore = -1;
        while (queue.length) {
            const target = queue.shift();
            if (!target || visited.has(target)) continue;
            visited.add(target);
            try {
                const api = target.__H5_MAIL_CLAIM_ARCHIVE__;
                if (api) {
                    let snapshot = null;
                    try {
                        snapshot = api.snapshot?.() || null;
                    } catch (_) {}
                    const eligibleCount = jsonArchiveEligibleRecords(snapshot).length;
                    const score =
                        (snapshot?.hasRuntime ? 10 : 0) +
                        (snapshot?.hasMailManager ? 20 : 0) +
                        (String(snapshot?.accountId || '').trim() ? 40 : 0) +
                        (snapshot?.durableStoreLoaded === true ? 80 : 0) +
                        (eligibleCount > 0 ? 160 : 0);
                    if (!best || score > bestScore) {
                        best = api;
                        bestScore = score;
                    }
                }
                for (let index = 0; index < target.frames.length; index += 1) queue.push(target.frames[index]);
            } catch (_) {}
        }
        return best;
    }

    function jsonArchiveEligibleRecords(snapshot) {
        const targetAccountId = String(snapshot?.accountId || '').trim();
        if (!targetAccountId || !Array.isArray(snapshot?.records)) return [];
        return snapshot.records.filter((record) =>
            record?.jsonAutoClaim === true &&
            ['single-gift', 'dbs-item'].includes(record?.claimRoute) &&
            String(record?.accountId || '') === targetAccountId
        );
    }

    function evaluateJsonArchiveReadiness(snapshot, restored = {}) {
        if (!snapshot?.hasRuntime) {
            return { ready: false, reason: 'runtime-not-ready', eligible: [] };
        }
        if (!snapshot?.hasMailManager) {
            return { ready: false, reason: 'mail-manager-not-ready', eligible: [] };
        }
        const targetAccountId = String(snapshot?.accountId || '').trim();
        if (!targetAccountId) {
            return { ready: false, reason: 'account-not-ready', eligible: [] };
        }
        const eligible = jsonArchiveEligibleRecords(snapshot);
        const persistedListReadable =
            restored.readCompleted === true ||
            snapshot?.durableStoreLoaded === true ||
            eligible.length > 0;
        if (!persistedListReadable) {
            return {
                ready: false,
                reason: restored.error || 'persisted-list-not-ready',
                eligible
            };
        }
        if (eligible.some((record) => record?.claimRoute === 'single-gift') &&
            !snapshot?.hasGiftManager) {
            return { ready: false, reason: 'gift-manager-not-ready', eligible };
        }
        return {
            ready: true,
            reason: eligible.length ? 'ready' : 'ready-empty',
            eligible
        };
    }

    function classifyJsonClaimResult(entry) {
        const state = String(entry?.state || '');
        if (state === 'server-accepted') return 'accepted';
        if (state.startsWith('server-reported-already-')) return 'already';
        if (state === 'no-response-timeout') return 'timeout';
        if (state === 'request-error' || state.startsWith('server-rejected:')) return 'failed';
        return 'unconfirmed';
    }

    function jsonClaimResultLabel(entry) {
        const category = classifyJsonClaimResult(entry);
        if (category === 'accepted') return '服务器确认成功';
        if (category === 'already') return '服务器提示已领取';
        if (category === 'timeout') return '超时未确认';
        if (category === 'failed') return String(entry?.state || '').startsWith('server-rejected:')
            ? `服务器拒绝(${String(entry.state).slice('server-rejected:'.length) || '?'})`
            : '请求异常';
        return `未确认(${String(entry?.state || '无状态')})`;
    }

    function findDurableMailStoreBridge() {
        const candidates = [pageWindow, window];
        try { candidates.push(pageWindow.top); } catch (_) {}
        try { candidates.push(pageWindow.parent); } catch (_) {}
        const visited = new Set();
        for (const target of candidates) {
            if (!target || visited.has(target)) continue;
            visited.add(target);
            try {
                const bridge = target.__SGSOL_BRIDGE__;
                if (bridge &&
                    typeof bridge.readMailArchiveStore === 'function' &&
                    typeof bridge.writeMailArchiveStore === 'function') {
                    return bridge;
                }
            } catch (_) {}
        }
        return null;
    }

    function restorePersistedJsonIntoRuntimeApi(api, snapshot) {
        const targetAccountId = String(snapshot?.accountId || '').trim();
        if (!targetAccountId) {
            return { snapshot, readCompleted: false, error: 'account-not-ready' };
        }
        const durableBridge = findDurableMailStoreBridge();
        if (!durableBridge) {
            return { snapshot, readCompleted: false, error: 'durable-bridge-unavailable' };
        }
        try {
            const response = durableBridge.readMailArchiveStore(targetAccountId);
            if (!response || response.ok !== true) {
                return {
                    snapshot,
                    readCompleted: false,
                    error: String(response?.error || 'durable-read-failed')
                };
            }
            if (!response.found || !response.data) {
                return { snapshot, readCompleted: true, storedWhitelistCount: 0 };
            }
            const stored = response.data;
            if (String(stored.accountId || '') !== targetAccountId) {
                return { snapshot, readCompleted: false, error: 'durable-account-mismatch' };
            }
            const storedRecords = Array.isArray(stored.records) ? stored.records : [];
            const currentRecords = Array.isArray(snapshot?.records) ? snapshot.records : [];
            const storedWhitelist = storedRecords.filter((record) =>
                record?.jsonAutoClaim === true &&
                ['single-gift', 'dbs-item'].includes(record?.claimRoute) &&
                String(record?.accountId || '') === targetAccountId
            );
            const currentWhitelistMids = new Set(currentRecords
                .filter((record) =>
                    record?.jsonAutoClaim === true &&
                    ['single-gift', 'dbs-item'].includes(record?.claimRoute) &&
                    String(record?.accountId || '') === targetAccountId
                )
                .map((record) => String(record.mid || '')));
            const needsHydration = storedWhitelist.length !== currentWhitelistMids.size ||
                storedWhitelist.some((record) => !currentWhitelistMids.has(String(record.mid || '')));
            let hydratedSnapshot = snapshot;
            if (needsHydration && typeof api.importSameAccountBackup === 'function') {
                api.importSameAccountBackup({
                    formatVersion: 2,
                    accountId: targetAccountId,
                    records: storedRecords,
                    crossAccountTests: Array.isArray(stored.crossRecords) ? stored.crossRecords : [],
                    crossAccountAttemptLedger: stored.crossAttemptLedger &&
                        typeof stored.crossAttemptLedger === 'object' &&
                        !Array.isArray(stored.crossAttemptLedger)
                        ? stored.crossAttemptLedger
                        : {}
                });
                try { hydratedSnapshot = api.snapshot?.() || snapshot; } catch (_) {}
            }
            return {
                snapshot: hydratedSnapshot,
                readCompleted: true,
                storedWhitelistCount: storedWhitelist.length,
                hydrated: needsHydration
            };
        } catch (error) {
            return {
                snapshot,
                readCompleted: false,
                error: String(error?.message || error)
            };
        }
    }

    function inspectPersistedJsonArchiveReadiness() {
        const api = findArchiveApi();
        if (!api || typeof api.runAutoGiftQueueAfterLiveMail !== 'function') {
            return {
                api,
                snapshot: null,
                ready: false,
                reason: 'archive-api-not-ready',
                loadError: ''
            };
        }
        try { api.scan?.(); } catch (_) {}
        let snapshot = null;
        try { snapshot = api.snapshot?.() || null; } catch (_) {}
        const preliminary = evaluateJsonArchiveReadiness(snapshot);
        if (['runtime-not-ready', 'mail-manager-not-ready', 'account-not-ready'].includes(preliminary.reason)) {
            return {
                api,
                snapshot,
                ready: false,
                reason: preliminary.reason,
                loadError: ''
            };
        }
        const restored = restorePersistedJsonIntoRuntimeApi(api, snapshot);
        snapshot = restored.snapshot || snapshot;
        const evaluated = evaluateJsonArchiveReadiness(snapshot, restored);
        return {
            api,
            snapshot,
            ready: evaluated.ready,
            reason: evaluated.reason,
            eligible: evaluated.eligible,
            loadError: restored.error || '',
            readCompleted: restored.readCompleted === true,
            storedWhitelistCount: Number(restored.storedWhitelistCount || 0)
        };
    }

    async function waitForPersistedJsonArchive() {
        const startedAt = Date.now();
        let latest = {
            api: null,
            snapshot: null,
            ready: false,
            reason: 'archive-api-not-ready',
            loadError: ''
        };
        while (Date.now() - startedAt <= JSON_ARCHIVE_READY_WAIT_MS) {
            latest = inspectPersistedJsonArchiveReadiness();
            if (latest.ready) return { ...latest, waitedMs: Date.now() - startedAt };
            await new Promise((resolve) => window.setTimeout(resolve, JSON_ARCHIVE_READY_POLL_MS));
        }
        return {
            ...latest,
            waitedMs: Date.now() - startedAt,
            ready: false
        };
    }

    function summarizeJsonWhitelistedArchiveResult(result, eligibleCount) {
        const processed = Number(result?.processed || result?.processedMids?.length || 0);
        const processedMids = Array.isArray(result?.processedMids)
            ? result.processedMids.map((mid) => String(mid))
            : [];
        const claimResults = Array.isArray(result?.claimResults)
            ? result.claimResults.map((entry) => ({
                mid: String(entry?.mid || ''),
                route: String(entry?.route || ''),
				attachmentId: String(entry?.attachmentId || ''),
				attachmentKind: String(entry?.attachmentKind || ''),
                state: String(entry?.state || ''),
                resultCode: entry?.resultCode != null && Number.isFinite(Number(entry.resultCode)) ? Number(entry.resultCode) : null,
                requestedAt: Number(entry?.requestedAt || 0),
                sentAt: Number(entry?.sentAt || 0),
                respondedAt: Number(entry?.respondedAt || 0),
                responseMs: Number(entry?.responseMs || 0)
            }))
            : [];
        const finalWaitTimedOut = result?.finalWaitTimedOut === true;
        const finalResponseWaitMs = Math.max(0, Number(result?.finalResponseWaitMs || 0));
        const accepted = claimResults.filter((entry) => classifyJsonClaimResult(entry) === 'accepted').length;
        const already = claimResults.filter((entry) => classifyJsonClaimResult(entry) === 'already').length;
        const rejected = claimResults.filter((entry) => classifyJsonClaimResult(entry) === 'failed').length;
        const timedOut = claimResults.filter((entry) => classifyJsonClaimResult(entry) === 'timeout').length;
        const unconfirmed = claimResults.filter((entry) => classifyJsonClaimResult(entry) === 'unconfirmed').length;
        const resultDetails = claimResults
			.map((entry) => {
				const rejectedIdentity = classifyJsonClaimResult(entry) === 'failed' && entry.attachmentId
					? ` / ${entry.attachmentKind || (entry.route === 'single-gift' ? 'GiftID' : '道具ID')} ${entry.attachmentId}`
					: '';
				return `MID ${entry.mid || '?'}${rejectedIdentity}：${jsonClaimResultLabel(entry)}`;
			})
            .join('、');
        return {
            text: `；JSON 逐封结果：成功 ${accepted}、已领取 ${already}、失败 ${rejected}、超时 ${timedOut}、其他未确认 ${unconfirmed}${finalWaitTimedOut ? `；其他操作结束后又等待 ${Math.round(finalResponseWaitMs / 1000)} 秒，仍有回包未确认` : ''}${resultDetails ? `；${resultDetails}` : (processedMids.length ? `；仅确认已发送 MID ${processedMids.join('、')}` : '')}`,
            eligibleCount: Math.max(0, Number(eligibleCount || 0)),
            processed,
            failed: rejected,
            accepted,
            already,
            rejected,
            timedOut,
            unconfirmed,
            finalWaitTimedOut,
            finalResponseWaitMs,
            processedMids,
            claimResults
        };
    }

    async function finalizeJsonWhitelistedArchive(pendingResult) {
        if (!pendingResult?.deferred) return pendingResult;
        const api = pendingResult.archiveApi || findArchiveApi();
        const eligibleCount = Math.max(0, Number(pendingResult.eligibleCount || 0));
        try {
            if (!api || typeof api.finalizeAutoGiftQueueAfterLiveMail !== 'function') throw new Error('归档模块不支持延后收包');
            const result = await withTimeout(
                Promise.resolve(api.finalizeAutoGiftQueueAfterLiveMail()),
                JSON_CLAIM_BATCH_FALLBACK_TIMEOUT_MS,
                `JSON 白名单最终收包超过 ${JSON_CLAIM_BATCH_FALLBACK_TIMEOUT_MS / 1000} 秒兜底时限`
            );
            return summarizeJsonWhitelistedArchiveResult(result, eligibleCount);
        } catch (error) {
            return {
                text: `；JSON 白名单：最终收包异常（${error instanceof Error ? error.message : String(error)}）`,
                eligibleCount,
                processed: Math.max(0, Number(pendingResult.processed || 0)),
                failed: eligibleCount,
                accepted: 0,
                already: 0,
                rejected: eligibleCount,
                timedOut: 0,
                unconfirmed: 0,
                processedMids: Array.isArray(pendingResult.processedMids) ? pendingResult.processedMids : [],
                claimResults: []
            };
        }
    }

    async function claimJsonWhitelistedArchive(options = {}) {
        const archiveReady = await waitForPersistedJsonArchive();
        const api = archiveReady.api;
        if (!api || typeof api.runAutoGiftQueueAfterLiveMail !== 'function') {
            return {
                text: '；JSON 白名单：归档模块未就绪，本轮未发送请求',
                readinessFailed: true,
                readinessReason: archiveReady.reason || 'archive-api-not-ready',
                eligibleCount: 0,
                processed: 0,
                failed: 0,
                accepted: 0,
                already: 0,
                rejected: 0,
                timedOut: 0,
                unconfirmed: 0,
                processedMids: [],
                claimResults: []
            };
        }
        const snapshot = archiveReady.snapshot;
        if (!archiveReady.ready) {
            return {
                text: `；JSON 白名单：账号或本机持久化清单在 ${Math.round(archiveReady.waitedMs / 1000)} 秒内仍未就绪，本轮未发送请求${archiveReady.loadError ? `（${archiveReady.loadError}）` : ''}`,
                readinessFailed: true,
                readinessReason: archiveReady.reason || archiveReady.loadError || 'persisted-list-not-ready',
                eligibleCount: 0,
                processed: 0,
                failed: 0,
                accepted: 0,
                already: 0,
                rejected: 0,
                timedOut: 0,
                unconfirmed: 0,
                processedMids: [],
                claimResults: []
            };
        }
        const eligible = jsonArchiveEligibleRecords(snapshot);
        if (!eligible.length) {
            return {
                text: '；JSON 白名单：当前没有可处理附件，本轮未调用现场邮箱',
                eligibleCount: 0,
                processed: 0,
                failed: 0,
                accepted: 0,
                already: 0,
                rejected: 0,
                timedOut: 0,
                unconfirmed: 0,
                processedMids: [],
                claimResults: []
            };
        }
        const deferFinalWait = options.deferFinalWait === true && typeof api.finalizeAutoGiftQueueAfterLiveMail === 'function';
        setMessage(deferFinalWait
            ? `JSON 专用自动化：正在快速发送全部领取请求（${eligible.length} 封）；回包在后台收集，随后继续兑换码和日常任务`
            : `JSON 专用自动化：正在快速发送全部领取请求（${eligible.length} 封）；发送完统一等待回包，最多 4 秒`);
        try {
            const result = await withTimeout(
                Promise.resolve(api.runAutoGiftQueueAfterLiveMail({ deferFinalWait })),
                JSON_CLAIM_BATCH_FALLBACK_TIMEOUT_MS,
                `JSON 白名单队列处理超过 ${JSON_CLAIM_BATCH_FALLBACK_TIMEOUT_MS / 1000} 秒兜底时限`
            );
            if (deferFinalWait && result?.deferred === true) {
                return {
                    text: '',
                    deferred: true,
                    archiveApi: api,
                    eligibleCount: eligible.length,
                    processed: Number(result?.processed || result?.processedMids?.length || 0),
                    failed: 0,
                    accepted: 0,
                    already: 0,
                    rejected: 0,
                    timedOut: 0,
                    unconfirmed: 0,
                    processedMids: Array.isArray(result?.processedMids) ? result.processedMids.map(String) : [],
                    claimResults: []
                };
            };
            return summarizeJsonWhitelistedArchiveResult(result, eligible.length);
        } catch (error) {
            return {
                text: `；JSON 白名单：处理异常（${error instanceof Error ? error.message : String(error)}）`,
                eligibleCount: eligible.length,
                processed: 0,
                failed: eligible.length,
                accepted: 0,
                already: 0,
                rejected: eligible.length,
                timedOut: 0,
                unconfirmed: 0,
                processedMids: [],
                claimResults: []
            };
        }
    }

    function archiveTime(seconds) {
        const value = Number(seconds);
        if (!Number.isFinite(value) || value <= 0) return '时间未知';
        return new Date(value * 1000).toLocaleString('zh-CN', { hour12: false });
    }

    function readSelectedJsonFile(file) {
        if (file && typeof file.text === 'function') return file.text();
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(String(reader.result || ''));
            reader.onerror = () => reject(reader.error || new Error('读取 JSON 失败'));
            reader.readAsText(file, 'utf-8');
        });
    }

    function downloadArchiveJson(api) {
        const json = api?.exportJson?.();
        if (typeof json !== 'string' || !json) throw new Error('归档尚未就绪');
        const blob = new Blob([json], { type: 'application/json;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const anchor = document.createElement('a');
        anchor.href = url;
        anchor.download = `三国杀邮件归档-${Date.now()}.json`;
        anchor.style.display = 'none';
        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();
        window.setTimeout(() => URL.revokeObjectURL(url), 1000);
    }

    function renderCrossAccountTests(api, snapshot) {
        if (!archiveCrossList) return;
        while (archiveCrossList.firstChild) archiveCrossList.removeChild(archiveCrossList.firstChild);
        const records = Array.isArray(snapshot?.crossRecords) ? snapshot.crossRecords.slice() : [];
        if (!records.length) {
            const empty = document.createElement('div');
            empty.textContent = '尚未导入其他本人账号的 JSON。';
            empty.style.cssText = 'padding:9px 6px;text-align:center;color:#8e806a;font-size:10px';
            archiveCrossList.appendChild(empty);
            return;
        }
        for (const record of records) {
            const attempts = Array.isArray(record.claimAttempts) ? record.claimAttempts : [];
            const attempted = attempts.length > 0;
            const card = document.createElement('div');
            card.style.cssText = 'margin-top:6px;padding:7px;border:1px solid #754a42;border-radius:5px;background:rgba(91,43,37,.16)';
            const title = document.createElement('strong');
            title.textContent = String(record.title || `邮件 ${record.mid || ''}`);
            title.style.cssText = 'display:block;color:#ead1c9;font-size:11px';
            const route = document.createElement('div');
            route.textContent = `A ${record.originAccountId || '-'} → B ${record.importedIntoAccountId || snapshot?.accountId || '-'} · MID ${record.mid || '-'}`;
            route.style.cssText = 'margin-top:3px;color:#b99990;font-size:10px;word-break:break-all';
            const result = document.createElement('div');
            result.textContent = attempted
                ? `已完成单次测试：${record.lastClaimResult || attempts[0]?.state || '已发送'}`
                : '尚未测试；只允许手动发送一次';
            result.style.cssText = 'margin-top:3px;color:#c9aea5;font-size:10px';
            const button = document.createElement('button');
            button.type = 'button';
            button.textContent = attempted ? '已测试' : '发送一次测试';
            button.disabled = attempted;
            button.style.cssText = `margin-top:6px;border:1px solid ${attempted ? '#554541' : '#9b5f52'};border-radius:4px;padding:3px 8px;background:${attempted ? '#2a2422' : '#4a2d28'};color:${attempted ? '#756963' : '#f0d2ca'};cursor:${attempted ? 'not-allowed' : 'pointer'};font-size:11px`;
            if (!attempted) {
                button.addEventListener('click', async () => {
                    try {
                        await api.claimCrossAccount(record.originAccountId, record.mid);
                        archiveStatus.textContent = `跨账号实验 MID ${record.mid} 已发送一次，等待服务器回包`;
                        renderArchivePage();
                        window.setTimeout(renderArchivePage, 900);
                        window.setTimeout(renderArchivePage, 13000);
                    } catch (error) {
                        archiveStatus.textContent = `跨账号实验失败：${error instanceof Error ? error.message : String(error)}`;
                        renderArchivePage();
                    }
                });
            }
            card.append(title, route, result, button);
            archiveCrossList.appendChild(card);
        }
    }

    function resetArchiveManualForm() {
        if (!archiveManualForm || !archiveManualInputs) return;
        archiveManualForm.reset();
        archiveManualInputs.attachmentType.value = '1';
        archiveManualInputs.count.value = '1';
        archiveManualInputs.title.focus();
    }

    function fillArchiveManualForm(record) {
        if (!record || !archiveManualForm || !archiveManualInputs) return;
        const attachment = record.attachment || {};
        archiveManualInputs.title.value = String(record.title || '');
        archiveManualInputs.mid.value = String(record.mid || '');
        archiveManualInputs.attachmentType.value = String(Number(record.attachmentType) === 2 ? 2 : 1);
        archiveManualInputs.giftId.value = String(Array.isArray(attachment.id) ? attachment.id[0] ?? '' : '');
        archiveManualInputs.count.value = String(Array.isArray(attachment.ctn) ? attachment.ctn[0] ?? 1 : 1);
        archiveManualInputs.key.value = String(Array.isArray(attachment.key) ? attachment.key[0] ?? '' : '');
        const details = archiveManualForm.closest('details');
        if (details) details.open = true;
        archiveManualForm.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
        archiveManualInputs.title.focus();
    }

    function renderArchivePage() {
        if (!archivePage || activePanelPage !== 'archive') return;
        const api = findArchiveApi();
        if (!api) {
            archiveStatus.textContent = '归档模块等待游戏加载；进入所选版本后再刷新。';
            while (archiveList.firstChild) archiveList.removeChild(archiveList.firstChild);
            while (archiveCrossList?.firstChild) archiveCrossList.removeChild(archiveCrossList.firstChild);
            return;
        }
        let snapshot;
        try {
            snapshot = api.snapshot();
        } catch (error) {
            archiveStatus.textContent = `读取归档失败：${error instanceof Error ? error.message : String(error)}`;
            return;
        }
        const records = Array.isArray(snapshot?.records) ? snapshot.records.slice() : [];
        const crossCount = Array.isArray(snapshot?.crossRecords) ? snapshot.crossRecords.length : 0;
        if (archiveLocalTabButton) archiveLocalTabButton.textContent = `本账号归档 (${records.length})`;
        if (archiveCrossTabButton) archiveCrossTabButton.textContent = `跨账号实验 (${crossCount})`;
        const archiveBaseStatus = snapshot?.hasRuntime
            ? `账号 ${snapshot.accountId || '识别中'} · 本账号归档 ${records.length} 封 · 跨账号实验 ${crossCount} 封 · ${snapshot.durableStoreAvailable ? '永久保存已开启' : '等待微端重启启用永久保存'}`
            : '已连接归档模块，等待游戏 runtime';
        archiveStatus.textContent = archiveNotice ? `${archiveBaseStatus}\n${archiveNotice}` : archiveBaseStatus;
        archiveStatus.style.whiteSpace = 'pre-wrap';
        while (archiveList.firstChild) archiveList.removeChild(archiveList.firstChild);
        renderCrossAccountTests(api, snapshot);
        if (!records.length) {
            const empty = document.createElement('div');
            empty.textContent = '暂无 JSON 白名单；可导入本账号 JSON，或等待本地正式列表扫描到新附件邮件。';
            empty.style.cssText = 'padding:12px 6px;text-align:center;color:#9f9279;font-size:11px';
            archiveList.appendChild(empty);
        } else {
          records.sort((a, b) => Number(b.originalEndtime || 0) - Number(a.originalEndtime || 0));
          for (const record of records) {
            const expired = Number(record.originalEndtime || 0) > 0 && Date.now() >= Number(record.originalEndtime) * 1000;
            const card = document.createElement('div');
            card.className = 'local-sgs-archive-card';
            card.style.cssText = 'margin-top:6px;padding:7px;border:1px solid #665234;border-radius:5px;background:rgba(0,0,0,.18)';
            const head = document.createElement('div');
            head.style.cssText = 'display:flex;align-items:flex-start;gap:6px';
            const title = document.createElement('strong');
            title.textContent = String(record.title || `邮件 ${record.mid || ''}`);
            title.style.cssText = 'margin-right:auto;color:#ead9b8;font-size:12px';
            const badge = document.createElement('span');
            badge.textContent = record.jsonAutoClaim === true ? 'JSON 自动' : (expired ? '仅归档·过期' : '仅归档');
            badge.style.cssText = `color:${expired ? '#efad7d' : '#89c692'};font-size:10px;white-space:nowrap`;
            head.append(title, badge);
            const meta = document.createElement('div');
            const attachmentId = Array.isArray(record.attachment?.id) ? record.attachment.id[0] : '';
            const attachmentLabel = Number(record.attachmentType) === 2 ? '道具ID' : 'GiftID';
            meta.textContent = `MID ${record.mid || '-'} · ${attachmentLabel} ${attachmentId || '-'} · ${archiveTime(record.originalEndtime)} · ${record.presentInLiveList ? '现场扫描' : '本地保存'}`;
            meta.style.cssText = 'margin-top:3px;color:#9f9279;font-size:10px;line-height:1.35';
            const result = document.createElement('div');
            result.textContent = `最近结果：${record.lastClaimResult || '尚未尝试'}`;
            result.style.cssText = 'margin-top:3px;color:#c6b895;font-size:10px';
            const claimButton = document.createElement('button');
            claimButton.type = 'button';
            const jsonWhitelisted = record.jsonAutoClaim === true;
            claimButton.textContent = jsonWhitelisted ? '手动重试' : '仅归档';
            claimButton.disabled = !jsonWhitelisted;
            claimButton.title = jsonWhitelisted ? '单击后立即发送一次 JSON 白名单记录的原生领取请求' : '非 JSON 白名单记录不允许走归档领取';
            claimButton.style.cssText = `margin-top:6px;border:1px solid ${jsonWhitelisted ? '#a98243' : '#51483a'};border-radius:4px;padding:3px 8px;background:${jsonWhitelisted ? '#3b2d1d' : '#29251f'};color:${jsonWhitelisted ? '#f3e6c7' : '#756b5b'};cursor:${jsonWhitelisted ? 'pointer' : 'not-allowed'};font-size:11px`;
            if (jsonWhitelisted) {
                claimButton.addEventListener('click', async () => {
                    try {
                        claimButton.disabled = true;
                        archiveStatus.textContent = `MID ${record.mid} 正在发送请求`;
                        await api.claim(record.mid, { skipConfirmation: true, requireJsonWhitelist: true });
                        archiveStatus.textContent = `MID ${record.mid} 已发送请求，等待服务器回包`;
                        window.setTimeout(renderArchivePage, 900);
                        window.setTimeout(renderArchivePage, 13000);
                    } catch (error) {
                        archiveStatus.textContent = `MID ${record.mid} 请求失败：${error instanceof Error ? error.message : String(error)}`;
                    } finally {
                        claimButton.disabled = false;
                    }
                });
            }
            const editButton = document.createElement('button');
            editButton.type = 'button';
            editButton.textContent = '编辑';
            editButton.title = '把这条记录载入上方表单；保存时按 MID 更新';
            editButton.addEventListener('click', () => fillArchiveManualForm(record));
            const deleteButton = document.createElement('button');
            deleteButton.type = 'button';
            deleteButton.textContent = '删除';
            deleteButton.className = 'local-sgs-danger-button';
            deleteButton.title = '仅从本机邮件库删除，并阻止现场扫描重新添加；不删除服务器邮件';
            let deleteConfirmTimer = 0;
            deleteButton.addEventListener('click', () => {
                if (deleteButton.dataset.confirming !== '1') {
                    deleteButton.dataset.confirming = '1';
                    deleteButton.textContent = '再次点击删除';
                    deleteButton.classList.add('is-confirming');
                    deleteButton.title = '5 秒内再次点击，才会从本机邮件库删除；服务器邮件不会删除';
                    window.clearTimeout(deleteConfirmTimer);
                    deleteConfirmTimer = window.setTimeout(() => {
                        deleteButton.dataset.confirming = '0';
                        deleteButton.textContent = '删除';
                        deleteButton.classList.remove('is-confirming');
                        deleteButton.title = '仅从本机邮件库删除，并阻止现场扫描重新添加；不删除服务器邮件';
                    }, 5000);
                    return;
                }
                window.clearTimeout(deleteConfirmTimer);
                try {
                    const removed = api.removeRecord(record.mid, { skipConfirmation: true });
                    if (removed?.removed) archiveNotice = `已删除 MID ${record.mid}；只删除本机记录，服务器邮件未动。`;
                } catch (error) {
                    archiveNotice = `删除失败：${error instanceof Error ? error.message : String(error)}`;
                }
                renderArchivePage();
            });
            const actions = document.createElement('div');
            actions.className = 'local-sgs-card-actions';
            actions.append(claimButton, editButton, deleteButton);
            card.append(head, meta, result, actions);
            archiveList.appendChild(card);
          }
        }
    }

    function showArchiveTab(tabName) {
        activeArchiveTab = tabName === 'cross' ? 'cross' : 'local';
        if (archiveLocalSection) archiveLocalSection.hidden = activeArchiveTab !== 'local';
        if (archiveCrossSection) archiveCrossSection.hidden = activeArchiveTab !== 'cross';
        const activeStyle = 'border:1px solid #c7964e;border-radius:5px;padding:5px 7px;background:#5a3f20;color:#fff0ca;cursor:pointer;font-size:11px;font-weight:700';
        const idleStyle = 'border:1px solid #665234;border-radius:5px;padding:5px 7px;background:#29231a;color:#b9aa8d;cursor:pointer;font-size:11px';
        if (archiveLocalTabButton) {
            archiveLocalTabButton.style.cssText = activeArchiveTab === 'local' ? activeStyle : idleStyle;
            archiveLocalTabButton.setAttribute('aria-selected', activeArchiveTab === 'local' ? 'true' : 'false');
        }
        if (archiveCrossTabButton) {
            archiveCrossTabButton.style.cssText = activeArchiveTab === 'cross' ? activeStyle : idleStyle;
            archiveCrossTabButton.setAttribute('aria-selected', activeArchiveTab === 'cross' ? 'true' : 'false');
        }
    }

    function formatGeneralUpgradeNumber(value) {
        return Math.max(0, Number(value) || 0).toLocaleString('zh-CN');
    }

    function syncGeneralUpgradeInputs() {
        const counts = readGeneralUpgradeCounts();
        const resources = readGeneralUpgradeResources();
        for (const [key, controls] of generalUpgradeCountInputs) {
            const value = counts[key] || 0;
            controls.range.max = String(Math.min(GENERAL_UPGRADE_MAX_COUNT, Math.max(100, value * 2)));
            controls.range.value = String(value);
            controls.number.value = String(value);
        }
        for (const [key, controls] of generalUpgradeResourceInputs) {
            const value = resources[key] || 0;
            controls.range.max = String(Math.min(GENERAL_UPGRADE_RESOURCE_MAX, Math.max(10000, value * 2)));
            controls.range.value = String(value);
            controls.number.value = String(value);
        }
    }

    function formatGeneralUpgradeRosterUpdatedAt(value) {
        const date = new Date(String(value || ''));
        if (!Number.isFinite(date.getTime())) return '时间未知';
        return date.toLocaleString('zh-CN', { hour12: false });
    }

    function renderGeneralUpgradeRosterStatus() {
        if (!generalUpgradeRosterStatus) return;
        const accountId = currentGeneralUpgradeAccountId();
		if (!accountId) {
			generalUpgradeRosterStatus.textContent = '当前账号尚未识别；登录游戏后才能查看实时武将快照。';
            generalUpgradeRosterStatus.className = 'local-sgs-upgrade-roster-status is-missing';
            return;
        }
        const roster = readGeneralUpgradeRoster(accountId);
		if (!roster) {
			generalUpgradeRosterStatus.textContent = '当前账号暂无手动快照；升阶每轮会重新读取当前拥有武将，无需预先扫描。';
            generalUpgradeRosterStatus.className = 'local-sgs-upgrade-roster-status is-missing';
            return;
        }
        const preview = roster.ids.slice(0, 8).join(' → ');
		const sourceText = roster.sourceCounts.length
			? `；来源 ${roster.sourceCounts.map((item) => `${item.name}:${item.count}/${item.rawCount}${item.rejectedCount ? `退${item.rejectedCount}` : ''}`).join('、')}`
			: '';
		generalUpgradeRosterStatus.textContent = `最近快照 ${formatGeneralUpgradeNumber(roster.count)} 名 · 升阶每轮实时重读 · 首 ID ${roster.firstId} · 更新于 ${formatGeneralUpgradeRosterUpdatedAt(roster.updatedAt)} · 顺序预览 ${preview}${roster.ids.length > 8 ? ' …' : ''} · 原始 ${formatGeneralUpgradeNumber(roster.rawCount)}、拒绝 ${formatGeneralUpgradeNumber(roster.rejectedCount)}${sourceText}`;
        generalUpgradeRosterStatus.className = 'local-sgs-upgrade-roster-status is-ready';
    }

    let lastGeneralUpgradeRenderKey = '';
    function renderGeneralUpgradePage() {
        if (!generalUpgradeResult) return;
        const key = JSON.stringify([readGeneralUpgradeCounts(), readGeneralUpgradeResources(), generalUpgradeRunBusy]);
        if (key === lastGeneralUpgradeRenderKey) { renderGeneralUpgradeRosterStatus(); return; }
        lastGeneralUpgradeRenderKey = key;
        syncGeneralUpgradeInputs();
        renderGeneralUpgradeRosterStatus();
        const plan = calculateGeneralUpgradePlan();
        if (generalUpgradeTargetSummary) {
            generalUpgradeTargetSummary.textContent = `唯一武将 ${formatGeneralUpgradeNumber(plan.uniqueGeneralCount)} 名 · 共升阶 ${formatGeneralUpgradeNumber(plan.totalUpgradeActions)} 次 · 所需经验 ${formatGeneralUpgradeNumber(plan.requiredExp)} · 总帅点 ${formatGeneralUpgradeNumber(plan.targetPoints)}`;
        }
        if (generalUpgradeResourceSummary) {
            generalUpgradeResourceSummary.textContent = `资源总数 ${formatGeneralUpgradeNumber(plan.totalResourceCount)} 个 · 折算总经验 ${formatGeneralUpgradeNumber(plan.totalExp)}`;
        }
        const status = document.createElement('div');
        status.className = `local-sgs-upgrade-status ${plan.targetEnough ? 'is-enough' : 'is-short'}`;
        status.textContent = plan.targetEnough
            ? `经验总量足够：完成目标后剩余 ${formatGeneralUpgradeNumber(plan.expRemaining)} 经验`
            : `经验总量不足：尚缺 ${formatGeneralUpgradeNumber(plan.expShortage)} 经验`;
        const fixed = document.createElement('div');
        fixed.className = 'local-sgs-upgrade-fixed-status';
        fixed.textContent = plan.fixedSealsEnough
            ? '对应将印数量足够自动发包（每层每名固定消耗对应将印 ×1）'
            : '对应将印不足：总经验可能足够，但自动升阶不会改用功勋或其他将印';
        const metrics = document.createElement('div');
        metrics.className = 'local-sgs-upgrade-metrics';
        for (const [label, value] of [
            ['可用总经验', formatGeneralUpgradeNumber(plan.totalExp)],
            ['目标需经验', formatGeneralUpgradeNumber(plan.requiredExp)],
            ['目标帅点', formatGeneralUpgradeNumber(plan.targetPoints)],
            ['按经验可得帅点', formatGeneralUpgradeNumber(plan.feasiblePoints)]
        ]) {
            const card = document.createElement('div');
            const caption = document.createElement('span');
            caption.textContent = label;
            const strong = document.createElement('strong');
            strong.textContent = value;
            card.append(caption, strong);
            metrics.appendChild(card);
        }
        const stages = document.createElement('div');
        stages.className = 'local-sgs-upgrade-stage-results';
        for (const stage of plan.stages) {
            const row = document.createElement('div');
            row.className = 'local-sgs-upgrade-stage-result';
            const label = document.createElement('strong');
            label.textContent = `${stage.from}→${stage.to}阶`;
            const detail = document.createElement('span');
            detail.textContent = `目标 ${stage.target} · 经验池可完成 ${stage.poolCompleted} · 对应将印可发 ${stage.fixedCompleted} · 单独投入上限 ${stage.standaloneMax}`;
            row.append(label, detail);
            stages.appendChild(row);
        }
        generalUpgradeResult.textContent = '';
        generalUpgradeResult.append(status, fixed, metrics, stages);
        if (generalUpgradeSummary) {
            generalUpgradeSummary.textContent = `每轮目标：${plan.stages.map((stage) => `${stage.from}→${stage.to} ${stage.target}名`).join(' · ')}`;
        }
    }

    function createGeneralUpgradeSliderRow({ key, labelText, hintText, max, value, onValue, resource = false }) {
        const row = document.createElement('div');
        row.className = 'local-sgs-upgrade-input-row';
        const head = document.createElement('div');
        head.className = 'local-sgs-upgrade-input-head';
        const label = document.createElement('strong');
        label.textContent = labelText;
        const hint = document.createElement('span');
        hint.textContent = hintText;
        head.append(label, hint);
        const controls = document.createElement('div');
        controls.className = 'local-sgs-upgrade-input-controls';
        const range = document.createElement('input');
        range.type = 'range';
        range.min = '0';
        range.max = String(Math.min(max, Math.max(resource ? 10000 : 100, value * 2)));
        range.step = '1';
        range.value = String(value);
        const number = document.createElement('input');
        number.type = 'number';
        number.min = '0';
        number.max = String(max);
        number.step = '1';
        number.value = String(value);
        range.addEventListener('input', () => onValue(range.value, false));
        number.addEventListener('input', () => onValue(number.value, false));
        number.addEventListener('change', () => onValue(number.value, true));
        controls.append(range, number);
        row.append(head, controls);
        (resource ? generalUpgradeResourceInputs : generalUpgradeCountInputs).set(key, { range, number });
        return row;
    }

