        resourceSection.append(resourceTitle, resourceHint, generalUpgradeResourceSummary, resourceRows);
        generalUpgradeResult = document.createElement('section');
        generalUpgradeResult.className = 'local-sgs-upgrade-result';
		page.append(notice, rosterSection, standaloneSection, generalUpgradeResult, targetSection, resourceSection);
        window.setTimeout(renderGeneralUpgradePage, 0);
        return page;
    }

    function showPanelPage(pageName) {
		activePanelPage = ['archive', 'upgrade'].includes(pageName) ? pageName : 'main';
        if (panelBody) panelBody.hidden = activePanelPage !== 'main';
        if (archivePage) archivePage.hidden = activePanelPage !== 'archive';
		if (generalUpgradePage) generalUpgradePage.hidden = activePanelPage !== 'upgrade';
		if (panelTitleText) panelTitleText.textContent = activePanelPage === 'archive'
			? `邮件助手 · 邮件库 ${VERSION}`
            : (activePanelPage === 'upgrade' ? `武将升阶 ${VERSION}` : `邮件助手 ${VERSION}`);
		if (panelArchiveButton) {
			panelArchiveButton.textContent = activePanelPage === 'archive' ? '助手' : '邮件库';
			panelArchiveButton.title = activePanelPage === 'archive' ? '返回运行助手' : '管理自动邮件、扫描附件邮件和跨账号实验';
		}
		if (panelGeneralUpgradeButton) {
			panelGeneralUpgradeButton.textContent = activePanelPage === 'upgrade' ? '助手' : '升阶';
			panelGeneralUpgradeButton.title = activePanelPage === 'upgrade' ? '返回运行助手' : '查看实时武将快照、设置每轮人数并计算资源';
		}
        if (activePanelPage === 'archive') renderArchivePage();
		if (activePanelPage === 'upgrade') renderGeneralUpgradePage();
    }

    function createArchivePage() {
        const page = document.createElement('div');
        page.className = 'local-sgs-archive-page';
        page.hidden = true;
        const toolbar = document.createElement('div');
        toolbar.className = 'local-sgs-archive-toolbar';
        toolbar.style.cssText = 'display:flex;gap:5px;flex-wrap:wrap;margin-bottom:7px';
        const scanButton = document.createElement('button');
        scanButton.textContent = '扫描当前邮件';
        scanButton.title = '读取当前游戏邮件列表，只保存带附件的邮件';
        scanButton.addEventListener('click', () => {
            const api = findArchiveApi();
            if (!api) return renderArchivePage();
            try {
                const summary = api.scanCurrentAttachmentMails();
                archiveNotice = `扫描完成：当前 ${summary.visibleMailCount || 0} 封，带附件 ${summary.visibleAttachmentCount || 0} 封，新保存 ${summary.addedCount || 0} 封。`;
            } catch (error) {
                archiveNotice = `扫描失败：${error instanceof Error ? error.message : String(error)}`;
            }
            renderArchivePage();
        });
        const refreshButton = document.createElement('button');
        refreshButton.textContent = '刷新服务器再扫描';
        refreshButton.title = '调用官方邮件刷新接口，收到列表后保存带附件邮件';
        refreshButton.addEventListener('click', async () => {
            const api = findArchiveApi();
            if (!api) return renderArchivePage();
            archiveStatus.textContent = '正在刷新邮件列表并归档…';
            try { await api.refreshMailList(); } catch (error) {
                archiveStatus.textContent = `刷新失败：${error instanceof Error ? error.message : String(error)}`;
            }
            renderArchivePage();
        });
        const restoreButton = document.createElement('button');
        restoreButton.textContent = '导入本账号 JSON（自动）';
        const fileInput = document.createElement('input');
        fileInput.type = 'file';
        fileInput.accept = 'application/json,.json';
        fileInput.hidden = true;
        restoreButton.addEventListener('click', () => fileInput.click());
        fileInput.addEventListener('change', async () => {
            const file = fileInput.files?.[0];
            if (!file) return;
            try {
                const api = findArchiveApi();
                if (!api) throw new Error('归档模块尚未就绪');
                const summary = api.importSameAccountBackup(await readSelectedJsonFile(file));
                archiveNotice = `JSON 自动白名单已覆盖并永久保存：本次 ${summary.jsonWhitelistCount || 0} 封（新增 ${summary.localImportedCount || 0}，合并 ${summary.localMergedCount || 0}，解除删除墓碑 ${summary.restoredTombstoneCount || 0}，取消旧白名单 ${summary.previousWhitelistDisabledCount || 0}，跳过 ${summary.skippedCount || 0}）；后续登录会自动读取，无需再次导入。`;
            } catch (error) {
                archiveNotice = `恢复失败：${error instanceof Error ? error.message : String(error)}`;
            } finally {
                fileInput.value = '';
                renderArchivePage();
            }
        });
        const exportButton = document.createElement('button');
        exportButton.textContent = '导出 JSON';
        exportButton.addEventListener('click', () => {
            try {
                downloadArchiveJson(findArchiveApi());
                archiveStatus.textContent = '归档 JSON 已导出';
            } catch (error) {
                archiveStatus.textContent = `导出失败：${error instanceof Error ? error.message : String(error)}`;
            }
        });
        for (const button of [scanButton, refreshButton, restoreButton, exportButton]) {
            button.type = 'button';
            button.style.cssText = 'border:1px solid #a98243;border-radius:5px;padding:4px 7px;background:#3b2d1d;color:#f3e6c7;cursor:pointer;font-size:11px';
            toolbar.appendChild(button);
        }
        toolbar.appendChild(fileInput);
        archiveStatus = document.createElement('div');
        archiveStatus.className = 'local-sgs-archive-status';
        archiveStatus.style.cssText = 'padding:6px;border:1px solid #665234;border-radius:5px;background:rgba(0,0,0,.16);color:#d8c9aa;font-size:11px';
        const archiveTabs = document.createElement('div');
        archiveTabs.className = 'local-sgs-archive-tabs';
        archiveTabs.setAttribute('role', 'tablist');
        archiveTabs.style.cssText = 'display:grid;grid-template-columns:1fr 1fr;gap:5px;margin-top:7px';
        archiveLocalTabButton = document.createElement('button');
        archiveLocalTabButton.type = 'button';
        archiveLocalTabButton.setAttribute('role', 'tab');
        archiveLocalTabButton.textContent = '本账号归档';
        archiveLocalTabButton.addEventListener('click', () => showArchiveTab('local'));
        archiveCrossTabButton = document.createElement('button');
        archiveCrossTabButton.type = 'button';
        archiveCrossTabButton.setAttribute('role', 'tab');
        archiveCrossTabButton.textContent = '跨账号实验';
        archiveCrossTabButton.addEventListener('click', () => showArchiveTab('cross'));
        archiveTabs.append(archiveLocalTabButton, archiveCrossTabButton);
        archiveLocalSection = document.createElement('div');
        const manualDetails = document.createElement('details');
        manualDetails.className = 'local-sgs-manual-mail';
        const manualSummary = document.createElement('summary');
        manualSummary.textContent = '＋ 手动添加或更新邮件';
        const manualHint = document.createElement('div');
        manualHint.className = 'local-sgs-manual-hint';
        manualHint.textContent = '同一 MID 再次保存会更新名称和附件参数；所有内容只保存在本机。';
        archiveManualForm = document.createElement('form');
        archiveManualForm.className = 'local-sgs-manual-form';
        const makeManualField = (labelText, input) => {
            const label = document.createElement('label');
            const caption = document.createElement('span');
            caption.textContent = labelText;
            label.append(caption, input);
            return label;
        };
        const manualTitle = document.createElement('input');
        manualTitle.type = 'text';
        manualTitle.maxLength = 100;
        manualTitle.placeholder = '例如：8月维护礼包';
        manualTitle.required = true;
        const manualMid = document.createElement('input');
        manualMid.type = 'text';
        manualMid.inputMode = 'numeric';
        manualMid.maxLength = 32;
        manualMid.placeholder = 'MID';
        manualMid.required = true;
        const manualAttachmentType = document.createElement('select');
        for (const [value, label] of [['1', '礼包 GiftID'], ['2', '道具附件 + Key']]) {
            const option = document.createElement('option');
            option.value = value;
            option.textContent = label;
            manualAttachmentType.appendChild(option);
        }
        const manualGiftId = document.createElement('input');
        manualGiftId.type = 'text';
        manualGiftId.inputMode = 'numeric';
        manualGiftId.maxLength = 16;
        manualGiftId.placeholder = 'GiftID / 道具ID';
        manualGiftId.required = true;
        const manualCount = document.createElement('input');
        manualCount.type = 'number';
        manualCount.min = '1';
        manualCount.max = '999999';
        manualCount.value = '1';
        const manualKey = document.createElement('input');
        manualKey.type = 'text';
        manualKey.maxLength = 256;
        manualKey.placeholder = '礼包可留空；道具附件必填';
        archiveManualInputs = {
            title: manualTitle,
            mid: manualMid,
            attachmentType: manualAttachmentType,
            giftId: manualGiftId,
            count: manualCount,
            key: manualKey
        };
        const manualFields = document.createElement('div');
        manualFields.className = 'local-sgs-manual-grid';
        manualFields.append(
            makeManualField('名称', manualTitle),
            makeManualField('MID', manualMid),
            makeManualField('附件类型', manualAttachmentType),
            makeManualField('GiftID / 道具ID', manualGiftId),
            makeManualField('数量', manualCount),
            makeManualField('验证码 Key', manualKey)
        );
        const saveManualButton = document.createElement('button');
        saveManualButton.type = 'submit';
        saveManualButton.textContent = '保存到自动列表';
        const resetManualButton = document.createElement('button');
        resetManualButton.type = 'button';
        resetManualButton.textContent = '清空';
        resetManualButton.addEventListener('click', resetArchiveManualForm);
        const manualActions = document.createElement('div');
        manualActions.className = 'local-sgs-manual-actions';
        manualActions.append(saveManualButton, resetManualButton);
        archiveManualForm.append(manualFields, manualActions);
        archiveManualForm.addEventListener('submit', (event) => {
            event.preventDefault();
            try {
                const api = findArchiveApi();
                if (!api || typeof api.upsertRecord !== 'function') throw new Error('邮件库接口尚未就绪');
                const summary = api.upsertRecord({
                    title: manualTitle.value,
                    mid: manualMid.value,
                    attachmentType: Number(manualAttachmentType.value),
                    giftId: manualGiftId.value,
                    count: manualCount.value,
                    key: manualKey.value
                });
                archiveNotice = `${summary.created ? '已添加' : '已更新'} MID ${summary.record?.mid || manualMid.value}，后续自动循环将读取该记录。`;
                resetArchiveManualForm();
            } catch (error) {
                archiveNotice = `保存失败：${error instanceof Error ? error.message : String(error)}`;
            }
            renderArchivePage();
        });
        manualDetails.append(manualSummary, manualHint, archiveManualForm);
        const automationNote = document.createElement('div');
        automationNote.textContent = 'JSON 专用自动化：处理人工导入及本地正式列表扫描新增的 MID；现场邮箱不会走 H5 点击领取，跨账号实验永不进入自动队列。';
        automationNote.style.cssText = 'margin-top:6px;padding:6px;border-left:3px solid #a98243;background:rgba(169,130,67,.1);color:#cdbb98;font-size:10px;line-height:1.45';
        archiveList = document.createElement('div');
        archiveList.className = 'local-sgs-archive-list';
        archiveList.style.cssText = 'max-height:360px;overflow:auto;margin-top:2px';
        archiveLocalSection.append(manualDetails, automationNote, archiveList);
        archiveCrossSection = document.createElement('div');
        archiveCrossSection.style.cssText = 'margin-top:7px;padding:8px;border:1px solid #754a42;border-radius:5px;background:rgba(74,45,40,.12)';
        const crossHeader = document.createElement('div');
        crossHeader.textContent = '跨账号实验 · 本人控制账号 · 单封一次';
        crossHeader.style.cssText = 'color:#dfa99b;font-weight:700;font-size:11px';
        const crossWarning = document.createElement('div');
        crossWarning.textContent = '导入来源账号 A 的 JSON 后，使用当前账号 B 手动发送；每条记录最多尝试一次，发送前再次确认。';
        crossWarning.style.cssText = 'margin-top:3px;color:#a98e86;font-size:10px;line-height:1.4';
        const crossImportButton = document.createElement('button');
        crossImportButton.type = 'button';
        crossImportButton.textContent = '导入其他账号 JSON';
        crossImportButton.style.cssText = 'margin-top:6px;border:1px solid #9b5f52;border-radius:5px;padding:4px 7px;background:#4a2d28;color:#f0d2ca;cursor:pointer;font-size:11px';
        const crossFileInput = document.createElement('input');
        crossFileInput.type = 'file';
        crossFileInput.accept = 'application/json,.json';
        crossFileInput.hidden = true;
        crossImportButton.addEventListener('click', () => crossFileInput.click());
        crossFileInput.addEventListener('change', async () => {
            const file = crossFileInput.files?.[0];
            if (!file) return;
            try {
                const api = findArchiveApi();
                if (!api) throw new Error('归档模块尚未就绪');
                const summary = api.importCrossAccountArchive(await readSelectedJsonFile(file));
                archiveStatus.textContent = `跨账号 JSON 已导入：新增 ${summary.importedCount || 0}，重复 ${summary.duplicateCount || 0}，跳过 ${summary.skippedCount || 0}`;
            } catch (error) {
                archiveStatus.textContent = `跨账号导入失败：${error instanceof Error ? error.message : String(error)}`;
            } finally {
                crossFileInput.value = '';
                renderArchivePage();
            }
        });
        archiveCrossList = document.createElement('div');
        archiveCrossList.style.cssText = 'max-height:280px;overflow:auto';
        archiveCrossSection.append(crossHeader, crossWarning, crossImportButton, crossFileInput, archiveCrossList);
        page.append(toolbar, archiveStatus, archiveTabs, archiveLocalSection, archiveCrossSection);
        showArchiveTab('local');
        return page;
    }

