    function setPanelText(node, text) {
        if (node && node.textContent !== String(text)) node.textContent = String(text);
    }
    function renderPanel(state = readState()) {
        if (!panel) return;
        armVersionEntry(state);
        const officerTab = readOfficerLinkTab();
        let label = phaseLabel(state.phase);
        if (officerTab.mode === 'listener') {
            label = officerTab.active ? '官阶监听端 · 持续在线监听' : '官阶监听端 · 已停止';
        } else if (officerTab.mode === 'receiver' && (!state.enabled || ['idle', 'stopped'].includes(state.phase))) {
            label = officerTab.active ? '官阶接收端 · 等待 LV1 事件' : '官阶接收端 · 已停止';
        } else if (state.enabled && state.phase === 'recovery_wait') {
            label = '微端恢复中（立即开启新一轮）';
        } else if (state.enabled && state.retryAt > Date.now()) {
            label = `重试倒计时 ${formatDuration(state.retryAt - Date.now())}`;
        } else if (state.enabled && Number(state.scheduledEntryAt || 0) > Date.now()) {
            const backoffTip = (ADAPTIVE_INTERVAL_ENABLED && Number(state.adaptiveIntervalMs) > readCycleMs())
                ? `（等邮件刷新 ${formatDuration(Number(state.adaptiveIntervalMs))}）`
                : '';
            const waitingAtEntryPage = ['login', 'login_submitted'].includes(state.phase);
            label = `${waitingAtEntryPage ? gameEntryLabel(state.gameEntryTarget || readGameEntryTarget()) + '进入游戏' : '版本页准备'}倒计时 ${formatDuration(Number(state.scheduledEntryAt) - Date.now())}${backoffTip}`;
        } else if (state.enabled && state.phase === 'idle' && state.nextRunAt > Date.now()) {
            label = `登录准备倒计时 ${formatDuration(state.nextRunAt - Date.now())}`;
        }
        setPanelText(panelState, label);
        panelMessage.textContent = officerTab.mode === 'listener'
            ? (officerTab.status || '')
            : (officerTab.mode === 'timer' || state.enabled
                ? (state.message || '')
                : (officerTab.status || state.message || ''));
        toggleButton.textContent = officerTab.mode === 'timer'
            ? (state.enabled ? '暂停' : '启动')
            : (officerTab.mode === 'listener'
                ? (officerTab.active ? '停止监听' : '启动监听')
                : (officerTab.active ? '停止等待' : '启用等待'));
        renderOfficerLinkControls(officerTab);
        if (cycleValue && cycleSecondValue &&
            document.activeElement !== cycleValue && document.activeElement !== cycleSecondValue) {
            const cycleMs = readCycleMs();
            syncMinuteSecondInputs(cycleValue, cycleSecondValue, cycleMs);
            const title = `当前 ${formatDuration(cycleMs)}；直接输入分钟和秒（秒为 0～59）`;
            cycleValue.title = title;
            cycleSecondValue.title = title;
        }
        if (gameEntryTargetSelect && document.activeElement !== gameEntryTargetSelect) {
            const activeTarget = state.enabled && !['idle', 'stopped'].includes(state.phase)
                ? state.gameEntryTarget
                : readGameEntryTarget();
            gameEntryTargetSelect.value = normalizeGameEntryTarget(activeTarget);
        }
        if (mailSourceValue) mailSourceValue.textContent = JSON_ONLY_MAIL_AUTOMATION ? 'JSON + 本地扫描新增' : '现场邮箱 + JSON';
        if (officerTargetInput) {
            const officialMax = visibleOfficialOfficerMaxLevel();
            officerTargetInput.max = String(officialMax);
            if (document.activeElement !== officerTargetInput) officerTargetInput.value = String(readOfficerTargetLevel());
            officerTargetInput.title = `全服统一上限 LV${officialMax}；用户可自行调整本轮目标`;
            if (officerTargetMaxValue) officerTargetMaxValue.textContent = `统一上限 LV${officialMax}`;
        }
        if (dailyRewardItemButtons && dailyRewardItemButtons.size) {
            const dailyItems = readDailyRewardItems();
            for (const item of DAILY_REWARD_ITEM_DEFS) {
                const button = dailyRewardItemButtons.get(item.key);
                if (!button) continue;
                const supported = DAILY_REWARD_SUPPORTED_ITEM_KEYS.has(item.key);
                const enabled = dailyItems[item.key] === true;
                button.setAttribute('aria-pressed', enabled ? 'true' : 'false');
                button.setAttribute('aria-disabled', supported ? 'false' : 'true');
                button.dataset.enabled = enabled ? '1' : '0';
                button.style.borderColor = !supported ? '#302b25' : (enabled ? '#e2b55c' : '#51483a');
                button.style.background = !supported ? '#15120f' : (enabled ? '#6a4819' : '#211a12');
                button.style.color = !supported ? '#4e473d' : (enabled ? '#fff1bd' : '#756b5b');
                button.style.cursor = supported ? 'pointer' : 'not-allowed';
                button.style.boxShadow = supported && enabled ? '0 0 8px rgba(240,201,121,.55),inset 0 0 4px rgba(255,225,150,.18)' : 'none';
            }
        }
        if (generalUpgradeSummary) {
            const counts = readGeneralUpgradeCounts();
            generalUpgradeSummary.textContent = `每轮目标：${GENERAL_UPGRADE_STAGE_DEFS.map((stage) => `${stage.from}→${stage.to} ${counts[stage.key]}名`).join(' · ')}（点击设置/计算）`;
        }
        if (dailyFreqButton) dailyFreqButton.textContent = readDailyFreq() === 'cycle' ? '普通日常：每轮' : '普通日常：每天一次';
        if (giftCodeStatus) giftCodeStatus.textContent = formatGiftCodeQueueStatus();
        refreshLogButtonLabel();
        if (logBox && !logBox.hidden) renderLogs();
    }

    async function tickBody() {
        await officerLinkTick();
        if (readOfficerLinkTab().mode === 'listener') {
            // 监听端与接收端会同时看到主进程统一存储中的邮件助手状态。
            // 监听端必须在这里止步，避免把接收端的登录轮次误认成自己的游戏页并参与领取。
            clearScheduledLoginTimer();
            renderPanel(readState());
            return;
        }
        let state = readState();
        state = applyWatchdogRecovery(state);
        if (state.phase === 'recovery_wait') {
            state = startFreshCycleAfterWatchdogRecovery(state);
            renderPanel(state);
            return;
        }
        state = recoverInterruptedClaimingState(state);
        state = recordPendingElectronGamePageRecovery(state);
        renderPanel(state);
        if (!state.enabled) {
            clearScheduledLoginTimer();
            return;
        }

        // 微端或 webview 恢复可能正好打断“游戏页 -> 登录页”的退出跳转。
        // 旧轮已经完成领取时，logout_pending 不能留在游戏页空等；每 10 秒最多补一次官方登录页导航，
        // 到达登录页后仍由原有的退出按钮/账密表单稳定确认逻辑收尾。
        if (TOP_WINDOW && state.phase === 'logout_pending' && !isLoginUrl()) {
            const now = Date.now();
            const lastNavigationAt = Math.max(0, Number(state.logoutPageRefreshAt) || 0);
            if (!lastNavigationAt || now - lastNavigationAt >= LOGOUT_PAGE_REFRESH_GRACE_MS) {
                state = setMessage('检测到退出跳转被恢复过程打断：正在重新前往官方登录页完成退出确认', {
                    logoutPageRefreshAt: now,
                    retryAt: 0,
                    retryAction: ''
                });
                requestTopNavigation(LOGIN_URL);
            }
            return;
        }

        // 退出确认后若版本选择页仍残留可见“退出登录”，说明此前只是页面误判，
        // 必须在 adoptAlreadyLoadedGamePage 和定时登录之前优先完成真正退出。
        if (TOP_WINDOW
            && state.phase === 'idle'
            && state.scheduleFinalizedForCycle === state.cycleId
            && Number(state.nextRunAt || 0) > 0) {
            const staleLogout = findVisibleLogoutButton();
            if (staleLogout && isVisible(staleLogout)) {
                const now = Date.now();
                clearScheduledLoginTimer();
                state = setMessage('检测到版本选择页仍有退出按钮：暂停下一轮登录并继续执行真正退出；首次进入计划保持不变', {
                    phase: 'logout_pending',
                    nextRunAt: 0,
                    logoutClickedFor: state.cycleId,
                    logoutAttemptAt: now,
                    logoutUiStableSince: 0,
                    logoutPageRefreshAt: 0,
                    retryAt: 0,
                    retryAction: ''
                });
                pushRawLog('logout-timing', `退出计划复核：版本选择页仍可退出 @ ${new Date(now).toISOString()}；保留首次周期计划`);
                staleLogout.click();
                renderPanel(state);
                return;
            }
        }

        ensureMailArrivalHook();

        if (adoptAlreadyLoadedGamePage()) return;

        if (state.phase === 'idle') {
            if (!TOP_WINDOW) return;
            if (readOfficerLinkTab().mode !== 'timer') {
                clearScheduledLoginTimer();
                return;
            }
            if (!isLoginUrl() && Number(state.lastLogoutConfirmedAt) > 0) {
                requestTopNavigation(LOGIN_URL);
                return;
            }
            if (isLoginUrl() && findVisibleLogoutButton()) {
                await handleLoginPage();
                return;
            }
            if (isLoginUrl() && Number(state.scheduledEntryAt || state.targetLoginAt || state.nextRunAt) > Date.now()) {
                if (await dispatchScheduledLoginEarly(state)) return;
            }
            armScheduledLogin(readState());
            if (Date.now() >= Number(readState().nextRunAt || 0)) {
                await dispatchScheduledLogin(Number(readState().nextRunAt) || 0);
            }
            return;
        }

        clearScheduledLoginTimer();

        if (isLoginUrl() && TOP_WINDOW) await handleLoginPage();
        if (state.phase === 'game_loading') await handleGamePage();
    }

    installCredentialSessionCache();
    installLoginClickGuard();
    installTimeoutAlertGuard();

    if (TOP_WINDOW) {
        window.addEventListener('message', (event) => {
            const data = event.data;
            if (!data || data.type !== MESSAGE_TYPE || data.action !== 'navigate') return;
            if (data.url !== LOGIN_URL) return;
            let hostname = '';
            try { hostname = new URL(event.origin).hostname; } catch (_) { return; }
            if (!isOfficialHost(hostname)) return;
            location.assign(LOGIN_URL);
        });

        const mountPanel = () => createPanel();
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', mountPanel, { once: true });
        } else {
            mountPanel();
        }

        registerMenu('启动/暂停当前启动方式', toggleEnabled);
        registerMenu('立即执行一轮（忽略登录锁）', runNow);
        registerMenu('清除本机保存的账号密码', clearSessionCredentials);
        registerMenu('清除运行记录', clearLogs);
    }

    reportMailAssistantWatchdog(readState());
    Object.defineProperty(pageWindow, '__SGSOL_OFFICER_TRIGGER__', {
        configurable: true,
        value: Object.freeze({
            version: VERSION,
            snapshot: () => {
                const tab = readOfficerLinkTab();
                return {
                    mode: tab.mode,
                    active: tab.active,
                    ownAccountId: officerOwnAccountId() || tab.ownAccountId,
                    receiverId: tab.receiverId,
                    listenerTargets: tab.listenerTargets,
                    friends: tab.friends,
                    bridgeOnline: tab.bridgeOnline,
                    bridgePeers: tab.bridgePeers,
                    activeEvent: tab.activeEvent,
                    status: tab.status,
                    lastError: tab.lastError,
                    mailState: readState()
                };
            },
            collectFriends: collectOfficerFriends,
            refreshFriends: refreshOfficerFriends,
            rearm: rearmOfficerListener,
            setMode: updateOfficerLinkMode,
            connect: testOfficerBridgeConnection,
            poll: officerLinkTick
        })
    });

    function armVersionEntry(state) {
        const deadline = state.enabled && ['login', 'login_submitted'].includes(state.phase) ? Number(state.scheduledEntryAt) : 0;
        if (!deadline) { if (versionEntryTimer) clearTimeout(versionEntryTimer); versionEntryTimer = 0; versionEntryDeadline = 0; return; }
        if (versionEntryDeadline === deadline) return;
        if (versionEntryTimer) clearTimeout(versionEntryTimer);
        versionEntryDeadline = deadline;
        versionEntryTimer = setTimeout(() => { versionEntryTimer = 0; void tick(); }, Math.max(0, deadline - Date.now()));
    }
    let tickBusy = false;
    async function tick() {
        if (tickBusy) return;
        tickBusy = true;
        try { await tickBody(); } catch (error) { console.warn('[mail-cycle]', error.message); }
        finally { tickBusy = false; }
    }
    setInterval(() => { void tick(); }, 1000);
    const sharedBridge = mailAssistantSharedBridge();
    if (sharedBridge && typeof sharedBridge.onMailAssistantSharedChange === 'function') {
        let queued = false;
        sharedBridge.onMailAssistantSharedChange(({ key }) => {
            const cached = sharedValueCache.get(key);
            if (cached) cached.at = 0;
            if (queued) return;
            queued = true;
            setTimeout(() => { queued = false; try { if (panel) renderPanel(readState()); } catch (_) {} }, 50);
        });
    }
    setInterval(() => { try { if (panel) renderPanel(readState()); } catch (error) {
        if (panelMessage) panelMessage.textContent = sharedStorageError || error.message;
    } }, 500);
    void tick();
})();

