	let clearArmedUntil = 0;

	function loadState() {
		let parsed = null;
		try {
			const raw = window.localStorage && window.localStorage.getItem(STORAGE_KEY);
			parsed = raw ? JSON.parse(raw) : null;
		} catch (error) {}
		const records = Array.isArray(parsed && parsed.records)
			? parsed.records.filter(record => record && record.clientId && record.nickname).slice(-MAX_RECORDS)
			: [];
		const position = parsed && parsed.position && Number.isFinite(Number(parsed.position.left)) && Number.isFinite(Number(parsed.position.top))
			? { left: Number(parsed.position.left), top: Number(parsed.position.top) }
			: { left: null, top: null };
