		const guild = stringValue(readField(profile, ["guildName", "GuildName"]).value) || stringValue(readField(extra, ["guildName", "GuildName"]).value);
		const md5 = stringValue(readField(profile, ["md5Account", "Md5Account"]).value) || stringValue(readField(extra, ["md5Account", "Md5Account"]).value);
		const record = {
			clientId: id,
			nickname,
			guildName: guild,
			md5Account: md5,
			dailyGamePlayedCount: optionalNumber(readField(extra, ["dailyGamePlayedCount"]).value),
			tongQian: optionalNumber(readField(extra, ["tongQian"]).value),
			tongShuai: optionalNumber(readField(extra, ["tongShuai"]).value),
			tongShuaiTotalCnt: optionalNumber(readField(extra, ["TongShuaiTotalCnt"]).value),
			tongShuaiWinCnt: optionalNumber(readField(extra, ["TongShuaiWinCnt"]).value),
			tongShuaiFleeCnt: optionalNumber(readField(extra, ["TongShuaiFleeCnt"]).value),
			joinFactionTime: optionalNumber(readField(extra, ["join_faction_time"]).value),
			factionType: optionalNumber(readField(extra, ["faction_type"]).value),
			factionSlogan: optionalNumber(readField(extra, ["faction_slogan"]).value),
			userMark: optionalNumber(readField(extra, ["user_mark"]).value),
			isSelf: Boolean(readField(profile, ["IsSelf", "isSelf"]).value),
			isNormalRobot: Boolean(readField(profile, ["IsNormalRobot", "isNormalRobot"]).value),
			isPowerRobot: Boolean(readField(profile, ["IsPowerRobot", "isPowerRobot"]).value),
			isSsuperRobot: Boolean(readField(profile, ["IsSsuperRobot", "isSsuperRobot"]).value)
		};
