	}

	function mergeRecord(target, source) {
		const nullableFields = [
			"dailyGamePlayedCount", "tongQian", "tongShuai", "tongShuaiTotalCnt",
			"tongShuaiWinCnt", "tongShuaiFleeCnt", "joinFactionTime",
			"factionType", "factionSlogan", "userMark"
		];
		for (const field of nullableFields) {
			if (source[field] !== null && source[field] !== undefined) target[field] = source[field];
		}
		if (source.guildName) target.guildName = source.guildName;
		if (source.md5Account) target.md5Account = source.md5Account;
		target.isSelf = source.isSelf;
		target.isNormalRobot = source.isNormalRobot;
		target.isPowerRobot = source.isPowerRobot;
		target.isSsuperRobot = source.isSsuperRobot;
	}

	function capture(view, countCall, source) {
		const incoming = makeRecord(view);
		if (!incoming) return;
		incoming.lastCapturedBy = source || "profile";
