		}
		state.records.sort((a, b) => Number(b.lastSeenAt || 0) - Number(a.lastSeenAt || 0));
		if (state.records.length > MAX_RECORDS) state.records.length = MAX_RECORDS;
		persist();
		render();
	}

	function resolveLayaRuntime() {
