	function element(tag, className, text) {
		const node = document.createElement(tag);
		if (className) node.className = className;
		if (text !== undefined) node.textContent = text;
		return node;
	}

	function applyPanelPosition(left, top, save) {
		if (!panel) return;
		const width = panel.offsetWidth || 380;
		const height = panel.offsetHeight || 280;
		const maxLeft = Math.max(8, window.innerWidth - width - 8);
		const maxTop = Math.max(8, window.innerHeight - Math.min(height, window.innerHeight - 8) - 8);
		const nextLeft = Math.max(8, Math.min(maxLeft, Number(left)));
		const nextTop = Math.max(8, Math.min(maxTop, Number(top)));
		panel.style.left = nextLeft + "px";
		panel.style.top = nextTop + "px";
		panel.style.right = "auto";
		panel.style.bottom = "auto";
		state.position = { left: nextLeft, top: nextTop };
		if (save) persist();
	}

	function setCollapsed(collapsed) {
		if (!panel) return;
		state.collapsed = Boolean(collapsed);
		panel.classList.toggle("xc-upo-collapsed", state.collapsed);
		const button = panel.querySelector("[data-action='collapse']");
		if (button) {
			button.textContent = state.collapsed ? "+" : "−";
			button.title = state.collapsed ? "展开" : "折叠";
			button.setAttribute("aria-label", button.title);
		}
		persist();
	}

	function formatTime(timestamp) {
		if (!timestamp) return "--";
		try {
			return new Date(timestamp).toLocaleTimeString("zh-CN", { hour12: false });
		} catch (error) {
			return "--";
		}
	}

	function profileState(record) {
		const daily = record.dailyGamePlayedCount === null || record.dailyGamePlayedCount === undefined
			? "今日场次 --"
			: "今日场次 " + record.dailyGamePlayedCount;
		return [record.guildName || "无工会", daily].join(" · ");
	}

	function deleteUser(clientId, nickname) {
		const id = String(clientId || "");
		const name = String(nickname || "");
		state.records = state.records.filter(record => !(String(record.clientId || "") === id && String(record.nickname || "") === name));
		persist();
		render();
	}

	function deleteClientId(clientId) {
		const id = String(clientId || "");
		state.records = state.records.filter(record => String(record.clientId || "") !== id);
		persist();
		render();
	}

	function render() {
		if (!panel || !panelBody || !summaryNode) return;
		const groups = new Map();
		for (const record of state.records) {
			const id = String(record.clientId || "未知");
			if (!groups.has(id)) groups.set(id, []);
			groups.get(id).push(record);
		}
		const orderedGroups = [...groups.entries()].sort((a, b) => {
			const sizeDiff = b[1].length - a[1].length;
			if (sizeDiff) return sizeDiff;
			return Number(b[1][0].lastSeenAt || 0) - Number(a[1][0].lastSeenAt || 0);
		});
		summaryNode.textContent = groups.size + " 个 ID · " + state.records.length + " 个用户名";
		const hookStatus = hookReady ? "监听中" : "等待 UserInfoView";
		statusNode.textContent = state.records.length
			? hookStatus + " · 最后记录 " + formatTime(state.records[0].lastSeenAt)
			: hookStatus + " · 暂无资料";
		panelBody.textContent = "";
		panelBody.appendChild(statusNode);
		if (!orderedGroups.length) {
			panelBody.appendChild(element("div", "xc-upo-empty", "暂无用户资料"));
			return;
		}
		for (const [id, records] of orderedGroups) {
			records.sort((a, b) => Number(b.lastSeenAt || 0) - Number(a.lastSeenAt || 0));
			const group = element("section", "xc-upo-group" + (records.length > 1 ? " xc-upo-shared" : ""));
			const head = element("div", "xc-upo-group-head");
			head.appendChild(element("span", "xc-upo-group-id", "ClientId " + id));
			head.appendChild(element("span", "xc-upo-badge", records.length > 1 ? "同 ID " + records.length + " 人" : "1 人"));
			const deleteGroupButton = element("button", "xc-upo-delete xc-upo-group-delete", "×");
			deleteGroupButton.type = "button";
			deleteGroupButton.title = "删除此 ClientId 分组";
			deleteGroupButton.setAttribute("aria-label", deleteGroupButton.title);
			deleteGroupButton.addEventListener("click", event => {
				event.stopPropagation();
				deleteClientId(id);
			});
			head.appendChild(deleteGroupButton);
			group.appendChild(head);
			for (const record of records) {
				const row = element("div", "xc-upo-row");
				const rowInfo = element("div", "xc-upo-row-main");
				rowInfo.appendChild(element("span", "xc-upo-name", record.nickname));
				rowInfo.appendChild(element("span", "xc-upo-meta", profileState(record)));
				row.appendChild(rowInfo);
				const deleteUserButton = element("button", "xc-upo-delete xc-upo-user-delete", "×");
				deleteUserButton.type = "button";
				deleteUserButton.title = "删除此用户名";
				deleteUserButton.setAttribute("aria-label", deleteUserButton.title);
				deleteUserButton.addEventListener("click", event => {
					event.stopPropagation();
					deleteUser(record.clientId, record.nickname);
				});
				row.appendChild(deleteUserButton);
				row.title = "查看 " + (record.seenCount || 0) + " 次，最后 " + formatTime(record.lastSeenAt);
				group.appendChild(row);
			}
			panelBody.appendChild(group);
		}
	}

	function exportJson() {
		const groups = {};
		for (const record of state.records) {
			if (!groups[record.clientId]) groups[record.clientId] = [];
			groups[record.clientId].push(record);
		}
		const json = JSON.stringify({
			exportedAt: new Date().toISOString(),
			records: state.records,
			groups
		}, null, 2);
		try {
			const blob = new Blob([json], { type: "application/json;charset=utf-8" });
			const link = document.createElement("a");
			link.href = URL.createObjectURL(blob);
			link.download = "sgs-user-profiles-" + Date.now() + ".json";
			document.body.appendChild(link);
			link.click();
			link.remove();
			window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
		} catch (error) {}
		return json;
	}

	function clearRecords() {
		const now = Date.now();
		if (now > clearArmedUntil) {
			clearArmedUntil = now + 4000;
			if (clearButton) {
				clearButton.textContent = "再清";
				clearButton.title = "4 秒内再次点击清空";
				window.setTimeout(() => {
					if (Date.now() >= clearArmedUntil && clearButton) {
						clearButton.textContent = "清";
						clearButton.title = "清空本地记录";
					}
				}, 4100);
			}
			return;
		}
		clearArmedUntil = 0;
		state.records = [];
		persist();
		if (clearButton) {
			clearButton.textContent = "清";
			clearButton.title = "清空本地记录";
		}
		render();
	}

	function ensurePanel() {
		if (!document.body) return false;
