		panel = element("section", "xc-upo-panel");
		panel.id = PANEL_ID;
		panel.setAttribute("aria-label", "用户资料分类");
		const header = element("div", "xc-upo-header");
		const title = element("span", "xc-upo-title", "用户资料分类");
		summaryNode = element("span", "xc-upo-summary");
		const actions = element("span", "xc-upo-actions");
		const collapse = element("button", "", state.collapsed ? "+" : "−");
		collapse.type = "button";
		collapse.dataset.action = "collapse";
		collapse.title = state.collapsed ? "展开" : "折叠";
		collapse.setAttribute("aria-label", collapse.title);
		const exportButton = element("button", "", "出");
		exportButton.type = "button";
