		exportButton.setAttribute("aria-label", exportButton.title);
		const clear = element("button", "", "清");
		clear.type = "button";
		clear.title = "清空本地记录";
		clear.setAttribute("aria-label", clear.title);
		actions.append(collapse, exportButton, clear);
		header.append(title, summaryNode, actions);
		panelBody = element("div", "xc-upo-body");
		statusNode = element("div", "xc-upo-status");
		panelBody.appendChild(statusNode);
		panel.append(header, panelBody);
