		return true;
	}

	function start() {
		ensurePanel();
		ensureHook();
		if (!hookTimer) hookTimer = window.setInterval(() => { ensurePanel(); ensureHook(); }, 250);
		if (!panelTimer && !document.body) panelTimer = window.setInterval(() => ensurePanel(), 500);
	}

	function show() {
		ensurePanel();
		if (panel) panel.style.display = "";
	}

	function hide() {
		if (panel) panel.style.display = "none";
	}

	function stop() {
		if (hookTimer) window.clearInterval(hookTimer);
		if (panelTimer) window.clearInterval(panelTimer);
		hookTimer = 0;
		panelTimer = 0;
		restoreHook();
		if (panel) panel.remove();
		const style = document.getElementById(STYLE_ID);
		if (style) style.remove();
		panel = null;
		panelBody = null;
		summaryNode = null;
		statusNode = null;
		clearButton = null;
	}

	const api = {
