(function installBanSchemeLibrary() {
	'use strict';
	if (window.__H5_BAN_SCHEME_LIBRARY__) return;

	var PANEL_BODY_ID = 'xc-starting-hand-reroller-body';
	var SECTION_ID = 'xc-ban-scheme-export-section';
