	var lastStatus = 'waiting:runtime';
	var lastSummary = null;

	function runtime() {
		return window.__H5_SKIN_RUNTIME__ || null;
	}

	function shieldManager() {
		var value = null;
		var valueRuntime = runtime();
		if (!valueRuntime || typeof valueRuntime.class !== 'function') return null;
		try { value = valueRuntime.class('GameShieldGeneralManager', true); } catch (error) {}
		if (!value) {
			try { value = valueRuntime.class('GameShieldGeneralManager'); } catch (error) {}
		}
		try {
			if (value && typeof value.I === 'function') value = value.I();
		} catch (error) {}
		return value && (value.instance || value);
	}

	function finiteId(value) {
		var number = Number(value);
		return Number.isFinite(number) && number > 0 ? Math.floor(number) : 0;
	}

	function uniqueIds(values) {
		var seen = Object.create(null);
		return (Array.isArray(values) ? values : []).map(finiteId).filter(function (id) {
			if (!id || seen[id]) return false;
			seen[id] = true;
			return true;
		}).sort(function (left, right) { return left - right; });
	}

	function dictionaryKeys(dictionary) {
		var result = [];
		try {
			if (dictionary && typeof dictionary.forEach === 'function') {
				dictionary.forEach(function (key) { result.push(key); });
			}
		} catch (error) {}
