	}

	function nativeSchemeName(manager, schemeId) {
		try {
			var schemes = manager.GetAllShieldGeneralSCheme();
			for (var index = 0; index < schemes.length; index += 1) {
				if (Number(schemes[index].scheme_id) === schemeId) {
					return String(schemes[index].scheme_node && schemes[index].scheme_node.scheme_name || '方案' + schemeId);
				}
			}
		} catch (error) {}
		return '方案' + schemeId;
	}

	function readNativeSchemes() {
		var manager = shieldManager();
		if (!manager) throw new Error('请先登录游戏并打开一次禁将窗口');
		var generalIds = dictionaryKeys(manager.ShieldGeneralDic);
		var schemes = [];
		for (var schemeId = 1; schemeId <= 4; schemeId += 1) {
			var bannedGeneralIds = generalIds.filter(function (generalId) {
				try { return Boolean(manager.GetShieldGeneralState(generalId, schemeId)); }
				catch (error) { return false; }
