	}

	function applyNativeScheme(payload) {
		var manager = shieldManager();
		if (!manager) throw new Error('请先登录游戏并打开一次禁将窗口');
		var schemeId = finiteId(payload && payload.nativeSchemeId);
		if (schemeId < 1 || schemeId > 4) throw new Error('只能写入游戏方案一至四');
		var desired = uniqueIds(payload && payload.bannedGeneralIds);
		var desiredMap = Object.create(null);
		desired.forEach(function (id) { desiredMap[id] = true; });
		var current = dictionaryKeys(manager.ShieldGeneralDic).filter(function (generalId) {
			try { return Boolean(manager.GetShieldGeneralState(generalId, schemeId)); }
			catch (error) { return false; }
		});
		var currentMap = Object.create(null);
		current.forEach(function (id) { currentMap[id] = true; });
		var skipped = [];
		var toClose = desired.filter(function (id) {
			if (currentMap[id]) return false;
			try {
				if (typeof manager.InShieldCloseGeneral === 'function' && !manager.InShieldCloseGeneral(id)) {
					skipped.push(id);
					return false;
				}
			} catch (error) {}
			return true;
		});
		var toOpen = current.filter(function (id) { return !desiredMap[id]; });
		if (toClose.length || toOpen.length) {
			manager.ShieldGeneralBatchState = 0;
			manager.SendClientShieldGeneralBatchReq(schemeId, toClose, toOpen);
		}
