			'<div class="xc-ban-row xc-ban-actions"><button type="button" data-ban-apply>一键套用</button><button type="button" data-ban-delete>删除</button><button type="button" data-ban-import>导入</button><button type="button" data-ban-export>导出</button></div>' +
