		lastStatus = displayedPayload ? 'showing-solutions' : 'waiting:yanjiao-cards';
		return true;
	}

	function copyEquation(text) {
		try {
			if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(text);
		} catch (error) {}
	}

	function postToChildren(message) {
		for (let index = 0; index < window.frames.length; index += 1) {
			try { window.frames[index].postMessage(message, '*'); } catch (error) {}
		}
	}

	function performLocalAssignment(message) {
		if (!currentLocalRequest || currentLocalRequest.sourceId !== message.sourceId || currentLocalRequest.requestId !== message.requestId) return false;
		const solution = currentLocalRequest.rawSolutions[Number(message.solutionIndex)];
		if (!solution || !currentLocalRequest.canAssign || typeof currentLocalRequest.assigner !== 'function') return false;
		currentLocalRequest.assigner(solution, Number(message.side));
		assignmentCount += 1;
		lastStatus = 'assignment-requested';
		return true;
	}

	function requestSolutionAction(payload, solutionIndex, side) {
		const solution = payload.solutions[solutionIndex];
		if (!solution) return;
		if (!payload.canAssign) {
			copyEquation(solutionText(solution));
			lastStatus = 'solution-copied';
			return;
		}
		const message = {
			type: MESSAGE_TYPE,
			action: 'assign',
			sourceId: payload.sourceId,
			requestId: payload.requestId,
			solutionIndex,
			side,
			hops: 0
		};
		performLocalAssignment(message);
		postToChildren(message);
		lastStatus = 'assignment-requested';
		const note = document.querySelector('#' + RESULT_ID + ' .xc-yj-note');
		if (note) note.textContent = '已请求自动分配';
	}

	function renderPayload(payload) {
		displayedPayload = payload;
		if (!mountSection()) return false;
		const result = document.getElementById(RESULT_ID);
		if (!result) return false;
		result.innerHTML = '';
		if (!payload.solutions.length) {
			result.innerHTML = '<div class="xc-yj-empty">【严教】无解</div>';
			lastStatus = 'no-solution';
			return true;
		}
		payload.solutions.forEach(function (solution, index) {
			const row = document.createElement('div');
			row.className = 'xc-yj-row';
			const left = document.createElement('button');
			const equals = document.createElement('span');
			const right = document.createElement('button');
			left.type = right.type = 'button';
			left.className = right.className = 'xc-yj-side';
			left.textContent = groupText(solution.left);
			right.textContent = groupText(solution.right);
			equals.className = 'xc-yj-equals';
			equals.textContent = '=';
			const title = payload.canAssign ? '点击后把这一侧分给自己' : '点击复制此方案';
			left.title = right.title = title;
			left.addEventListener('click', function () { requestSolutionAction(payload, index, 2); });
			right.addEventListener('click', function () { requestSolutionAction(payload, index, 0); });
			row.append(left, equals, right);
			result.appendChild(row);
		});
		const note = document.createElement('div');
		note.className = 'xc-yj-note';
		note.textContent = payload.canAssign ? '点击任意一侧分给自己' : '旁观方案：点击可复制';
		result.appendChild(note);
		lastStatus = 'showing-solutions';
		return true;
	}

	function publish(cardNumbers, canAssign, assigner) {
		const normalized = Array.from(cardNumbers || [], Number).filter(rank => Number.isInteger(rank) && rank >= 1 && rank <= 13);
		const rawSolutions = computeSolutions(normalized);
		const requestId = Date.now().toString(36) + '-' + (++publishCount);
		const payload = {
			type: MESSAGE_TYPE,
			action: 'solutions',
			sourceId,
			requestId,
			canAssign: Boolean(canAssign),
			cards: normalized,
			solutions: rawSolutions.map(solution => ({
				left: countsToRanks(solution[0]),
				right: countsToRanks(solution[1]),
				remaining: countsToRanks(solution[2])
			})),
			hops: 0
		};
		currentLocalRequest = { sourceId, requestId, canAssign: Boolean(canAssign), rawSolutions, assigner };
		if (window.top === window.self) renderPayload(payload);
		else {
			try { window.parent.postMessage(payload, '*'); } catch (error) {}
		}
		return true;
	}

	function handleMessage(event) {
		const message = event && event.data;
		if (!message || message.type !== MESSAGE_TYPE) return;
		if (message.action === 'solutions') {
			if (window.top === window.self) renderPayload(message);
			else if ((Number(message.hops) || 0) < 3) {
				try { window.parent.postMessage({ ...message, hops: (Number(message.hops) || 0) + 1 }, '*'); } catch (error) {}
			}
			return;
		}
		if (message.action !== 'assign') return;
		performLocalAssignment(message);
		const hops = Number(message.hops) || 0;
		if (hops < 3) postToChildren({ ...message, hops: hops + 1 });
	}

	window.addEventListener('message', handleMessage);
	const mountTimer = window.setInterval(mountSection, 800);
	window[API_KEY] = Object.freeze({
		offline: true,
		compute: function compute(cardNumbers) {
			return computeSolutions(cardNumbers).map(solution => ({
				left: countsToRanks(solution[0]),
				right: countsToRanks(solution[1]),
				remaining: countsToRanks(solution[2])
			}));
		},
		publish,
		refresh: mountSection,
		snapshot: function snapshot() {
			return {
				offline: true,
				status: lastStatus,
				publishCount,
				assignmentCount,
				hasSection: Boolean(document.getElementById(SECTION_ID)),
				cards: displayedPayload ? displayedPayload.cards.slice() : [],
				solutionCount: displayedPayload ? displayedPayload.solutions.length : 0,
				canAssign: Boolean(displayedPayload && displayedPayload.canAssign)
			};
		},
		stop: function stop() {
			window.clearInterval(mountTimer);
			window.removeEventListener('message', handleMessage);
			const section = document.getElementById(SECTION_ID);
			if (section) section.remove();
			lastStatus = 'stopped';
		}
	});
	mountSection();
})();

/* ===== 牌堆情况：复用原版 Card/Zone 统计，嵌入手气卡助手并支持独立折叠 ===== */
/* ===== current hand sha counter: move the original top marker into the helper panel ===== */
(function installStartingHandShaCounter() {
	'use strict';
	return;

	const API_KEY = '__H5_STARTING_HAND_SHA_COUNTER__';
	const PANEL_BODY_ID = 'xc-starting-hand-reroller-body';
	const COUNTER_ID = 'xc-starting-hand-sha-counter';
	const MODEL_KEY = '__H5_CARD_PILE_MODEL_BRIDGE__';
	const STYLE_ID = 'xc-starting-hand-sha-counter-style';
	const MESSAGE_TYPE = 'xc-starting-hand-sha-counter-v1';
	const UPDATE_INTERVAL_MS = 250;

	if (window[API_KEY]) return;

	let lastSnapshot = null;
	let lastPublishedSignature = '';

	function installStyle() {
		if (document.getElementById(STYLE_ID)) return;
		const style = document.createElement('style');
		style.id = STYLE_ID;
		style.textContent =
			'#' + COUNTER_ID + '{display:flex;align-items:center;gap:8px;min-height:32px;margin-bottom:8px;padding:5px 8px;border:1px solid rgba(231,211,157,.32);border-radius:4px;background:#24272c;color:#f4f4f5;box-sizing:border-box}' +
			'#' + COUNTER_ID + ' .xc-sh-sha-icon{display:inline-flex;align-items:center;justify-content:center;width:20px;color:#e35c62;font-size:18px;line-height:1}' +
			'#' + COUNTER_ID + ' .xc-sh-sha-label{color:#d7d9df;font-size:13px}' +
			'#' + COUNTER_ID + ' [data-sha-count]{min-width:18px;color:#fff4d7;font-size:14px;font-weight:700;text-align:center}' +
			'#' + COUNTER_ID + '[data-state="waiting"]{border-color:#50545c;color:#9ca0a8}' +
			'#' + COUNTER_ID + '[data-state="waiting"] .xc-sh-sha-icon{color:#8b8f98}';
		(document.head || document.documentElement).appendChild(style);
	}

	function mount() {
		if (window.top !== window.self) return null;
		const body = document.getElementById(PANEL_BODY_ID);
		if (!body) return null;
		installStyle();
		let counter = document.getElementById(COUNTER_ID);
		if (!counter) {
			counter = document.createElement('div');
			counter.id = COUNTER_ID;
			counter.className = 'xc-sh-section xc-sh-sha-counter';
			counter.setAttribute('aria-live', 'polite');
			counter.innerHTML = '<span class="xc-sh-sha-icon" aria-hidden="true">&#9876;</span><span class="xc-sh-sha-label">\u5269\u4f59\uff1a<strong data-sha-count>--</strong></span>';
			body.insertBefore(counter, body.firstElementChild || null);
		}
		return counter;
	}

	function readSnapshot() {
		const model = window[MODEL_KEY];
		if (!model || typeof model.snapshotHand !== 'function') return null;
		try { return model.snapshotHand(); } catch (error) { return null; }
	}

	function renderSnapshot() {
		const counter = mount();
		if (!counter) return false;
		suppressLegacyCounter();
		const countNode = counter.querySelector('[data-sha-count]');
		const ready = Boolean(lastSnapshot && lastSnapshot.ready && lastSnapshot.hasPlayer);
		if (countNode) countNode.textContent = ready ? String(Math.max(0, Number(lastSnapshot.countSha) || 0)) : '--';
		counter.dataset.state = ready ? 'ready' : 'waiting';
		counter.title = ready ? '\u5f53\u524d\u624b\u724c\u4e2d\u7684\u6740\u724c\u6570\u91cf' : '\u7b49\u5f85\u8fdb\u5165\u724c\u5c40';
		return true;
	}

	function publishSnapshot(snapshot) {
		if (window.top === window.self) {
			lastSnapshot = snapshot;
			return renderSnapshot();
		}
		try {
			window.parent.postMessage({ type: MESSAGE_TYPE, action: 'snapshot', snapshot, hops: 0 }, '*');
			return true;
		} catch (error) {
			return false;
		}
	}

	function update() {
		if (window.top === window.self) return renderSnapshot();
		const snapshot = readSnapshot();
		if (!snapshot) return false;
		const signature = JSON.stringify(snapshot);
		if (signature === lastPublishedSignature) return true;
		lastPublishedSignature = signature;
		return publishSnapshot(snapshot);
	}

	/* The original helper writes the small sword/remaining-sha marker to #result.
	 * Hide only that marker; #result is reused by other status messages. */
	function suppressLegacyCounter() {
		const legacy = document.getElementById('result');
		if (!legacy) return;
		const text = String(legacy.textContent || '').replace(/\s+/g, '');
		const isStandaloneCounter = /^(?:剩余|剩餘)[:：]?\d+$/.test(text);
		const isShaCounter = isStandaloneCounter || /(?:杀|劍|剑|⚔)[^\d]{0,12}(?:剩余|剩餘)[:：]?\d+/.test(text) || /(?:剩余|剩餘)[:：]?\d+[^\d]{0,12}(?:杀|劍|剑|⚔)/.test(text);
		if (isShaCounter) {
			legacy.dataset.xcShaCounterHidden = '1';
			legacy.style.setProperty('display', 'none', 'important');
		} else if (legacy.dataset.xcShaCounterHidden === '1') {
			delete legacy.dataset.xcShaCounterHidden;
			legacy.style.removeProperty('display');
		}
	}

	function handleMessage(event) {
		const message = event && event.data;
		if (!message || message.type !== MESSAGE_TYPE || message.action !== 'snapshot') return;
		if (window.top === window.self) {
			if (!message.snapshot || typeof message.snapshot !== 'object') return;
			lastSnapshot = message.snapshot;
			renderSnapshot();
		} else if ((Number(message.hops) || 0) < 4) {
			try { window.parent.postMessage({ ...message, hops: (Number(message.hops) || 0) + 1 }, '*'); } catch (error) {}
		}
	}

	window.addEventListener('message', handleMessage);
	const updateTimer = window.setInterval(update, UPDATE_INTERVAL_MS);
	window[API_KEY] = Object.freeze({
		offline: true,
		refresh: update,
		snapshot: function snapshot() {
			return lastSnapshot ? { ...lastSnapshot } : null;
		},
		stop: function stop() {
			window.clearInterval(updateTimer);
			window.removeEventListener('message', handleMessage);
			const counter = document.getElementById(COUNTER_ID);
			if (counter) counter.remove();
			lastSnapshot = null;
		}
	});
	update();
})();

