	}

	function beginOperation(input) {
		const source = String(input && input.source || "").slice(0, 80);
		const requestId = String(input && input.requestId || "").slice(0, 120);
		if (!source || !requestId || !operationKind(source)) return null;
		for (const op of operations.values()) {
			if (op.source === source && op.requestId === requestId && operationAlive(op)) return op;
		}
		const id = source + ":" + requestId + ":" + nextOpSerial;
		nextOpSerial += 1;
		const baseline = new WeakSet();
		const walk = collectStageNodes();
		for (const node of walk.nodes) baseline.add(node);
		const op = {
			id,
			source,
			kind: operationKind(source),
			requestId,
			phase: "active",
			until: 0,
			baseline,
			windowIds: []
		};
		operations.set(id, op);
		ensureTimer();
		logChange("begin:" + id, { action: "begin", source, requestId, kind: op.kind });
		return op;
	}

	function finishOperation(operationId, options) {
		const op = operations.get(operationId);
		if (!op) return snapshot();
		const drainMs = Number.isFinite(options && options.drainMs) ? options.drainMs : DEFAULT_DRAIN_MS;
		op.phase = "draining";
		op.until = nowMs() + Math.max(0, drainMs);
		logChange("finish:" + op.id, { action: "drain", source: op.source, requestId: op.requestId, drainMs });
