	}

	function associate(op, node, evidence, sourceInfo) {
		const rec = {
			id: nextWindowId,
			name: String(node.name || ""),
			operationId: op.id,
			source: op.source,
			kind: op.kind,
			requestId: op.requestId,
			evidence,
			sourceKind: sourceInfo.kind,
			sourceTypes: sourceInfo.types.slice(),
			closeState: "idle",
			reason: "",
			lastCloseAt: 0,
			closeCount: 0,
			contentGeneration: 0,
			itemsRef: undefined,
			contentSignature: undefined,
			consumedGeneration: null,
			awaitingSince: 0
		};
		if (node.name === SPECIAL_WINDOW_NAME) noteContentGeneration(rec, node);
		nextWindowId += 1;
		records.set(node, rec);
		associated.add(node);
		op.windowIds.push(rec.id);
		logChange("assoc:" + rec.id, {
			action: "associate",
			source: op.source,
			requestId: op.requestId,
			window: rec.name,
			windowId: rec.id,
			evidence,
			sourceKind: rec.sourceKind,
