	}

	function maybeAssociate(op, node, manager) {
		if (!operationAlive(op) || op.phase !== "active") return;
		if (!node || typeof node !== "object") return;
		if (associated.has(node)) return;
		if (op.baseline.has(node)) return;
		let name = "";
		try { name = String(node.name || ""); } catch (error) { return; }
		if (!REWARD_WINDOW_NAMES.has(name) || isGoutuoPreview(name)) return;
		try { if (node.destroyed) return; } catch (error) { return; }
		if (typeof node.Close !== "function") return;
		let identity = "";
		if (manager && officialInstance(manager, name) === node) identity = "manager-instance";
		else if (typeof node.removeModalBg === "function") identity = "ozt-lifecycle";
		if (!identity) return;
		const sourceInfo = classifySource(node);
		if (sourceInfo.kind === "unknown" || sourceInfo.kind === "mixed" || sourceInfo.kind !== op.kind) {
			logChange("skip-source:" + name + ":" + sourceInfo.kind, {
				action: "associate-skip",
				source: op.source,
				window: name,
				reason: "source-" + sourceInfo.kind,
				sourceKind: sourceInfo.kind,
				sourceTypes: sourceInfo.types
			});
			return;
		}
		associate(op, node, identity + "+source:" + sourceInfo.kind, sourceInfo);
	}

	function updateCloseState(node, manager, now) {
		const rec = records.get(node);
		if (!rec) return;
		if (lifecycleClosed(node, manager)) {
			if (rec.closeState !== "closed") {
				rec.closeState = "closed";
				rec.reason = "lifecycle-closed";
				closedRewardWindows += 1;
				logChange("closed:" + rec.id, {
					action: "closed",
					source: rec.source,
					window: rec.name,
					windowId: rec.id,
					entry: "Close",
					reason: rec.reason
				});
			}
			return;
		}
		try {
			if (node.closeing && rec.closeState !== "closed") rec.closeState = "closing";
		} catch (error) {}
		const op = operations.get(rec.operationId);
		const owned = sourceStillOwned(node, rec, op);
		if (!owned.ok) {
			stopForSourceMismatch(rec, owned.live);
			return;
		}
		if (rec.closeState !== "awaiting-progress") return;
		if (rec.name !== SPECIAL_WINDOW_NAME) {
			if (now - rec.awaitingSince >= PROGRESS_WAIT_MS) {
				rec.closeState = "stopped";
				rec.reason = "normal-window-no-retry";
				logChange("stop:" + rec.id, {
					action: "stop-auto",
					source: rec.source,
					window: rec.name,
					windowId: rec.id,
					reason: rec.reason,
					closeCount: rec.closeCount
				});
			}
			return;
		}
		if (noteContentGeneration(rec, node) && rec.consumedGeneration !== rec.contentGeneration) {
			rec.closeState = "idle";
			rec.reason = "new-content-generation";
			logChange("progress:" + rec.id + ":" + rec.contentGeneration, {
				action: "progress",
				source: rec.source,
				window: rec.name,
				windowId: rec.id,
				reason: rec.reason,
				contentGeneration: rec.contentGeneration,
				contentSignature: rec.contentSignature
			});
			return;
		}
		if (now - rec.awaitingSince >= PROGRESS_WAIT_MS) {
			rec.closeState = "stopped";
			rec.reason = "no-special-batch-progress";
			logChange("stop:" + rec.id, {
				action: "stop-auto",
				source: rec.source,
				window: rec.name,
				windowId: rec.id,
				reason: rec.reason,
				closeCount: rec.closeCount
			});
		}
	}

	function requestClose(node, now) {
		const rec = records.get(node);
		if (!rec) return;
		if (rec.closeState === "closed" || rec.closeState === "stopped" || rec.closeState === "pending" || rec.closeState === "awaiting-progress" || rec.closeState === "closing") return;
		const op = operations.get(rec.operationId);
		if (!operationAlive(op)) return;
		if (typeof node.Close !== "function") {
			rec.closeState = "stopped";
			rec.reason = "close-method-unavailable";
			logChange("stop:" + rec.id, {
				action: "stop-auto",
				source: rec.source,
				window: rec.name,
				windowId: rec.id,
				reason: rec.reason
			});
			return;
		}
		const owned = sourceStillOwned(node, rec, op);
		if (!owned.ok) {
			stopForSourceMismatch(rec, owned.live);
			return;
		}
		if (rec.name === SPECIAL_WINDOW_NAME) {
			noteContentGeneration(rec, node);
			if (!specialCloseReady(node)) {
				rec.reason = "special-not-ready";
				return;
			}
			if (rec.consumedGeneration === rec.contentGeneration) return;
			const ownedAgain = sourceStillOwned(node, rec, op);
			if (!ownedAgain.ok) {
				stopForSourceMismatch(rec, ownedAgain.live);
				return;
			}
			rec.consumedGeneration = rec.contentGeneration;
		}
		rec.closeState = "pending";
		rec.lastCloseAt = now;
		rec.closeCount += 1;
		try {
			node.Close();
			rec.closeState = "awaiting-progress";
			rec.awaitingSince = now;
			rec.reason = rec.name === SPECIAL_WINDOW_NAME ? "special-close-submitted" : "close-submitted";
			logChange("close:" + rec.id + ":" + rec.closeCount, {
				action: "close",
				source: rec.source,
				window: rec.name,
				windowId: rec.id,
				entry: "Close",
				closeCount: rec.closeCount,
				reason: rec.reason,
				contentGeneration: rec.contentGeneration,
				contentSignature: rec.contentSignature
			});
		} catch (error) {
			rec.closeState = "stopped";
			rec.reason = "close-threw";
			logChange("stop:" + rec.id, {
				action: "stop-auto",
				source: rec.source,
				window: rec.name,
				windowId: rec.id,
				reason: rec.reason
			});
		}
	}

	function ownerCloseComplete(owner, manager) {
		return lifecycleClosed(owner, manager);
	}

	function modalLayerBusy(mask, owner, manager, nodes) {
		try {
			const opening = manager && Array.isArray(manager.modalWinsOpeningList) ? manager.modalWinsOpeningList : [];
			for (let index = 0; index < opening.length; index += 1) {
				const other = opening[index];
				if (!other || other === owner) continue;
				try {
					if (other.closeing) return true;
					if (other.parent && other.visible !== false && !other.destroyed) return true;
				} catch (error) { return true; }
			}
		} catch (error) { return true; }
		const layer = mask && mask.parent;
		if (!layer) return false;
		for (const node of nodes) {
			if (!node || node === owner) continue;
			try {
				if (node.parent !== layer) continue;
				if (node.destroyed || node.visible === false) continue;
