				if (node.modal || node.modalBg || node.ModalBg) return true;
			} catch (error) {}
		}
		return false;
	}

	function layerIdentity(mask) {
		let layer = null;
		try { layer = mask && mask.parent || null; } catch (error) { return "unknown"; }
		if (!layer) return "none";
		let id = layerIds.get(layer);
		if (!id) {
			id = "L" + nextLayerId;
			nextLayerId += 1;
			layerIds.set(layer, id);
		}
		return id;
	}

	function pruneMaskBindings(now) {
		maskBindings = maskBindings.filter(function (binding) {
			if (!binding || binding.until <= now) return false;
			try { if (binding.mask && binding.mask.destroyed) return false; } catch (error) { return false; }
			return true;
		});
	}

	function rememberMaskOwners(managed, now) {
		if (!managed || !managed.complete) return;
		for (const owner of managed.windows) {
			if (!owner) continue;
			let mask = null;
			try { mask = owner.modalBg || owner.ModalBg || null; } catch (error) { continue; }
			if (!mask || !isRewardModalBg(mask)) continue;
			let updated = false;
			for (let index = 0; index < maskBindings.length; index += 1) {
				const binding = maskBindings[index];
				if (binding.owner === owner && binding.mask === mask) {
					binding.until = now + MASK_BIND_MS;
					updated = true;
					break;
				}
