		const owners = [];
		const seen = new Set();
		function add(node) {
			if (!node || seen.has(node)) return;
			try {
				if (node.modalBg === mask || node.ModalBg === mask) {
					seen.add(node);
					owners.push(node);
				}
			} catch (error) {}
		}
		for (const node of managed.windows) add(node);
		for (let index = 0; index < maskBindings.length; index += 1) {
			if (maskBindings[index].mask === mask) add(maskBindings[index].owner);
		}
		return { owners, verified: true };
	}

	function isRewardModalBg(mask) {
		if (!mask || typeof mask !== "object") return false;
		try {
			if (mask.destroyed) return false;
			return String(mask.name || "").toLowerCase() === "modalbg";
		} catch (error) {
			return false;
		}
	}

	function rememberMaskFailure(mask, owner, reason) {
		maskFailures.set(mask, { epoch: sceneEpoch, reason: reason, at: nowMs() });
		orphanTimers.delete(mask);
		const rec = owner && records.get(owner);
		logChange("orphan-fail:" + (rec && rec.id || "unassociated") + ":" + reason, {
			action: "orphan-fail",
			source: rec && rec.source || "unassociated",
