			orphanTimers.delete(mask);
			return false;
		}
		if (modalLayerBusy(mask, owner, manager, nodes)) {
			orphanTimers.delete(mask);
			return false;
		}
		const rec = records.get(owner);
		const ownerId = rec ? rec.id : "bound";
		const layer = layerIdentity(mask);
		const sig = sceneEpoch + "|" + ownerId + "|" + String(owner && owner.name || "") + "|" + layer;
		let timer = orphanTimers.get(mask);
		if (!timer || timer.sig !== sig || timer.epoch !== sceneEpoch) {
			timer = { sig, since: now, epoch: sceneEpoch, layer };
			orphanTimers.set(mask, timer);
			logChange("orphan-wait:" + ownerId, {
				action: "orphan-wait",
				source: rec && rec.source || "closed-owner",
				window: String(owner && owner.name || ""),
				windowId: rec && rec.id || 0,
				reason: "conditions-met",
