			return false;
		}
		try {
			if (owner.destroyed) {
				rememberMaskFailure(mask, owner, "owner-destroyed");
				return false;
			}
			if (owner.modalBg !== mask && owner.ModalBg !== mask) {
				rememberMaskFailure(mask, owner, "mask-owner-mismatch");
				return false;
			}
			if (typeof owner.removeModalBg !== "function") {
				rememberMaskFailure(mask, owner, "removeModalBg-unavailable");
				return false;
			}
			owner.removeModalBg();
			if (owner.modalBg === mask || owner.ModalBg === mask) {
				rememberMaskFailure(mask, owner, "official-remove-did-not-clear");
				return false;
			}
			orphanTimers.delete(mask);
			removedRewardMasks += 1;
			logChange("orphan-clean:" + ownerId, {
				action: "orphan-clean",
				source: rec && rec.source || "closed-owner",
				window: String(owner && owner.name || ""),
				windowId: rec && rec.id || 0,
				entry: "removeModalBg",
				reason: "orphan-confirmed"
			});
			return true;
		} catch (error) {
			rememberMaskFailure(mask, owner, "removeModalBg-threw");
			return false;
		}
	}

	function observe() {
		const now = nowMs();
		for (const op of Array.from(operations.values())) {
			if (op.phase === "draining" && op.until && now > op.until) releaseOperation(op, "drain-elapsed");
