		if (!usable) {
			const reason = !stage ? "stage-missing"
				: !manager ? "manager-missing"
				: !walk.complete ? (walk.reason || "stage-incomplete")
				: "manager-dict-unreadable";
			markSceneUnusable(reason);
			if (stage) sceneState.stage = stage;
			if (manager) sceneState.manager = manager;
			return snapshot();
		}
		sceneState = {
			stage,
			manager,
			lastSeenStage: stage,
			lastSeenManager: manager,
			complete: true,
			unusableReason: "",
			epoch: sceneEpoch
		};

		const managed = collectManagedWindows(manager, walk.nodes);
		if (!managed.complete) {
			markSceneUnusable("manager-dict-unreadable");
			return snapshot();
		}
		rememberMaskOwners(managed, now);
		for (const node of walk.nodes) tryCloseStuckHiddenSpecialReward(node, manager, now);
		try {
			const opening = manager.modalWinsOpeningList;
			if (Array.isArray(opening)) {
				for (let index = 0; index < opening.length; index += 1) {
					tryCloseStuckHiddenSpecialReward(opening[index], manager, now);
				}
			}
		} catch (error) {}

		for (const op of operations.values()) {
			if (!operationAlive(op)) continue;
			for (const node of walk.nodes) maybeAssociate(op, node, manager);
		}
		for (const node of Array.from(associated)) {
			updateCloseState(node, manager, now);
			requestClose(node, now);
		}
		for (const node of walk.nodes) {
			if (!isRewardModalBg(node)) continue;
			const ownership = ownersOfMask(node, managed, now);
			if (!ownership.verified) continue;
			if (ownership.owners.length !== 1) {
				orphanTimers.delete(node);
				if (ownership.owners.length > 1) {
					logChange("mask-shared", { action: "mask-skip", reason: "shared-mask" });
				}
				continue;
			}
			tryRemoveOrphanMask(node, ownership.owners[0], manager, walk.nodes, now);
		}
		return snapshot();
	}

	function snapshot() {
		let pending = 0;
		let stopped = 0;
		for (const node of associated) {
			const rec = records.get(node);
			if (!rec) continue;
			if (rec.closeState === "stopped") stopped += 1;
			if (rec.closeState === "pending" || rec.closeState === "awaiting-progress" || rec.closeState === "closing") pending += 1;
		}
		return {
			offline: true,
			operations: operations.size,
			associated: associated.size,
			closedRewardWindows,
			removedRewardMasks,
			stuckHiddenCloses,
			pending,
			stopped,
			sceneEpoch,
			sceneComplete: sceneState.complete,
			skipReason: sceneState.complete ? "" : (sceneState.unusableReason || ""),
			hasRuntime: Boolean(window.Laya && window.Laya.stage),
			hasManager: Boolean(findWindowManager(collectStageNodes().nodes)),
			managerSource: lastManagerSource,
			scanning: Boolean(timerId)
		};
	}

	function recoverManual() {
		const stats = observe();
		logChange("recover:" + nowMs(), {
			action: "manual-recover",
			reason: "shared-attribution",
			associated: stats.associated,
			closedRewardWindows: stats.closedRewardWindows,
			removedRewardMasks: stats.removedRewardMasks
		});
		return stats;
	}

	window[API_KEY] = Object.freeze({
		offline: true,
		windowNames: Array.from(REWARD_WINDOW_NAMES),
		beginOperation,
		finishOperation,
		observe,
		recoverManual,
		snapshot,
		stop: function stop() {
			if (timerId) window.clearInterval(timerId);
			timerId = 0;
			return snapshot();
		}
	});
	ensureTimer();
})();

