		notice.textContent = String(detail.targetDraws || DEFAULT_DRAW_COUNT) + "抽未完成：" + String(detail.message || "未知错误");
		notice.hidden = false;
		if (errorNoticeTimer) window.clearTimeout(errorNoticeTimer);
		errorNoticeTimer = window.setTimeout(function () { notice.hidden = true; errorNoticeTimer = 0; }, 12000);
	}
	function dispatchStatus(detail) {
		try { showBatchStatus(detail); } catch (_) {}
		try {
			window.dispatchEvent(new CustomEvent(STATUS_EVENT, { detail: cloneState(detail) }));
		} catch (error) {}
	}

	function relayToChildren(message) {
		let count = 0;
		try {
			for (let index = 0; index < window.frames.length; index += 1) {
				try {
					window.frames[index].postMessage(message, "*");
					count += 1;
				} catch (error) {}
			}
		} catch (error) {}
		return count;
	}

	function publish(nextState) {
		state = Object.assign({}, state, nextState || {});
		updateNativeButtonState();
		dispatchStatus(state);
		try {
			if (window.parent && window.parent !== window) {
				window.parent.postMessage({ type: MESSAGE_TYPE, action: "status", detail: cloneState(state) }, "*");
			}
		} catch (error) {}
		return cloneState(state);
	}

	function isTianGongPanel(node) {
		return Boolean(
			node &&
			!node.destroyed &&
			typeof node.btnClick === "function" &&
			typeof node.UpdateCtn === "function" &&
			typeof node.checkBoxClick === "function" &&
			node.mutiBtn &&
			node.checkBox &&
			node.numTxt2 &&
			Number(node.tabId) > 0
		);
	}

	function findTianGongPanel() {
		const stage = window.Laya && window.Laya.stage;
		if (!stage) return null;
		const queue = [stage];
		const seen = new WeakSet();
		let visited = 0;
		while (queue.length && visited < 7000) {
			const node = queue.shift();
			if (!node || typeof node !== "object" || seen.has(node)) continue;
			seen.add(node);
			visited += 1;
			if (isTianGongPanel(node) && node.visible !== false) return node;
			let childCount = 0;
			try { childCount = Number(node.numChildren) || 0; } catch (error) {}
			for (let index = 0; index < childCount; index += 1) {
				try { queue.push(node.getChildAt(index)); } catch (error) {}
			}
		}
		return null;
	}

	function readInventoryCount(panel) {
		try { panel.UpdateCtn(); } catch (error) {}
		const text = String(panel && panel.numTxt2 && panel.numTxt2.text || "");
		const match = text.replace(/,/g, "").match(/\d+/);
		return match ? Number(match[0]) : NaN;
	}

	function setSkipAnimation(panel, enabled) {
		if (!panel || !panel.checkBox || typeof panel.checkBoxClick !== "function") return false;
		panel.checkBox.selected = Boolean(enabled);
		panel.checkBoxClick();
		return true;
	}

	function setNodeVisible(node, visible) {
		if (!node || node.destroyed) return;
		try { node.visible = Boolean(visible); } catch (error) {}
	}

	function installRewardAnimationSuppressor(panel) {
		const ownDescriptor = Object.getOwnPropertyDescriptor(panel, "showEffect");
		Object.defineProperty(panel, "showEffect", {
			configurable: true,
			writable: true,
			value: function suppressDragonBallRewardAnimation() {
				setNodeVisible(this.taiBackEffect, true);
				setNodeVisible(this.taiFrontEffect, true);
				setNodeVisible(this.uiSp, true);
				setNodeVisible(this.effSp, true);
				setNodeVisible(this.btnsSp, true);
				setNodeVisible(this.taiEffEct, false);
				setNodeVisible(this.taiEffEct2, false);
				setNodeVisible(this.levelUpEffEct, false);
				this.rewardRepList = null;
				this.rewardRepType = 0;
				this.isPlayMuti = false;
				this.shareWinParams = null;
			}
		});
		return function restoreRewardAnimation() {
			if (ownDescriptor) Object.defineProperty(panel, "showEffect", ownDescriptor);
			else delete panel.showEffect;
		};
	}

	function collectStageNodes() {
		const stage = window.Laya && window.Laya.stage;
		if (!stage) return [];
		const queue = [stage];
		const nodes = [];
		const seen = new WeakSet();
		let visited = 0;
		while (queue.length && visited < 9000) {
			const node = queue.shift();
			if (!node || typeof node !== "object" || seen.has(node)) continue;
			seen.add(node);
			visited += 1;
			nodes.push(node);
			let childCount = 0;
			try { childCount = Number(node.numChildren) || 0; } catch (error) {}
			for (let index = 0; index < childCount; index += 1) {
				try { queue.push(node.getChildAt(index)); } catch (error) {}
			}
		}
		return nodes;
	}

	function findAncestorByName(node, expectedName) {
		let current = node;
		let depth = 0;
		while (current && depth < 30) {
			if (String(current.name || "") === expectedName) return current;
			current = current.parent;
			depth += 1;
		}
		return null;
	}

	function isAttachedToStage(node) {
		const stage = window.Laya && window.Laya.stage;
		let current = node;
		let depth = 0;
		while (current && depth < 60) {
			if (current === stage) return true;
			current = current.parent;
			depth += 1;
		}
		return false;
	}

	function removeModalMaskNode(mask, ownerCandidates) {
		if (!mask || mask.destroyed) return false;
		let owner = null;
		for (const candidate of ownerCandidates || []) {
			if (!candidate || typeof candidate !== "object") continue;
			try {
				if (candidate.modalBg === mask || candidate.ModalBg === mask) {
					owner = candidate;
					break;
				}
			} catch (error) {}
		}
		if (owner && typeof owner.removeModalBg === "function") {
			try { owner.removeModalBg(); } catch (error) {}
		}
		try {
			mask.mouseEnabled = false;
			mask.mouseThrough = true;
			mask.visible = false;
			if (mask.parent && typeof mask.removeSelf === "function") mask.removeSelf();
			if (!mask.destroyed && typeof mask.destroy === "function") mask.destroy(true);
		} catch (error) {}
		if (owner) {
			try { if (owner.modalBg === mask) owner.modalBg = null; } catch (error) {}
		}
		return true;
	}

	function coordinatorApi() {
		return window.__H5_REWARD_SURFACE_COORDINATOR__;
	}

	function createBatchRewardCleaner(panel, requestId, drawCount) {
		const api = coordinatorApi();
		if (!api || typeof api.beginOperation !== "function") {
			return {
				clean: function() { return { closedRewardWindows: 0, removedRewardMasks: 0 }; },
				postClean: function() { return { closedRewardWindows: 0, removedRewardMasks: 0 }; },
				stop: function() { return { closedRewardWindows: 0, removedRewardMasks: 0 }; }
			};
		}
		const operation = api.beginOperation({
			source: Number(drawCount) === 5000 ? "dragon-5000" : "dragon-500",
			requestId: String(requestId || "")
		});
		function stats() {
			const snap = api.observe();
			return {
				closedRewardWindows: snap.closedRewardWindows,
				removedRewardMasks: snap.removedRewardMasks
			};
		}
		return {
			clean: stats,
			postClean: stats,
			stop: function() {
				if (operation && operation.id) api.finishOperation(operation.id, { drainMs: POST_BATCH_GUARD_MS });
				return stats();
			}
		};
	}

	function stopPostBatchGuard() {
		if (postBatchGuardTimerId != null) window.clearInterval(postBatchGuardTimerId);
		postBatchGuardTimerId = null;
		postBatchGuardCleaner = null;
		state.postGuardActive = false;
		state.postGuardUntil = 0;
	}

	function armPostBatchGuard(cleaner) {
		stopPostBatchGuard();
		if (!cleaner || typeof cleaner.postClean !== "function") return;
		postBatchGuardCleaner = cleaner;
		state.postGuardActive = true;
		state.postGuardUntil = Date.now() + POST_BATCH_GUARD_MS;
		postBatchGuardTimerId = window.setInterval(function () {
			if (Date.now() >= state.postGuardUntil) { stopPostBatchGuard(); return; }
			try {
				const stats = cleaner.postClean();
				state.closedRewardWindows = Number(stats.closedRewardWindows) || 0;
				state.removedRewardMasks = Number(stats.removedRewardMasks) || 0;
			} catch (_) { stopPostBatchGuard(); }
		}, POST_BATCH_GUARD_INTERVAL_MS);
	}

	function forceRecoverLocal() {
		const api = coordinatorApi();
		let snap = { closedRewardWindows: 0, removedRewardMasks: 0 };
		if (postBatchGuardCleaner) {
			try { snap = postBatchGuardCleaner.postClean() || snap; } catch (error) {}
		}
		if (api && typeof api.recoverManual === "function") {
			try { snap = api.recoverManual() || snap; } catch (error) {}
		}
		state.closedRewardWindows = Number(snap.closedRewardWindows) || 0;
		state.removedRewardMasks = Number(snap.removedRewardMasks) || 0;
		state.manualRecoveries = (Number(state.manualRecoveries) || 0) + 1;
		state.message = "已执行灰屏恢复";
		publish(state);
		return {
			closedRewardWindows: state.closedRewardWindows,
			removedRewardMasks: state.removedRewardMasks,
			manualRecoveries: state.manualRecoveries
		};
	}

	function drawNativeButton(button, hovered) {
		if (!button || button.destroyed || !button.graphics) return;
		const running = Boolean(localRunPromise);
		const fill = running ? "#4d4035" : (hovered ? "#a63a28" : "#84291f");
		try {
			button.graphics.clear();
			button.graphics.drawRect(0, 0, 125, 41, fill, "#d6a54f", 2);
			button.alpha = running ? 0.72 : 1;
		} catch (error) {}
	}

	function updateNativeButtonState() {
		const running = Boolean(localRunPromise) || state.state === "running";
		const activeDraws = Number(state.targetDraws) || DEFAULT_DRAW_COUNT;
		for (const config of DRAW_CONFIGS) {
			const button = nativeButtons.get(config.drawCount);
			const label = nativeButtonLabels.get(config.drawCount);
			if (!button || button.destroyed || !label) continue;
			button.mouseEnabled = !running;
			if (running && activeDraws === config.drawCount) {
				label.text = Math.max(0, Number(state.completedBatches) || 0) + "/" + config.totalBatches;
			} else if (state.state === "error" && activeDraws === config.drawCount) {
				label.text = "重试" + config.drawCount + "次";
			} else {
				label.text = "开启" + config.drawCount + "次";
			}
			drawNativeButton(button, false);
		}
	}

	function positionNativeButtons(panel) {
		if (!panel || !panel.mutiBtn) return;
		const baseX = Number(panel.mutiBtn.x) + Number(panel.mutiBtn.width || 125) + 12;
		const y = Number(panel.mutiBtn.y) || 0;
		for (let index = 0; index < DRAW_CONFIGS.length; index += 1) {
			const config = DRAW_CONFIGS[index];
			const button = nativeButtons.get(config.drawCount);
			if (!button || button.destroyed) continue;
			const x = baseX + index * 137;
			if (typeof button.pos === "function") button.pos(x, y);
			else {
				button.x = x;
				button.y = y;
			}
		}
	}

	function removeNativeButtons() {
		for (const button of nativeButtons.values()) {
			if (!button || button.destroyed) continue;
			try { button.destroy(true); } catch (error) {
				try { button.removeSelf(); } catch (nestedError) {}
			}
		}
		buttonOwner = null;
		nativeButtons.clear();
		nativeButtonLabels.clear();
	}

	function installNativeButtons(panel) {
		const Laya = window.Laya;
		if (!Laya || typeof Laya.Sprite !== "function" || typeof Laya.Text !== "function" || !panel.btnsSp) return false;
		const hasAllButtons = DRAW_CONFIGS.every(config => {
			const button = nativeButtons.get(config.drawCount);
			return Boolean(button && !button.destroyed);
		});
		if (buttonOwner === panel && hasAllButtons) {
			positionNativeButtons(panel);
			updateNativeButtonState();
			return true;
		}
		removeNativeButtons();

		for (const config of DRAW_CONFIGS) {
			const button = new Laya.Sprite();
			button.name = config.buttonName;
			button.size(125, 41);
			button.mouseEnabled = true;
			button.mouseThrough = false;
			button.zOrder = 1000;
			button.ButtonMode = true;

			const label = new Laya.Text();
			label.name = config.buttonName + "Label";
			label.size(125, 41);
			label.align = "center";
			label.valign = "middle";
			label.fontSize = 20;
			label.bold = true;
			label.color = "#f6df9d";
			label.stroke = 2;
			label.strokeColor = "#512019";
			label.mouseEnabled = false;
			button.addChild(label);

			const clickEvent = Laya.Event && Laya.Event.CLICK || "click";
			const overEvent = Laya.Event && Laya.Event.MOUSE_OVER || "mouseover";
			const outEvent = Laya.Event && Laya.Event.MOUSE_OUT || "mouseout";
			button.on(clickEvent, null, function(event) {
				try { if (event && typeof event.stopPropagation === "function") event.stopPropagation(); } catch (error) {}
				if (localRunPromise) return;
				const requestId = Date.now().toString(36) + "-native-" + config.drawCount;
				runLocalBatch(requestId, config.drawCount);
			});
			button.on(overEvent, null, function() { if (!localRunPromise) drawNativeButton(button, true); });
			button.on(outEvent, null, function() { drawNativeButton(button, false); });
			panel.btnsSp.addChild(button);
			nativeButtons.set(config.drawCount, button);
			nativeButtonLabels.set(config.drawCount, label);
		}

		buttonOwner = panel;
		positionNativeButtons(panel);
		updateNativeButtonState();
		return true;
	}

	function scanForNativeButton() {
		const panel = findTianGongPanel();
		if (!panel) {
			if (buttonOwner && (buttonOwner.destroyed || buttonOwner.visible === false)) removeNativeButtons();
			return;
		}
		installNativeButtons(panel);
	}

	async function waitForInventoryDrop(panel, beforeCount, expectedDrop) {
		const startedAt = Date.now();
		while (Date.now() - startedAt < RESPONSE_TIMEOUT_MS) {
			if (!isTianGongPanel(panel)) throw new Error("祈愿台窗口已关闭");
			const currentCount = readInventoryCount(panel);
			if (Number.isFinite(currentCount) && currentCount <= beforeCount - expectedDrop) return currentCount;
			await sleep(POLL_INTERVAL_MS);
		}
		throw new Error("等待第" + (state.completedBatches + 1) + "轮库存刷新超时，已停止后续请求");
	}

	async function runLocalBatch(requestId, targetDraws) {
		if (localRunPromise) return localRunPromise;
		const requestedConfig = getDrawConfig(targetDraws);
		localRunPromise = (async function() {
			const drawConfig = requestedConfig;
			const totalBatches = drawConfig.totalBatches;
			const drawCount = drawConfig.drawCount;
			publish({ state: "running", message: "检查龙珠数量...", completedBatches: 0,
				totalBatches, targetDraws: drawCount, requestId, lastError: "", availableBefore: null, availableNow: null });
			const panel = findTianGongPanel();
			if (!panel) throw new Error("请先打开祈愿台的龙珠抽取页面");
			const perDrawCost = Number(panel.needItemCtn) || 0;
			const nativeBatchSize = Number(panel.mutiTimes) || 0;
			if (perDrawCost <= 0 || nativeBatchSize !== DRAWS_PER_BATCH) {
				throw new Error("未识别到游戏原生50抽按钮");
			}
			const costPerBatch = perDrawCost * DRAWS_PER_BATCH;
			const totalCost = costPerBatch * totalBatches;
			const availableBefore = readInventoryCount(panel);
			if (!Number.isFinite(availableBefore)) throw new Error("无法读取当前龙珠数量");
			if (availableBefore < totalCost) throw new Error("龙珠不足：需要" + totalCost + "，当前" + availableBefore);

			const previousSkip = Boolean(panel.checkBox.selected);
			let skipChanged = false;
			let restoreRewardAnimation = function() {};
			let rewardCleaner = null;
			try {
				stopPostBatchGuard();
				if (!setSkipAnimation(panel, false)) throw new Error("无法临时关闭游戏原生跳过动画");
				skipChanged = true;
				restoreRewardAnimation = installRewardAnimationSuppressor(panel);
				rewardCleaner = createBatchRewardCleaner(panel, requestId, drawCount);
				publish({
					state: "running",
					message: "准备执行 0/" + totalBatches,
					completedBatches: 0,
					totalBatches,
					targetDraws: drawCount,
					availableBefore,
					availableNow: availableBefore,
					requestId,
					lastError: "",
					closedRewardWindows: 0,
					removedRewardMasks: 0,
					postGuardActive: false,
					postGuardUntil: 0
				});

				for (let index = 0; index < totalBatches; index += 1) {
					if (!isTianGongPanel(panel)) throw new Error("祈愿台窗口已关闭");
					const beforeCount = readInventoryCount(panel);
					if (!Number.isFinite(beforeCount) || beforeCount < costPerBatch) {
						throw new Error("第" + (index + 1) + "轮前龙珠不足");
					}
					publish({ state: "running", message: "正在执行 " + (index + 1) + "/" + totalBatches });
					panel.btnClick(panel.mutiBtn, true);
					const availableNow = await waitForInventoryDrop(panel, beforeCount, costPerBatch);
					const cleanupStats = rewardCleaner.clean();
					publish({
						state: "running",
						message: "已完成 " + (index + 1) + "/" + totalBatches + "，剩余" + availableNow,
						completedBatches: index + 1,
						availableNow,
						closedRewardWindows: cleanupStats.closedRewardWindows,
						removedRewardMasks: cleanupStats.removedRewardMasks
					});
					if (index + 1 < totalBatches) await sleep(BETWEEN_BATCHES_MS);
				}
				await sleep(FINAL_REWARD_SETTLE_MS);
				const finalCleanupStats = rewardCleaner.clean();
				return publish({
					state: "complete",
					message: drawCount + "抽完成，剩余" + state.availableNow,
					completedBatches: totalBatches,
					closedRewardWindows: finalCleanupStats.closedRewardWindows,
					removedRewardMasks: finalCleanupStats.removedRewardMasks
				});
			} finally {
				if (rewardCleaner) {
					try {
						const cleanupStats = rewardCleaner.stop();
						state.closedRewardWindows = cleanupStats.closedRewardWindows;
						state.removedRewardMasks = cleanupStats.removedRewardMasks;
						armPostBatchGuard(rewardCleaner);
					} catch (error) {}
				}
				try { restoreRewardAnimation(); } catch (error) {}
				if (skipChanged) {
					try { setSkipAnimation(panel, previousSkip); } catch (error) {}
				}
			}
		})().catch(error => publish({
			state: "error",
			message: String(error && error.message || error),
			lastError: String(error && error.stack || error),
			requestId,
			totalBatches: requestedConfig.totalBatches,
			targetDraws: requestedConfig.drawCount
		})).finally(() => {
			localRunPromise = null;
			updateNativeButtonState();
		});
		return localRunPromise;
	}

	function handleStart(message) {
		const requestId = String(message && message.requestId || "");
		if (!requestId || seenRequests.has(requestId)) return;
		seenRequests.add(requestId);
		const targetDraws = getDrawConfig(message && message.targetDraws).drawCount;
		const panel = findTianGongPanel();
		if (panel) {
			runLocalBatch(requestId, targetDraws);
			return;
		}
		relayToChildren({ type: MESSAGE_TYPE, action: "start", requestId, targetDraws });
	}

	function handleRecover() {
		const hasRuntime = Boolean(window.Laya && window.Laya.stage);
		const result = hasRuntime ? forceRecoverLocal() : null;
		relayToChildren({ type: MESSAGE_TYPE, action: "recover" });
		return result;
	}

	window.addEventListener("message", event => {
		const message = event && event.data;
		if (!message || message.type !== MESSAGE_TYPE) return;
		if (message.action === "recover") {
			if (window.Laya && window.Laya.stage) forceRecoverLocal();
			return;
		}
		if (message.action === "start") {
			handleStart(message);
			return;
		}
		if (message.action !== "status" || !message.detail) return;
		lastRemoteState = cloneState(message.detail);
		dispatchStatus(lastRemoteState);
		try {
			if (window.parent && window.parent !== window) window.parent.postMessage(message, "*");
		} catch (error) {}
	});

	function startBatch(targetDraws) {
		const drawConfig = getDrawConfig(targetDraws);
		if (localRunPromise || state.state === "running") return String(state.requestId || "");
		const requestId = Date.now().toString(36) + "-" + drawConfig.drawCount + "-" + Math.random().toString(36).slice(2, 9);
		dispatchStatus({
			state: "running",
			message: "正在寻找祈愿台...",
			requestId,
			completedBatches: 0,
			totalBatches: drawConfig.totalBatches,
			targetDraws: drawConfig.drawCount
		});
		handleStart({ requestId, targetDraws: drawConfig.drawCount });
		window.setTimeout(() => {
			const latest = lastRemoteState || state;
			if (window.top === window && (!latest || latest.requestId !== requestId)) {
				dispatchStatus({
					state: "error",
					message: "未找到已打开的祈愿台页面",
					requestId,
					completedBatches: 0,
					totalBatches: drawConfig.totalBatches,
					targetDraws: drawConfig.drawCount
				});
			}
		}, 4000);
		return requestId;
	}

	function createBatchApi(targetDraws) {
		return Object.freeze({
			offline: true,
			start: function() {
				return startBatch(targetDraws);
			},
			recover: function() {
				return handleRecover();
			},
			snapshot: function() {
				const panel = findTianGongPanel();
				return Object.assign(cloneState(lastRemoteState || state), {
					hasRuntime: Boolean(window.Laya && window.Laya.stage),
					hasTianGongPanel: Boolean(panel),
					availableNow: panel ? readInventoryCount(panel) : (lastRemoteState || state).availableNow,
					running: Boolean(localRunPromise)
				});
			}
		});
	}

	window[API_KEY_500] = createBatchApi(500);
	window[API_KEY_5000] = createBatchApi(5000);

	scanForNativeButton();
	window.setInterval(scanForNativeButton, BUTTON_SCAN_INTERVAL_MS);
})();

(function installRewardPopupAutoCloser() {
	"use strict";

	const API_KEY = "__H5_REWARD_POPUP_AUTO_CLOSER__";
	if (window[API_KEY]) return;

	function coordinatorApi() {
		return window.__H5_REWARD_SURFACE_COORDINATOR__;
	}

	function snapshot() {
		const api = coordinatorApi();
		return api && typeof api.snapshot === "function"
			? api.snapshot()
			: { offline: true, hasRuntime: Boolean(window.Laya && window.Laya.stage) };
	}

	window[API_KEY] = Object.freeze({
		offline: true,
		get windowNames() {
			const api = coordinatorApi();
			return api && Array.isArray(api.windowNames) ? api.windowNames.slice() : [];
		},
		closeNow: function closeNow() {
			const api = coordinatorApi();
			return api && typeof api.observe === "function" ? api.observe() : snapshot();
		},
		scan: function scanNow() {
			const api = coordinatorApi();
			return api && typeof api.observe === "function" ? api.observe() : snapshot();
		},
		snapshot,
		stop: function stop() {
			return snapshot();
		}
