			const runtimeStage = getXushaoStage();
			const controller = findXushaoWindow(runtimeStage);
			const entries = getXushaoButtons(controller);
			if (entries.length === XUSHAO_BOARD_SIZE * XUSHAO_BOARD_SIZE) {
				const chars = entries.map(item => item.text);
				if (!chars.some(text => [...text].length !== 1)) {
					const words = Array.from(new Set(findXushaoLines(chars).map(line => line.word)));
					return { words, current: !0 };
				}
			}
		} catch (_) {}
		return { words: [], current: !1 };
	}

	function updateXushaoCopyControl(source = { words: [], current: !1 }) {
		const button = document.querySelector(`#${STARTING_HAND_PANEL_ID} [data-xushao-copy]`);
		if (!button) return;
		const words = Array.from(new Set(Array.isArray(source.words) ? source.words : []));
		if (!source.current) {
			button.textContent = "复制本局可连战功（未开始）";
			button.title = "小游戏尚未出现";
		} else if (!words.length) {
			button.textContent = "复制本局可连战功（暂无）";
			button.title = "当前棋盘没有识别到可连战功";
		} else {
			button.textContent = `复制本局可连战功：${words.join("、")}`;
			button.title = words.join("\n");
		}
	}

	function refreshXushaoCopyControl() {
		if (xushaoCopyRefreshPending) return;
		xushaoCopyRefreshPending = !0;
		requestCurrentXushaoWordsFromFrames().then(updateXushaoCopyControl).catch(() => {}).finally(() => {
			xushaoCopyRefreshPending = !1;
		});
	}

	async function copyXushaoWordsToClipboard() {
		const source = await requestCurrentXushaoWordsFromFrames();
		if (!source.current || !source.words.length) {
			updateXushaoCopyControl(source);
			setXushaoHelperStatus(source.current ? "当前棋盘暂无可连战功" : "小游戏尚未开始，暂无可复制战功", "guarded");
			return !1;
		}
		const words = source.words;
		const text = words.join("\n");
		let copied = !1;
		try {
			if (navigator.clipboard && typeof navigator.clipboard.writeText === "function") {
				await navigator.clipboard.writeText(text);
				copied = !0;
			}
		} catch (_) {}
		if (!copied) {
			try {
				const textarea = document.createElement("textarea");
				textarea.value = text;
				textarea.setAttribute("readonly", "");
				textarea.style.cssText = "position:fixed;left:-9999px;top:-9999px;opacity:0";
				document.body.appendChild(textarea);
				textarea.select();
				copied = Boolean(document.execCommand && document.execCommand("copy"));
				textarea.remove();
			} catch (_) {}
		}
		setXushaoHelperStatus(copied ? `已复制本局可连 ${words.length} 条战功` : "复制失败，请检查浏览器剪贴板权限", copied ? "matched" : "guarded");
		return copied;
	}

	function cancelXushaoOverlay() {
		if (xushaoHiddenOverlay || xushaoFrameOverlayHidden) {
			broadcastXushaoFrameOverlay(!1);
			restoreXushaoOverlay();
			xushaoFrameOverlayHidden = !1;
			setXushaoHelperStatus("已恢复许劭画面", "idle");
			return !0;
		}
		try {
			if (window.frames.length > 0) {
				broadcastXushaoFrameOverlay(!0);
				xushaoFrameOverlayHidden = !0;
				updateXushaoOverlayControl();
				setXushaoHelperStatus("已向游戏 frame 发送隐藏命令", "running");
				return !0;
			}
		} catch (_) {}
		const runtimeStages = getXushaoStages();
		let runtimeStage = runtimeStages.find(stage => findXushaoWindows(stage).some(node => node.visible !== false)) || runtimeStages[0] || getXushaoStage();
		let targets = findXushaoWindows(runtimeStage).filter(node => node.visible !== false);
		// 已验证的旁观者路径：Stage/_children[3] 为 vzt，子节点 1/2 分别是遮罩和许劭层。
		for (const stage of runtimeStages) {
			try {
				const layer = stage.getChildAt?.(3);
				if (String(layer?.constructor?.name || "") === "vzt" && Number(layer.numChildren) >= 3) {
					const direct = [layer, layer.getChildAt(1), layer.getChildAt(2)].filter(Boolean);
					if (direct.some(node => node.visible !== false)) {
						runtimeStage = stage;
						targets = Array.from(new Set([...targets, ...direct]));
					}
				}
			} catch (_) {}
		}
		if (!targets.length) targets = collectXushaoStageNodes(runtimeStage).filter(node => {
			const name = String(node?.name || node?._name || "").toLowerCase();
			return node.visible !== false && (name === "modalbg" || name === "coversprite" || name === "modalsprite");
		});
		if (targets.length) {
			const neighbors = [];
			for (const mask of targets) {
				const parent = mask.parent;
				for (const sibling of xushaoChildren(parent)) if (sibling !== mask && isXushaoWindowCandidate(sibling)) neighbors.push(sibling);
			}
			targets = Array.from(new Set([...targets, ...neighbors]));
		}
		if (!runtimeStage || !targets.length) {
			setXushaoHelperStatus("未找到许劭小游戏画面", "guarded");
			return !1;
		}
		// Only suppress the window and nearby masks belonging to it; never all stage masks.
		const nodes = new Set;
		for (const target of targets) {
			nodes.add(target);
			for (const ref of [target.modalBg, target.ModalBg]) if (ref && !ref.destroyed) nodes.add(ref);
			// 旁观者的 PingJianWindow 位于 vzt 窗口容器中；隐藏子窗口后容器仍可能继续绘制。
			for (let owner = target.parent, depth = 0; owner && owner !== runtimeStage && depth < 2; owner = owner.parent, depth += 1) {
				nodes.add(owner);
			}
			for (let owner = target, depth = 0; owner && depth < 12; owner = owner.parent, depth += 1) {
			for (const node of [owner, ...xushaoChildren(owner)]) {
				const name = String(node?.name || node?._name || "").toLowerCase();
				if (name === "modalbg" || name === "coversprite" || name === "modalsprite") nodes.add(node);
				try {
					if (node.modalBg) nodes.add(node.modalBg);
					if (node.ModalBg) nodes.add(node.ModalBg);
				} catch (_) {}
			}
			}
		}
		const states = Array.from(nodes, node => ({
			node,
			parent: node.parent || null,
			index: node.parent && typeof node.parent.getChildIndex === "function" ? Number(node.parent.getChildIndex(node)) : -1,
			visible: node.visible,
			alpha: node.alpha,
			mouseEnabled: node.mouseEnabled,
			mouseThrough: node.mouseThrough,
			removed: !1
		}));
		xushaoHiddenOverlay = { targets, stage: runtimeStage, states, words: targets.map(node => Array.isArray(node.WordsStr) ? node.WordsStr.join("") : "").join("\u0001") };
		try {
			for (const state of states) {
				const node = state.node;
				node.visible = !1;
				node.alpha = 0;
				node.mouseEnabled = !1;
				node.mouseThrough = !0;
			}
		} catch (error) {
			restoreXushaoOverlay();
			setXushaoHelperStatus("隐藏失败，已恢复画面", "guarded");
			return !1;
		}
		 xushaoHelperRunToken += 1;
		xushaoHelperLastSignature = "";
		if (!xushaoOverlayGuardTimer) xushaoOverlayGuardTimer = window.setInterval(maintainXushaoOverlay, 50);
		updateXushaoOverlayControl();
		setXushaoHelperStatus(`已隐藏 ${targets.length > 1 ? "旁观" : "许劭"} 画面，请点击聊天框输入`, "idle");
		return !0;
	}

	function updateXushaoOverlayControl() {
		const button = document.querySelector(`#${STARTING_HAND_PANEL_ID} [data-xushao-overlay]`);
		if (button) button.textContent = "隐藏/恢复许劭画面";
	}

	function restoreXushaoOverlay() {
		const saved = xushaoHiddenOverlay;
		xushaoHiddenOverlay = null;
		if (xushaoOverlayGuardTimer) {
			window.clearInterval(xushaoOverlayGuardTimer);
			xushaoOverlayGuardTimer = 0;
		}
		if (saved) for (const state of saved.states) {
			if (state.node.destroyed) continue;
			try {
				if (state.node.visible === false) state.node.visible = state.visible;
				if (state.node.alpha === 0) state.node.alpha = state.alpha;
				if (state.node.mouseEnabled === false) state.node.mouseEnabled = state.mouseEnabled;
				if (state.node.mouseThrough === true) state.node.mouseThrough = state.mouseThrough;
			} catch (_) {}
		}
		updateXushaoOverlayControl();
	}

	function maintainXushaoOverlay() {
		const saved = xushaoHiddenOverlay;
		if (!saved) return;
		const currentTargets = findXushaoWindows(saved.stage).filter(node => node.visible !== false);
		for (const target of currentTargets) {
			if (saved.targets.includes(target)) continue;
			saved.targets.push(target);
			saved.states.push({
				node: target,
				parent: target.parent || null,
				index: target.parent && typeof target.parent.getChildIndex === "function" ? Number(target.parent.getChildIndex(target)) : -1,
				visible: target.visible,
				alpha: target.alpha,
				mouseEnabled: target.mouseEnabled,
				mouseThrough: target.mouseThrough,
				removed: !1
			});
		}
		for (const state of saved.states) {
			const node = state.node;
			if (!node || node.destroyed) continue;
			try {
				node.visible = !1;
				node.alpha = 0;
				node.mouseEnabled = !1;
				node.mouseThrough = !0;
			} catch (_) {}
		}
		try {
			const layer = saved.stage.getChildAt?.(3);
			if (String(layer?.constructor?.name || "") === "vzt") {
				for (const node of [layer, layer.getChildAt?.(1), layer.getChildAt?.(2)].filter(Boolean)) {
					node.visible = false;
					node.alpha = 0;
					node.mouseEnabled = false;
					node.mouseThrough = true;
				}
			}
		} catch (_) {}
	}

	function xushaoChildren(node) {
		const result = [];
		if (!node) return result;
		try {
			if (typeof node.getChildAt === "function" && Number.isFinite(node.numChildren)) {
				for (let index = 0; index < node.numChildren; index += 1) {
					const child = node.getChildAt(index);
					child && result.push(child)
				}
			}
			for (const list of [node.childs, node.children]) {
				if (Array.isArray(list)) for (const child of list) child && !result.includes(child) && result.push(child)
			}
		} catch (_) {}
		return result;
	}

	function collectXushaoStageNodes(stage) {
		const nodes = [];
		const queue = stage ? [stage] : [];
		const seen = new Set;
		while (queue.length && nodes.length < 12000) {
			const node = queue.shift();
			if (!node || seen.has(node)) continue;
			seen.add(node);
			nodes.push(node);
			for (const child of xushaoChildren(node)) queue.push(child);
		}
		return nodes;
	}

	function isXushaoWindowCandidate(node) {
		if (!node || node.destroyed) return !1;
		const name = String(node.name || node._name || "").toLowerCase();
		const runtimeName = String(node.constructor?.name || node.constructorName || node.type || "").toLowerCase();
		if (name.includes("pingjian") || name.includes("xushao") || runtimeName.includes("pingjian")) return !0;
		if (Array.isArray(node.WordsStr) && node.WordsStr.length === XUSHAO_BOARD_SIZE * XUSHAO_BOARD_SIZE) return !0;
		if (Array.isArray(node.items) && node.items.length === XUSHAO_BOARD_SIZE * XUSHAO_BOARD_SIZE) return !0;
		return xushaoChildren(node).some(child => /^grid_btn_0$/.test(String(child?.name || child?._name || "")));
	}

	function findXushaoWindows(stage) {
		const found = collectXushaoStageNodes(stage).filter(isXushaoWindowCandidate);
		if (found.length) return Array.from(new Set(found));
		const fallback = findXushaoWindow(stage);
		return fallback ? [fallback] : [];
	}

	function findXushaoWindow(node, seen = new Set(), depth = 0) {
		if (!node || depth > 24 || seen.has(node)) return null;
		seen.add(node);
		const runtimeName = String(node?.constructor?.name || "");
		const nodeType = String(node?.type || "");
		if (node.name === "PingJianWindow" || runtimeName === "PingJianWindow" || runtimeName === "yns" || nodeType === "yns" || String(node?.constructorName || "") === "yns") return node;
		if (Array.isArray(node.items) && node.items.length === XUSHAO_BOARD_SIZE * XUSHAO_BOARD_SIZE && Array.isArray(node.WordsStr)) return node;
		for (const child of xushaoChildren(node)) {
			const found = findXushaoWindow(child, seen, depth + 1);
			if (found) return found
		}
		return null;
	}

	function readXushaoButtonText(button) {
		const values = [button?.text, button?._text, button?.label, button?.textField?.text, button?.textField?._text];
		for (const value of values) {
			if (typeof value === "string" && value.trim()) return value.trim()
		}
		return ""
	}

	function getXushaoButtons(controller) {
		const source = Array.isArray(controller?.items) ? controller.items : [];
		const direct = source.filter(Boolean).map((button, index) => ({
			button,
			index: Number(String(button.name || "").replace("grid_btn_", "")),
			text: readXushaoButtonText(button),
			fallbackIndex: index
		})).filter(item => Number.isFinite(item.index)).sort((a, b) => a.index - b.index)
		if (direct.length === XUSHAO_BOARD_SIZE * XUSHAO_BOARD_SIZE) return direct;
		const found = [];
		const seen = new Set;
		const visit = (node, depth = 0) => {
			if (!node || depth > 8 || seen.has(node)) return;
			seen.add(node);
			const name = String(node.name || node._name || "");
			if (/^grid_btn_\d+$/.test(name)) found.push(node);
			for (const child of xushaoChildren(node)) visit(child, depth + 1);
		};
		visit(controller);
		return found.map((button, fallbackIndex) => ({
			button,
			index: Number(String(button.name || button._name || "").replace("grid_btn_", "")),
			text: readXushaoButtonText(button),
			fallbackIndex
		})).filter(item => Number.isFinite(item.index)).sort((a, b) => a.index - b.index);
	}

	function findXushaoLines(chars) {
		const lines = [];
		const seen = new Set;
		for (const word of XUSHAO_WORDS) {
			const length = [...word].length;
			if (length < 2 || length > XUSHAO_BOARD_SIZE) continue;
			for (let row = 0; row < XUSHAO_BOARD_SIZE; row += 1) {
				for (let col = 0; col <= XUSHAO_BOARD_SIZE - length; col += 1) {
					const indices = Array.from({ length }, (_, offset) => row * XUSHAO_BOARD_SIZE + col + offset);
					const text = indices.map(index => chars[index]).join("");
					if (text === word || [...text].reverse().join("") === word) {
						const orderedIndices = text === word ? indices : indices.slice().reverse();
						const key = `${word}:${orderedIndices.join(",")}`;
						if (!seen.has(key)) seen.add(key), lines.push({ word, indices: orderedIndices })
					}
				}
			}
			for (let col = 0; col < XUSHAO_BOARD_SIZE; col += 1) {
				for (let row = 0; row <= XUSHAO_BOARD_SIZE - length; row += 1) {
					const indices = Array.from({ length }, (_, offset) => (row + offset) * XUSHAO_BOARD_SIZE + col);
					const text = indices.map(index => chars[index]).join("");
					if (text === word || [...text].reverse().join("") === word) {
						const orderedIndices = text === word ? indices : indices.slice().reverse();
						const key = `${word}:${orderedIndices.join(",")}`;
						if (!seen.has(key)) seen.add(key), lines.push({ word, indices: orderedIndices })
					}
				}
			}
		}
		return lines
	}

	function dispatchXushaoPointer(button, kind) {
		try {
			if (!button || button.enabled === false || typeof button.event !== "function") return !1;
			const events = window.Laya?.Event || window.laya?.Event || {};
			const eventName = kind === "down" ? (events.MOUSE_DOWN || "mousedown") : kind === "over" ? (events.MOUSE_OVER || "mouseover") : (events.MOUSE_UP || "mouseup");
			button.event(eventName, button);
			return !0
		} catch (error) {
			console.debug("[手气卡助手] 许劭格子连线失败", error);
			return !1
		}
	}

	function resetXushaoRun() {
		xushaoHelperRunToken += 1;
		xushaoHelperLastSignature = "";
		xushaoHelperLastController = null;
	}

	function isXushaoRunCurrent(controller, signature, token) {
		return token === xushaoHelperRunToken && xushaoHelperEnabled && !xushaoHiddenOverlay && !xushaoFrameOverlayHidden
			&& controller === xushaoHelperLastController && !controller.destroyed && controller.visible !== false
			&& getXushaoButtons(controller).map(item => item.text).join("\u0001") === signature;
	}

	function dragXushaoLine(entries, line, token, startDelay, controller, signature) {
		const step = XUSHAO_DRAG_STEP_MS;
		const endDelay = startDelay + Math.max(0, line.indices.length - 1) * step + XUSHAO_DRAG_RELEASE_MS;
		let skipped = false;
		line.indices.forEach((index, offset) => {
			window.setTimeout(() => {
				if (!isXushaoRunCurrent(controller, signature, token)) return;
				if (offset === 0) skipped = Array.isArray(controller.matchedIds) && line.indices.some(id => controller.matchedIds.includes(id));
				if (skipped) return;
				const button = entries[index]?.button;
				if (offset === 0) dispatchXushaoPointer(button, "down");
				else dispatchXushaoPointer(button, "over");
			}, startDelay + offset * step);
		});
		window.setTimeout(() => {
			if (!skipped && isXushaoRunCurrent(controller, signature, token)) dispatchXushaoPointer(entries[line.indices[line.indices.length - 1]]?.button, "up");
		}, endDelay);
		return endDelay + XUSHAO_LINE_GAP_MS;
	}

	function completeXushaoPuzzle() {
		if (xushaoHiddenOverlay || xushaoFrameOverlayHidden || !xushaoHelperEnabled) {
			resetXushaoRun();
			return !1;
		}
		const runtimeStage = getXushaoStage();
		if (!runtimeStage) {
			resetXushaoRun();
			setXushaoHelperStatus("许劭辅助：等待游戏运行", "armed");
			return !1;
		}
		const controller = findXushaoWindow(runtimeStage);
		if (!controller || controller.destroyed || controller.visible === false) {
			resetXushaoRun();
			setXushaoHelperStatus("许劭辅助：等待许劭面板", "armed");
			return !1;
		}
		const entries = getXushaoButtons(controller);
		if (entries.length !== XUSHAO_BOARD_SIZE * XUSHAO_BOARD_SIZE) {
			resetXushaoRun();
			setXushaoHelperStatus(`许劭辅助：已定位面板，棋盘 ${entries.length}/36`, "armed");
			return !1;
		}
		const chars = entries.map(item => item.text);
		if (chars.some(text => [...text].length !== 1)) {
			resetXushaoRun();
			setXushaoHelperStatus("许劭辅助：棋盘文字读取失败", "guarded");
			return !1;
		}
		// Selection and match progress belong to this board, not a new drag batch.
		const signature = chars.join("\u0001");
		if (controller === xushaoHelperLastController && signature === xushaoHelperLastSignature) return !0;
		resetXushaoRun();
		xushaoHelperLastController = controller;
		xushaoHelperLastSignature = signature;
		const lines = findXushaoLines(chars);
		if (!lines.length) {
			xushaoHelperLastResult = "未找到战功";
			setXushaoHelperStatus("许劭辅助：未找到战功", "guarded");
			return !1
		}
		const token = ++xushaoHelperRunToken;
		let submitted = 0;
		let delay = 0;
		for (const line of lines) {
			delay = dragXushaoLine(entries, line, token, delay, controller, signature);
			submitted += 1;
		}
		window.setTimeout(() => {
			if (!isXushaoRunCurrent(controller, signature, token)) return;
			xushaoHelperLastResult = `已处理 ${submitted} 条战功连线，请以获技结果为准`;
			setXushaoHelperStatus(`许劭辅助：${xushaoHelperLastResult}`, "idle");
		}, Math.max(0, delay));
		setXushaoHelperStatus(`许劭辅助：发现 ${lines.length} 条战功`, "running");
		return !0
	}

	function startXushaoHelperMonitor() {
		if (xushaoHelperTimer) return;
		xushaoHelperTimer = window.setInterval(() => {
			maintainXushaoOverlay();
			refreshXushaoCopyControl();
			if (!xushaoHelperEnabled) return;
			try { completeXushaoPuzzle() } catch (error) { console.debug("[手气卡助手] 许劭辅助扫描失败", error) }
		}, 180)
	}

	function applyXushaoHelperEnabled(enabled, persist = !0) {
		xushaoHelperEnabled = Boolean(enabled);
		resetXushaoRun();
		if (persist) saveXushaoHelperEnabled(xushaoHelperEnabled);
		if (!xushaoHelperEnabled) {
			xushaoHelperLastResult = "disabled";
			setXushaoHelperStatus("许劭辅助：已关闭", "idle");
		} else {
			setXushaoHelperStatus("许劭辅助：等待小游戏", "armed");
			completeXushaoPuzzle();
		}
		updateXushaoHelperControl();
	}

	function executeStartingHandQuickAction(action) {
		try {
			if ("clear-red-dots" === action) {
				const manager = laya.class("TaskRedDotManager");
				if (!manager || "function" != typeof manager.setNodeState) return { handled: !1, ok: !1, text: "红点管理器尚未就绪" };
				return manager.setNodeState(Infinity, 0), { handled: !0, ok: !0, text: "已清除消不掉的红点" }
			}
			if ("lucky-preview" === action) {
				const generalManager = laya.class("GameGeneralManager"),
					gameEventDispatcher = laya.ged;
				if (!generalManager || !gameEventDispatcher || "function" != typeof gameEventDispatcher.ShowWindow) return { handled: !1, ok: !1, text: "随机武将运行环境尚未就绪" };
				const generalIds = goutuo.generalIds;
				if (!Array.isArray(generalIds) || !generalIds.length) return { handled: !0, ok: !1, text: "没有可展示的未拥有武将" };
				window[GOUTUO_PREVIEW_GRACE_KEY] = Date.now() + 5000;
				return null === goutuo.getGeneral(_0x14cc48(generalIds)) ? { handled: !0, ok: !1, text: "随机武将展示失败" } : { handled: !0, ok: !0, text: "已生成随机武将展示" }
			}
		} catch (error) {
