		if (!body || /^(?:return\s*;?|return\s+(?:void 0|undefined|null|!?[01])\s*;?)$/.test(body)) return "空壳";
		const net = /ServerProxy|sendMsg|SendMsg|\bproxy\b|Req\(|sendData|\bsend\(/.test(src);
		if (net) return arity > 0 ? ("发包需" + arity + "参") : "发包无参";
		if (arity > 0) return "需" + arity + "参";
