	const OFFICER_VERIFIED_SYSTEM_MAX_LEVEL = 38;
	let cachedOfficialOfficerConfigManager = null;
	let cachedOfficialOfficerMaxLevel = OFFICER_VERIFIED_SYSTEM_MAX_LEVEL;

	function officerConfigScalarSignature(item) {
		if (!item || "object" != typeof item) return "";
		const parts = [];
		try {
			for (const key of Object.keys(item).sort()) {
				let value;
				try { value = item[key]; } catch (_) { continue; }
				if (null == value || ["string", "number", "boolean"].includes(typeof value)) {
					parts.push(`${key}=${String(value)}`);
					continue;
				}
				if (Array.isArray(value)) {
					const samples = [];
					for (const child of [value[0], value[value.length - 1]]) {
						if (!child || "object" != typeof child) continue;
						const scalars = [];
						for (const childKey of Object.keys(child).sort().slice(0, 12)) {
							const childValue = child[childKey];
							if (null == childValue || ["string", "number", "boolean"].includes(typeof childValue)) {
								scalars.push(`${childKey}:${String(childValue)}`);
							}
						}
						if (scalars.length) samples.push(scalars.join(","));
					}
					parts.push(`${key}[${value.length}]${samples.join("|")}`);
				}
			}
		} catch (_) {}
		return parts.join(";");
	}

