		}
		// 扫描到安全边界仍未遇到配置末端时，不能把扫描边界误报成官方上限。
		if (!boundaryConfirmed) return cachedOfficialOfficerMaxLevel;
		const currentLevel = Number(officerManager && (officerManager.OfficerSLv || officerManager.CurOfficerLv || officerManager.curOfficerLv)) || 0;
