	function normalizeOfficerTaskSendInterval(value) {
		return Number(value) >= OFFICER_TASK_SAFE_SEND_INTERVAL_MS
			? OFFICER_TASK_SAFE_SEND_INTERVAL_MS
			: OFFICER_TASK_FAST_SEND_INTERVAL_MS
