		try {
			const candidate = manager && manager.TaskStatusDic && manager.TaskStatusDic._maps;
			if (candidate && "object" == typeof candidate) taskMap = candidate;
		} catch (_) {}
		const level = Number(manager && manager.OfficerSLv) || 0;
		const taskMapReady = !!taskMap;
		return {
			ready: level > 0 && dataInited !== !1 && (!requireTaskMap || taskMapReady),
			level,
			dataInited,
			taskMapReady,
			taskEntryCount: taskMapReady ? Object.keys(taskMap).length : 0
