	}

	async function waitForOfficerDataReadiness(manager, requireTaskMap, timeoutMs) {
		const startedAt = Date.now();
		const deadline = startedAt + Math.max(0, Number(timeoutMs) || 0);
		let snapshot = inspectOfficerDataReadiness(manager, requireTaskMap);
		while (!snapshot.ready && Date.now() < deadline) {
			await sleep(OFFICER_DATA_READY_POLL_MS);
			snapshot = inspectOfficerDataReadiness(manager, requireTaskMap);
		}
		return { ...snapshot, waitedMs: Math.max(0, Date.now() - startedAt) };
	}

	async function waitForOfficerDataWithRetry(manager, requireTaskMap) {
		const startedAt = Date.now();
		let snapshot = await waitForOfficerDataReadiness(manager, requireTaskMap, OFFICER_DATA_READY_TIMEOUT_MS);
		if (snapshot.ready) return { ...snapshot, attempts: 1, waitedMs: Math.max(0, Date.now() - startedAt) };
		await sleep(OFFICER_DATA_READY_RETRY_GAP_MS);
		snapshot = await waitForOfficerDataReadiness(manager, requireTaskMap, OFFICER_DATA_READY_RETRY_TIMEOUT_MS);
		return { ...snapshot, attempts: 2, waitedMs: Math.max(0, Date.now() - startedAt) };
	}

	async function waitForOfficerLevelChange(manager, before, timeoutMs = 3200) {
		const deadline = Date.now() + timeoutMs;
		while (Date.now() < deadline) {
			const current = Number(manager && manager.OfficerSLv) || 0;
			if (current > before) return current;
			await sleep(OFFICER_LEVEL_CONFIRM_POLL_MS);
		}
		return Number(manager && manager.OfficerSLv) || 0;
	}

	async function upgradeOfficerToConfiguredTarget(manager, requestedTargetLevel, done, requested, skipped, errors, em, officerDataReadiness) {
		const target = configuredOfficerTargetLevel(manager, requestedTargetLevel);
		let level = Number(manager && manager.OfficerSLv) || 0;
		let startLevel = level;
		if (level < target) {
			const readiness = officerDataReadiness || await waitForOfficerDataWithRetry(manager, !1);
			level = Number(readiness.level) || level;
			if (startLevel <= 0 && level > 0) startLevel = level;
			if (!readiness.ready) {
				requested.push(`官阶晋升:数据${readiness.waitedMs}ms内未就绪(LV${level || 0}/目标LV${target},尝试${readiness.attempts}次)`);
				return { target, startLevel, level, reached: !1, dataReady: !1, readiness };
			}
		}
		if (level <= 0) {
			skipped.push(`官阶晋升:当前等级未加载(目标LV${target})`);
			return { target, startLevel, level, reached: !1 };
		}
		if (level >= target) {
			skipped.push(`官阶晋升:已达目标LV${target}`);
			return { target, startLevel, level, reached: !0 };
		}
		if ("function" != typeof manager.sendUpgrade) {
			skipped.push("官阶晋升:接口无");
			return { target, startLevel, level, reached: !1 };
		}
		const maxAttempts = Math.max(0, target - level);
		for (let guard = 0; guard < maxAttempts && level < target; guard += 1) {
			try {
				const officialMax = OFFICER_VERIFIED_SYSTEM_MAX_LEVEL;
				level = Number(manager && manager.OfficerSLv) || level;
				if (level >= officialMax) {
					skipped.push(`官阶晋升:已达官方最高LV${officialMax}`);
					break;
				}
				if (manager.DataInited === !1) {
					skipped.push(`官阶晋升:数据未初始化(LV${level}/目标LV${target})`);
					break;
				}
				if (manager.isCanUpGrade !== !0) {
					skipped.push(`官阶晋升:当前条件不足(LV${level}/目标LV${target})`);
					break;
				}
				const before = level;
				manager.sendUpgrade(!1);
				level = await waitForOfficerLevelChange(manager, before);
				if (level <= before) {
					requested.push(`官阶晋升:LV${before}请求已发送但3.2秒内未确认`);
					break;
				}
			} catch (error) {
				errors.push(`官阶晋升:LV${level}->LV${Math.min(target, level + 1)}:` + em(error));
				break;
			}
		}
		if (level >= target) done.push(`官阶晋升(服务器状态确认LV${startLevel}->LV${level},目标LV${target})`);
		else if (level > startLevel) requested.push(`官阶晋升(已到LV${level},目标LV${target},等待后续条件)`);
		return { target, startLevel, level, reached: level >= target };
	}

	function claimableOfficerTaskEntries(manager) {
		const map = manager && manager.TaskStatusDic && manager.TaskStatusDic._maps;
		if (!map || "object" != typeof map) return [];
		return Object.entries(map).map(([rawId, rawPoint]) => ({
			id: Number(rawId) || 0,
			point: Number(rawPoint) || 0
		})).filter((item) => item.id > 0 && item.point > 0).sort((left, right) => left.id - right.id);
	}

	async function waitForOfficerTasksCleared(manager, timeoutMs = OFFICER_TASK_CONFIRM_TIMEOUT_MS) {
		const deadline = Date.now() + timeoutMs;
		let remaining = claimableOfficerTaskEntries(manager);
		while (remaining.length && Date.now() < deadline) {
			await sleep(OFFICER_TASK_CONFIRM_POLL_MS);
			remaining = claimableOfficerTaskEntries(manager);
		}
		return remaining;
	}

	async function claimAllOfficerTasks(manager, done, requested, skipped, errors, em, requestedIntervalMs, officerDataReadiness) {
		const startedAt = Date.now();
		const sendIntervalMs = normalizeOfficerTaskSendInterval(requestedIntervalMs);
		const result = (status, patch = {}) => ({
			enabled: !0,
			status,
			success: status === "server-confirmed" || status === "not-claimable",
			initialCount: 0,
			requestCount: 0,
			sentCount: 0,
			confirmedCount: 0,
			remainingCount: 0,
			requestedPoint: 0,
			confirmedPoint: 0,
			pendingPoint: 0,
			sendIntervalMs,
			elapsedMs: Math.max(0, Date.now() - startedAt),
			...patch
		});
		if ("function" != typeof manager.SendClientGJGetTaskPointReq) {
			skipped.push("官阶任务:接口无");
			return result("interface-unavailable");
		}
		const readiness = officerDataReadiness || await waitForOfficerDataWithRetry(manager, !0);
		if (!readiness.ready) {
			requested.push(`官阶任务:数据${readiness.waitedMs}ms内未就绪(DataInited=${String(readiness.dataInited)},任务字典=${readiness.taskMapReady ? "已加载" : "未加载"},尝试${readiness.attempts}次)`);
			return result("data-not-ready", {
				success: !1,
				dataReady: !1,
				dataInited: readiness.dataInited,
				taskMapReady: readiness.taskMapReady,
				readinessAttempts: readiness.attempts,
				readinessWaitedMs: readiness.waitedMs
			});
		}
		const initial = claimableOfficerTaskEntries(manager);
		if (!initial.length) {
			skipped.push("官阶任务:无可领");
			return result("not-claimable", {
				dataReady: !0,
				dataInited: readiness.dataInited,
				taskMapReady: readiness.taskMapReady,
				readinessAttempts: readiness.attempts,
				readinessWaitedMs: readiness.waitedMs
			});
		}
		let sent = 0, remaining = initial, lastSignature = "";
		const requestedTasks = new Map();
		for (let pass = 0; pass < OFFICER_TASK_MAX_PASSES && remaining.length; pass += 1) {
			const entries = remaining;
			const signature = entries.map((item) => `${item.id}:${item.point}`).join(",");
			if (pass > 0 && signature === lastSignature) break;
			lastSignature = signature;
			for (let index = 0; index < entries.length; index += 1) {
				const item = entries[index];
				try {
					manager.SendClientGJGetTaskPointReq(item.id);
					sent += 1;
					requestedTasks.set(item.id, item.point);
				} catch (error) {
					errors.push(`官阶任务(ID=${item.id}):` + em(error));
				}
				if (index + 1 < entries.length) await sleep(sendIntervalMs);
			}
			remaining = await waitForOfficerTasksCleared(manager);
		}
		remaining = claimableOfficerTaskEntries(manager);
		const remainingIds = new Set(remaining.map((item) => item.id));
		const requestedPoint = Array.from(requestedTasks.values()).reduce((sum, point) => sum + point, 0);
		const confirmedEntries = Array.from(requestedTasks.entries()).filter(([id]) => !remainingIds.has(id));
		const confirmedPoint = confirmedEntries.reduce((sum, [, point]) => sum + point, 0);
		const pendingPoint = Math.max(0, requestedPoint - confirmedPoint);
		if (!remaining.length) done.push(`官阶任务-帅点数${confirmedPoint}`);
		else requested.push(`官阶任务-帅点数${confirmedPoint}`);
		return result(remaining.length ? "partial" : "server-confirmed", {
			dataReady: !0,
			dataInited: readiness.dataInited,
			taskMapReady: readiness.taskMapReady,
			readinessAttempts: readiness.attempts,
			readinessWaitedMs: readiness.waitedMs,
			initialCount: initial.length,
			requestCount: requestedTasks.size,
			sentCount: sent,
			confirmedCount: confirmedEntries.length,
			remainingCount: remaining.length,
			requestedPoint,
			confirmedPoint,
			pendingPoint
		});
	}

	const GENERAL_UPGRADE_MIN_STAR = 1;
