	const GENERAL_UPGRADE_CONFIRM_BASE_TIMEOUT_MS = 20000;
	const GENERAL_UPGRADE_CONFIRM_MAX_TIMEOUT_MS = 180000;
	const GENERAL_UPGRADE_SINGLE_CONFIRM_TIMEOUT_MS = 2500;
