	// 由官方 ItemExpDict 现场确认；只使用固定配置发包，不查询背包数量。
	const GENERAL_UPGRADE_STAGES = Object.freeze([
		Object.freeze({ key: "stage1", from: 1, to: 2, goodId: 112301, name: "校尉将印", exp: 200, points: 10 }),
		Object.freeze({ key: "stage2", from: 2, to: 3, goodId: 112401, name: "中郎将印", exp: 1200, points: 15 }),
		Object.freeze({ key: "stage3", from: 3, to: 4, goodId: 112501, name: "大将军印", exp: 6000, points: 25 }),
		Object.freeze({ key: "stage4", from: 4, to: 5, goodId: 112601, name: "枭雄金印", exp: 24000, points: 70 })
	]);
	// 原生升阶页允许从全部经验道具中选择材料；这里只读五个已确认的固定材料，
	// 不遍历背包，也不触碰物品格。优先使用当前阶段将印，缺少时再退回低阶将印或功勋。
	const GENERAL_UPGRADE_MATERIALS = Object.freeze([
		Object.freeze({ goodId: 112601, name: "枭雄金印", exp: 24000 }),
		Object.freeze({ goodId: 112501, name: "大将军印", exp: 6000 }),
		Object.freeze({ goodId: 112401, name: "中郎将印", exp: 1200 }),
		Object.freeze({ goodId: 112301, name: "校尉将印", exp: 200 }),
		Object.freeze({ goodId: 111801, name: "功勋", exp: 6 })
	]);
	const generalUpgradeKnownStates = new Map();
	let generalUpgradeKnownAccountId = "";

	function normalizeGeneralUpgradeCounts(value) {
		const source = value && "object" == typeof value ? value : {};
		const values = GENERAL_UPGRADE_STAGES.map((stage, index) => {
			const raw = source[stage.key] ?? source[index] ?? 0;
			const parsed = Math.floor(Number(raw));
			return Math.max(0, Math.min(GENERAL_UPGRADE_MAX_COUNT, Number.isFinite(parsed) ? parsed : 0));
		});
		// 后一层必须是前一层的子集；若用户直接调高后层，就自动补足前置层人数。
		for (let index = values.length - 2; index >= 0; index -= 1) values[index] = Math.max(values[index], values[index + 1]);
		return Object.fromEntries(GENERAL_UPGRADE_STAGES.map((stage, index) => [stage.key, values[index]]));
	}

	function normalizeGeneralUpgradeRosterIds(value) {
		return Array.from(new Set((Array.isArray(value) ? value : [])
			.map((id) => Math.floor(Number(id) || 0))
			.filter((id) => Number.isInteger(id) && id > 0)))
			.sort((left, right) => left - right)
			.slice(0, GENERAL_UPGRADE_ROSTER_MAX_IDS);
	}

	function generalUpgradeConfirmBudgetMs(counts) {
		const actions = GENERAL_UPGRADE_STAGES.reduce((sum, stage) => sum + Math.max(0, Number(counts && counts[stage.key]) || 0), 0);
		const sendMs = actions * GENERAL_UPGRADE_SEND_INTERVAL_MS;
		const confirmationWaves = Math.ceil(actions / GENERAL_UPGRADE_MAX_CONCURRENCY);
		const confirmationMs = confirmationWaves * GENERAL_UPGRADE_SINGLE_CONFIRM_TIMEOUT_MS;
		return Math.min(GENERAL_UPGRADE_CONFIRM_MAX_TIMEOUT_MS,
			Math.max(GENERAL_UPGRADE_CONFIRM_BASE_TIMEOUT_MS, sendMs + confirmationMs + GENERAL_UPGRADE_CONFIRM_BASE_TIMEOUT_MS));
	}

	function patchGeneralUpgradeDisplayStar(general, star) {
		if (!general || typeof general !== "object") return;
		for (const key of ["Star", "star"]) {
			try {
				if (!(key in general) || typeof general[key] === "function") continue;
				const current = Number(general[key]);
				if (!Number.isFinite(current) || current < star) general[key] = star;
			} catch (_) {}
		}
	}

	function rememberGeneralUpgradeState(manager, state) {
		const id = Math.floor(Number(state && state.id) || 0);
		const star = Math.floor(Number(state && state.star) || 0);
		if (id <= 0 || star < GENERAL_UPGRADE_MIN_STAR || star > GENERAL_UPGRADE_MAX_STAR) return;
		const previous = generalUpgradeKnownStates.get(id);
		if (!previous || star >= previous.star) generalUpgradeKnownStates.set(id, { star, exp: Math.max(0, Number(state && state.exp) || 0) });
		const general = state && state.general;
		if (!general || typeof general !== "object") return;
