					confirmedIds: Array.isArray(report.confirmedIds) ? report.confirmedIds.slice(0, 20) : [],
					blockedCount: Array.isArray(report.blockedIds) ? report.blockedIds.length : 0,
					missingCount: Math.max(0, Number(report.missingCount) || 0),
					unsentCount: Array.isArray(report.unsentIds) ? report.unsentIds.length : 0,
					unconfirmedCount: Array.isArray(report.unconfirmedIds) ? report.unconfirmedIds.length : 0,
					materialPlanCount: Array.isArray(report.materialPlans) ? report.materialPlans.length : 0,
					materialFallbackCount: Array.isArray(report.materialPlans) ? report.materialPlans.filter((item) => item && item.fallback === !0).length : 0,
					materialUnavailableCount: Array.isArray(report.materialUnavailableIds) ? report.materialUnavailableIds.length : 0,
					materialPlans: Array.isArray(report.materialPlans) ? report.materialPlans.slice(0, 20) : [],
					blockedReason: String(report.blockedReason || '')
				});
		}
		const confirmedTotal = stages.reduce((sum, stage) => sum + stage.confirmedCount, 0);
		const sentTotal = stages.reduce((sum, stage) => sum + stage.sentCount, 0);
		const targetTotal = requestedStages.reduce((sum, stage) => sum + counts[stage.key], 0);
		const success = targetTotal === 0 || (stages.length === requestedStages.length
			&& stages.every((stage) => stage.confirmedCount >= stage.targetCount));
		const status = targetTotal === 0 ? "no-target" : success ? "success" : confirmedTotal > 0 ? "partial" : sentTotal > 0 ? "unconfirmed" : "failed";
		const confirmedTransitions = (reports || []).flatMap((report) => (Array.isArray(report.confirmedStates) ? report.confirmedStates : [])
			.map((state) => ({ id: Math.max(0, Number(state.id) || 0), star: Math.max(0, Number(state.star) || 0) }))
			.filter((state) => state.id > 0 && state.star >= GENERAL_UPGRADE_MIN_STAR && state.star <= GENERAL_UPGRADE_MAX_STAR));
		return {
			enabled: !0,
			status,
			success,
			reason: String(reason || ""),
			selectedCount: Math.max(0, Number(selectedCount) || 0),
			targetTotal,
			sentTotal,
			confirmedTotal,
			freshStateGuard: "live-snapshot+stable-target-prefix+known-star-high-water+single-scheduler+15ms-paced+event-first-transition+late-state-reconcile+dynamic-budget",
			preflight: preflight && "object" == typeof preflight ? { ...preflight } : null,
			confirmedTransitions,
			stages
		};
	}

	async function batchUpgradeGenerals(manager, rawCounts, context, done, requested, skipped, errors, em) {
		const batchStartedAt = Date.now();
		const apiDiagnostic = inspectGeneralUpgradeApiSources(manager);
		const counts = normalizeGeneralUpgradeCounts(rawCounts);
		const requestedFirstStage = counts.stage1;
		if (!requestedFirstStage) {
			skipped.push("武将升阶:目标人数均为0");
			return summarizeGeneralUpgradeRun(counts, 0, [], "target-empty");
		}
		if (!manager || "function" != typeof manager.sendStarExpAddReq) {
			skipped.push("武将升阶:接口无");
			return summarizeGeneralUpgradeRun(counts, 0, [], "interface-unavailable");
		}
		const expectedAccountId = String(context && context.accountId || "").trim();
		if (expectedAccountId) resetGeneralUpgradeKnownStates(expectedAccountId);
		const liveSnapshot = await scanOwnedGeneralRoster(manager);
		const snapshotAccountId = String(liveSnapshot && liveSnapshot.accountId || "").trim();
		const accountMismatch = expectedAccountId && snapshotAccountId && expectedAccountId !== snapshotAccountId;
		const snapshotReady = !!(liveSnapshot && liveSnapshot.ready && snapshotAccountId && !accountMismatch);
		if (!snapshotReady) {
			const status = accountMismatch ? "account-mismatch" : String(liveSnapshot && liveSnapshot.status || "roster-not-scanned");
			const reason = status === "account-mismatch" ? `实时账号不一致(${snapshotAccountId || "未知"}/${expectedAccountId})`
				: status === "roster-empty" ? "当前本地没有读到拥有武将"
				: status === "roster-unstable" ? "拥有武将列表仍在加载变化"
				: "实时拥有武将快照未就绪";
			skipped.push(`武将升阶:预检停止(${reason})`);
			return summarizeGeneralUpgradeRun(counts, 0, [], status, {
				...(liveSnapshot || {}),
				ready: !1,
				status,
				snapshot: liveSnapshot ? {
					rawCount: liveSnapshot.rawCount,
					acceptedCount: liveSnapshot.acceptedCount,
					rejectedCount: liveSnapshot.rejectedCount,
					sourceCounts: liveSnapshot.sourceCounts
				} : null
			});
		}
		resetGeneralUpgradeKnownStates(snapshotAccountId);
		const rosterIds = normalizeGeneralUpgradeRosterIds(liveSnapshot.ids);
		const checkedIds = rosterIds.slice(0, Math.max(1, requestedFirstStage));
		const preflight = await inspectGeneralUpgradePreflight(manager, snapshotAccountId, checkedIds, rosterIds.length);
		preflight.snapshot = {
			rawCount: Math.max(0, Number(liveSnapshot.rawCount) || 0),
			acceptedCount: Math.max(0, Number(liveSnapshot.acceptedCount) || rosterIds.length),
			rejectedCount: Math.max(0, Number(liveSnapshot.rejectedCount) || 0),
			sourceCounts: Array.isArray(liveSnapshot.sourceCounts) ? liveSnapshot.sourceCounts : []
		};
		if (!preflight.ready) {
			const reason = preflight.status === "account-not-ready" ? "当前账号未识别" : "实时快照目标前缀未稳定";
			skipped.push(`武将升阶:预检停止(${reason})`);
			return summarizeGeneralUpgradeRun(counts, 0, [], preflight.status, preflight);
		}
		const selectedIds = rosterIds.slice(0, requestedFirstStage);
		if (!selectedIds.length) {
			skipped.push("武将升阶:实时快照为空");
			return summarizeGeneralUpgradeRun(counts, 0, [], "roster-not-scanned", preflight);
		}
		if (selectedIds.length < requestedFirstStage) skipped.push(`武将升阶:实时快照仅${selectedIds.length}/${requestedFirstStage}名`);
		const materialInventory = readGeneralUpgradeMaterialInventory();
		const requestedStages = GENERAL_UPGRADE_STAGES.filter((stage) => counts[stage.key] > 0);
		const stageReports = requestedStages.map((stage) => {
			const targetCount = counts[stage.key];
			return {
				stage: stage.key,
				from: stage.from,
				to: stage.to,
				goodId: stage.goodId,
				name: stage.name,
				targetCount,
				candidateCount: 0,
				alreadySatisfiedIds: [],
				blockedIds: [],
				missingCount: Math.max(0, targetCount - selectedIds.slice(0, targetCount).length),
				unsentIds: [],
				sentIds: [],
				confirmedIds: [],
				confirmedStates: [],
				unconfirmedIds: [],
				materialPlans: [],
				materialUnavailableIds: [],
				blockedReason: ""
			};
		});
		const reportByStage = new Map(stageReports.map((report) => [report.stage, report]));
		const confirmationBudgetMs = generalUpgradeConfirmBudgetMs(counts);
		const confirmationDeadlineAt = Date.now() + confirmationBudgetMs;
		const sendScheduler = createGeneralUpgradeSendScheduler(confirmationDeadlineAt);
		const responseMonitor = createGeneralUpgradeResponseMonitor(manager);
		const workerCount = Math.min(GENERAL_UPGRADE_MAX_CONCURRENCY, selectedIds.length);
		let nextSelectedIndex = 0, activeConfirmations = 0, maxActiveConfirmations = 0;
		const processGeneralChain = async (selectedIndex) => {
			const id = selectedIds[selectedIndex];
			let chainBlocked = !1, provenStar = 0, responseWatch = null;
			for (let stageIndex = 0; stageIndex < requestedStages.length; stageIndex += 1) {
				const stage = requestedStages[stageIndex];
				if (selectedIndex >= counts[stage.key]) continue;
				const report = reportByStage.get(stage.key);
				if (chainBlocked) {
					report.blockedIds.push(id);
					report.blockedReason = "previous-stage-state-not-refreshed";
					continue;
				}
				let dispatch = null;
				{
					const observedBeforeQueue = readOwnedGeneralState(manager, id);
					if (observedBeforeQueue.star >= stage.to) {
						report.alreadySatisfiedIds.push(id);
						provenStar = Math.max(provenStar, observedBeforeQueue.star);
						continue;
					}
					const continuationProven = provenStar >= stage.from;
					if (!continuationProven && observedBeforeQueue.star !== stage.from) {
						report.blockedIds.push(id);
						report.blockedReason = "previous-stage-state-not-refreshed";
						chainBlocked = !0;
						continue;
					}
					report.candidateCount += 1;
					dispatch = await sendScheduler.enqueue(() => {
						const liveState = readOwnedGeneralState(manager, id);
						if (liveState.star >= stage.to) return { status: "already", state: liveState };
						if (!continuationProven && liveState.star !== stage.from) return { status: "blocked", state: liveState };
						const baseline = liveState.star === stage.from ? liveState : { ...liveState, star: stage.from };
						const material = chooseGeneralUpgradeMaterial(stage, baseline, materialInventory);
						if (!material.available) return { status: "material-unavailable", state: liveState, material };
						responseWatch = responseMonitor.watch(id, stage.to);
						const materialItems = Array.isArray(material.items) && material.items.length ? material.items : [{
							goodId: material.goodId,
							name: material.name,
							exp: material.exp,
							count: material.count,
							fallback: material.fallback === !0
						}];
						const firstMaterial = materialItems[0];
						manager.sendStarExpAddReq(id, firstMaterial.goodId, firstMaterial.count);
						if (materialInventory.available === !0) {
							const reserved = materialInventory.materials.find((item) => item.goodId === firstMaterial.goodId);
							if (reserved) reserved.count = Math.max(0, reserved.count - firstMaterial.count);
						}
						return { status: "sent", baseline, material: firstMaterial, materialItems };
					}, continuationProven);
				if (dispatch.status === "sent" && Array.isArray(dispatch.materialItems) && dispatch.materialItems.length > 1) {
					const sentMaterials = [dispatch.material];
					for (const material of dispatch.materialItems.slice(1)) {
						const nextDispatch = await sendScheduler.enqueue(() => {
							manager.sendStarExpAddReq(id, material.goodId, material.count);
							if (materialInventory.available === !0) {
								const reserved = materialInventory.materials.find((item) => item.goodId === material.goodId);
								if (reserved) reserved.count = Math.max(0, reserved.count - material.count);
							}
							return { status: "sent-part", material };
						}, !0);
						if (nextDispatch.status !== "sent-part") {
							dispatch.partialSendError = nextDispatch;
							break;
						}
						sentMaterials.push(material);
					}
					dispatch.materials = sentMaterials;
					if (dispatch.partialSendError && dispatch.partialSendError.status === "error") {
						errors.push(`武将升阶(${stage.from}→${stage.to},ID=${id},材料续发):` + em(dispatch.partialSendError.error));
					}
				}
				}
				if (dispatch.status === "already") {
					responseMonitor.cancel(responseWatch);
					responseWatch = null;
					report.alreadySatisfiedIds.push(id);
					provenStar = Math.max(provenStar, Number(dispatch.state && dispatch.state.star) || stage.to);
					continue;
				}
				if (dispatch.status === "deadline") {
					responseMonitor.cancel(responseWatch);
					responseWatch = null;
					report.unsentIds.push(id);
					chainBlocked = !0;
					continue;
				}
				if (dispatch.status === "blocked") {
					responseMonitor.cancel(responseWatch);
					responseWatch = null;
					report.blockedIds.push(id);
					report.blockedReason = "previous-stage-state-not-refreshed";
					chainBlocked = !0;
					continue;
				}
				if (dispatch.status === "material-unavailable") {
					responseMonitor.cancel(responseWatch);
					responseWatch = null;
					report.materialUnavailableIds.push(id);
					chainBlocked = !0;
					continue;
				}
				if (dispatch.status === "error") {
					responseMonitor.cancel(responseWatch);
					responseWatch = null;
					errors.push(`武将升阶(${stage.from}→${stage.to},ID=${id}):` + em(dispatch.error));
					chainBlocked = !0;
					continue;
				}
				report.sentIds.push(id);
				const sentMaterials = Array.isArray(dispatch.materials) && dispatch.materials.length ? dispatch.materials : (dispatch.material ? [dispatch.material] : []);
				for (const material of sentMaterials) report.materialPlans.push({ id, goodId: material.goodId, name: material.name, count: material.count, fallback: material.fallback === !0 });
				activeConfirmations += 1;
				maxActiveConfirmations = Math.max(maxActiveConfirmations, activeConfirmations);
				let confirmation;
				try {
					confirmation = await waitForGeneralUpgradeTransition(manager, dispatch.baseline, stage.to, confirmationDeadlineAt, responseWatch);
				} finally {
					responseMonitor.cancel(responseWatch);
					responseWatch = null;
					activeConfirmations = Math.max(0, activeConfirmations - 1);
				}
				if (confirmation.confirmed) {
					report.confirmedIds.push(id);
					report.confirmedStates.push(confirmation.state);
					provenStar = Math.max(provenStar, stage.to);
				} else {
					report.unconfirmedIds.push(id);
					chainBlocked = !0;
				}
			}
		};
		const runWorker = async () => {
			while (nextSelectedIndex < selectedIds.length) {
				const selectedIndex = nextSelectedIndex;
				nextSelectedIndex += 1;
				await processGeneralChain(selectedIndex);
			}
		};
		await Promise.all(Array.from({ length: workerCount }, () => runWorker()));
		sendScheduler.close();
		if (stageReports.some((report) => report.unconfirmedIds.length)) await sleep(GENERAL_UPGRADE_LATE_CONFIRM_SETTLE_MS);
		let lateConfirmedCount = 0;
		for (const report of stageReports) {
			const stillUnconfirmed = [];
			for (const id of report.unconfirmedIds) {
				const state = readOwnedGeneralState(manager, id);
				if (state.star >= report.to) {
					report.confirmedIds.push(id);
					report.confirmedStates.push({ ...state, lateConfirmed: !0 });
					lateConfirmedCount += 1;
				} else stillUnconfirmed.push(id);
			}
			report.unconfirmedIds = stillUnconfirmed;
		}
		const responseMonitorStats = responseMonitor.stats();
		responseMonitor.close();
		for (const report of stageReports) {
			report.alreadySatisfiedIds = Array.from(new Set(report.alreadySatisfiedIds));
			report.blockedIds = Array.from(new Set(report.blockedIds));
			report.unsentIds = Array.from(new Set(report.unsentIds));
			report.satisfiedIds = Array.from(new Set([...report.alreadySatisfiedIds, ...report.confirmedIds]));
			if (report.blockedIds.length) skipped.push(`武将升阶:${report.from}→${report.to}实时快照前${report.targetCount}名中${report.blockedIds.length}名前层未实时确认，本轮不补位`);
			if (report.materialUnavailableIds.length) skipped.push(`武将升阶:${report.from}→${report.to}已知材料不足${report.materialUnavailableIds.length}名，未发包`);
			if (report.confirmedIds.length) {
				done.push(`武将升阶:${report.from}→${report.to}即时确认${report.confirmedIds.length}/${report.sentIds.length}名(${report.name}×${report.sentIds.length})`);
			}
			if (report.alreadySatisfiedIds.length) done.push(`武将升阶:${report.from}→${report.to}当前已有${report.alreadySatisfiedIds.length}名达到目标阶数`);
			if (report.unconfirmedIds.length) {
				requested.push(`武将升阶:${report.from}→${report.to}已发${report.sentIds.length}次、单次${GENERAL_UPGRADE_SINGLE_CONFIRM_TIMEOUT_MS}ms内未捕获${report.unconfirmedIds.length}名`);
			}
		}
		const summary = summarizeGeneralUpgradeRun(counts, selectedIds.length, stageReports, "", preflight);
		const schedulerStats = sendScheduler.stats();
		summary.execution = {
			mode: "live-snapshot-event-first-v3",
			workerCount,
			maxActiveConfirmations,
			sendIntervalMs: GENERAL_UPGRADE_SEND_INTERVAL_MS,
			minimumObservedSendGapMs: schedulerStats.minimumGapMs,
			urgentContinuationCount: schedulerStats.urgentContinuationCount,
			singleConfirmTimeoutMs: GENERAL_UPGRADE_SINGLE_CONFIRM_TIMEOUT_MS,
			totalBudgetMs: confirmationBudgetMs,
			eventMonitorInstalled: responseMonitorStats.installed,
			eventObservedSuccessCount: responseMonitorStats.observedSuccessCount,
			lateConfirmedCount,
			materialInventory: materialInventory.available === !0
				? materialInventory.materials.map((item) => ({ goodId: item.goodId, name: item.name, count: item.count, exp: item.exp }))
				: { available: !1, reason: materialInventory.reason },
			elapsedMs: Math.max(0, Date.now() - batchStartedAt),
			apiDiagnostic
		};
		return summary;
	}

	function captureOfficerSprintRewardVos(manager) {
		if (!manager || "function" != typeof manager.GetOfficerRunCommonRewardState ||
			"function" != typeof manager.OnCheckOfficerRunCommonRewardRed) return [];
		const name = "GetOfficerRunCommonRewardState";
		const hadOwn = Object.prototype.hasOwnProperty.call(manager, name);
		const ownDescriptor = hadOwn ? Object.getOwnPropertyDescriptor(manager, name) : null;
		const original = manager[name], captured = [];
		try {
			manager[name] = function (vo) {
				if (vo && Number(vo.Id) > 0) captured.push(vo);
				return original.call(this, vo);
			};
			manager.OnCheckOfficerRunCommonRewardRed();
		} catch (_) {
		} finally {
			try {
				if (hadOwn && ownDescriptor) Object.defineProperty(manager, name, ownDescriptor);
				else delete manager[name];
			} catch (_) { try { manager[name] = original; } catch (_) {} }
		}
		const seen = new Set();
		return captured.filter((vo) => {
			const key = `${Number(vo.Stage) || 0}:${Number(vo.Id) || 0}`;
			if (seen.has(key)) return !1;
			seen.add(key);
			return !0;
		});
	}

	const OFFICER_SPRINT_REFRESH_TIMEOUT_MS = 3200;
	const OFFICER_SPRINT_REFRESH_POLL_MS = 100;
	const OFFICER_SPRINT_REFRESH_RETRY_GAP_MS = 250;
	const OFFICER_SPRINT_LOCAL_DATA_TIMEOUT_MS = 800;

	function officerSprintRewardFingerprint(manager) {
		const rewardVos = captureOfficerSprintRewardVos(manager);
		return rewardVos.map((vo) => {
			let state = -1;
			try { state = Number(manager.GetOfficerRunCommonRewardState(vo)); } catch (_) {}
			return `${Number(vo.Stage) || 0}:${Number(vo.Id) || 0}:${Number.isFinite(state) ? state : -1}`;
		}).sort().join("|");
	}

	async function refreshOfficerSprintData(manager) {
		// 登录早期可能已留下非空旧对象；必须以请求后的对象或奖励状态变化作为刷新信号。
		const beforeData = manager.curOfficerRunCommonData || null;
		const beforeFingerprint = officerSprintRewardFingerprint(manager);
		const startedAt = Date.now();
		const protocolWaiter = createDailyProtocolResponseWaiter(
			manager,
			DAILY_REWARD_PROTOCOL_IDS.officerSprintData,
			OFFICER_SPRINT_REFRESH_TIMEOUT_MS
		);
		let protocolReply = null, resultCode = null, actId = null;
		try {
			manager.SendOfficerRunCommonUserDataReq(0);
		} catch (error) {
			protocolWaiter.cancel();
			throw error;
		}
		if (protocolWaiter.supported) {
			protocolReply = await protocolWaiter.promise;
			const result = readDailyProtocolResult(protocolReply);
			if (result.present) resultCode = result.value;
			for (const scope of dailyProtocolScopes(protocolReply)) {
				if (!Object.prototype.hasOwnProperty.call(scope, "actId")) continue;
				const value = Number(scope.actId);
				actId = Number.isFinite(value) ? value : scope.actId;
				break;
			}
			if (protocolReply.status === "response" && result.present && Number(result.value) !== 0) {
				return {
					ready: !1,
					rejected: !0,
					resultCode,
					actId,
					waitedMs: Math.max(0, Date.now() - startedAt),
					fingerprint: beforeFingerprint,
					protocolReply
				};
			}
		}
		const deadline = startedAt + OFFICER_SPRINT_REFRESH_TIMEOUT_MS;
		let currentData = manager.curOfficerRunCommonData || null;
		let currentFingerprint = beforeFingerprint;
		do {
			await sleep(OFFICER_SPRINT_REFRESH_POLL_MS);
			currentData = manager.curOfficerRunCommonData || null;
			currentFingerprint = officerSprintRewardFingerprint(manager);
			if (currentData && (!beforeData || currentData !== beforeData || currentFingerprint !== beforeFingerprint)) {
				return {
					ready: !0,
					changed: !0,
					waitedMs: Math.max(0, Date.now() - startedAt),
					fingerprint: currentFingerprint,
					resultCode,
					actId,
					protocolReply
				};
			}
		} while (Date.now() < deadline);
		return {
			ready: !!currentData,
			changed: !1,
			waitedMs: Math.max(0, Date.now() - startedAt),
			fingerprint: currentFingerprint,
			resultCode,
			actId,
			protocolReply
		};
	}

	async function waitForOfficerSprintLocalData(manager, expectProgress) {
		const startedAt = Date.now();
		const beforeData = manager.curOfficerRunCommonData || null;
		const beforeFingerprint = officerSprintRewardFingerprint(manager);
		const deadline = startedAt + OFFICER_SPRINT_LOCAL_DATA_TIMEOUT_MS;
		let currentData = beforeData, currentFingerprint = beforeFingerprint, rewardVos = [], claimable = null;
		do {
			currentData = manager.curOfficerRunCommonData || null;
			currentFingerprint = officerSprintRewardFingerprint(manager);
			rewardVos = captureOfficerSprintRewardVos(manager);
			claimable = rewardVos.find((vo) => {
				try { return Number(manager.GetOfficerRunCommonRewardState(vo)) === 1; } catch (_) { return !1; }
			}) || null;
			if (claimable || currentData && rewardVos.length &&
				(expectProgress !== !0 || currentData !== beforeData || currentFingerprint !== beforeFingerprint)) break;
			if (Date.now() >= deadline) break;
			await sleep(OFFICER_SPRINT_REFRESH_POLL_MS);
		} while (Date.now() < deadline);
		return {
			ready: !!currentData || rewardVos.length > 0,
			changed: !!currentData && (!beforeData || currentData !== beforeData || currentFingerprint !== beforeFingerprint),
			waitedMs: Math.max(0, Date.now() - startedAt),
			fingerprint: currentFingerprint,
			rewardVos,
			claimable,
			refreshSupported: !1
		};
	}

	async function waitForOfficerSprintState(manager, rewardVo, expected, timeoutMs = 3200) {
		const deadline = Date.now() + timeoutMs;
		while (Date.now() < deadline) {
			try { if (Number(manager.GetOfficerRunCommonRewardState(rewardVo)) === expected) return !0; } catch (_) {}
			await sleep(100);
		}
		return !1;
	}

	async function claimOfficerSprintRewards(manager, done, requested, skipped, errors, em, options = {}) {
		const requiredMethods = [
			"SendClientOfficerRun3GetOfficerAwardReq",
			"GetOfficerRunCommonRewardState",
			"OnCheckOfficerRunCommonRewardRed"
		];
		const missingMethods = requiredMethods.filter((name) => "function" != typeof manager[name]);
		if (missingMethods.length) {
			skipped.push(`官阶冲刺:核心接口无(${missingMethods.join("/")})`);
			return;
		}
		const refreshSupported = "function" == typeof manager.SendOfficerRunCommonUserDataReq;
		const refreshAttempts = refreshSupported && options.expectProgress === !0 ? 2 : 1;
		let refreshResult = null, rewardVos = [], claimable = null;
		for (let attempt = 0; attempt < refreshAttempts; attempt += 1) {
			try {
				refreshResult = refreshSupported
					? await refreshOfficerSprintData(manager)
					: await waitForOfficerSprintLocalData(manager, options.expectProgress === !0);
			} catch (error) {
				errors.push("官阶冲刺:活动数据请求失败:" + em(error));
