	async function exchangeBlackMagicOrbsInGame() {
		const cfg = BLACK_MAGIC_ORB_EXCHANGE;
		const base = {
			ready: !1,
			activityId: cfg.activityId,
			exchangeId: cfg.exchangeId,
			itemId: cfg.itemId,
			costItemId: cfg.costItemId,
			costPerExchange: cfg.costPerExchange,
			rewardPerExchange: cfg.rewardPerExchange,
			weeklyLimit: cfg.weeklyLimit,
			requestedExchanges: cfg.requestedExchanges,
			sentExchanges: 0,
			beforeTimes: 0,
			afterTimes: 0,
			confirmed: !1,
			status: "not-ready"
		};
		try {
			if (Date.now() < Date.parse(cfg.activeFrom) || Date.now() >= Date.parse(cfg.activeUntil)) {
				return { ...base, ready: !0, status: "activity-outside-time" };
			}
			if ("undefined" == typeof laya || "function" != typeof laya.class) return { ...base, status: "laya-not-ready" };
			const manager = laya.class("ActivityManager");
			if (!manager) return { ...base, status: "activity-manager-not-ready" };
			if ("function" != typeof manager.SendClientExchangeInfoReq ||
				"function" != typeof manager.SendExchangeReq ||
				"function" != typeof manager.GetExchangeTimes) {
				return { ...base, ready: !0, status: "exchange-api-incomplete" };
			}

			// 先走官方兑换次数查询；事件数据为空时官方不会广播 EXCHANGE_INFO_NTF，
			// 所以查询最多等 1.5 秒，随后仍以服务器的周限作为最终兜底。
			const infoEvent = resolveGameEvent(manager, "EXCHANGE_INFO_NTF");
			let infoWaiter = null;
			if (infoEvent != null && "function" == typeof manager.on && "function" == typeof manager.off) {
				infoWaiter = waitForGameEvent(manager, infoEvent, () => manager.SendClientExchangeInfoReq(cfg.activityId), 1500);
			} else {
				manager.SendClientExchangeInfoReq(cfg.activityId);
			}
			if (infoWaiter) await infoWaiter;
			else await sleep(1500);

			const beforeTimes = readBlackMagicOrbExchangeTimes(manager);
			const remaining = Math.max(0, cfg.weeklyLimit - beforeTimes);
			if (!remaining) {
				return { ...base, ready: !0, beforeTimes, afterTimes: beforeTimes, status: "weekly-limit-reached" };
			}
			const sendTimes = Math.min(cfg.requestedExchanges, remaining);
			const successEvent = resolveGameEvent(manager, "EXCHANGE_SUCCESS");
			let eventResult = null;
			if (successEvent != null && "function" == typeof manager.on && "function" == typeof manager.off) {
				eventResult = await waitForGameEvent(
					manager,
					successEvent,
					() => manager.SendExchangeReq(cfg.activityId, cfg.exchangeId, cfg.itemId, sendTimes),
					4000
				);
			} else {
				manager.SendExchangeReq(cfg.activityId, cfg.exchangeId, cfg.itemId, sendTimes);
			}
			const expectedTimes = Math.min(cfg.weeklyLimit, beforeTimes + sendTimes);
			const afterTimes = await waitForBlackMagicOrbExchangeTimes(manager, expectedTimes, eventResult ? 1000 : 4000);
			const eventConfirmed = eventResult && eventResult.status === "event";
			const stateConfirmed = afterTimes >= expectedTimes;
			return {
				...base,
				ready: !0,
				sentExchanges: sendTimes,
				beforeTimes,
				afterTimes,
				confirmed: Boolean(eventConfirmed || stateConfirmed),
				status: eventConfirmed ? "server-confirmed" : (stateConfirmed ? "state-confirmed" : "sent-unconfirmed")
			};
		} catch (error) {
			return { ...base, ready: !0, status: "error", error: error && error.message ? error.message : String(error) };
		}
	}

